(function () {
  "use strict";
  var DATA = {"version":"2.1.0","builtAt":"2026-09-03T05:36:12.199Z","curriculum":{"$schema":"AI Knowledge OS · Curriculum v2.0 (Category → Chapter → Lesson → Concept)","note":"四层结构：Category 分类 → Chapter 章 → Lesson 课（真正学习单元）→ Concept（知识图谱最小节点）。134 个 Concept 被组织进约 52 个 Lesson；一个 Lesson 可由多个 Concept 组合而成。此时 Lesson 是学习单位，Concept 是图谱节点。","lessonCount":52,"flagShip":["l00-ai-world","l-attention","l-embedding","l-transformer","l-rag","l-agent"],"categories":[{"category":"c01-ai-world","title":"AI 世界地图","overview":{"headline":"让机器从数据里找到规律","questions":["AI、机器学习、深度学习到底是什么关系？","AI 现在能干什么、不能干什么？","为什么最近几年 AI 突然爆发？","我从哪里开始学起？"],"mentalModel":["数据 Data","模型 Model","预测 Prediction","误差 Loss","梯度 Gradient","参数更新 Update"]},"chapters":[{"title":"第一章 · AI 全景","lessons":[{"id":"l00-ai-world","ready":true,"title":"一张图看懂整个 AI 世界"},{"id":"l01-ai-vs-ml-dl","ready":false,"title":"AI / Machine Learning / Deep Learning 到底什么关系"}]}]},{"category":"c02-essentials","title":"AI 必备基础","overview":{"headline":"看懂 AI 需要的最小数学与概念地基","questions":["文字、图片怎么变成电脑能算的数字？","向量是什么？为什么意思相近的词距离更近？","什么叫梯度，为什么模型靠它学习？","概率和不确定性在 AI 里有什么用？"],"mentalModel":["实体","→ 向量 Vector","→ 向量空间","→ 相似度","→ 学习"]},"chapters":[{"title":"第一章 · 向量与语义","lessons":[{"id":"l-embedding","ready":true,"title":"Embedding｜怎么把词变成电脑能懂的数字"},{"id":"l02-vector-space","ready":false,"title":"向量空间与相似度"}]},{"title":"第二章 · 数学地基","lessons":[{"id":"l03-matrix-gradient","ready":false,"title":"矩阵、函数与梯度入门"},{"id":"l04-probability","ready":false,"title":"概率：AI 在预测什么"}]}]},{"category":"c03-ml","title":"机器学习","overview":{"headline":"让机器从数据里找到规律","questions":["机器到底怎么『学习』？","模型为什么能预测没见过的东西？","模型怎么知道自己错了？","为什么训练效果好，现实里却可能很差？"],"mentalModel":["数据","→ 模型","→ 预测","→ 误差 Loss","→ 梯度 Gradient","→ 参数更新","↺"]},"chapters":[{"title":"第一章 · 学会学习","lessons":[{"id":"l05-gradient-descent","ready":false,"title":"Gradient Descent｜模型怎么『往下走』学会预测"}]},{"title":"第二章 · 预测与评估","lessons":[{"id":"l06-overfitting","ready":false,"title":"为什么训练好、现实差：过拟合"},{"id":"l07-eval","ready":false,"title":"怎么判断模型到底好不好"}]}]},{"category":"c04-dl","title":"深度学习","overview":{"headline":"多层神经网络如何工作","questions":["神经元、层、网络是什么？","反向传播在传什么？","深度为什么有用？"],"mentalModel":["输入","→ 神经元","→ 层","→ 激活","→ 输出","← 反向传播 ← 误差"]},"chapters":[{"title":"第一章 · 神经网络","lessons":[{"id":"l08-neural-network","ready":false,"title":"Neural Network｜神经元如何组成可学习的网络"}]},{"title":"第二章 · 学习机制","lessons":[{"id":"l09-backprop","ready":false,"title":"反向传播：误差如何传回去改参数"},{"id":"l10-cnn-rnn","ready":false,"title":"CNN 与 RNN：两种经典网络在解决什么"}]}]},{"category":"c05-llm","title":"大语言模型","overview":{"headline":"ChatGPT 这类大模型到底在干嘛","questions":["大模型是怎么『学会』说话的？","Transformer 和 Attention 是什么？为什么它颠覆了一切？","上下文窗口、Token、温度是什么意思？","为什么模型会一本正经地胡说八道？"],"mentalModel":["Token","→ Embedding","→ Transformer","→ 生成下一个词","→ 上下文","→ 输出"]},"chapters":[{"title":"第一章 · 语言如何进入模型","lessons":[{"id":"l11-tokenization","ready":false,"title":"Tokenization｜LLM 是怎么『读』文字的"},{"id":"l12-context-window","ready":false,"title":"上下文窗口：模型一次能『看见』多少"}]},{"title":"第二章 · Transformer","lessons":[{"id":"l-transformer","ready":true,"title":"Transformer｜大模型的地基架构"},{"id":"l-attention","ready":true,"title":"Attention｜模型为什么知道该关注哪个词"}]},{"title":"第三章 · 训练与推理","lessons":[{"id":"l13-llm-training","ready":false,"title":"预训练 / 微调 / RLHF"},{"id":"l14-inference","ready":false,"title":"推理：模型如何生成一个词一个词地说话"},{"id":"l15-prompt","ready":false,"title":"Prompt 工程：怎么和模型说清楚"}]}]},{"category":"c06-llm-app","title":"LLM 应用","overview":{"headline":"把大模型接进真实产品","questions":["怎么调用一个模型做出产品？","函数调用、结构化输出、流式是什么？","怎么评估一个 AI 功能做得好不好？"],"mentalModel":["用户输入","→ API","→ 模型","→ 输出","→ 评估"]},"chapters":[{"title":"第一章 · 接入模型","lessons":[{"id":"l16-llm-api","ready":false,"title":"用 API 把模型接进你的产品"},{"id":"l17-function-calling","ready":false,"title":"Function Calling｜让模型能『动手』"}]}]},{"category":"c07-rag","title":"RAG 检索增强","overview":{"headline":"让模型基于你的资料回答","questions":["模型记不住我的私有资料，怎么办？","RAG 是怎么『找到』相关内容的？","RAG 和微调有什么不同？"],"mentalModel":["文档","→ 切块 Chunk","→ 向量化","→ 检索","→ 上下文","→ 生成"]},"chapters":[{"title":"第一章 · RAG 全流程","lessons":[{"id":"l-rag","ready":true,"title":"RAG｜让模型『查资料』再回答"}]}]},{"category":"c08-agent","title":"Agent 智能体","overview":{"headline":"让 AI 从『回答』到『做事』","questions":["为什么 ChatGPT 不能帮我们操作电脑，Codex 却可以？","Agent 和普通聊天机器人差在哪？","Agent 怎么用工具、怎么规划、怎么循环？"],"mentalModel":["目标","→ 推理","→ 调用工具","→ 观察结果","→ 下一步","↺"]},"chapters":[{"title":"第一章 · 从会说到会做","lessons":[{"id":"l-agent","ready":true,"title":"Agent｜让 AI 自己动手做事"}]}]},{"category":"c09-multimodal","title":"多模态","overview":{"headline":"让 AI 看得见、听得见、能生成","questions":["AI 怎么『看懂』图片和视频？","声音、图像、文字怎么在一个模型里对齐？","扩散模型怎么生成图片？"],"mentalModel":["图像","→ 编码","→ 对齐","→ 生成"]},"chapters":[{"title":"第一章 · 多模态基础","lessons":[{"id":"l18-multimodal","ready":false,"title":"多模态｜AI 如何同时理解文字、图片、声音"},{"id":"l19-diffusion","ready":false,"title":"Diffusion｜图片是怎么被『画』出来的"}]}]},{"category":"c10-ai-eng","title":"AI 工程","overview":{"headline":"把 AI 系统做进生产环境","questions":["一个 AI 应用上线要做什么？","成本、延迟、评估怎么管理？","向量数据库、评估、框架怎么选？"],"mentalModel":["需求","→ 选型","→ 构建","→ 评估","→ 上线","→ 监控"]},"chapters":[{"title":"第一章 · 工程化","lessons":[{"id":"l20-ai-eng","ready":false,"title":"AI 工程：从原型到生产"},{"id":"l21-eval-cost","ready":false,"title":"评估与成本：怎么判断值不值"}]}]},{"category":"c11-ai-coding","title":"AI 编程","overview":{"headline":"用 AI 大幅提升编码效率","questions":["AI 结对编程怎么用？","Agentic Coding 和补全有什么不同？","上下文工程怎么让 AI 更懂你的代码库？"],"mentalModel":["需求","→ 上下文","→ AI 生成","→ 审查","→ 迭代"]},"chapters":[{"title":"第一章 · AI Coding","lessons":[{"id":"l22-ai-coding","ready":false,"title":"AI Coding｜把 AI 变成你的结对程序员"}]}]},{"category":"c12-ai-product","title":"AI 产品与商业","overview":{"headline":"判断一个 AI 产品值不值得做","questions":["一个 AI 产品『技术上能不能做』怎么判断？","AI 产品怎么创造真实价值？","合规、伦理、成本怎么权衡？"],"mentalModel":["用户问题","→ AI 能力","→ 产品形态","→ 价值","→ 商业模式"]},"chapters":[{"title":"第一章 · 产品思维","lessons":[{"id":"l23-ai-product","ready":false,"title":"AI 产品：从想法到落地"}]}]}]},"lessonCount":10,"flagship":["l00-ai-world","l-attention","l-embedding","l-transformer","l-rag","l-agent"],"lessons":{"l00-ai-world":{"id":"l00-ai-world","title":"一张图看懂整个 AI 世界","subtitle":"在学任何一个概念之前，先拿到整张地图：你现在站在哪里，接下来要走到哪里。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"15-20 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl","ai-apps","ai-limits"],"prereqLessons":[],"nextLesson":"l-embedding","sections":[{"type":"opening","question":"你每天听到的 ChatGPT、大语言模型（LLM）、Transformer、Agent、RAG……它们到底谁包含谁、谁建在谁之上？如果你现在只能用一句话回答「它们是什么关系」，你会怎么说？","guess":"很多人会脱口而出「都是一回事，就是 AI」。","next":"这节课不教任何公式，只画一张总地图。学完你不仅能说清这些词的关系，还能知道接下来 5 节旗舰课各自站在这张地图的哪个格子里。"},{"type":"why","before":"你在标题、文章、面试里反复遇到 Token、Attention、Transformer、RAG、Agent、Fine-tune……每个词单独看都懂一点，但凑在一起就乱。","problem":"初学者最大的障碍不是「不够努力」，而是没有地图：他不知道现在学的东西将来会连到哪里，于是学一个忘一个，越学越焦虑。","need":"所以第一节课我们不讲任何实现细节，只建立骨架：AI 世界分哪几层、每一层由什么构成、你将来要学的每一块长在哪个位置。地图在手里，后面的路才走得稳。"},{"type":"oneline","text":"AI（人工智能）是整片森林；机器学习是其中『会自己从数据里找规律』的那片林子；深度学习是最能长的那几棵大树；大语言模型（LLM）是最近最抢眼、能和你聊天的那一棵；而 RAG、Agent 这些，是围绕这棵树搭起来的『脚手架』——让树上的果子更好摘。"},{"type":"visual","kind":"ai-world-map","title":"AI 世界全景图","hint":"从最外层的 AI 一路收缩到 LLM，再向外展开 Vision / Speech / Agent / RAG 等应用方向。点击让你看明白的节点，就能往下一层走。"},{"type":"intuition","blocks":[{"k":"用俄罗斯套娃来想","t":"AI 是最大的套娃，机器学习是里面一层，深度学习再里面一层，LLM 是最小最精致的那层。每往里一层，都建立在外层之上——这叫『包含』，不是『并列』。"},{"k":"用搭积木来想","t":"只给你一个 LLM 你只能『聊天』。但当你往它外面搭『检索』（RAG）、『工具调用』（Agent）、『工作流编排』（Workflow）这些积木，你就从『会聊天』升级成『会办事』。产品形态 = 模型 + 一层层积木。"},{"k":"一句话记住主干","t":"AI ⊃ ML ⊃ DeepLearning ⊃ Foundation Model ⊃ LLM。这一个箭头链，就是整张地图的主干，也串起了你即将学的六节课。"}]},{"type":"how","intro":"把 AI 世界拆成「五层结构」与「五大应用方向」，你学完至少知道每块知识的归属，再也不会把它们混为一谈。","steps":[{"in":"第 0 层 · AI（人工智能）","process":"最上层总称：让机器表现出智能的一切技术，包括早期靠人写规则、搜索、专家系统。","out":"范围最大，是『目标』而不是某一门具体技术"},{"in":"第 1 层 · Machine Learning 机器学习","process":"不再靠人写死规则，而是让机器从数据里『自己找规律』，再拿规律去做预测。","out":"监督学习 / 无监督学习 / 强化学习 三大流派"},{"in":"第 2 层 · Deep Learning 深度学习","process":"用『多层神经网络』来自动提取特征，是机器学习的子集，能力更强：不用人手设计特征。","out":"CNN（图像）、RNN/Transformer（序列）、扩散模型（生成）等结构"},{"in":"第 3 层 · Foundation Model 基础模型","process":"在大规模数据上预训练好的『通用大脑』，可以微调或直接复用到很多不同任务。","out":"LLM（语言）、视觉基础模型、多模态基础模型"},{"in":"第 4 层 · LLM 大语言模型","process":"把『预测下一个词』当唯一训练目标，靠海量文本硬学出来的语言模型，意外获得了语言与世界的知识。","out":"ChatGPT、Claude、Gemini 背后的模型本体"},{"in":"围绕 LLM 的『脚手架』与应用架构","process":"光会聊天不够，为了让模型能办成事，在外面叠加外围技术。","out":"Prompt 提示 · RAG 检索增强 · Workflow 工作流 · Agent 智能体 · 多模态"}]},{"type":"realworld","items":[{"name":"ChatGPT","note":"「纯 LLM 对话产品」：你打字，它预测下一段话。它本身不做检索也不调工具，是最纯粹的一层。"},{"name":"Claude / Gemini","note":"同样是 LLM 驱动的对话产品，但在模型能力与对齐上做得不同，代表『同一个塔、不同的果』。"},{"name":"NotebookLM / 企业知识库问答","note":"「LLM + RAG」：你上传私有资料，系统先检索相关片段，再让模型基于这些片段回答，杜绝凭空编造。"},{"name":"Workflow 编排（如 Zapier AI / Coze 工作流）","note":"「LLM + 规则流程」：把『先做A、判断结果再做B』写成固定流水线，模型只负责其中某一环。"},{"name":"Codex / Claude Code","note":"「LLM + Agent 智能体」：不只是回答，还能自主决定『读文件→改代码→跑测试→看报错→再改』，直到把活干完。"},{"name":"Midjourney / Sora","note":"「不是 LLM 的另一棵树」：用扩散模型做图像/视频生成。提醒你 AI 世界不只有语言这一棵大树。"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是「目标——机器有智能」；机器学习是实现它的一种主流手段（用数据学出来）。早期用规则实现的人工智能，不属于机器学习，但仍然属于 AI。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是「从数据学习」；机器学习范围更大（含决策树、SVM 等传统算法），深度学习专指用多层神经网络，能自动提取特征，是机器学习的一个子集。"},{"a":"LLM","b":"Foundation Model","diff":"LLM 是专做语言的基础模型；Foundation Model 是更大的类，还包括视觉、多模态基础模型。LLM ⊂ 基础模型。"},{"a":"RAG","b":"Agent","diff":"RAG 是『给模型外接资料库』的检索增强；Agent 是『让模型自主决策与调用工具』的智能体。两者常配合：Agent 需要信息时用 RAG 检索。它们都不是模型本身，而是脚手架。"},{"a":"模型（Model）","b":"产品（Product）","diff":"模型是被训练出来的『大脑』；产品是把这个大脑装进界面、加上检索/记忆/工具后的完整应用。你用的是产品，不直接是模型。"}]},{"type":"mistakes","items":["把「AI、机器学习、深度学习、LLM」当同义词——它们是一层层包含关系，不是并列。","以为 ChatGPT = 整个 AI。ChatGPT 只是 LLM 的一颗果实；AI 世界还有视觉、语音、生成、机器人、Agent 等一大片。","以为 RAG 和 Agent 是「模型」。它们是在模型外面搭的脚手架/架构，本身没有『大脑』。","以为只有学完高等数学才能开始。第一门旗舰课（Embedding）就能带你把概念走通，数学按「够用」给，不是研究生讲义。","以为 Fine-tuning（微调）和 RAG 是一回事。前者改模型自身权重，后者不改模型、只改给它看的外部资料——它们解决不同问题。"]},{"type":"deep","title":"深入一点：把「领域 / 模型 / 技术 / 应用架构 / 产品形态」五顶帽子分清楚","beginner":["用「帽子」来记：同一个东西，问问题的角度不同，答案就不同。","「这属于哪个**领域**？」—— 问的是地图范围（AI、ML、DL 是领域/学科级）。","「这是个什么**模型**？」—— 问的是被训练出来的产物（LLM、扩散模型、视觉模型是模型级）。","「用了什么**技术/算法**？」—— 问的是怎么做（Attention、Transformer、RAG 检索是技术级）。","「这是什么**应用架构**？」—— 问的是怎么组合（RAG 架构、Agent 循环、Workflow 流水线是架构级）。","「最终做成什么**产品**？」—— 问的是用户能用的东西（ChatGPT、Codex、NotebookLM 是产品级）。"],"advanced":["用一条「从模型到产品」的抽象层次链来定位任何 AI 名词：","「AI 世界 = 领域层（AI⊃ML⊃DL）→ 模型层（Foundation Model→LLM/Diffusion/多模态）→ 技术层（Attention、位置编码、损失函数）→ 架构层（RAG、Agent、Workflow、多智能体协作）→ 产品层（ChatGPT、Claude Code）」。","判断法则：问「它能不能被『训练』出来」？能 → 模型层或更深；问「它是不是一个『零件/接法』」？能 → 技术层或架构层。训练产物是模型，接法是架构。","示例定位：Transformer 是技术层（一种网络结构）；GPT 系列是基于 Transformer 训练出来的模型（模型层）；把 GPT 接上检索= RAG 架构（架构层）；打包成网站= ChatGPT 产品（产品层）。","顺带一个工程事实：你平时说的「大模型」绝大多数指 LLM 或基础模型；而「智能体」「Agent」在业界常被定义为『模型 + 记忆 + 规划 + 工具调用』，是一个架构概念而非单个模型。"]},{"type":"exercise","prompt":"你现在打开了一款「企业知识库问答」App，上传公司政策文件后提了个问题，系统给出的回答里标注了「依据文件第 3 页」。你觉得它最可能是下面哪种组合？","opts":["只有 LLM，全靠模型自己编","LLM + RAG（先检索你的文件，再基于片段回答）","LLM + Agent（让模型自己去改代码）","纯扩散模型"],"a":1,"explain":"回答『依据你上传的文件』并带引用，正是 RAG 的典型特征：先检索相关片段，再让模型基于片段生成答案。","jump":"sec5-step5","jumpLabel":"围绕 LLM 的脚手架（RAG 检索）这一段"},{"type":"check","title":"结课检测：你真的懂这幅地图了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"下面哪条包含关系是正确的？","opts":["AI ⊃ LLM ⊃ Deep Learning ⊃ ML","AI ⊃ ML ⊃ Deep Learning ⊃ LLM","LLM ⊃ AI ⊃ ML ⊃ Deep","Deep Learning ⊃ ML ⊃ AI ⊃ LLM"],"a":1,"explain":"AI 包含机器学习，机器学习包含深度学习，LLM 是深度学习上长出的具体模型。","jump":"sec5-step0","jumpLabel":"五层结构第一步"},{"q":"ChatGPT 最准确地说是下面哪一个？","opts":["一个 Agent 智能体","一个纯 LLM 对话产品","一个 RAG 系统","一个视觉模型"],"a":1,"explain":"ChatGPT 的核心就是大语言模型：输入→预测下一段。RAG/Agent 是对它的增强，而不是它的本质。","jump":"sec5-step4","jumpLabel":"第 4 层 LLM 这一段"},{"q":"「NotebookLM 先查你上传的资料再回答」主要用到了哪项技术？","opts":["RAG 检索增强生成","纯预训练","扩散模型","只靠提示词"],"a":0,"explain":"针对私有资料，RAG 让模型先检索相关片段再回答，这正是 NotebookLM 类产品的核心。","jump":"sec5-step5","jumpLabel":"脚手架之 RAG 这一段"},{"q":"Codex「自己读代码、改代码、跑测试、看报错再重试」的能力，对应哪种架构？","opts":["RAG 检索增强","Agent 智能体循环","纯一次性生成","工作流固定流水线"],"a":1,"explain":"自主决策 + 调用工具 + 根据反馈循环，这正是 Agent 的核心：想→做→看→再想。","jump":"sec5-step5","jumpLabel":"脚手架之 Agent 这一段"},{"q":"「Midjourney 能生成图片」用到的模型，和 ChatGPT 的 LLM 是什么关系？","opts":["同一个模型","都是 LLM","Midjourney 用的是扩散模型，是 AI 世界里另一棵大树","Midjourney 不用 AI"],"a":2,"explain":"图像生成多靠扩散模型（Diffusion），与语言类的 LLM 是并列的不同模型，提醒你 AI 世界不止语言一棵树。","jump":"sec6","jumpLabel":"现实应用里的 Midjourney / Sora"}],"done":"现在你手里有整张地图了。接下来我们要下到模型的正下方——先搞清楚：电脑到底怎么把一句话变成它算得动的『数字』。","nextLesson":"l-embedding"},{"type":"connection","known":["（这是第一节课，还没有前置知识）"],"learned":["AI → ML → DL → Foundation Model → LLM 的主干链条（包含关系）","领域 / 模型 / 技术 / 应用架构 / 产品形态 五顶帽子怎么分","RAG、Agent、Workflow 是围绕 LLM 的脚手架，不是模型","ChatGPT、Claude（LLM产品）、NotebookLM（RAG）、Coze（工作流）、Codex（Agent）、Midjourney（扩散）各代表一类"],"next":"下一课我们钻到模型正下方：Embedding——电脑怎么把『一句话』变成『一串数字』。这是理解 LLM 的第一块砖，也是 RAG、搜索、推荐的地基。"}]},"l-embedding":{"id":"l-embedding","title":"Embedding｜怎么把词变成电脑能懂的数字","subtitle":"为什么文字不能直接进神经网络？为什么不是给每个词编个号？为什么意思相近的词离得更近？","category":"c02-essentials","chapterTitle":"第一章 · 向量与语义","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["embedding","vector","cosine-similarity","emb-vector-store"],"prereqLessons":["l00-ai-world"],"nextLesson":"l-attention","sections":[{"type":"opening","question":"你让 ChatGPT 翻译『苹果很好吃』，它内部第一件事不是『读懂』这句话，而是把『苹果』变成了一串数字。猜一猜：为什么电脑不能用『苹果』这两个汉字直接思考，非得多此一举先转成数字？","guess":"有人会想：给猫=1、狗=2、苹果=3 编个号不就行了？","next":"这节课就回答『为什么不能简单编号』，以及真正的 Embedding 是怎么做到『意思相近的词，数字也相近』的。"},{"type":"why","before":"神经网络只会做数学运算：加法、乘法、比较大小、算距离。它天生看不懂『猫』『狗』『苹果』这些文字。","problem":"如果文字根本送不进神经网络，那后面的一切——翻译、对话、理解、检索——全都是空中楼阁。这是所有语言模型的『第一道门』，绕不过去。","need":"所以我们必须在『文字』和『数字』之间搭一座桥，让电脑既能「算」文字，又能保留文字的含义。这座桥就是 Embedding。","visualNote":"下面这张 2D 语义空间图，就是你要带走的直觉：位置 = 语义。"},{"type":"oneline","text":"Embedding 就是把『一个词』变成『一串数字（向量）』，并且让意思相近的词，数字串长得也相近——于是电脑就能『算』语义了。"},{"type":"visual","kind":"embedding-space","title":"Embedding 2D 语义空间（可交互）","hint":"这是把词『压扁』到二维的示意：意思相近的词会聚在一起。观察猫/狗/狮子聚在『动物角』，苹果/香蕉聚在『食物角』。试试输入几个词，看它落在哪一群。"},{"type":"intuition","blocks":[{"k":"为什么不能直接给词编号？","t":"你可能会想：猫=1、狗=2、苹果=3 不就行了？但问题是：2 和 3 只差 1，可『狗』和『苹果』的语义差得十万八千里。编号把『数字距离』和『语义距离』完全搞乱了——电脑会误以为狗和苹果几乎一样。"},{"k":"用一张坐标纸来想","t":"想象一张地图，横轴是『是不是动物』，纵轴是『是不是食物』。『猫』放左边靠上，『狗』紧挨它，『苹果』放右上角。位置越近，意思越像。Embedding 本质就是在几百上千维的『坐标纸』上，给每个词找个位置。"},{"k":"一个生活类比","t":"就像地理坐标：北京和天津坐标很近，所以在空间里相邻；语义相近的词，在 Embedding 空间里坐标也相邻。"}]},{"type":"how","intro":"Embedding 是怎么『学』出来的？核心思想只有一句话：一个词的含义 = 它经常和哪些词一起出现。","steps":[{"in":"收集海量文本","process":"从整个互联网语料里，观察『猫』总是和『狗、宠物、喵、毛』一起出现，而『苹果』总跟『水果、吃、红色』一起出现。","out":"得到每个词在语料里的『共现模式』"},{"in":"用共现模式训练向量","process":"训练一开始给每个词一组随机数字，然后不断调整，让『经常一起出现』的词向量越走越近，『从不一起出现』的词向量越走越远。","out":"每个词最终固定成一个固定长度的向量（如 300 或 768 维）"},{"in":"用向量距离比较语义","process":"两个词的向量越接近（夹角越小、余弦相似度越高），语义越相近。电脑从此『算得出』猫≈狗、苹果≠猫。","out":"文字第一次可以被数值比较"},{"in":"送入下游模型","process":"这个数字向量就是神经网络的输入。LLM 只认数字，现在它『看得懂』词了，可以开始做翻译、对话、生成。","out":"模型能对词做运算、比较、生成"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude","note":"内部第一件事就是把你的每个 Token 转成 Embedding 向量，再送进 Transformer 网络。"},{"name":"搜索引擎语义检索","note":"把『怎么养猫』和『养宠物指南』都向量化，语义相近就能互相匹配，不必字面相同也能搜到。"},{"name":"NotebookLM / RAG","note":"把你的资料切成块并向量化，用户提问时在向量空间里『找最像的那几块』再交给模型回答——这就是 RAG 的地基。"}]},{"type":"compare","pairs":[{"a":"Token","b":"Embedding","diff":"Token 是文字切出的『小块』（词/子词）；Embedding 是把每个小块变成的『数字向量』。先切 Token，再做 Embedding。"},{"a":"Embedding 模型","b":"LLM","diff":"Embedding 模型把文本压成『定位向量』（不生成文字）；LLM 生成文字。一个是『编码员』，一个是『作家』。"},{"a":"One-hot 编号","b":"Embedding","diff":"One-hot 让所有词互相『等距』、无法表达语义；Embedding 让相近的词更近，真正抓住含义。"}]},{"type":"mistakes","items":["以为 Embedding 只是『给每个词一个数字』。其实是一整串数字（向量），且数字之间存在『相似关系』——这才是关键。","以为 Embedding 模型和 LLM 是同一个东西。它们是分工不同的两个模型：一个负责编码相似度，一个负责生成文字。","以为向量维度越高一定越好。维度越高表达力越强，但更贵、更易过拟合，常见几百维就够用。","以为 Embedding 能『理解逻辑』。它只捕捉统计上的相似，不保证逻辑正确——所以光靠 Embedding 做问答会答非所问。"]},{"type":"deep","title":"深入一点：从二维直觉到真实向量空间","beginner":["Embedding 在工程上就是『查表』：模型里有一张巨大的表，每个词一行，那一行数字就是它的向量。训练好了之后，直接用查到的数字即可。","维度越高，能表达的语义越细腻，但计算越贵。常见几百维就够处理大多数任务。","真正常用的是一种叫『子词』的粒度：一个字被拆成更小的片段（如 'unbreakable' → 'un' + 'break' + 'able'），这样遇到没见过的词也能拼出向量。"],"advanced":["向量不只给每个词一个『标签』，它把语义结构编进了几何里：经典例子 king − man + woman ≈ queen，说明向量『方向』也承载意义。","Embedding 模型（如 text-embedding 系列）与 LLM 是不同模型：前者把文本压缩成『定位码』，后者生成文字。它们可以分开训练、分开使用。","计算两个向量有多像，最常用的指标是**余弦相似度** cos(θ)：只看方向、不看长度，数值越接近 1 越像。",{"code":"# 余弦相似度：越大越像\nimport numpy as np\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\ncat   = np.array([0.9, 0.1])   # 靠近动物方向\napple = np.array([0.1, 0.9])   # 靠近食物方向\ndog   = np.array([0.85, 0.15]) # 很接近猫\n\nprint(round(cosine(cat, apple), 2))  # 0.22  → 语义远\nprint(round(cosine(cat, dog), 2))    # 1.0   → 语义很近","lang":"python"},"维度本质：真实 Embedding（如 OpenAI text-embedding-3）常达上千维，一个词就是一个上千维空间里的点。降维可视化（t-SNE / PCA）只是把上千维『压扁』到 2D 方便人看。"]},{"type":"exercise","prompt":"在一个语义空间里，『国王』向量减去『男人』向量，再加上『女人』向量，猜一猜结果最可能靠近下面哪个词？","opts":["王子","女王（皇后）","父亲","阿姨"],"a":1,"explain":"这正是著名的 king − man + woman ≈ queen 现象：向量的方向承载意义，『王 - 男 + 女』就指向『女王』的方向。它说明 Embedding 抓到的不是孤立的词，而是语义结构。","jump":"sec5-step3","jumpLabel":"用向量距离比较语义这一步"},{"type":"check","title":"结课检测：你真正理解 Embedding 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么不能直接给每个词编个号（猫=1，狗=2，苹果=3）？","opts":["因为编号会让相近的词距离更近","因为编号会破坏语义距离：狗和苹果只差 1，但语义差很远","因为编号需要太多内存","因为编号不能用于神经网络"],"a":1,"explain":"编号把数字距离和语义距离搞混了：狗(2)和苹果(3)只差1会被当成很相似，但它们的含义毫无关系。","jump":"sec4","jumpLabel":"『为什么不能直接给词编号』这一段"},{"q":"两个 Embedding 向量夹角越小（余弦相似度越高），说明什么？","opts":["两个词的语义越相近","两个词的字符串越长越像","两个词出现频率越接近","两个词的长度越接近"],"a":0,"explain":"夹角越小，向量在空间里越靠近，代表语义越相近。这就是『用距离算语义』。","jump":"sec5-step2","jumpLabel":"『用向量距离比较语义』这一步"},{"q":"关于 Embedding 模型与 LLM 的关系，正确的是？","opts":["它们是同一个模型","Embedding 模型把文本变向量、LLM 生成文字，二者分工不同","LLM 内部根本不做 Embedding","Embedding 模型能直接写文章"],"a":1,"explain":"Embedding 模型负责『编码相似度』，LLM 负责『生成内容』，是两个可分开训练的模型。","jump":"sec7","jumpLabel":"『Embedding 模型 vs LLM』那一条对比"},{"q":"Embedding 的『含义』主要来自哪里？","opts":["每个字在字典里的官方解释","这个模型『预测下一个词』时学到的共现模式","开发者手写的规则","词的笔画数"],"a":1,"explain":"一个词的含义 = 它常和哪些词一起出现。模型在大量文本上学到的正是这种共现模式。","jump":"sec5-step0","jumpLabel":"『收集海量文本』这一步"},{"q":"下面哪句关于向量维度的说法正确？","opts":["维度越高一定越好，越细越好","维度越低越好，因为一定更便宜","维度是表达力与成本的权衡，常见几百维就够用，过高更贵且易过拟合","维度只影响颜色不影响语义"],"a":2,"explain":"维度是权衡的结果：高维表达强但贵且易过拟合，低维省但表达粗糙。实际常用几百维。","jump":"sec9","jumpLabel":"深入一节关于维度的说明"}],"done":"你已经理解了『文字 → 数字向量 → 算距离』这条链路，这是 RAG、搜索、推荐共同的地基。","nextLesson":"l-attention"},{"type":"connection","known":["AI 世界全景：模型只能处理数字","Embedding 是文字进入模型的第一道门"],"learned":["文字 → 向量，让电脑能算语义","相近的词向量距离更近，用余弦相似度衡量","Embedding 模型与 LLM 分工不同","向量方向也能承载意义（king − man + woman ≈ queen）"],"next":"有了『每个词是一个数字向量』，下一步就是大招：Attention——模型怎么在一句话里决定『该重点关注哪个词』。这决定了模型能不能读懂『这只狗没咬那只猫，是因为它怕它』里『它』到底指谁。"}]},"l-attention":{"id":"l-attention","title":"Attention｜模型为什么知道该关注哪个词","subtitle":"当模型读到『它』，怎么知道是猫还是狗？为什么句子再长，模型也能把前后的词对上号？","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["attention","qkv","multihead","attention-long"],"prereqLessons":["l-embedding"],"nextLesson":"l-transformer","sections":[{"type":"opening","question":"请读这句话：「小狗跑向小猫，因为它害怕小狗。」这个『它』指的到底是小猫还是小狗？只盯着『它』一个词，谁也说不清——那 ChatGPT 是怎么判断出来的呢？","guess":"有人会说「代词当然指前面离得最近的动物」。但中文里『它』常跨好几个词、甚至跨好几句指代，光看位置根本猜不准。","next":"这节课要讲的就是模型的『读心术』——Attention 注意力机制。它让模型在处理『它』时，回头看一眼整句话，自己判断该靠哪些词来理解『它』。"},{"type":"why","before":"上节课我们把每个词变成了向量。但词是孤立的：『猫』『追』『狗』『它』，每一个都只是单独的一串数字。","problem":"真正的语言是互相指代的。『猫追狗，它跑得飞快』——这个『它』是谁？只看『它』这个词本身，根本答不上来。更糟的是：在 Attention 出现以前，老式模型（RNN）看长句时，越靠前的词就越『记不清』。","need":"我们需要一个机制：在处理任何一个词时，能直接『回看』整句话里的所有词，按相关程度加权吸收它们的信息。这就是 Attention——『注意力』，它解决了『远距离指代』和『长句遗忘』两大难题。","visualNote":"下面你可以亲手造一句中文，点任何一个词，看它把注意力分给了谁。"},{"type":"oneline","text":"Attention 是这样一种机制：模型在理解某个词时，会『回头看一眼』句子里的每一个词，给它们分别打一个权重分——分数越高的词，模型花越多注意力在它身上。于是『它』到底指猫还是狗，模型有了办法分清。"},{"type":"visual","kind":"attention-heatmap","title":"Attention 热力图：点一个词，看它关注谁","hint":"输入一句话，点任意一个词（比如那棵/那株），热力图会显示这个词对其它词的『关注权重』——颜色越深，越关注。试试改动量词，体验权重如何跟着语义线索移动。"},{"type":"intuition","blocks":[{"k":"老师点名：每读一个词都在点名","t":"读到『它』这个词时，模型其实在问：『谁能告诉我『它』指谁？』——它把问题抛向所有词，然后重点听『猫』『跑』这些最相关的答案。"},{"k":"查字典：不是顺序读，而是跳着看","t":"Attention 最反直觉的一点：它不老老实实从左往右读。读到『它』，它像翻开一本字典快速扫过所有词条，直接锁定『猫』『跑』，记下『我主要靠这几个词来理解自己』。"},{"k":"聚光灯：每个词都举着无数盏灯","t":"句子里每个词都举着一盏聚光灯照向其它词。灯越亮，代表『我理解你时越依赖你』。Attention 就是计算这盏灯亮度的过程。远近都一样亮——这是它比老方法强的地方。"}]},{"type":"how","intro":"Attention 到底怎么『算』注意力？核心就一句话：每个词同时扮演三个角色——Query（我找谁）、Key（我是谁）、Value（我的内容），然后『找相似、按相似加权吸收』。","steps":[{"in":"乘上三个矩阵，得到 Q / K / V","process":"每个词的向量分别乘以三个不同的矩阵，变成三个新向量：Query『我要去匹配谁』、Key『我是谁，请拿我来匹配』、Value『我的有效内容』。","out":"单词 → (Query, Key, Value) 三件套"},{"in":"用 Query 和所有 Key 算相似度","process":"以『它』的 Query 为例，和句子里每个词的 Key 做点积（就是 Embedding 课学过的『方向越像越接近』）。","out":"得到分数列表：它 vs 猫 = 高分，它 vs 跑 = 中等……"},{"in":"Softmax 归一化成权重","process":"把所有分数经过 softmax，变成『加起来等于 100%』的权重。这一步保证分数变成可比较、可加权的概率。","out":"注意力权重：猫 0.6、跑 0.25、飞快 0.15……"},{"in":"用权重 × Value 加权求和","process":"把每个词的 Value 乘上对应权重再全部相加。权重大的词，内容在结果里占的份量就大。","out":"『它』的新向量 = 主要吸收了『猫』的信息 → 模型知道『它≈猫』"},{"in":"每个词同时做，得到上下文向量","process":"句子里每个词都执行同一套操作，得到一批『结合了全局上下文的新向量』。","out":"整句话从一串孤立向量 → 一串互相理解的向量"},{"in":"多个头并行（多头注意力）","process":"为了不只从一种角度看，模型并行做多组 Q/K/V（不同随机初始化的矩阵），相当于多个不同视角同时观察。","out":"一个头看指代关系、另一个头看语法结构、再一个看长度……组合出更丰富的理解"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude 生成每个词","note":"每生成一个 token，模型都要对上下文做一次 Attention：决定下一个词更依赖前面的哪部分。这是生成的核心动作。"},{"name":"翻译模型的对齐","note":"把『I love you』翻成中文时，Attention 让『love』和『爱』自动对上号，哪怕位置完全错开（这就是 Cross-Attention 用武之地）。"},{"name":"代码补全","note":"补全函数体时，Attention 帮模型盯住几千行前的函数签名和参数定义，而不是只看到最近几行。"},{"name":"长文档问答","note":"在长文章里问『第三部分的结论是？』，Attention 让模型跳过大段无关内容，直接聚焦第三部分的句子。"}]},{"type":"compare","pairs":[{"a":"RNN 顺序处理","b":"Attention 全局直连","diff":"RNN 必须一个字一个字按顺序传，远处信息会衰减；Attention 让任意两个位置直接相连，没有距离衰减。"},{"a":"Self-Attention","b":"Cross-Attention","diff":"Self 是同句话内部互相理解；Cross 是让一方去『读』另一方（翻译、RAG 上下文注入都用它）。"},{"a":"单头注意力","b":"多头注意力","diff":"单头只有一种看法；多头并行多组 Q/K/V，相当于同时用多个角度理解，效果明显更好。"},{"a":"注意力（Attention）","b":"记忆（Memory）","diff":"注意力是每次计算时动态算出的关注权重，不存下来；记忆是存下来的长期信息。很多人把注意力误当成记忆。"}]},{"type":"mistakes","items":["以为 Attention 是『看一遍就记住』的长期记忆。它不是记忆，而是每次计算时动态分配的关注权重——每次都要重新算，不会存下来。","以为注意力可视化等于模型的可解释性。权重高代表统计上相关，不代表模型逻辑上『是因为这个』。","把『注意力』和『上下文窗口』混为一谈。窗口决定能看多远，Attention 决定窗口内怎么分配关注。","以为只看『最近几个词』。Attention 恰恰是全局的——它牺牲计算量，换来的是真正看全上下文。","以为 Attention 零成本。它的核心开销是 O(n²)：n 个词两两算一遍。这正是上下文窗口成为瓶颈的原因。"]},{"type":"deep","title":"深入一点：从直觉到公式","beginner":["注意力权重加起来等于 1（100%）。Softmax 就是把一坨分数变成『加起来为 1、且大的更大』的数。","不必纠结矩阵怎么算，你只需记住一句口诀：『Query 找人，Key 被找，Value 是内容，三者相乘加权求和』。","它最厉害的地方：任意两个词无论隔多远都能直接相关——远处那个词和眼前这个词，算注意力的成本完全一样，这是它战胜 RNN 的根本原因。"],"advanced":["核心公式：Attention(Q, K, V) = softmax( (Q·Kᵀ) / √d ) · V。除以 √d（d 是向量维度）是为了防止点积过大把 softmax 压死、导致梯度消失。","Self-Attention 的 Q/K/V 都来自同一句话，让句子内部互相理解；Cross-Attention 的 Q 来自一方、K/V 来自另一方（如翻译、RAG 上下文注入）。","复杂度 O(n²)：n 个词两两都算一遍。这正是上下文窗口成为瓶颈的原因，也是稀疏注意力、局部注意力、线性注意力研究的动机。","不要神化注意力可视化：权重高 ≠ 模型真『懂』了，它更多是统计相关而非可解释的因果。",{"code":"# 概念示意：手工算一次注意力（极简 2 词版）\nimport math\n\ndef softmax(xs):\n    ex = [math.exp(x) for x in xs]\n    s = sum(ex)\n    return [e / s for e in ex]\n\nq = [1.0, 0.0]  # 我是『它』的 Query\nks = {\"猫\": [0.9, 0.1], \"狗\": [0.2, 0.8]}  # 两个词的 Key\n\nscores = {w: round(q[0]*k[0] + q[1]*k[1], 3) for w, k in ks.items()}\nprint(\"点积分数:\", scores)\nweights = dict(zip(scores, softmax(list(scores.values()))))\nprint(\"softmax 权重:\", {w: round(v,3) for w,v in weights.items()})\n# 猫的权重明显更高 → 模型认为『它』更像猫","lang":"python"}]},{"type":"exercise","prompt":"「它拿起了那支笔，因为【　】太亮了。」这个【　】里的词，会让『太亮了』把更多注意力分给『笔』而不是『它』，你能猜出最合理的一个词吗？","opts":["灯","笔帽","手","桌"],"a":0,"explain":"『灯太亮了』语义合理，Attention 会让『亮』和『灯』形成高权重连接；而『笔帽太亮了』虽然通顺，但更重要是体会：有了『亮』这个线索，Attention 会去找『最配得上的名词』。模型正是靠大量这样的共现线索来分配注意力。","jump":"sec5-step1","jumpLabel":"用 Query 和 Key 算相似度这一步"},{"type":"check","title":"结课检测：你真的理解 Attention 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"Attention 中 Query、Key、Value 各自的作用，最准确的说法是？","opts":["Q 是内容，K 是找人，V 是被找","Q 在找人，K 是被找的标签，V 是被吸收的内容","三者完全相同","Q 是权重，K 是分数，V 是标签"],"a":1,"explain":"Q（Query）发起匹配去『找谁』；K（Key）告诉别人『我是谁』供匹配；V（Value）是被加权吸收进的真正内容。","jump":"sec5-step0","jumpLabel":"乘上三个矩阵得到 Q/K/V 这一步"},{"q":"为什么说 Attention 解决了 RNN『记不住长句』的问题？","opts":["因为它是顺序处理的","因为任意两个词都可以直接相关，不随距离衰减","因为它把句子变短了","因为它只关心最近的词"],"a":1,"explain":"RNN 依赖顺序传递、距离远信息衰减；Attention 让任意两个位置直接相连、远近一视同仁。","jump":"sec8","jumpLabel":"『以为只看最近几个词』那条误区"},{"q":"把注意力分数做 softmax 是为了什么？","opts":["让负数变成正数","让分数变成加和为 1 的权重，且强调大的","让计算更快","让向量变短"],"a":1,"explain":"Softmax 把一坨任意分数变成『加起来为 1』、且大者更大的概率分布，这样加权求和才合理、可解释。","jump":"sec5-step2","jumpLabel":"Softmax 归一化成权重这一步"},{"q":"Self-Attention 与 Cross-Attention 的区别是？","opts":["没有区别","Self 是同句话内部互相理解；Cross 是让一方去读另一方","Self 只用于图片，Cross 只用于文字","Self 更快，Cross 更慢"],"a":1,"explain":"Self-Attention 的 Q/K/V 来自同一句话；Cross-Attention 的 Q 来自一方、K/V 来自另一方（翻译、RAG 都用）。","jump":"sec7","jumpLabel":"对比区里的 Self vs Cross 那一条"},{"q":"多头注意力（Multi-Head）的本质好处是？","opts":["让模型更快","让模型从多个不同视角同时理解，组合出更丰富的语义","让上下文窗口变长一倍","省掉 Softmax"],"a":1,"explain":"把模型注意力想象成多个不同的专家，各看一面（指代、语法、距离），最后合并，理解更全面。","jump":"sec5-step5","jumpLabel":"多个头并行这一步"}],"done":"你已经理解 Attention 是 Transformer 的心脏。这个『找相似、加权吸收』的机制，也是后面 RAG 把检索结果喂进模型时的同一套逻辑。","nextLesson":"l-transformer"},{"type":"connection","known":["词 → 向量（Embedding）","向量方向越像、语义越近（余弦相似度）"],"learned":["每个词同时扮演 Query / Key / Value 三角色","注意力 = 相似度分数 → softmax 权重 → 加权求和","Self-Attention 让句子内部互相理解，多头提供多视角","Attention 任意位置直连、无距离衰减，解决了长句遗忘"],"next":"Attention 是 Transformer 的心脏。下一课我们把这套注意力装进一个完整的架构：位置编码、多头、归一化……看看它怎么组成一个能真正训练、能翻译能写诗的大模型——Transformer。"}]},"l-transformer":{"id":"l-transformer","title":"Transformer｜大模型的地基架构","subtitle":"为什么 2017 年诞生的它，能横扫翻译、写作、代码、对话？一个 20 分钟看懂『大模型的心脏是怎么拼出来的』。","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"25-30 分钟","difficulty":3,"concepts":["transformer","position-enc","multihead","attention"],"prereqLessons":["l-attention"],"nextLesson":"l-rag","sections":[{"type":"opening","question":"上一课我们有了 Attention，它能让任何两个词互相关注。但只用 Attention 还是没法当一个能工作的模型——它不知道『第 5 个词和第 2 个词』谁先谁后，也堆不了很深。猜一猜：研究人员 2017 年到底在 Attention 外面『加了哪些零件』，才把它拼成了横扫一切的 Transformer？","guess":"很多人以为 Transformer = Attention，觉得『注意力』就是全部。","next":"这节课我们把注意力装进完整的大脑：位置编码、多头、残差、归一化、前馈网络、N 层堆叠。学完你就明白，为什么它能取代 RNN、成为所有大模型的共同地基。"},{"type":"why","before":"上一课我们有了 Attention：任何两个词都能直接互相关注。但这只是一块『积木』，离一个能真正工作的模型还差很远。","problem":"只靠 Attention 不够：1) 它不知道词的位置——『猫追狗』和『狗追猫』词全一样；2) 一层注意力学到的东西有限；3) 想堆深又容易训练不动（梯度消失）。","need":"Transformer 就是给 Attention 配上『位置感、深度、稳定训练』三件装备，把一块积木组装成一台可以训练、可以并行、可以堆得极深的机器。它是 ChatGPT、Claude、Gemini 的共同地基。","visualNote":"下面这张图是 Transformer 的主干流水线，你可以一步一步点开看每一层在干什么。"},{"type":"oneline","text":"Transformer 是 2017 年提出的一个『把注意力机制组装成完整大脑』的架构：它用『多头注意力 + 前馈网络 + 残差连接 + 位置编码』堆成一层又一层的模块，能并行、能训练得非常深，从此成为所有现代大语言模型的共同地基。"},{"type":"visual","kind":"transformer-flow","title":"Transformer 主干流水线：一步一步看","hint":"点击【下一步】，观察一个词从数字向量走到预测下一个词的完整过程：输入 → 位置编码 → 多头注意力 → 残差+归一化 → 前馈网络 → 重复堆叠 → 输出。"},{"type":"intuition","blocks":[{"k":"一个加工厂流水线","t":"把 Transformer 想成一家加工厂：原料是一串向量。每个工位（层）做两件事——同事协作（注意力，大家互通信息）+ 个人精加工（前馈网络，每个词独自想更深）。一层做完送下一层，共 N 层。"},{"k":"用乐高积木来想","t":"Attention 只是其中一块积木。Transformer 是说明书：告诉你这一层要怎么拼——注意力 + 残差 + 归一化 + 前馈，然后复制粘贴 N 次。"},{"k":"办公室里的并行会议","t":"RNN 像只有一个话筒的圆桌，每人必须轮流说（慢）；Transformer 像微信群——所有人同时发言、同时收听（并行快），谁跟谁相关自己匹配（注意力）。这就是它又快又强的秘密。"}]},{"type":"how","intro":"一个词在 Transformer 里的完整旅程。每一步都围绕同一批向量做变换，最后模型学会『预测下一个词』。","steps":[{"in":"输入：词向量 + 位置编码","process":"每个词先查表得到 Embedding 向量。但向量本身不含位置，所以再加一个位置信息（位置编码），让模型知道『这是第 5 个词』。","out":"每个词都带上位置的向量"},{"in":"多头注意力层（同事协作）","process":"这一层让每个词结合全局上下文：用上节课的 Q/K/V 机制，多组并行，输出再拼接。词的『含义』从此包含了周围所有词。","out":"每个词变成理解上下文后的新向量"},{"in":"残差连接 + 归一化（稳定训练）","process":"把『进来的向量 + 注意力算完的向量』加在一起（残差），再做归一化。这就像修了一条高速公路：信息不衰减地直接流过深层。","out":"浅层信息能无损抄近道到达深层，网络可以堆得深"},{"in":"前馈网络 FFN（个人精加工）","process":"一个两层全连接网络，对每个词独立做非线性变换，让模型有能力表达更复杂的关系。","out":"每个词被再想一想，表达能力增强"},{"in":"重复堆叠 N 层","process":"把『注意力 + 残差 + 归一化 + 前馈』复制 N 次叠起来（GPT 有十到上百层）。每层都让词的表示更抽象、更接近任务。","out":"深层的向量已经浓缩了整句话的语义"},{"in":"输出：预测下一个词","process":"最后一层接线性层 + softmax，把向量变成词典里每个词的概率，取概率最高的作为下一个词。","out":"生成一个词 → 拼回输入 → 继续预测下一个词"}]},{"type":"realworld","items":[{"name":"ChatGPT / GPT 系列","note":"Decoder-only Transformer：单纯地一层层预测下一个词，就长出了对话和推理能力。"},{"name":"Claude / Gemini","note":"同一架构的不同工程实现：同样的多头注意力 + 深层堆叠，在尺度与训练技巧上各有差异。"},{"name":"翻译与摘要模型（T5/BART）","note":"Encoder-Decoder 结构：编码器读懂全文，解码器再一句句生成译文或摘要。"},{"name":"代码补全（Codex 前身/Copilot）","note":"把代码当另一种语言喂给 Decoder-only Transformer，学会了补全、续写、改 bug。"}]},{"type":"compare","pairs":[{"a":"RNN","b":"Transformer","diff":"RNN 顺序串行、远处信息衰减、难并行；Transformer 全局直连、天然并行、能堆深。2017 后几乎完全取代 RNN。"},{"a":"Encoder-only（BERT）","b":"Decoder-only（GPT）","diff":"前者双向读全文、擅长理解（分类/检索）；后者只能从左往右、擅长生成（对话/写作/代码）。"},{"a":"单层注意力","b":"N 层堆叠的 Transformer","diff":"单层只做一次互相看；Transformer 把多次『互相看 + 精加工』叠起来，让表示一层比一层抽象。"},{"a":"Transformer","b":"Attention","diff":"Attention 是其中的一个子模块；Transformer 是包含注意力在内的一整套完整架构。很多人把两者画等号，其实 Attention ⊆ Transformer。"}]},{"type":"mistakes","items":["以为『Transformer = Attention』。Attention 只是其中一个子模块，完整架构还包括残差、归一化、前馈、位置编码。","以为 BERT 和 GPT 一样。BERT 双向理解、GPT 单向生成，职权完全不同。","以为层数越多一定越好。层越深效果提升有边际，还带来更大算力和训练难度。","把『位置编码』当可选项。没有它，『猫追狗』和『狗追猫』对模型来说完全一样——这可是天壤之别。","以为 ChatGPT 用的是完整 Encoder-Decoder。GPT 只用 Decoder-only，这是它和 T5 这类翻译模型的关键区别。"]},{"type":"deep","title":"深入一点：从直觉到架构细节","beginner":["位置编码就是给每个词加一个『第几个』的记号，否则『猫追狗』和『狗追猫』对模型来说字全一样。","残差连接简单说就是『进来和出去加一起』，像搭桥——让深层的梯度不会消失，模型才能堆数十上百层。","前馈网络 FFN 是给每个词单独换个角度想一遍，和注意力（词与词协作）分工不同、缺一不可。","GPT 其实只用了 Transformer 的一半：只有解码器那套（Decoder-only），用来不停地预测下一个词。"],"advanced":["核心是 Decoder：每个 token 只看自己和前面（因果掩码 causal mask），保证预测时不偷看未来。这是它和编码器的最大区别。","缩放点积注意力：Attention = softmax( (Q·Kᵀ) / √d )·V。除以 √d 防点积过大导致梯度消失 / softmax 饱和。","三种架构：Encoder-only（BERT：理解）、Decoder-only（GPT：生成）、Encoder-Decoder（T5：翻译/转换）。ChatGPT 系清一色 Decoder-only。","残差连接 + LayerNorm（常采用 Pre-LN 顺序：先归一化再进子层）是训练稳定性的关键工程细节，是它能堆到千亿参数的原因之一。","复杂度 O(n²)：上下文窗口越大成本越高——这直接决定了长上下文为什么贵、为什么要引入 RAG。",{"code":"# 概念示意：位置编码的经典公式（体会它想表达什么即可）\nimport math\n\ndef pos_encoding(pos, d_model=8):\n    vec = []\n    for i in range(d_model):\n        angle = pos / (10000 ** (2 * (i // 2) / d_model))\n        vec.append(round(math.sin(angle), 3) if i % 2 == 0 else round(math.cos(angle), 3))\n    return vec\n\nfor p in [0, 1, 2, 3]:\n    print(f\"第{p}个词的位置: {pos_encoding(p)}\")\n# 每个位置生成一组各不相同的位置向量 → 模型据此知道先后顺序","lang":"python"}]},{"type":"exercise","prompt":"如果完全不给模型位置编码，只给它 Attention，那么『猫追狗』和『狗追猫』这两句话，模型会怎么看待？","opts":["认为它们语义完全不同（追的方向相反）","认为它们几乎一样（词完全相同，注意力无差别混合）","认为它们字数不同","完全无法处理两个词以上的句子"],"a":1,"explain":"注意力是把所有词互相加权求和，本质记不得先后顺序。没有位置编码，模型会认为两句话『字都一样所以差不多』，分不清谁追谁。这正是位置编码存在的意义。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"type":"check","title":"结课检测：你真的理解 Transformer 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 Transformer 需要位置编码？","opts":["为了让向量维度变大","因为注意力本身不含位置信息，没有它『狗追猫』和『猫追狗』无法区分","为了加快计算","为了让训练更快收敛"],"a":1,"explain":"注意力把所有词互相加权、天然不记顺序；位置编码把『第几个』注入向量，模型才知道先后。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"q":"残差连接（Residual）的主要作用是？","opts":["增加参数数量","让信息能无损跨层传递，网络可以堆得很深且训练稳定","让模型更快生成","代替位置编码"],"a":1,"explain":"把输入与输出相加，像搭桥一样让信息直达深层，缓解梯度消失，是能堆几十上百层的关键。","jump":"sec5-step2","jumpLabel":"残差连接 + 归一化这一步"},{"q":"GPT 属于哪种结构？","opts":["Encoder-only","Decoder-only","Encoder-Decoder","既不是编码器也不是解码器"],"a":1,"explain":"GPT 只用解码器（带因果掩码、从左往右生成），反复预测下一个词。","jump":"sec9","jumpLabel":"深入节里 GPT=Decoder-only 那条"},{"q":"Attention 和 Transformer 的正确关系是？","opts":["它们是同一个东西","Transformer 是 Attention 的一个零件","Attention 是 Transformer 的一个子系统，Transformer 是完整架构","完全没有关系"],"a":2,"explain":"Attention ⊆ Transformer：Transformer 在 Attention 之外还包含残差、归一化、前馈、位置编码等。","jump":"sec8","jumpLabel":"『以为 Transformer=Attention』那条误区"},{"q":"为什么说 Transformer 比 RNN 快（并行）？","opts":["因为它跳过了很多词","因为它让所有词同时参与计算，不用一个字一个字排队","因为它更短","因为它的层更少"],"a":1,"explain":"RNN 必须按顺序串行处理每个词；Transformer 所有位置并行计算，谁跟谁相关靠注意力自己匹配。","jump":"sec7","jumpLabel":"对比区 RNN vs Transformer"}],"done":"你已经明白大模型的地基长什么样了。但这个『什么都会的模型』只记得训练时的知识——它不知道你公司的最新政策。下一课解决这个问题。","nextLesson":"l-rag"},{"type":"connection","known":["Attention：Q/K/V 加权求和，让词与词互相关注","词是向量，语义可算相似度"],"learned":["Transformer = 多头注意力 + 残差 + 归一化 + 前馈网络的 N 层堆叠","位置编码让模型感知顺序，否则猫追狗 = 狗追猫","GPT 是 Decoder-only，靠预测下一个词长出能力","O(n²) 复杂度是长上下文贵的根源，引出 RAG"],"next":"Transformer 有了，模型『什么都懂但只记得训练时的知识』。下一课我们解决这个关键问题：RAG——怎么让模型在回答前先到你的资料库查资料，从而答出它没学过的私有内容。"}]},"l-rag":{"id":"l-rag","title":"RAG｜让模型『查资料』再回答","subtitle":"为什么 ChatGPT 不知道你的私有文档？怎么让模型『翻开你的资料』再回答？从切块到生成，一条流水线看懂 RAG。","category":"c07-rag","chapterTitle":"第一章 · RAG 全流程","level":"base","estTime":"30-35 分钟","difficulty":2,"concepts":["rag-pain","rag-pipeline","chunking","emb-vector-store","vector-search","rerank"],"prereqLessons":["l-transformer","l-embedding"],"nextLesson":"l-agent","sections":[{"type":"opening","question":"你的同事把公司 80 页的员工手册发给你，让你问 ChatGPT『年假到底有几天』。但 ChatGPT 根本没见过这本手册——你猜它是会照着手册答，还是自己编一个答案？如果它答错了，该怎么办？","guess":"很多人觉得「那就把整本手册贴上问它」。但手册几十万字，靠粘贴根本塞不进一次对话，而且重点会淹没在噪声里。","next":"这节课要讲的就是正解：RAG 检索增强生成。它让模型在回答前，先去你的资料库里『只挑最相关的几段』，再照着这几段回答——既答得准，又附出处。"},{"type":"why","before":"经过前面几课，我们已经有了一个很聪明的模型（Decoder-only Transformer）。但它有一个致命限制：它只知道训练时见过的东西，而且经常一本正经地编造（幻觉）。","problem":"1) 你的合同、内部 SOP、论文——模型训练时根本没看过；2) 即使看过，版本也早就过期了；3) 让它硬答私有问题，它大概率会编。而重新训练整个模型，又贵又慢又不可能频繁做。","need":"与其改模型的『脑子』，不如每次回答时给它配一本『说明书』：先把相关的资料找出来喂给它，让它照着说。这个思路就是 RAG——简单、便宜、资料随时能更新。","visualNote":"下面这条流水线是 RAG 的完整精神：切块 → 向量化 → 检索 → 重排 → 组装 → 生成。你可以点『运行』亲手体验。"},{"type":"oneline","text":"RAG（检索增强生成）就是：让模型在回答之前，先去你的资料库里检索相关内容，把查到的片段拼进上下文，再让模型照着一小份『精选资料』作答。于是它能回答自己没学过的私有知识，还能顺便指出出处。"},{"type":"visual","kind":"rag-pipeline","title":"RAG 完整流水线：从文档到回答（可交互）","hint":"这就是升级版可交互 RAG 实验：左边填一份『你要提问的文档』，下面输问题，点【▶ 运行 RAG】。观察系统如何切块 → 向量化 → 检索 → 重排 → 组装上下文 → 生成带引用的回答。"},{"type":"intuition","blocks":[{"k":"开卷考试 vs 闭卷考试","t":"普通 LLM 是闭卷考试：只凭脑子里的记忆答题，记不住就编。RAG 是开卷考试：允许你翻资料，翻到相关的那页再答。显然开卷更可靠、更可核对。"},{"k":"图书馆查书再回答","t":"你问『公司年假制度是什么』。RAG 不会直接在记忆里编，而是先去公司知识库检索年假相关文档，找到后引用着回答。"},{"k":"不是变聪明，是带了参考书","t":"RAG 不提升模型智商，而是每次回答都带着最新、属于你的资料。资料一更新，回答立刻跟着更新，完全不用重新训练模型。"}]},{"type":"how","intro":"RAG 分两个阶段：『入库』（离线，把文档变成可检索的向量库）和『查询』（在线，用户提问时检索 + 生成）。下面是完整流程，也是本课的主干。","steps":[{"in":"先想清楚：为什么要用 RAG","process":"场景判断：需要回答私有/最新/超长知识，或答案需要可溯源时用 RAG。如果模型自带答案且内容不敏感，也许不需要 RAG。","out":"RAG 解决『知识更新与私有化』，不是『让模型变聪明』"},{"in":"解析 Parsing","process":"把原始文档（PDF、Word、网页）用解析器抽取出结构化文本，去掉页眉页脚、图表残渣，必要时做 OCR。","out":"干净、可用的纯文本"},{"in":"切块 Chunking","process":"把长的文本切成几百到上千字的小块。切多大、是否重叠、按什么切（标题/段落）直接影响检索质量。","out":"文档 → 若干 chunk（带来源、页码等元数据）"},{"in":"向量化 Embedding","process":"用 Embedding 模型把每个 chunk 变成一个向量（语义相近的向量相近）。","out":"每个 chunk → 一个向量"},{"in":"存入向量库 VectorDB","process":"把『向量 + 原文 + 元数据』存进向量数据库（FAISS、Milvus、pgvector、Qdrant），并建好索引以便毫秒级检索。","out":"可快速相似检索的向量库"},{"in":"检索 Retrieval（含 Top-K）","process":"用户提问时，把问题也向量化，在向量库里找最像的『Top-K 块』（通常 K=5~20，按余弦相似度排名）。","out":"问题 → 排好序的 N 个候选 chunk"},{"in":"重排序 Rerank","process":"初筛的 Top-K 往往有噪音。用一个更精细的模型把 K 个候选再精排，把真正相关的提到最前、滤掉无关项。","out":"更精准的少量片段（通常取前 3~5 块）"},{"in":"组装上下文 + 生成","process":"把精选 chunks 拼进 Prompt，附上问题，提示模型『只依据下面资料回答并引用出处』。LLM 据此生成带引用的回答。","out":"有出处、可更新、针对私有知识的回答"}]},{"type":"realworld","items":[{"name":"NotebookLM","note":"你上传 PDF/视频，它检索你的资料再回答，还能生成带引用的播客、摘要。教科书级 RAG 产品。"},{"name":"企业内部知识库客服","note":"把 SOP、产品手册向量化，客服 AI 查文档再回答，而不是对着空气编。"},{"name":"Claude Projects / 附件上传","note":"给对话挂上资料，模型按需检索引用，本质是一套轻量 RAG。"},{"name":"搜索增强的 ChatGPT / Perplexity","note":"它先联网检索实时网页，再基于检索结果回答——用互联网当『向量库』的 RAG。"}]},{"type":"compare","pairs":[{"a":"RAG","b":"微调 Fine-tuning","diff":"RAG 每次查最新资料、可溯源、便宜、可随时更新；微调是改模型脑子、更适合学风格学格式。知识类更新首选 RAG。"},{"a":"向量检索（语义）","b":"关键词检索（BM25）","diff":"向量找语义相近（换个说法也能找到）；关键词精准匹配字面（找人名/编号更稳）。生产常用『混合检索』互补。"},{"a":"RAG","b":"超长上下文","diff":"RAG 主动挑最相关片段、便宜快速；超长上下文把整本书塞进去、贵且重点容易淹没。大资料库优先 RAG。"},{"a":"RAG","b":"Agent","diff":"RAG 是『查资料再回答的单步机制』；Agent 是『多步决策、自己调用工具的循环』。两者常配合：Agent 需要信息时用 RAG。"}]},{"type":"mistakes","items":["以为 RAG = 把文档一股脑塞进提示词。真正的 RAG 要先切块、向量化、检索、重排，只喂最相关的几块。","忽略 chunking 质量。切坏了，再好的模型也答不准——检索进来自的都是垃圾，这叫『垃圾进、垃圾出』。","以为检索到就完了、不必做 rerank。初检的 Top-K 常有噪音，重排能明显提高准确率。","忘记引用溯源。落地到医疗/法务/企业等严肃场景，没有出处等于不可信。","把 RAG 当成解决幻觉的万灵药。资料里没有、或检索失败时，模型照样可能编——还要做『越权拒答』『检索兜底』。","只在单文档上跑 RAG 就上生产。跨多文档局部推理（关系、总分结构）需要更进阶的方案（如 GraphRAG、切分策略优化）。"]},{"type":"deep","title":"深入一点：把 RAG 的每一个零件都拆开","beginner":["chunk 太小 → 语义不完整；chunk 太大 → 噪音多、可能被截断。常见几百~一千字，配合 20%~50% 重叠（overlap）避免把完整语义在边界切断。","向量相似 ≠ 字面相似：换个说法（『年假』vs『带薪假期』）有时也能检索到，这是向量检索比关键词强的地方。","RAG 不会凭空创造知识，它只会引用你给的东西——资料库质量 ≈ 回答质量。","Top-K 的含义：K 是取前几个相似块。K 太小漏信息，K 太大引入噪音挤占上下文，通常 5~20 之间调。"],"advanced":["混合检索（Hybrid）：向量检索（语义）+ 关键词检索（BM25，精确匹配人名/编号）并行，再用加权或 RRF 融合，互补漏检。","Rerank 为什么必要：初检向量健壮但不精，专门的 rerank 模型（cross-encoder）能逐对精判相关性，显著提升准确率和最终回答质量。","引用溯源（Citation / Grounding）：让模型输出带片段编号，用户可核对来源；对合规落地几乎是刚需。","切分进阶：按章节/标题等『结构感知』切块（structure-aware chunking）、父子块（parent-child）、滚动窗口，都比盲目按字数切更好。","评估：用『召回率（该找到的找到没）+ 准确率（找到的是不是都相关）』评价检索，用『忠实度/有据率』评价最终回答，还要做『检索失败与拒答』的兜底。","Agentic RAG：把检索从单次升级成『多轮自主规划』——Agent 先判断需要什么信息、决定检索哪几个库、必要时多轮追问或修正查询词，而不是一次检索定死。",{"code":"# 概念示意：RAG 里最核心的一步——向量检索（伪代码思路）\nimport numpy as np\n\nchunks = [\"年假制度：入职满一年享 5 天…\", \"报销流程：金额低于 1000 走 OA…\"]\nchunk_vecs = [np.array([0.9, 0.1]), np.array([0.1, 0.9])]  # 示意向量\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\nquery_vec = np.array([0.85, 0.15])  # 用户问题『年假有几天』向量化\ntop_k = 1\nranked = sorted(((cosine(query_vec, v), i) for i, v in enumerate(chunk_vecs)),\n                reverse=True)[:top_k]\nprint('最相关的资料块:', chunks[ranked[0][1]])\n# → 年假制度那一段","lang":"python"}]},{"type":"exercise","prompt":"继上一课：公司手册 80 页，你的知识库已经把它切成几百块并存好向量。现在问『年假有几天』，系统检索返回了 8 个候选块，其中第 3 块是『员工福利总览』、第 7 块是『请假制度细则』。下一步系统应该做什么？","opts":["直接把 8 块全部塞进提示词","对 8 块做 Rerank 精排，只取最相关的 3~5 块再喂给模型","不用检索了，直接让模型猜","把 8 块向量相加存回库里"],"a":1,"explain":"初检的 Top-K 常有噪音。正确做法是先 Rerank 精排，把真正相关的『请假制度』提到最前、滤掉无关的『福利总览』，再只喂少量精选块给模型——既省上下文又更准。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"type":"check","title":"结课检测：你真的理解 RAG 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"RAG 解决的核心问题是？","opts":["让模型数学更好","让模型能回答私有/最新知识并可溯源，而不用重新训练","让模型更快生成","让模型学会编程"],"a":1,"explain":"RAG 的核心价值：用检索到的外部资料补充模型没学过的知识，便宜、可更新、可引用。","jump":"sec5-step0","jumpLabel":"先想清楚为什么要用 RAG 这一步"},{"q":"RAG 的『入库』阶段，正确的顺序是？","opts":["向量化 → 切块 → 存库","切块 → 向量化 → 存库","存库 → 向量化 → 切块","检索 → 切块 → 向量化"],"a":1,"explain":"先把长文档切成 chunk，再逐块向量化，最后连向量带原文存进向量库。检索是查询阶段的事。","jump":"sec5-step2","jumpLabel":"切块 Chunking 这一步"},{"q":"『切块太大（比如把整章当一个块）』最可能带来什么问题？","opts":["向量库存不下","块内噪声多、关键信息被淹没，检索和回答变差","一定比小块更准","会让模型忘掉上下文"],"a":1,"explain":"块太大噪声多、语义杂，检索命中后无关内容挤占上下文，回答质量下降。所以要用合适的块大小 + 重叠。","jump":"sec9","jumpLabel":"深入节里关于 chunk 大小/重叠的说明"},{"q":"为什么生产系统里还要做 Rerank 重排？","opts":["为了多花一点算力","初检的 Top-K 常有噪音，用更精细的模型重排能显著提升相关性与准确率","为了把回答变长","为了跳过 Embedding"],"a":1,"explain":"向量初检健壮但不精，专门的 rerank 模型能逐对精判，把真正相关的片段提到最前。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"q":"资料库里根本没有答案时，一个设计良好的 RAG 系统应该？","opts":["强行编一个最像的答案","在引用不到出处时明确『资料中未找到』或拒答，做检索兜底","把用户问题原样丢回","删掉这个问题"],"a":1,"explain":"RAG 不是幻觉万灵药。检索不到可靠出处时应『越权拒答/检索兜底』，而不是硬编。","jump":"sec8","jumpLabel":"『把 RAG 当万灵药』那条误区"}],"done":"你已经掌握 RAG 的完整流水线和调优要点。现在模型会查资料了，但它还是『你问一句、它答一句』。最后一课，我们让它自己动起手来。","nextLesson":"l-agent"},{"type":"connection","known":["Embedding：文字 → 向量，语义相近的向量相近","Transformer：模型的脑子","上下文窗口：模型一次能看多少"],"learned":["RAG 让模型先检索资料再回答，解决私有/最新/可溯源","完整流程：解析 → 切块 → 向量化 → 向量库 → 检索 Top-K → 重排 → 组装 → 生成 + 引用","chunk 大小/重叠、混合检索、Top-K、rerank、评估、Agentic RAG 等调优点","RAG vs 微调 vs 长上下文 vs Agent 的取舍"],"next":"RAG 让模型会查资料，但模型仍停在你说一句、它应一句。下一课是这个旅程的终点也是新起点：Agent——让模型自己拆目标、自己调用工具、根据反馈循环，把一整件事独立做完。"}]},"l-agent":{"id":"l-agent","title":"Agent｜让 AI 自己动手做事","subtitle":"为什么 ChatGPT 只能在对话框里打字，而 Codex 能改你的代码、跑你的测试、提交 PR？Agent 就是把『会说话』的模型，变成『会做事』的执行者。","category":"c08-agent","chapterTitle":"第一章 · 从会说到会做","level":"base","estTime":"25-30 分钟","difficulty":2,"concepts":["agent-intro","agent-loop","tool-use","agent-planning","agent-memory","agent-reflection"],"prereqLessons":["l-rag","l-transformer"],"nextLesson":"l22-ai-coding","sections":[{"type":"opening","question":"你已经能让 ChatGPT 把某个概念讲得头头是道，也能用 RAG 让它查你的资料。但如果你说『去我 GitHub 仓库里把那个测试失败修掉』——为什么 ChatGPT 只能在对话框里给建议，而 Codex 却能真的打开文件、改代码、跑测试、把活干完？","guess":"有人会说「Codex 的模型更聪明」。","next":"这节课揭穿这个误会：Agent 的厉害不在模型智商，而在于给模型装上一个『决策循环 + 一双能动手的工具』。学完你就掌握 Agent = 模型 + 工具 + 循环这条主线。"},{"type":"why","before":"到这一课，我们有了很聪明的模型、也有了让它查资料的 RAG。但你还是有个困扰：让 ChatGPT 整理个表格它倒是能，让它『去我仓库里改掉那个 bug』，它做不到。","problem":"因为聊天模型只有一张嘴：它只能输出文字，看不见你的文件、读不了你的代码、跑不了测试命令。你让它操作仓库，它连仓库在哪都不知道。","need":"Model（思考）+ Tools（手和眼）+ Loop（循环驱动）= Agent。它想一下 → 动一下 → 看一眼结果 → 再想 → 再动。这就是 ChatGPT 和 Codex 的分水岭。","visualNote":"下面这个循环图就是 Agent 的灵魂——你可以亲手点不同工具，看它每一步怎么决策、怎么应对失败。"},{"type":"oneline","text":"Agent（智能体）不是换个更厉害的模型，而是给模型装上一个『决策循环』：它会自己拆目标、自己调用工具（读写文件、执行代码、搜网页）、观察结果、再决定下一步，如此循环直到把事情做完。同样一个模型，套上这个循环，就从『只会回答』变成了『会做事』。"},{"type":"visual","kind":"agent-loop","title":"Agent 循环模拟器：想 → 做 → 看 → 再想（可交互）","hint":"这是一个升级版交互模拟器：你扮演一个修复 bug 的 Codex Agent，在每个步骤从几个工具里选一个。选对了推进，选错了会得到失败反馈，教你『Agent 正是靠不断试错修正才把活干完』。"},{"type":"intuition","blocks":[{"k":"计算器只会算，助理会办事","t":"普通聊天模型像一台高级计算器：你问它答。Agent 像你的助理：你交代一件事，它自己拆步骤、打电话（调工具）、核对结果，办完给你汇报。"},{"k":"不是变聪明，是变『能动』","t":"它没有比 ChatGPT 更聪明——它只是多了一圈『能动手、能看反馈、能再试』的回路。代码还是那个代码，差别在于它学会了执行-反馈-调整。"},{"k":"有钥匙的实习生 vs 没钥匙的实习生","t":"ChatGPT 是没钥匙的实习生：看到门（需要改文件）只会描述『你应该去改那个文件』。Agent 是有钥匙的实习生：自己开门、改文件、跑测试、看结果、再改。"}]},{"type":"how","intro":"一个 Agent 改 bug 的完整工作过程。核心就一句话：目标 → 循环（想 + 做 + 看）→ 交付。这也是本课的骨架。","steps":[{"in":"理解目标","process":"用户下达：『修好注册页面的 bug』。模型先把模糊目标翻译成具体子任务列表。","out":"一个可执行的任务清单"},{"in":"规划 Planning","process":"它推理出步骤：先找到注册页代码 → 读源码定位问题 → 想怎么改 → 改 → 跑测试验证。","out":"Agenda：找代码 → 读 → 改 → 测"},{"in":"调用工具 Tool Use（做）","process":"它请求调用工具：read_file 读代码、edit_file 修改、run_command 跑测试。工具返回结果。","out":"一次具体的『动手』"},{"in":"观察结果 Observe（看）","process":"看到工具返回值：测试报错，或编译失败。它读到反馈，判断是否达到目标。","out":"对『刚才做对没有』的感知"},{"in":"循环 Loop：再想再做","process":"若未达成，回到『想』：根据报错调整方案，再调用工具。如此循环直到测试通过或放弃。","out":"反复的 agent loop（这正是与 ChatGPT 的本质区别）"},{"in":"交付与汇报","process":"任务完成：向用户总结改了什么、测试结果，甚至主动提交 PR、申请权限。","out":"一件完成的事，而不是一段话"}]},{"type":"realworld","items":[{"name":"Codex / Claude Code","note":"Agentic Coding 的典型：能读你的仓库、找 bug、改代码、跑测试、提交 PR。这就是『ChatGPT 做不到、它做得到』的原因——它装了代码工具 + agent loop。"},{"name":"Cursor / Windsurf","note":"IDE 里的 Agent：理解整个项目上下文，跨多个文件完成重构，而不只是一行行补全。"},{"name":"浏览器 Agent（Browser Use / Operator）","note":"自己打开网页、读取、点击、填表，把逛网页办事自动化。"},{"name":"n8n / 工作流编排","note":"让 Agent 串联多个工具/API 完成端到端业务流程（取数 → 处理 → 发通知）。"}]},{"type":"compare","pairs":[{"a":"Chatbot（聊天机器人）","b":"Agent（智能体）","diff":"Chatbot 只输出文字、终结于回答；Agent 拆目标、调工具、看结果、循环迭代，终结于做成事。"},{"a":"单次工具调用","b":"多步 Agent Loop","diff":"会调一个工具的助手只是初级；真正的 Agent 会根据结果决定下一调用，持续多轮直到完成。"},{"a":"RPA（脚本化机器人）","b":"LLM Agent","diff":"RPA 按写死的剧本执行、一变就崩；Agent 动态推理、能处理没见过的异常情况。"},{"a":"Agent","b":"RAG","diff":"Agent 是『多步决策、自己调用工具的循环』；RAG 是『查资料再回答的单步机制』。Agent 需要信息时常用 RAG 当其中一个工具。"}]},{"type":"mistakes","items":["以为 Agent 只是换了个更聪明的模型。本质差别在『循环 + 工具』，不是模型本身。","以为 Agent 能无限可靠地自主执行。它也会反复失败、会犯错，所以需要权限门槛（approval gate）、观测和护栏。","忽视权限与安全。放任 Agent 删文件/发数据/花钱是最危险的坑，生产环境必须加授权与审计。","把会调用工具当成有规划和反思。会调一个函数 ≠ 会拆解复杂目标并自我修正，后者才是 Agent 的进阶。","以为多 Agent 一定更好。多数场景单 Agent 更简单可控，盲目堆 Agent 只会带来编排复杂度和成本。"]},{"type":"deep","title":"深入一点：Agent 的工程骨架","beginner":["Agent Loop 不是魔法：本质就是模型的 for/while 循环——决定下一步 → 调用工具 → 看结果 → 决定再下一步。","工具（Tool）就是一个函数：read_file、write_file、run_command、web_search。模型学会了在合适时机调用它们。","最朴素的 Agent = LLM + 工具集 + 一个决定何时停止的循环。它也可以有记忆和规划，但核心就是这个循环。"],"advanced":["Tool Use / Function Calling：模型输出结构化的『要调用哪个函数、传什么参数』，由系统执行并把结果喂回去，形成闭环。","记忆分两层：短期（当前任务的对话/工具历史）与长期（跨对话的项目知识、偏好，常存向量库）。","Planning 范式：ReAct（Reason + Act 交替）、Plan-and-Execute（先定计划再逐步执行，plan 可被动态修订）、Tree-of-Thought 等。","权限与安全 Permission：Agent 不会无限乱来——危险操作（删文件、花钱、外发数据）要求用户授权（approval gate）。","MCP（Model Context Protocol）：统一工具/数据源接入协议，让一个 Agent 能标准化接入文件系统、数据库、浏览器等多种工具，避免每家写一套私有接口。","Reflection 反思：让 Agent 回顾刚才失败的原因再调整，显著提升长任务可靠性。多 Agent 协作则是多个专业 Agent 分工。",{"code":"# 概念示意：Agent 循环的骨架，就长这样\nwhile not goal_reached:\n    thought = model.think(state, memory)      # 想：我要做哪一步？\n    if thought.should_stop: break              # 判断是否完成\n    tool_result = call_tool(thought.tool_call) # 做：调用工具\n    state.append(tool_result)                  # 看：把结果存进上下文\n    memory.update(state)                       # 记住教训\n# 交付\nreport(model.summarize(state))","lang":"python"}]},{"type":"exercise","prompt":"你（作为 Codex Agent）被要求『修好登录页的 bug』。你读完代码，发现登录按钮点击后有报错。现在到了『做』这一步——猜一猜，Agent 下一步最合理的选择是哪个？","opts":["直接凭记忆改掉一行代码","先运行测试/查看报错日志，定位错误来源，再决定改哪里","马上发邮件问用户想怎么改","直接重新写整个登录页"],"a":1,"explain":"正确动作是先『看』——运行测试或读日志拿到报错信息，有了反馈才知道要改哪。这正是 Agent loop 里『做』与『看』的配合：不观察就动手，等于闭眼改代码。","jump":"sec5-step3","jumpLabel":"观察结果 Observe 这一步"},{"type":"check","title":"结课检测：你真的理解 Agent 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 ChatGPT 不能操作你的仓库，而 Codex 可以？","opts":["因为 Codex 的模型更聪明","因为 Codex 被接上了工具（读写文件/跑命令）+ Agent 循环，ChatGPT 只有对话输出","因为 ChatGPT 没联网","因为模型大小不同"],"a":1,"explain":"决定性差异不是模型智能，而是 Agent 结构：工具让它能动手，循环让它能做→看→修正直到完成。","jump":"sec2","jumpLabel":"一句话理解 Agent 那条"},{"q":"Agent Loop 的核心循环顺序是？","opts":["看 → 做 → 想","想 → 做 → 看 → 再想","只做不看不回头","想 → 想 → 想"],"a":1,"explain":"标准 agent loop：决定下一步（想）→ 调用工具（做）→ 观察结果（看）→ 根据结果再决定下一步（再想），循环到目标达成。","jump":"sec5-step4","jumpLabel":"循环 Loop 这一步"},{"q":"MCP（Model Context Protocol）主要解决什么问题？","opts":["让模型跑得更快","统一 Agent 接入工具/数据源的接口标准，避免各家用私有协议","代替向量数据库","让模型更聪明"],"a":1,"explain":"MCP 是 Agent 与文件、数据库、浏览器等外部工具的标准化接入协议，一次接入、到处复用。","jump":"sec9","jumpLabel":"深入节里 MCP 那条"},{"q":"下面哪个最能代表『Agent 与 Chatbot 的本质区别』？","opts":["Agent 文字更长","Agent 会拆目标、调工具、看反馈并循环，终结于做成事；Chatbot 只回复文字","Agent 不需要模型","Chatbot 也能调用工具"],"a":1,"explain":"Chatbot 止于回答；Agent 以『做成事』为目标，通过循环驱动工具完成多步任务。","jump":"sec7","jumpLabel":"对比区 Chatbot vs Agent"},{"q":"为什么生产环境里 Agent 的危险操作要加『授权门槛（approval gate）』？","opts":["为了拖慢速度","Agent 也会犯错，删文件/花钱/外发数据必须先经用户确认，防止不可逆损失","模型必须要人帮它思考","为了多收费"],"a":1,"explain":"Agent 并非无限可靠，危险动作必须先授权再执行，是落地安全的关键护栏。","jump":"sec8","jumpLabel":"『忽视权限与安全』那条误区"}],"done":"你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。最后一章会带你顺着这条主线进入真正的 AI 编程实践。","nextLesson":"l22-ai-coding"},{"type":"connection","known":["Transformer：模型怎么生成内容","RAG：怎么让模型查资料","工具调用 Function Calling"],"learned":["Agent = 模型 + 工具 + 循环（想→做→看→再想）","它能拆目标、规划、调用工具、观察反馈、反复修正","关键工程点：Tool Use / Memory / Planning / Permission / MCP / Reflection","Chatbot 回答问题，Agent 做成事"],"next":"到这里，你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。想继续深入，建议顺着目标分支走：做产品学 LLM 应用与 RAG，写代码就进入 AI 编程（Agentic Coding / Claude Code）那一章——用 Agent 亲自改代码、跑测试、提交 PR。"}]},"v01-web":{"id":"v01-web","title":"一个 Web 产品是怎么跑起来的","subtitle":"你在浏览器里敲回车到内容出现，中间发生了什么？把这条链路看懂，你才谈得上『改对地方』。","course":"vibe","courseNo":"01","level":"base","estTime":"15-25 分钟","difficulty":1,"concepts":[],"prereqLessons":[],"nextLesson":"v03-api","sections":[{"type":"opening","question":"你每天打开网页、用 App、点外卖、刷视频——但有没有想过，你在浏览器地址栏输入一串字母并按下回车，到底是哪台机器、用哪段程序、按什么顺序，把你要的内容送到你面前的？","guess":"很多人会回答「就是电脑把网站打开了呀」。","next":"这节课我们不写代码，只把『一个 Web 产品』从头到尾拆开：前端、后端、数据库、服务器、浏览器、网络各是什么，数据是怎么一层层流动的，以及每一层出错时你该怀疑谁。学完你就能对着一屏『转圈』或一条报错，说出它大概死在哪个环节。"},{"type":"why","before":"你想用 AI 辅助做一个自己的小产品（一个网页、一个小工具、一个小网站）。AI 很会写代码，但你写完点开经常『跑不起来』或『一片空白』，你不知道该往哪看。","problem":"问题不在 AI 写的代码——而在于你对『这段代码在什么环境里跑、和谁通信』没有概念。你分不清『报错是我的 HTML 写错了』『还是服务器没启动』『还是数据库没连上』『还是网络被墙了』。于是只能把同样的问题反复丢给 AI，越问越乱。","need":"所以第一课先不碰一行代码，而是先建立『一台 Web 产品从上到下有哪些层、每层做什么』的骨架。当你把『前端 / 后端 / 数据库 / 服务器 / 浏览器 / 网络协议』这条链装进脑子，AI 给的报错就不再是天书，而是能对号入座的线索。"},{"type":"oneline","text":"一个 Web 产品 = 浏览器（前端，负责看得见摸得着的界面）+ 服务器上的程序（后端，负责处理逻辑和读写数据）+ 数据库（负责长期存数据），它们之间靠『网络请求』（HTTP）搬来搬去；而这一切最终都跑在『操作系统 + CPU/内存/磁盘』这台物理机器上。"},{"type":"visual","kind":"request-flow","title":"互动实验：点一次请求，看它走完整条路","hint":"点击『发送请求』，看一次『用户敲回车』的动作如何依次经过浏览器 → DNS 解析 → 网络 → 服务器 → 后端程序 → 数据库 → 再原路返回。每亮起一格就说明数据到了哪一层。"},{"type":"intuition","blocks":[{"k":"用点外卖来想","t":"前端＝你看得到的『点单 App 界面』；后端＝『餐厅后厨，负责接单、炒菜、出餐』；数据库＝『冷库里长期保存的食材和菜谱』；服务器＝『餐厅所在的整栋楼，有水电（CPU/内存/磁盘）』；浏览器就是那个帮你点单、再把菜端到你面前的『外卖小哥』。你看到的每一道菜，都是后厨＋冷库＋外卖小哥协作的结果。"},{"k":"用写信来想","t":"你在浏览器输入网址，就像写一封信：『地址』（域名）要翻译成具体的『门牌号 + 邮编』（IP + 端口），信通过『邮政网络』（网络/IP）送出去，邮局先查收信人住在哪（DNS 解析），送到后对方拆信、处理、再回信。回信能不能到，取决于信中地址写没写对。"},{"k":"一句话记住分层","t":"从上到下：浏览器（前端）→ 网络（DNS/IP/HTTP）→ 服务器 → 后端程序 → 数据库。数据请求沿这条链往下，响应再原路往上。出错时按这条链一层层排查，永远不要跳着乱试。"}]},{"type":"how","intro":"把『输入网址到页面出现』拆成一条 7 步因果链。每一步都回答『数据此刻在哪、谁在处理、为什么能做下一步』。","steps":[{"in":"① 你输入网址，按下回车","process":"浏览器得到一串人类好记的名字，比如 ai-learn.example.com。但网络本身不认名字，它只认数字地址（IP：像 203.0.113.7）。所以第一步要『翻译』。","out":"浏览器准备发起一次『网络请求』"},{"in":"② DNS 解析：把域名翻译成 IP","process":"浏览器向 DNS（域名系统）询问：ai-learn.example.com 对应哪个 IP？DNS 就像电话簿，查到后把『数字地址』告诉浏览器。没有这一步，浏览器不知道该把信寄到哪台机器。","out":"得到了服务器的 IP 地址 + 端口（默认 80/443）"},{"in":"③ 建立连接 + 发送 HTTP 请求","process":"浏览器通过 TCP（可靠的传输协议）连上服务器，然后发送一个『HTTP 请求』：里面写着『我要 GET 这个页面』，还带着浏览器自己是谁（User-Agent / Cookie）等信息。","out":"请求沿着网络，送到那台服务器的指定端口"},{"in":"④ 服务器接收并把请求交给后端程序","process":"这台机器上正跑着一个『服务器进程』（如 Nginx / Node / Python）。它把请求转交给对应后端程序；后端程序执行你自己的业务逻辑：查一查、算一算。","out":"后端程序开始处理：可能要读数据库"},{"in":"⑤ 后端读写数据库","process":"需要持久数据的，后端会去数据库查询或写入。数据库把结果（比如『这个用户的名字』）返回给后端。注意：数据库不住在浏览器里，它住在服务器那台机器上。","out":"后端拿到数据，拼出一份『响应』"},{"in":"⑥ 后端返回 HTTP 响应","process":"后端把生成的 HTML / JSON / 图片，打包成一条『HTTP 响应』发回去，附带状态码（200 成功 / 404 找不到 / 500 服务器出错）与响应头。","out":"响应沿着网络原路回到浏览器"},{"in":"⑦ 浏览器解析并渲染","process":"浏览器收到 HTML，逐行解析：先搭出页面结构，再拉取其中的 CSS/JS/图片等资源，最后把内容画到屏幕上。你这才『看到』了页面。","out":"页面出现在你眼前（一次完整的前后端往返）"}]},{"type":"realworld","items":[{"name":"你平时的网页 = 前端静态页","note":"很多『首页』其实只是浏览器直接渲染的一堆 HTML/CSS/JS 文件，可能根本没有后端。它依然需要前面的 ①②③⑦ 几步，但没有 ④⑤⑥。知道这一点，你排查为何『页面能开但功能没反应』时就能猜到问题多半在后端那段。."},{"name":"登录注册 = 必须有后端 + 数据库","note":"『注册新账号』必须把密码/信息写进数据库，所以必然经过完整的 ①→⑦。前端只是收集输入，真正的校验和存储都在后端 + 数据库。这是『看代码时』判断某功能是否需要后端的标尺。"},{"name":"动态内容（推荐、订单、消息）= 后端在返回数据","note":"你刷到的『为你推荐』是后端程序实时查库、算好、再以 JSON 返回给前端渲染的。这类功能换任何界面（网页/App/小程序）后端代码都基本相同——这也是为什么『前后端分离』这么常见。"},{"name":"云服务器 / 租一台机器","note":"你的产品真正上线后，就『住』在一台云服务器（如腾讯云、阿里云的 ECS）上，这台机器有操作系统、CPU、内存、磁盘，常年开机。你的前端文件、后端程序、数据库都装/跑在这上面。"}]},{"type":"compare","pairs":[{"a":"前端 Frontend","b":"后端 Backend","diff":"前端＝用户看到的界面（运行在浏览器/手机里，负责渲染和交互）；后端＝用户看不到、运行在服务器上的程序（负责业务逻辑、鉴权、读写数据库）。前端决定『长什么样、能不能点』，后端决定『数据对不对、安不安全』。"},{"a":"接口 API","b":"直接操作数据库","diff":"后端对外提供的是『接口（API）』——一个约定好的请求地址与返回格式；前端只调用接口，永远不直接连数据库。这样可以隔离权限、便于维护。这也是产品安全的第一道墙。"},{"a":"本地 localhost","b":"线上服务器","diff":"你在自己电脑上跑的前后端叫『本地环境』，地址常是 localhost:3000；部署上线后跑在云服务器上，是公网地址。很多『本地正常、线上挂』的问题，都源于两套环境不完全一样（如数据库没迁移、环境变量没配）。"},{"a":"TCP（可靠）","b":"UDP（快速但不可靠）","diff":"TCP 会确认每份数据都到达（网页、文件用），UDP 不确认、丢了就丢（实时音视频、游戏用）。Web 的 HTTP 默认走 TCP，所以网络差时表现为『加载慢/卡』而不是『内容错乱』。"}]},{"type":"mistakes","items":["以为『网页能打开 = 后端没问题』——错，很多页面是纯前端静态页，后端可能根本没启动。","报错时随手把错误原样丢给 AI，而不说清『发生在哪个层』——AI 只能瞎猜。正确做法是先定位：报错来自浏览器控制台、后端终端、还是数据库连接？","以为『改完代码点刷新就行』——前端改了刷新即可，后端改了常常要重启服务才能生效；数据库结构改了还要迁移。不知道该不该重启，等于不知道该层是否生效。","把 IP、域名、端口混为一谈——域名给人记，IP 给网络认，端口标识这台机器上『哪个程序在服务』。三者不同。","以为 AI 写的代码『放对文件夹就能跑』——代码必须在『正确的环境』（装好依赖、正确版本、正确目录、可执行的权限）里才能运行。环境对不上，代码再对也是白搭（这正是第 7 课上线的核心矛盾）。"]},{"type":"deep","title":"深入一点：把『机器、程序、运行方式』讲透","beginner":["这台电脑/服务器里面有什么？三样最关键的硬件：","**CPU**（中央处理器）：真正会『算』的部分，负责执行指令。它快、但几乎没有记忆。","**内存 RAM**：临时、高速的『草稿本』，程序运行时把正在用的东西放这里；一断电全清空。","**磁盘 Disk**：长期、慢速的『仓库』，文件、数据库、图片都躺在这；断电也保留。","三者关系：程序从『磁盘』读进来 → 在『内存』里运行 → 由『CPU』逐条执行。所以『进程/线程』就是运行中的程序在内存和 CPU 上的具体存在。","**操作系统（OS）**：介于硬件和你程序之间的大管家。它负责：管理文件、管理进程、分配内存、读写磁盘、管理网络与权限。你的程序不是直接拿 CPU 干活，而是『请操作系统帮你安排』。Windows / macOS / Linux 都是操作系统。"],"advanced":["**编译 (Compile) vs 解释 (Interpret)**：代码有两种变可执行的方式。编译型（如 C、Go）：先整体翻译成机器码，再运行，快但改后要重新编译；解释型（如 Python、JavaScript）：一边翻译一边运行，改了就生效，但慢。","**Runtime（运行时）**：指『解释器 / 虚拟机 / 平台环境』，如 Node.js（能让 JS 在服务器上跑）、Python 解释器、Java 虚拟机（JVM）、浏览器的 JS 引擎（V8）。同一个 JS 文件，在浏览器里和 Node 里跑，用的是不同 Runtime——所以『它在浏览器能跑，不代表服务器能跑』。","**进程 (Process) vs 线程 (Thread)**：进程＝一个独立运行的程序实例，有自己独立的内存（跑崩一个不影响别的）；线程＝进程内部可并发的轻量任务单元，共享进程内存。一个 Node 服务通常是一个进程，一次请求常会用到多个线程/异步任务来并行处理。","**文件 / 路径 / 权限**：一切配置、代码、静态资源都是『文件』，文件有『路径』（在哪个文件夹）和『权限』（谁能读/写/执行）。很多部署报错是『权限不够』（403）或『路径不对』（404）——这不是代码逻辑问题，而是环境问题。","**环境 (Environment)**：你的程序依赖很多东西：命令、依赖包、环境变量、数据库地址、端口。这些合称『运行环境』。第 7 课上线的本质，就是把『你本机那套环境』尽量一致地搬到服务器上。"]},{"type":"ask","title":"怎么用 AI 帮你改代码：先问清『第几层』","scenario":"你的页面打开了，但点击『登录』没反应，控制台报了个错。怎么把这个信息高效地交给 AI？","template":"[我要描述] 我在做一个登录功能，点击登录按钮后页面没反应。\n[它能观测到的现象] 浏览器控制台报错：Cannot read properties of undefined (reading 'catch')，出错在 main.js 第 42 行。\n[我判断在哪一层] 前端 JS 在做请求时出错（尚未到后端）。\n[请给我] 帮我定位 main.js 第 42 行为什么报错，并给出修复方案与原因。","acceptance":["AI 给的答案里是否指明了『问题所在的那一层』（前端/后端/数据库/网络/环境）？","修复方案是否同时告诉你『为什么之前会错』（因果），而不只是『把这段换成这段』？","改完是否教你该怎么验证（例如：刷新？重启后端？看哪个日志？）？","如果 AI 只给了代码而你仍不确定，是否会继续追问『这个报错出现在哪一层、我怎么验证』？"],"tip":"给 AI 的信息越『分好层』，它越能准确判断。‘分层 + 现象 + 报错 + 我的判断’ 四件套，能大幅减少来回试错。"},{"type":"exercise","prompt":"你在浏览器打开自己刚做的网站，页面显示出来了，但点『提交表单』后页面一点反应都没有，浏览器控制台也没报错。根据这一课的分层，你最应该先怀疑哪一层？","opts":["我的 HTML 结构写错了（前端静态层）","后端程序没启动或没连上（后端层）","我的屏幕/显卡坏了（硬件层）","域名没过期（网络层）"],"a":1,"explain":"页面能正常显示说明前端静态层基本没问题；但『提交表单』要发请求给后端，没反应最可能是后端没启动、路径不对、或请求根本没发出去。先检查后端服务在不在跑、接口地址对不对。","jump":"sec7-step3","jumpLabel":"第 ④ 步：服务器接收并把请求交给后端"},{"type":"check","title":"结课检测：你能给报错『分层』了吗","intro":"共 5 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"浏览器里 DNS 解析这一步骤主要解决什么问题？","opts":["把域名翻译成 IP 地址","把 HTML 渲染成画面","把代码编译成机器码","把密码加密"],"a":0,"explain":"网络只认数字 IP，DNS 负责把人类好记的域名翻译成 IP，浏览器才知道该把请求发到哪台机器。","jump":"sec5-step1"},{"q":"『注册新账号后数据能永久保存』，这件事主要由哪几层协作完成？","opts":["只有浏览器（前端）","后端程序 + 数据库，前端只负责收集输入","只有网络（TCP/IP）","只有操作系统"],"a":1,"explain":"注册必须把信息写入数据库才叫『永久保存』；后端程序负责接收并由数据库落盘，前端只是收集输入。","jump":"sec5-step4"},{"q":"『代码在浏览器能跑』是否代表『同样的代码在服务器上也能跑』？","opts":["一定可以","不一定，因为浏览器和 Node/Python 是不同的 Runtime","一定不可以","只和网速有关"],"a":1,"explain":"浏览器里的 JS 由浏览器 JS 引擎跑，服务器上的 JS 由 Node.js 跑，是不同的 Runtime，能力与可用模块不同。","jump":"sec7"},{"q":"一个『Web 产品』由前端、后端、数据库组成。下面哪句最准确？","opts":["前端能直接连接数据库","后端程序通过接口把数据给前端，数据库由后端访问","数据库必须放在浏览器里","后端程序只能写死数据，不能读数据库"],"a":1,"explain":"前端只调用后端提供的接口(API)，后端负责访问数据库并返回结果，这样能隔离权限、便于维护。","jump":"sec7-step5"},{"q":"某功能『本地 localhost 一切正常，部署到线上就报数据库连不上』，最可能是哪两类环境不一致？","opts":["前端字体大小不同","数据库地址/密码/环境变量，以及迁移状态不一致","屏幕分辨率不同","键盘语言不同"],"a":1,"explain":"本地与线上最多的差距是数据库连接信息（地址、账号、密码）、环境变量配置，以及数据库结构是否已迁移。","jump":"sec7"}],"done":"你现在能把『一个 Web 产品』按层拆开了——前端、后端、数据库、服务器、网络各归其位，报错也能分到对应层。下一课我们钻到『后端』这一层：HTTP 到底是什么，API 怎么写、怎么调。","nextLesson":"v03-api"},{"type":"connection","known":["（这是 Vibe Coding 路径的第一课，默认你已经上过《从零看懂 AI》路径或至少了解『模型/产品』概念。）"],"learned":["一个 Web 产品 = 前端 + 后端 + 数据库 + 服务器 + 网络，彼此通过 HTTP 通信","一次请求的 7 步因果链：输入地址 → DNS → 建立连接/HTTP → 服务器 → 后端 → 数据库 → 渲染返回","CPU / 内存 / 磁盘 / 操作系统 / 进程 / 线程 / 编译解释 / Runtime 的定位","前端 / 后端 / 接口 API / 本地 localhost / 线上 的区别","给 AI 提问前先给报错『分层』，能显著提高一次成功率"],"next":"下一步我们进入『后端』层。想了解 AI 生成/理解代码，可回看 AI 路径的《AI Coding》一课；想把这条链路里『数据是怎么被长期记住的』讲透，下一课（API 与后端）与再下一课（数据库、登录与安全）会分别展开。","links":[{"href":"#/lesson/l22-ai-coding","text":"回看 AI 路径《AI Coding：把 AI 变成结对程序员》"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},"v03-api":{"id":"v03-api","title":"API 与后端：前后端怎么『对话』","subtitle":"前端要数据、后端给数据，靠的是一套约定好的『暗号』——HTTP 方法与状态码。看懂它对 AI 来说轻而易举，对你是判断代码靠不靠谱的分水岭。","course":"vibe","courseNo":"03","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web"],"nextLesson":"v04-db","sections":[{"type":"opening","question":"你的 App 在前端里点了个『收藏』按钮，后端怎么知道你要『新增一条收藏』而不是『删除一条』？同样是敲同一个接口地址，凭什么这次是加分、那次是删东西？","guess":"很多人会说『靠传一个名字不一样的按钮』。","next":"答案藏在 HTTP 的『方法（Method）』里。这一课我们把前后端之间的对话协议——HTTP 方法和状态码——彻底讲透：GET 和 POST 到底差在哪，200/404/500 各代表什么，什么是 API、什么是 JSON。学完你会开始『读』接口而不是『猜』接口。"},{"type":"why","before":"AI 写了个后端接口，前端也调了。你看着代码：有一堆 `app.get('/api/friends')`、`app.post('/api/friends')`、`req.body`、`res.json(...)`。你不懂为什么有的用 get 有的用 post，也不知道返回的 `{status:'ok', data:[...]}` 是什么。","problem":"不懂 HTTP 方法与状态码，你会犯两种错：要么把『该用 POST 写数据的操作』写成了 GET，导致数据带在 URL 里、既不安全又不支持大内容；要么拿到报错号 404/500 完全没概念，不知道该看前端还是后端。AI 生成的代码你再不敢动，一改就崩。","need":"把 HTTP 的『动词』（方法）、『回执』（状态码）、『货单』（请求/响应头与正文 JSON）看明白，你就拥有了『判断一段接口代码对不对』的最小能力：方法对不对、状态码合不合理、参数传没传对。这正是把 AI 代码从『能跑』升级到『可靠』的一步。"},{"type":"oneline","text":"API 是后端对外开的一扇扇门（URL），你用『HTTP 方法』说明你想干嘛（GET 拿数据 / POST 新增 / PUT 整体更新 / PATCH 部分更新 / DELETE 删除），后端用『状态码』告诉你结果（2xx 成功 / 4xx 你这边的问题 / 5xx 服务器的问题），数据通常以 JSON 格式在请求和响应里传递。"},{"type":"visual","kind":"http-viewer","title":"互动实验：HTTP 查看器，亲手发一个请求","hint":"选一个方法、填一个地址（或点预设接口），点『发送』。它会向你展示：这次请求带了哪些方法/头部/参数，服务器会返回什么状态码与 JSON 正文，以及每个状态码对应的含义。体会『同一个 URL，方法不同 = 动作不同』。"},{"type":"intuition","blocks":[{"k":"用餐厅点菜来想","t":"API 地址（URL）＝餐厅的『窗口名』，比如『/api/friends』是『朋友窗口』；HTTP 方法＝你点菜的动作——‘看看今天的菜单’（GET）、‘点一个菜’（POST）、‘把整个菜换掉’（PUT）、‘加个辣’（PATCH）、‘退掉这个菜’（DELETE）。后端（厨师）按你的动作处理，再用状态码告诉你：‘上菜了’（200）、‘这个菜没有’（404）、‘厨房炸了’（500）。"},{"k":"用寄快递来想","t":"GET 就像‘查单号’——只读，不改变任何东西，可以来很多次；POST 就像‘下单寄件’——会产生一个新的快递（新增数据）。所以‘收藏、下单、注册、发帖’这些会新增数据的操作用 POST，而‘翻页、搜索’这种只看不动的用 GET。"},{"k":"一句话记住状态码","t":"2 开头的都成功；3 开头的是‘让你去别处看’（重定向）；4 开头的是‘你（客户端）的问题’（404 找不到、401 没登录、403 没权限、400 请求写错）；5 开头的是‘服务器（后端）的问题’（500 内部出错）。看到 4 或 5，你就能立刻判断该检查哪一边。"}]},{"type":"how","intro":"把一个 HTTP 请求拆成 5 个部分，从头到尾走一遍『前端 → 后端 → 响应回前端』。","steps":[{"in":"① 请求行：方法 + URL","process":"前端发起一行字：`POST /api/friends`。前半是方法（动作），后半是接口地址（去哪扇门）。这决定了后端接下来执行哪段逻辑。","out":"例如 POST = 新增；GET = 查询；DELETE = 删除"},{"in":"② 请求头 Headers","process":"附带的一堆元信息：Content-Type（正文是 JSON 还是表单）、Authorization（登录凭证，如 Bearer token）、Accept（你想要什么格式）、携带的 Cookie 等。后端靠这些判断『你是谁、你给的是什么』。","out":"身份与格式声明"},{"in":"③ 请求正文 Body","process":"POST / PUT 需要把要写入的数据放进正文，通常是 JSON：`{\"name\":\"小明\",\"phone\":\"138...\"}`。GET 一般没有正文，参数放在 URL 查询串里（?name=小明）。","out":"数据内容（多为 JSON）"},{"in":"④ 后端处理并返回状态码","process":"后端读到方法+地址+头+正文，跑对应的逻辑，无论成败都返回一个状态码：成功 200/201，找不到 404，参数错 400，没登录 401，服务器异常 500。","out":"状态码：2xx / 4xx / 5xx"},{"in":"⑤ 响应正文 + 响应头","process":"成功后后端通常返回一个 JSON：`{\"ok\":true,\"data\":{...}}`，前端拿到这个结构再决定如何渲染。响应头里也常有 Set-Cookie、Cache-Control 等控制信息。","out":"前端拿到 JSON，渲染到界面"}]},{"type":"realworld","items":[{"name":"浏览器开发者工具 Network 面板","note":"按 F12 → Network，你能亲眼看到每一笔请求：方法、URL、状态码、耗时、请求/响应头与 JSON。这是『读接口』最重要的工具，AI 给不了你，但它能解释你从里面截到的任何一行。"},{"name":"REST 设计风格","note":"REST 是一套流行的接口组织约定：把『资源』当名词放 URL（/users、/posts），把动作当方法（GET/POST/PUT/DELETE）。例如 GET /users/5 读用户5，DELETE /users/5 删用户5。看懂 REST，你便看懂了大半后端代码的结构。"},{"name":"第三方开放 API（天气/支付/地图）","note":"你在产品里调的天气、支付、地图接口，就是对面公司后端暴露的 API。你会看到它要求固定方法、固定鉴权头（Authorization/ApiKey）、返回固定 JSON 结构。会读 API 文档 = 会接第三方能力。"},{"name":"前后端分离项目","note":"很多现代项目前端与后端是两个独立工程，只通过一组 API 契约对接。只要接口约定不变，前端可以换成任何形态（网页/App/小程序），后端完全不用改。这也解释了为什么『接口规范』如此重要。"}]},{"type":"compare","pairs":[{"a":"GET","b":"POST","diff":"GET 用于『读』数据：参数放 URL，可分享/可缓存，不应产生副作用（不会改服务器的数据）；POST 用于『写』数据：参数放正文，用于新增/提交，会产生副作用。安全与不大数据量的操作用 GET，会改数据的操作用 POST。"},{"a":"状态码 4xx","b":"状态码 5xx","diff":"4xx 是『客户端问题』：请求写错、没登录（401）、没权限（403）、找不到（404）——请检查你前端发出去的请求；5xx 是『服务器问题』：后端代码异常（500）、超时（504）——请检查后端日志。"},{"a":"REST API","b":"GraphQL","diff":"REST 靠『多个端点 URL + 方法』组织接口；GraphQL 靠『一个端点 + 查询语句』按需取字段。REST 更简单通用、生态大；GraphQL 更灵活但要学查询语法。入门从 REST 开始最稳。"},{"a":"JSON","b":"表单 Form-encoded","diff":"JSON 是一种结构化文本（{\"k\":v}），后端好解析、支持嵌套，是现代 API 主流；传统表单格式（a=1&b=2）较简单但在复杂数据前吃力。看到 Content-Type: application/json 就知道后面是 JSON。"}]},{"type":"mistakes","items":["AI 常犯（也常让你中招）的错误案例①：把『该用 POST 的新增操作』写成了 GET，导致密码等敏感数据出现在 URL / 日志里，既不安全又不支持大内容。","错误案例②：删改操作应返回合适状态码，却一律返回 200——前端永远‘成功’，数据却没被真正删掉。看到代码里所有分支都 res.json({ok:true}) 且不看状态码，就要警惕。","错误案例③：前端没把 token/Cookie 带上（没设置 headers.Authorization），导致后端每次回 401；前端却把锅甩给‘后端 bug’。判断法：看 Network 里那次请求的请求头带没带凭证。","把 404 理解成‘页面不见了’就完事——404 也可能是‘接口地址写错’，要不检查前端 URL，要不检查后端路由。/api/users 与 /api/user 差一个字母就是两个世界。","盲目照抄 AI 生成的接口而不看返回结构：前端拿 res.data.data 却和接口对不上，出来全是 undefined。学会看 Network 里真实的 JSON 结构再写渲染。"]},{"type":"deep","title":"深入一点：怎么判读一段 AI 写的接口代码","beginner":["拿到 AI 写的后端接口，按下面三问逐一看，就能快速判断靠不靠谱：","**一问方法**：这个操作该不该用这个 HTTP 方法？读操作用 GET，写操作用 POST/PUT/DELETE。方法不对 = 语义错。","**二问状态码**：成功路径返回 2xx 吗？参数错返回 400 吗？没登录返回 401 吗？没有的数据返回 404 吗？服务器异常会抛 500 吗？一个只返回 200 的接口是不合格的。","**三问数据流**：后端取参数的字段名，和前端传的字段名一致吗（body.name）？返回的 JSON 结构和前端 res.data.xxx 对得上吗？对不上就是坑。"],"advanced":["**express（Node 后端框架最小示例）**：","```js\napp.get('/api/users/:id', async (req, res) => {\n  const user = await db.one('SELECT * FROM users WHERE id=$1', [req.params.id]);\n  res.status(200).json({ ok: true, data: user });\n});\n```","注意三件事：`:id` 是路径参数（req.params.id）；操作是读 → 用 GET；成功返回 200。若查不到应 `return res.status(404).json({ok:false})`，而不是硬返回 200 空对象。","**错误处理缺失是最大隐患**：AI 常写出‘只管成功不管失败’的接口。可靠接口要捕获异常并返回 5xx：","```js\napp.post('/api/users', async (req, res) => {\n  try { await db.insert('users', req.body); res.status(201).json({ok:true}); }\n  catch (e) { console.error(e); res.status(500).json({ok:false, msg:'写入失败'}); }\n});\n```","**‘如何向 AI 验收一个接口’**：让 AI 给出‘该方法、正常/异常状态码、请求/响应 JSON 示例’三件套；你再对照 方法→语义 是否正确。能给出完整三件套的接口定义，才值得写进产品。"]},{"type":"ask","title":"怎么用 AI 帮你写/改一个接口","scenario":"你让 AI 写一个‘新增好友’的后端接口，并希望它可靠、前后端好对接。","template":"[我要做一个] POST /api/friends 的新增好友接口。\n[我希望的入参] JSON：{ nickname, remark }。\n[我希望的结果] 成功后返回 201 + {ok,data};昵称为空返回 400;后端异常返回 500。\n[请给我] 完整的 Node/Express 代码（含错误处理），并附：请求示例 JSON、成功/失败状态码与返回体、以及前端如何 fetch 调用的示例。","acceptance":["接口是否用对了 HTTP 方法（新增→POST）？","是否覆盖了成功(201)、参数错(400)、服务器错(500) 至少三类状态码？","请求与响应 JSON 结构是否给出、且前后端字段名一致？","是否包含 try/catch 错误处理而不是只管成功？用浏览器 Network 面板实测一下接口是否按文档返回。"],"tip":"把‘我要什么入参 + 我要什么结果 + 我要什么状态码’写成模板，AI 生成的接口会立刻规范很多；再用 Network 面板实测验证，别只看它嘴上说‘OK’。"},{"type":"exercise","prompt":"你在前端写了一个请求，点按钮后 Network 面板显示某请求返回 401。你最应该先检查什么？","opts":["后端 SQL 写错了","前端这次请求有没有带上登录凭证（Authorization/Cookie）","服务器机器坏了","网络 DNS 解析失败"],"a":1,"explain":"401 = 未认证/未登录，最常见原因就是请求没带凭证。去看 Network 里这一次请求的请求头，确认是否带了 token 或 Cookie。","jump":"sec5-step1","jumpLabel":"第 ② 步：请求头 Headers"},{"type":"check","title":"结课检测：你会读 API 了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"‘把一条收藏记录保存起来’应该用哪个 HTTP 方法？","opts":["GET","POST","PUT","DELETE"],"a":1,"explain":"产生新数据的写操作应该用 POST；GET 只用于读，不该产生副作用。","jump":"sec5-step0"},{"q":"状态码 401 表示什么？","opts":["找不到页面","未认证/未登录","服务器内部错误","请求太大"],"a":1,"explain":"401 Unauthorized = 未认证，需要登录凭证；403 才是‘已登录但没权限’。","jump":"sec5-step4"},{"q":"看到返回 500，你优先怀疑哪一层？","opts":["前端渲染","浏览器缓存","后端程序异常","CSS 样式"],"a":2,"explain":"500 = Internal Server Error，是服务器（后端）处理出错，去查后端日志与代码。","jump":"sec5-step4"},{"q":"REST 接口中，URL 里的名词代表什么？","opts":["动作（增删改查）","资源（如 /users、/posts）","设计者名字","数据库类型"],"a":1,"explain":"REST 把资源当名词放 URL，动作由 HTTP 方法表达。GET /users/5 是‘读用户5’。","jump":"sec6"},{"q":"前端请求里，登录凭证通常放在哪个位置？","opts":["URL 查询串","请求头 Headers（如 Authorization）","CSS 文件","浏览器书签"],"a":1,"explain":"凭证（token/Cookie）一般放在请求头里，如 Authorization: Bearer xxx；不放会导致 401。","jump":"sec5-step1"}],"done":"你已经能读懂前后端之间的‘暗号’了：方法定动作、状态码定结果、JSON 传数据。下一课我们把线的另一头——数据本身——讲清楚：数据库怎么设计，登录与安全怎么做。","nextLesson":"v04-db"},{"type":"connection","known":["你已经知道一个 Web 产品 = 前端 + 后端 + 数据库，通过 HTTP 通信（上一课）。","你已经会调用模型/看得懂 AI 相关 API 的基础概念（AI 路径）。"],"learned":["HTTP 方法：GET 读 / POST 写 / PUT 整体更新 / PATCH 局部更新 / DELETE 删除","状态码：2xx 成功 / 4xx 客户端问题 / 5xx 服务器问题","请求 = 方法 + URL + 头 + 正文(JSON)；响应 = 状态码 + JSON","REST 设计：名词当资源，方法当动作","给 AI 描述接口需求时，用‘入参+结果+状态码’三件套模板"],"next":"接口是承上启下的：它把‘数据’从后端递给前端。可数据从哪来、怎么存、怎么保证安全？这正是下一课《数据库、登录与安全》要解决的。和 AI 路径的联系：你调用大模型 API 的本质也是‘前端→HTTP→别人家后端的接口’，底层逻辑完全相同。","links":[{"href":"#/lesson/l16-llm-api","text":"回看 AI 路径《用 API 把模型接进你的产品》(规划中)"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},"v04-db":{"id":"v04-db","title":"数据库、登录与安全","subtitle":"数据是产品的命，登录是产品的门。这一课把‘数据怎么存’、‘你怎么证明是你’、‘怎么防坏人’讲透。","course":"vibe","courseNo":"04","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api"],"nextLesson":"v07-deploy","sections":[{"type":"opening","question":"用户注册了账号、收藏了文章、下了单——这些数据如果不做任何抽象地乱放在一起，会出什么问题？‘收藏’和‘用户’之间到底是什么关系？而你按下‘登录’，服务器凭什么相信你就是那个人，而不是冒充的？","guess":"很多人觉得‘数据随便存个文件不就行了，登录就是在数据库里对一下密码’。","next":"这一课回答三件事：①数据用‘关系表’组织才不乱（表、列、主键、外键、索引、SQL）；②‘登录’不是查一下密码那么简单——Session、JWT、OAuth 各是怎么证明‘你是谁’的；③坏人会怎么攻击（SQL 注入、XSS），以及怎么守住（参数化、转义、加密/哈希、最小权限）。"},{"type":"why","before":"AI 帮你生成登录/注册/收藏/下单功能，里面全是你不认识的词：SQL、primary key、foreign key、index、session、token、bcrypt、JWT、OAuth、SQL 注入。你照抄能跑，但出问题时完全无法判断是‘表没建对’‘还是登录逻辑错’‘还是被人攻击了’。","problem":"数据库设计与安全是‘你几乎不会让 AI 自己随便发挥’的地方——因为数据是用户资产、登录是安全边界。如果不懂“为什么用户表要 id 做主键”“为什么密码要哈希不能存明文”“为什么 SQL 要参数化防止注入”，你根本没法验收 AI 的代码，等于把产品最关键的部分交出去赌运气，早晚出事。","need":"这一课把最少必备的数据库设计与安全知识补上：会看表结构、会写最基础的 SQL、能对比 Session / JWT / OAuth、知道 SQL 注入和 XSS 是什么并知道对应防御。这样当 AI 给出表结构和登录代码，你能像审稿人一样快速挑出明显错误。"},{"type":"oneline","text":"产品数据大多存在关系型数据库（如 PostgreSQL/MySQL）：数据按‘表’组织，每行一条记录，靠‘主键’唯一标识，表与表用‘外键’建立关系，用 SQL 增删改查；登录靠加密凭证证明身份（Session 服务端记、JWT 它自己证明、OAuth 让第三方背书）；安全的核心三件事——密码要哈希不要明文、SQL 用参数化防注入、输出要转义防 XSS。"},{"type":"visual","kind":"db-designer","title":"互动实验：设计一张数据库表","hint":"这是一个迷你‘表设计器’：你决定表有哪些列、哪列是主键、要不要加索引、要不要存密码明文。点击‘预览 SQL / 检查问题’，它会告诉你这张表会不会踩主键、密码明文、可空、无索引等常见坑。体会‘多花一分钟设计，省无数 bug’。"},{"type":"intuition","blocks":[{"k":"用班级花名册来想","t":"数据库里的‘表’就像一张花名册：‘列’是表头（学号、姓名、班级），‘行’是一条记录（某个同学）。‘主键（primary key）’＝学号——全班唯一，靠它能精准找到某个人；‘外键（foreign key）’＝‘本班编号’——它指向另一张‘班级表’的主键，从而把两张表关联起来。没有主键，你用‘姓名’找人会遇到重名；没有外键，班级和学生就接不上。"},{"k":"用门禁卡来想登录","t":"Session＝你在前台刷了一次脸后，前台给你一把只在这栋楼有效的临时钥匙，钥匙上是你进门时发的一个号码（sessionId），门卫每次核对后台名单；JWT＝一把自带信息的加密卡片，上面写着‘我是小明，3 小时后过期’，门卫验签名就放行，不用每次查后台；OAuth＝你出示‘微信已认证’的凭证，门卫信微信的背书就让你进。三种都是‘证明你是你’，只是证明的方式和存放地点不同。"},{"k":"一句话记住安全","t":"密码只存哈希（加盐），不存明文；SQL 永远用参数化（?/$1 占位符），别拼字符串；输出到页面要转义（防 XSS）；后端始终校验，前端校验只是体验。记住这四条，你能挡住绝大多数入门级攻击。"}]},{"type":"visual","kind":"auth-compare","title":"互动实验：Session / JWT / OAuth 三种登录横评","hint":"点击三种登录方式，看同一个‘登录→鉴权→访问’场景在后台是怎么不同的：状态存在哪、怎么验证、有没有跨端问题、优缺点一目了然。帮你给产品选对登录方案。"},{"type":"how","intro":"把‘数据入库 + 登录鉴权’拆成两条因果链：先看一张表从设计到查询怎么走，再看一次登录如何完成。","steps":[{"in":"① 设计表结构（Schema）","process":"确定这张表存什么：用户表要有 id（主键）、username、password_hash、created_at。列的类型要选对（数字用 integer、文本用 varchar）。先想好‘要回答什么问题’，再定表，否则后面改结构（迁移）很麻烦。","out":"一张结构清晰的表 + 主键"},{"in":"② 建表 + 加索引","process":"用 SQL 建表；对‘经常按它来查’的列（如 username）加上索引（index），否则数据多了每次都全表扫描、慢到卡死。索引=书的目录，能加速查找。","out":"表建好，查询有索引加持"},{"in":"③ 用 SQL 增删改查","process":"INSERT 插入、SELECT 查询、UPDATE 更新、DELETE 删除。查询可加 WHERE 过滤、JOIN 关联别表。这是后端操作数据库的日常。","out":"数据被正确写入/读出"},{"in":"④ 表和表用外键建立关系","process":"比如‘收藏表’里放一个 user_id 外键指向用户表、一个 article_id 指向文章表，就能表达‘这个用户收藏了那篇文章’的关系。","out":"数据之间有明确关联，不重复、不乱"},{"in":"⑤ 登录：验证 + 发凭证","process":"用户输入密码 → 后端把输入的密码加盐哈希，和库里存的那个哈希比对 → 相同则信任，创建会话凭证（Session 存服务端 / JWT 返回一个 token / OAuth 走第三方）。","out":"前端拿到凭证，后续请求都带上它"},{"in":"⑥ 访问控制：每步鉴权","process":"后续每个需要身份的请求，后端都校验凭证 → 合法才放行，非法返回 401。同时用权限逻辑控制在‘只能动自己的数据’（不能改别人的）。","out":"只有合法用户能访问其权限内的数据"}]},{"type":"realworld","items":[{"name":"用户系统崩了=数据库没备份/没迁移","note":"很多线上事故是数据库结构改了没做迁移，或连接串配错。知道‘表结构=产品地基’，你就会让 AI 在改表时同步给迁移脚本（ALTER TABLE…），并先在本地/测试库验证。"},{"name":"密码泄露事件=明文存储的代价","note":"反复出现的‘XX 网站密码库泄露’事故，根源常是明文或弱哈希存密码。正确做法：bcrypt/scrypt 加盐哈希。这是判断 AI 登录代码‘安全与否’的第一眼标准。"},{"name":"登录方案选择=产品形态决定","note":"简单网页用 Session 就够；前后端分离/多端（App+网页+小程序）常用 JWT；要‘微信一键登录’就用 OAuth。你会常看到这三者在真实项目里混用（如 JWT 登录 + 微信 OAuth 授权）。"},{"name":"防火墙/最小权限=运维层防御","note":"生产数据库通常不直接暴露公网，只允许服务器内网访问；应用账号只给它需要的库表权限。这是安全纵深的一部分，和‘代码那次注入’互补。"}]},{"type":"compare","pairs":[{"a":"Session（服务端会话）","b":"JWT（令牌）","diff":"Session 把状态存在服务器（内存/Redis/库），客户端只持一个 sessionId，好处是可随时踢人/注销；JWT 把身份信息加密签进 token 给客户端，服务器无状态，好处是天然适合多端与分布式，缺点是一旦签发难在过期前吊销。选型：传统/单一服务用 Session，前后端分离多端多用 JWT。"},{"a":"JWT","b":"OAuth","diff":"JWT 是一种‘凭证格式’（我信任它的签名）；OAuth 是一种‘授权协议’（用户把权限授予第三方，如‘微信允许这个 App 读我的昵称头像’）。OAuth 常把 JWT 当作其中一种 access_token 的载体。"},{"a":"哈希 Hash（单向）","b":"加密 Encrypt（可逆）","diff":"哈希不可逆：密码只做比对，任何人（包括你自己）都无法还原，适合存密码；加密可逆：能解回原文，适合传输敏感信息（但要妥善保管密钥）。拿加密去存密码是常见误区。"},{"a":"SQL 注入","b":"XSS 跨站脚本","diff":"注入是‘坏人把 SQL 代码塞进输入，骗后端执行’，防御靠参数化查询；XSS 是‘坏人把脚本塞进页面内容，骗浏览器执行’，防御靠输出转义。一个打数据库、一个打浏览器，都要防。"}]},{"type":"mistakes","items":["错误案例①（AI 高频）：密码用明文存进数据库列 `password`。正确是 `password_hash` 且用 bcrypt/scrypt 加盐哈希。看到列名叫 password 就要警觉。","错误案例②（致命）：SQL 用字符串拼接——`SELECT * FROM users WHERE name = '` + input + `'`。坏人输入 `' OR '1'='1` 就能登录一切人。必须改成参数化：`WHERE name = $1`（PG）或 `?`（MySQL）。","错误案例③：用户表没有主键，或把‘用户名’当唯一标识——重名就会数据错乱。主键必须稳定唯一（通常用自增 id 或 UUID）。","错误案例④：前端校验当安全边界——‘我在前端限制了只能填数字’并不能挡住直接调接口的攻击者。真正的校验必须在后端。","错误案例⑤：把 token 存 localStorage 又不设过期、也不校验是不是当前用户——一旦 XSS 就能偷走凭证。安全要‘防御纵深’，别只做一层。"]},{"type":"deep","title":"深入一点：手把手判读一张 AI 建的‘用户表’和登录接口","beginner":["看一张 AI 生成的用户表，先问五件事：","**有没有主键？** 要有 id（或 UUID）作主键，能唯一稳定地定位记录。","**密码是不是哈希列？** 应该叫 password_hash / password_digest，用 bcrypt，绝不存明文。","**必填列有没有 NOT NULL？** 用户名、密码哈希不能为空。","**会不会被注入？** 查询语句是不是参数化的（用占位符而非拼接）？","**有没有做访问控制？** 比如‘只能读自己的数据’，而不是任何人传个 id 就能读到别人的。"],"advanced":["**合法但可以更好的设计**：除了基础列，常加 created_at/updated_at 时间戳（审计用）；经常按 username 查就加唯一索引 `UNIQUE(username)`；邮箱/手机号单独存或用正则后端校验。","**登录接口应返回什么**：成功后（201/200）返回凭证；密码错返回 401；账号不存在也返回 401（而不是 404，避免暴露‘这账号存在’）。失败要记日志，但日志里别打明文密码。","**一个可参考的 SQL 建表**：","```sql\nCREATE TABLE users (\n  id BIGSERIAL PRIMARY KEY,\n  username VARCHAR(50) NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n```","**登录校验（参数化防注入的示范）**：","```js\nconst row = await db.oneOrNone('SELECT * FROM users WHERE username=$1', [username]);\nconst ok = row && await bcrypt.compare(password, row.password_hash);\nif (!ok) return res.status(401).json({ ok:false, msg:'用户名或密码错误' });\n```","注意 `$1` 占位符 + `[username]` 参数数组 = 参数化，SQL 注入无从下手。"]},{"type":"ask","title":"怎么用 AI 帮你设计数据库和登录","scenario":"你做了一个‘用户能注册、能收藏文章’的小产品，想让 AI 一次性给出靠谱的表设计和登录方案。","template":"[产品场景] 用户注册登录后，可以收藏文章（一个用户可收藏多篇文章）。\n[请帮我设计] ①用户表与收藏表的结构（含主键、外键、索引）；②注册/登录后端代码，密码用 bcrypt 加盐哈希、SQL 用参数化防注入；③返回 401/201 等状态码。\n[验收标准] 请说明：主键是谁、外键怎么关联、密码如何存储、如何防 SQL 注入、登录凭证用 Session 还是 JWT 并说明理由。","acceptance":["表结构是否给出了主键、外键和需要加的索引？","密码是否明确用了 bcrypt 之类加盐哈希而非明文？","SQL 是否参数化（占位符）而非字符串拼接？","登录凭证方案是否说明了 Session/JWT 的选择及理由？是否覆盖成功与失败状态码？"],"tip":"涉及数据库和安全，务必让 AI 把‘为什么这么做’讲出来，而不能只给代码。你再用上面的‘五问’走一遍，就能当半个审查。"},{"type":"exercise","prompt":"你的登录接口被人用输入 `' OR '1'='1` 打穿了，任何密码都能登进去。这最可能是下面哪种代码导致的？","opts":["用 bcrypt 哈希密码","SQL 用了字符串拼接用户输入（未参数化）","给 username 加了唯一索引","登录返回了 401"],"a":1,"explain":"把用户输入直接拼进 SQL 会造成 SQL 注入——输入里含有的引号和 OR 让查询恒真，从而绕过密码。改成参数化查询即可堵住。","jump":"sec8","jumpLabel":"深入一点的 SQL 注入示范段"},{"type":"check","title":"结课检测：数据库与安全你真的懂了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"用户的‘收藏表’要关联用户和文章，最正规的做法的核心是？","opts":["把所有用户名和文章名塞进同一列","用外键 user_id 和 article_id 分别指向用户表、文章表的主键","每次复制一份用户表","收藏不存数据库"],"a":1,"explain":"用外键指向各自表的主键，才能表达‘哪个用户收藏了哪篇文章’的关系且不重复存储。","jump":"sec5-step3"},{"q":"密码正确的存储方式是？","opts":["明文存进 password 列","加密（可逆）后存","加盐哈希（如 bcrypt）后存，且不存明文","存进 cookie"],"a":2,"explain":"哈希是不可逆的，任何人不包括你自己都无法还原密码，只能用于比对；加盐防止相同密码产生相同哈希。","jump":"sec5-step4"},{"q":"SQL 注入的根本防御是？","opts":["在前端把输入框禁用","用参数化查询（占位符）","把数据库放到公网","把 SQL 写成大写字母"],"a":1,"explain":"参数化查询把用户输入当作数据而不是可执行的 SQL 代码，因此注入失效。","jump":"sec8"},{"q":"Session 与 JWT 的区别，哪句最准确？","opts":["Session 把状态存服务器，JWT 把身份信息加密进令牌交给客户端","两者完全一样","JWT 不能加密","Session 只用于 HTTPS"],"a":0,"explain":"Session 服务端有状态、可随时注销；JWT 无状态、令牌自证身份，适合多端，但签发后较难在过期前撤销。","jump":"sec6"},{"q":"别人的博客里嵌了你的登录页代码，结果是坏人代码执行——这属于用什么方式防御的问题？","opts":["SQL 注入","XSS 跨站脚本","数据库索引","密码哈希"],"a":1,"explain":"把脚本塞进页面内容让浏览器执行的是 XSS，防御靠输出转义 + CSP 等；这不是 SQL 注入（那是打数据库的）。","jump":"sec6"}],"done":"你现在能看懂表结构、能审 AI 的建表与登录代码、知道 Session/JWT/OAuth 怎么选、也知道 SQL 注入/XSS 怎么防。下一课我们把这一切真正‘送上线’：从本地 Demo 变成一台公网可访问、稳定可回滚的真实产品。","nextLesson":"v07-deploy"},{"type":"connection","known":["你知道后端通过 API 和数据库交互（上一课）。","你知道数据要长期保存、要按关系组织（本课）。"],"learned":["数据库用表组织数据：列、行、主键唯一、外键关联、索引加速","SQL 增删改查与参数化防注入","登录三方案：Session 存服务端 / JWT 自证令牌 / OAuth 第三方授权","安全四原则：密码哈希、SQL 参数化、输出转义、后端校验"],"next":"数据和身份都准备好了，下一步是把它们‘送上线’。这与 AI 路径的联系：当你要做的是 AI 产品（如 RAG 问答），RAG 的向量库也是一种‘数据库’，登录/安全同样适用。下一课《从本地 Demo 到正式上线》会把 部署、健康检查、回滚 讲透。","links":[{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——了解向量数据库在 AI 产品里的角色"},{"href":"#/lesson/l20-ai-eng","text":"回看 AI 路径《AI 工程：从原型到生产》(规划中)"}]}]},"v07-deploy":{"id":"v07-deploy","title":"从本地 Demo 到正式上线","subtitle":"代码在你自己电脑上能跑，不算数；让全世界都能访问、且挂了能快速恢复，才是‘上线’。这一课讲清楚那条从 localhost 到公网的最后一公里。","course":"vibe","courseNo":"07","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api","v04-db"],"nextLesson":"","sections":[{"type":"opening","question":"你的产品在自己电脑上跑得欢，你联调、测试都通过了。现在要把它放到公网，让外地、外网、别家浏览器都能访问——为什么这件事永远比想象中麻烦？常见的‘本地正常、线上挂掉’到底差在哪？","guess":"很多人以为‘上线就是把文件传到服务器上，然后就能用了’。","next":"这一课我们拆解上线全流程：环境如何保持一致（环境变量）、如何把项目部署到服务器/云平台、域名与 HTTPS 怎么配、上线后怎么确认它是‘健康的’（健康检查）、出问题怎么快速回滚、以及要不要上 CI/CD。学完后你拥有的能力是：把 AI 做的 Demo 安全地变成可上线产品，并知道每一步万一失败该怎么退回来。"},{"type":"why","before":"你写好了产品，AI 也说‘好了，部署吧’。可你一部署，报‘连接数据库失败’‘端口被占用’‘找不到 .env’‘静态资源 404’……你完全不知道从哪查起，只能一遍遍粘日志给 AI，反复重装环境。","problem":"本地与线上天然不同：路径不同、数据库地址不同、端口不同、依赖版本可能不同、还要面对公网连接、域名、HTTPS 证书、防火墙。如果你没有‘环境一致性’与‘可回滚’的意识，即使这次勉强跑起来，下次改动也会随时把线上搞挂而无法恢复。","need":"掌握上线的最小可靠流程：用环境变量（.env）把差异集中管理；部署常走三大路径（静态托管 / PaaS 平台 / 自管服务器）分别怎么选；配域名 + HTTPS；加‘健康检查’让系统自己喊救命；上线清单与回滚流程让‘挂了也能退回去’。这是把 Demo 变成产品的临门一脚。"},{"type":"oneline","text":"上线 = 把代码 + 环境一致地搬上公网机器 + 配好域名/HTTPS + 挂上健康检查 + 准备好一键回滚。核心三句话：环境用变量隔离差异（不同环境不同值）、部署用脚本/平台保证可重复（别靠手敲）、发布用‘灰度/可回滚’控制风险（挂了能退）。"},{"type":"visual","kind":"deploy-console","title":"互动实验：部署控制台，看一次完整上线","hint":"这是一个模拟部署终端：点‘部署’会经历 构建 → 迁移 → 健康检查 → 流量切换；如果健康检查失败，系统会拒绝放量并自动回滚到上一个版本。你还能故意制造‘健康检查失败’来亲眼看到回滚是怎么保命的。"},{"type":"intuition","blocks":[{"k":"用开餐厅来想","t":"本地 Demo 像在你的厨房试菜——火候是你自己调好的、食材在你冰箱里。上线＝在商业街上开正式的餐厅：要租店面（服务器）、接水电气（网络/HTTPS）、换统一采购的食材（数据库搬到线上）、店员按标准作业（健康检查/监控）、万一某天厨房着火（服务挂）要能立刻换上备用后厨（回滚/容灾）。‘本地试菜’和‘正式营业’根本不是一回事。"},{"k":"用电梯/红绿灯来想健康检查","t":"健康检查＝系统自己定时喊一嗓子‘我还活着’（探测 /health 接口）。就像电梯每隔几秒报一次运行状态。如果它不喊了，编排系统（如负载均衡）就把它踢出队伍并拉起一个新的——而不是让用户对着白屏干等。"},{"k":"一句话记住上线","t":"环境变量隔离差异 → 构建产物可重复 → 部署到线上 → 健康检查确认活着 → 出问题回滚上个版本。五个动作，缺一不可；其中‘能回滚’是你最后的保险绳。"}]},{"type":"visual","kind":"llm-retry","title":"互动实验：给 LLM 调用加上超时 + 重试 + 回退","hint":"你的产品里调了大模型 API（这也是你 AI 产品的‘后厨’）。网络抖动/超时/限流在线上是家常便饭。这个实验模拟‘调用 → 超时 → 重试 → 回退(fallback)’，体会电商级 API 调用为什么要设计超时与降级。这也是 Vibe Coding 路径与 AI 路径的连接点。"},{"type":"how","intro":"把一次‘安全上线’拆成 6 步：每一步都有明确的‘成功标志’和‘失败补救’。","steps":[{"in":"① 环境变量：把差异抽出来","process":"本地/测试/线上需要不同的数据库地址、密钥、端口。把它们写进环境变量（如 .env 文件或平台面板），代码里用 process.env.XXX（Node）/ os.environ（Python）读取，而不是写死。","out":"代码与环境解耦：同一份代码换环境即可"},{"in":"② 构建 + 迁移","process":"前端打包成静态文件（npm run build → dist/）；数据库结构变化用迁移脚本（migration）跑一遍。构建产物要是‘可重复’的——同一份源码应产出同样的产物。","out":"得到一个可直接发布的‘构建物’+ 数据库就绪"},{"in":"③ 部署到线上","process":"三大路径：静态托管（页面纯前端，丢到 GitHub Pages/CF Pages/OSS 即可）；PaaS 平台（Vercel/Netlify/Railway/Render，把代码推送即可自动部署，适合新手与中等项目）；自管服务器（买 ECS/VPS，自己配 Nginx + 进程守护如 PM2/systemd）。新手从 PaaS 起步最稳。","out":"公网可以访问你的服务"},{"in":"④ 域名 + HTTPS","process":"买个域名，把 DNS 解析到你的服务（A 记录指向 IP / CNAME 指向平台）；再签 HTTPS 证书（平台自动，或云厂商+Letʼs Encrypt），让访问走 https:// 加密。浏览器地址栏的小锁 = 加密。","out":"用户通过好记的 https://你的域名 访问"},{"in":"⑤ 健康检查 + 监控","process":"后端提供 /health 接口（返回 200 + 状态）。负载均衡/编排平台每 X 秒探测它：活着→正常放量；不活→摘除并重启该实例，同时报给你（监控告警）。","out":"系统自己‘喊救命’，而不是等用户来报"},{"in":"⑥ 发布即回滚预案","process":"大型发布用‘灰度’：先 10% 流量验证，稳妥再全量；每版都保留上一个版本，发现异常立刻一键回滚（切回旧版本）。回滚能力 = 你改线上时的底气。","out":"即使新版本有问题，也可在几分钟内恢复"}]},{"type":"realworld","items":[{"name":"GitHub Pages（本站就是这么上线的）","note":"纯前端静态站可直接推到 GitHub Pages，免费公网、自带 HTTPS。适合‘文档/演示/静态首页’。注意它只托管静态资源，没有后端/数据库——需要后端的要另选 PaaS 或 VPS。"},{"name":"Vercel / Render / Railway（PaaS）","note":"‘连上 Git 仓库，push 即部署’：自动构建、自动 HTTPS、给环境变量面板、自动健康检查与回滚。是前端+轻后端产品（含 Next.js 全栈）最省心的上线方式。"},{"name":"云服务器 + 进程守护（VPS）","note":"腾讯云/阿里云的 ECS 上装 Node/Python、用 PM2/systemd 守护进程、Nginx 反代 + HTTPS。灵活可控但维护成本高。适合要自己掌控环境、或者后端较重/要连自己数据库的产品。"},{"name":"CI/CD（持续集成/持续部署）","note":"把‘测试 → 构建 → 部署’做成流水线：你 push 代码，系统自动跑测试并部署。好处是上线行为可重复、可审计；新手至少理解它的存在，平滑后再引入 (如 GitHub Actions)。"}]},{"type":"compare","pairs":[{"a":"静态托管（GitHub Pages/OSS）","b":"PaaS 平台（Vercel/Render）","diff":"静态托管只能放纯前端静态文件、无后端、一般免费；PaaS 能托管前端+后端（有的带数据库），源码推送自动构建/部署/HTTPS，更适合‘有后端的完整产品’。纯静态选前者，有后端选后者。"},{"a":"PaaS 平台","b":"自管云服务器（VPS+PM2+Nginx）","diff":"PaaS 帮你管环境、自动部署、内置回滚，省心但灵活度有限；VPS 完全可控（能装任意软件）但要自己维护系统、进程守护、HTTPS、备份，运维成本高。新手/中小产品从 PaaS 起步，要深度控制再上 VPS。"},{"a":"环境变量 .env","b":"写死在代码里","diff":"环境变量让同一份代码在不同环境（本地/测试/线上）用不同配置，且密钥不进代码库；写死会导致‘本地行、线上不行’，且密钥泄露风险大。必须用环境变量管理差异与密钥。"},{"a":"健康检查 /health","b":"用户报错才知道挂了","diff":"健康检查是主动、自动、秒级的探活，挂了立刻摘除重启并告警；等用户报告则被动、慢、伤口碑。生产环境必须有健康检查。"}]},{"type":"mistakes","items":["错误案例①：把数据库连接串、API 密钥写死在代码/前端里并 push 到公开仓库——等于把保险柜密码贴在门口。密钥必须进环境变量并严格保密。","错误案例②：没有环境意识，‘本地跑通了就认为线上能跑’。正确的验证方式：线上部署后跑一遍健康检查 + 真实浏览器访问，而不是‘本地 200 就完事’。","错误案例③：上线直接改线上数据库结构却不做迁移回滚——出事退不回去。数据库结构变更要保留迁移脚本、可逆可回退。","错误案例④：追逐‘最新框架/功能’把线上当实验场，改一次崩一次却没有任何回滚按钮。生产稳定 > 炫技；改版前后都要有一键回滚能力。","错误案例⑤：把‘调大模型 API’当成不会失败——线上网络抖动、超时、限流很常见。不给 API 调用加超时/重试/回退(fallback) 的 AI 功能，用户会频繁看到转圈/报错。"]},{"type":"deep","title":"深入一点：一次失败的线上事故是怎么被救回来的","beginner":["把‘回滚像不像重装系统’想明白：回滚不是把线上机器清空重装，而是‘把流量切回上一个已知良好的版本镜像/构建物’。现代平台（PaaS、容器编排）都保留旧版本，一键切换即可，秒级恢复。","健康检查的 /health 接口长什么样？就是一个后端路由，返回 200 和一个简单的 JSON：`{status:'ok'}`。它常常还会顺带检查数据库能否连上。如果数据库挂了，/health 也会返回失败——这样编排系统才会判断这台机器‘不健康’并把它踢出去。"],"advanced":["**一次事故的完整剧本**：新版本把数据库连接串写错 → 部署平台探测 /health → 数据库连不上 → /health 返回 500 → 平台判定‘不健康’→ 拒绝放量 / 自动回滚到旧版本 → 监控告警发到你手机 → 你看日志定位到环境变量拼错 → 修正后重新部署。全程用户几乎无感知。这就是‘健康检查 + 回滚 + 监控’三件套的价值。","**LLM 调用的可靠性设计（与 AI 路径的接口）**：真实产品调大模型 API 时，用模式是‘超时 + 指数退避重试 + 回退（缓存结果 / 备用模型 / 返回友好提示）’：","```js\nconst response = await fetchLLMWithRetry({\n  prompt, timeoutMs: 8000,            // 超时：8 秒没回应就放弃重试\n  retries: 3, backoffMs: 1000,         // 重试 3 次，指数退避\n  fallback: () => cache.get(key)       // 兜底：用缓存或降级文案\n});\n```","**上线检查清单（Checklist）**：①环境变量配全了吗？②数据库迁移跑了吗？③HTTPS 生效了吗（浏览器锁）？④/health 探针过吗？⑤日志与告警接了吗？⑥旧版本能一键回滚吗？⑦真实浏览器/多设备验证了吗？全部打勾，才算一次‘可上线发布’。"]},{"type":"ask","title":"怎么让 AI 帮你安全上线","scenario":"你的产品要第一次上线，不确定从哪下手、怕把线上搞挂。","template":"[我的产品] 是一个 [前端 + Node 后端 + PostgreSQL] 的小产品，目前只在本地能跑。\n[请给我] 一份最小可靠的上线方案：推荐用哪种托管方式（静态/PaaS/VPS）并说明理由；列出需要的环境变量清单；给出数据库迁移与开启 HTTPS 的步骤；提供 /health 接口示例与回滚预案。\n[验收标准] 每一步是否有明确操作与验证方法？是否包含失败时的回滚步骤？","acceptance":["部署方案是否说明了选型理由（静态/PaaS/VPS）与本产品的适配性？","环境变量清单是否完整且不包含明文密钥？","是否提供了可复现的部署步骤与验证方式（健康检查/浏览器访问）？","是否有明确的回滚/恢复预案，而不是‘挂了重装’？先小范围(灰度)验证再全量了吗？"],"tip":"上线是最不能‘赌一把’的环节。让 AI 给出‘选型 + 环境变量 + 验证 + 回滚’全套，再逐项打勾验收；任何一步读不懂就让 AI 解释‘为什么这样做’，直到你能复述为止。"},{"type":"exercise","prompt":"你上线了新版本，负载均衡探测 /health 连续几次都返回 500。接下来最正确的自动动作是什么？","opts":["继续放大流量，等用户反馈","把该实例摘除并自动回滚到上一个良好版本","重启浏览器","删掉数据库"],"a":1,"explain":"健康检查失败说明新版不健康，应把它踢出流量并回滚到上一版本，让用户在无感知的情况下继续使用。","jump":"sec7-step4","jumpLabel":"第 ⑤ 步：健康检查 + 监控"},{"type":"check","title":"结课检测：你的上线观念成立了吗","intro":"共 5 题。全部答对可进入下一节后续课程（或视为完成本路径第一批）。","questions":[{"q":"‘本地跑通 = 线上一定能跑’这句话？","opts":["完全正确","错误，本地与线上环境(变量/依赖/数据库)常不同，需部署后验证","只对前端成立","只对数据库成立"],"a":1,"explain":"环境差异（连接串、密钥、依赖版本、端口）是‘本地行、线上挂’的常见原因，必须部署后做健康检查与真实访问验证。","jump":"sec4"},{"q":"数据库地址、API 密钥这类差异应当怎么管？","opts":["写死在代码里方便","放进环境变量按环境区分，且密钥不进代码库","藏在注释里","放前端页面里"],"a":1,"explain":"环境变量让同一代码适应不同环境、密钥不进仓库，安全且可维护。","jump":"sec5-step0"},{"q":"完全不会写代码、只想让前端+后端都能自动上线，最省心的选项是？","opts":["自建机房","PaaS 平台（如 Vercel/Render），连 Git push 即部署","用纯记事本手写服务器脚本","不部署"],"a":1,"explain":"PaaS 负责构建、部署、HTTPS、健康检查与回滚，对新手最友好；VPS 更适合要深度控制的高级场景。","jump":"sec7"},{"q":"/health 健康检查的探测失败时，编排系统最合理的动作是？","opts":["什么都不做","摘除不健康实例并重启/拉起新的，必要时候选回滚","把数据库清空","关掉域名"],"a":1,"explain":"自动摘除+重启，必要时回滚旧版本，让用户几乎无感知；同时告警提醒你排查。","jump":"sec7-step4"},{"q":"调用大模型 API 时，‘超时 + 重试 + 回退(fallback)’组合主要防范什么？","opts":["防止代码有语法错误","线上网络抖动、超时、限流导致的偶发失败","防止数据库被删","防止前端样式错乱"],"a":1,"explain":"线上第三方 API 偶发失败是常态，超时避免无限等待、重试提高成功率、回退(缓存/备用/友好提示)兜底，保证用户体验不崩。","jump":"sec7"}],"done":"你已经掌握了从 localhost 到公网‘最后一百米’的全部关键：环境变量隔离、部署三路径选型、域名+HTTPS、健康检查、回滚预案、上线清单。Vibe Coding 第一批四门课到此收官——你已经能看懂代码结构、判断接口与数据库靠不靠谱、把 Demo 安全上线了。","nextLesson":""},{"type":"connection","known":["你知道一个 Web 产品如何分层（课1）、前后端怎么通信（课3）、数据怎么存与登录安全（课4）。","你会调大模型 API / 了解 RAG、Agent（AI 路径）。"],"learned":["环境变量隔离本地/测试/线上差异，密钥不进代码库","部署三路径：静态托管 / PaaS / 自管 VPS，以及各自适用场景","域名 + HTTPS（浏览器小锁）怎么配","健康检查(/health)探活 + 监控告警，挂了自动摘除","灰度 + 一键回滚 = 改线上时的底气；上线检查清单"],"next":"Vibe Coding 第一批四个环节到此闭环：看懂 → 懂接口 → 懂数据/安全 → 懂上线。下一步安排：第二批课程将覆盖 前端与语言基础（课2）、终端与 Git（课5）、存储缓存与测试排错（课6）、系统设计与 AI 产品工程（课8）。与本路径之外的联系：AI 产品的上线同样遵循本课原则，且多了‘LLM 调用可靠性’（超时/重试/回退）这一环——已在课 7 实验里有真机感受。","links":[{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"},{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——AI 产品上线的数据侧"},{"href":"#/lesson/l-agent","text":"回看 AI 路径《Agent：让 AI 自己动手做事》——Agent 产品化时的可靠性思考"}]}]}},"byId":{"l00-ai-world":{"id":"l00-ai-world","title":"一张图看懂整个 AI 世界","subtitle":"在学任何一个概念之前，先拿到整张地图：你现在站在哪里，接下来要走到哪里。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"15-20 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl","ai-apps","ai-limits"],"prereqLessons":[],"nextLesson":"l-embedding","sections":[{"type":"opening","question":"你每天听到的 ChatGPT、大语言模型（LLM）、Transformer、Agent、RAG……它们到底谁包含谁、谁建在谁之上？如果你现在只能用一句话回答「它们是什么关系」，你会怎么说？","guess":"很多人会脱口而出「都是一回事，就是 AI」。","next":"这节课不教任何公式，只画一张总地图。学完你不仅能说清这些词的关系，还能知道接下来 5 节旗舰课各自站在这张地图的哪个格子里。"},{"type":"why","before":"你在标题、文章、面试里反复遇到 Token、Attention、Transformer、RAG、Agent、Fine-tune……每个词单独看都懂一点，但凑在一起就乱。","problem":"初学者最大的障碍不是「不够努力」，而是没有地图：他不知道现在学的东西将来会连到哪里，于是学一个忘一个，越学越焦虑。","need":"所以第一节课我们不讲任何实现细节，只建立骨架：AI 世界分哪几层、每一层由什么构成、你将来要学的每一块长在哪个位置。地图在手里，后面的路才走得稳。"},{"type":"oneline","text":"AI（人工智能）是整片森林；机器学习是其中『会自己从数据里找规律』的那片林子；深度学习是最能长的那几棵大树；大语言模型（LLM）是最近最抢眼、能和你聊天的那一棵；而 RAG、Agent 这些，是围绕这棵树搭起来的『脚手架』——让树上的果子更好摘。"},{"type":"visual","kind":"ai-world-map","title":"AI 世界全景图","hint":"从最外层的 AI 一路收缩到 LLM，再向外展开 Vision / Speech / Agent / RAG 等应用方向。点击让你看明白的节点，就能往下一层走。"},{"type":"intuition","blocks":[{"k":"用俄罗斯套娃来想","t":"AI 是最大的套娃，机器学习是里面一层，深度学习再里面一层，LLM 是最小最精致的那层。每往里一层，都建立在外层之上——这叫『包含』，不是『并列』。"},{"k":"用搭积木来想","t":"只给你一个 LLM 你只能『聊天』。但当你往它外面搭『检索』（RAG）、『工具调用』（Agent）、『工作流编排』（Workflow）这些积木，你就从『会聊天』升级成『会办事』。产品形态 = 模型 + 一层层积木。"},{"k":"一句话记住主干","t":"AI ⊃ ML ⊃ DeepLearning ⊃ Foundation Model ⊃ LLM。这一个箭头链，就是整张地图的主干，也串起了你即将学的六节课。"}]},{"type":"how","intro":"把 AI 世界拆成「五层结构」与「五大应用方向」，你学完至少知道每块知识的归属，再也不会把它们混为一谈。","steps":[{"in":"第 0 层 · AI（人工智能）","process":"最上层总称：让机器表现出智能的一切技术，包括早期靠人写规则、搜索、专家系统。","out":"范围最大，是『目标』而不是某一门具体技术"},{"in":"第 1 层 · Machine Learning 机器学习","process":"不再靠人写死规则，而是让机器从数据里『自己找规律』，再拿规律去做预测。","out":"监督学习 / 无监督学习 / 强化学习 三大流派"},{"in":"第 2 层 · Deep Learning 深度学习","process":"用『多层神经网络』来自动提取特征，是机器学习的子集，能力更强：不用人手设计特征。","out":"CNN（图像）、RNN/Transformer（序列）、扩散模型（生成）等结构"},{"in":"第 3 层 · Foundation Model 基础模型","process":"在大规模数据上预训练好的『通用大脑』，可以微调或直接复用到很多不同任务。","out":"LLM（语言）、视觉基础模型、多模态基础模型"},{"in":"第 4 层 · LLM 大语言模型","process":"把『预测下一个词』当唯一训练目标，靠海量文本硬学出来的语言模型，意外获得了语言与世界的知识。","out":"ChatGPT、Claude、Gemini 背后的模型本体"},{"in":"围绕 LLM 的『脚手架』与应用架构","process":"光会聊天不够，为了让模型能办成事，在外面叠加外围技术。","out":"Prompt 提示 · RAG 检索增强 · Workflow 工作流 · Agent 智能体 · 多模态"}]},{"type":"realworld","items":[{"name":"ChatGPT","note":"「纯 LLM 对话产品」：你打字，它预测下一段话。它本身不做检索也不调工具，是最纯粹的一层。"},{"name":"Claude / Gemini","note":"同样是 LLM 驱动的对话产品，但在模型能力与对齐上做得不同，代表『同一个塔、不同的果』。"},{"name":"NotebookLM / 企业知识库问答","note":"「LLM + RAG」：你上传私有资料，系统先检索相关片段，再让模型基于这些片段回答，杜绝凭空编造。"},{"name":"Workflow 编排（如 Zapier AI / Coze 工作流）","note":"「LLM + 规则流程」：把『先做A、判断结果再做B』写成固定流水线，模型只负责其中某一环。"},{"name":"Codex / Claude Code","note":"「LLM + Agent 智能体」：不只是回答，还能自主决定『读文件→改代码→跑测试→看报错→再改』，直到把活干完。"},{"name":"Midjourney / Sora","note":"「不是 LLM 的另一棵树」：用扩散模型做图像/视频生成。提醒你 AI 世界不只有语言这一棵大树。"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是「目标——机器有智能」；机器学习是实现它的一种主流手段（用数据学出来）。早期用规则实现的人工智能，不属于机器学习，但仍然属于 AI。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是「从数据学习」；机器学习范围更大（含决策树、SVM 等传统算法），深度学习专指用多层神经网络，能自动提取特征，是机器学习的一个子集。"},{"a":"LLM","b":"Foundation Model","diff":"LLM 是专做语言的基础模型；Foundation Model 是更大的类，还包括视觉、多模态基础模型。LLM ⊂ 基础模型。"},{"a":"RAG","b":"Agent","diff":"RAG 是『给模型外接资料库』的检索增强；Agent 是『让模型自主决策与调用工具』的智能体。两者常配合：Agent 需要信息时用 RAG 检索。它们都不是模型本身，而是脚手架。"},{"a":"模型（Model）","b":"产品（Product）","diff":"模型是被训练出来的『大脑』；产品是把这个大脑装进界面、加上检索/记忆/工具后的完整应用。你用的是产品，不直接是模型。"}]},{"type":"mistakes","items":["把「AI、机器学习、深度学习、LLM」当同义词——它们是一层层包含关系，不是并列。","以为 ChatGPT = 整个 AI。ChatGPT 只是 LLM 的一颗果实；AI 世界还有视觉、语音、生成、机器人、Agent 等一大片。","以为 RAG 和 Agent 是「模型」。它们是在模型外面搭的脚手架/架构，本身没有『大脑』。","以为只有学完高等数学才能开始。第一门旗舰课（Embedding）就能带你把概念走通，数学按「够用」给，不是研究生讲义。","以为 Fine-tuning（微调）和 RAG 是一回事。前者改模型自身权重，后者不改模型、只改给它看的外部资料——它们解决不同问题。"]},{"type":"deep","title":"深入一点：把「领域 / 模型 / 技术 / 应用架构 / 产品形态」五顶帽子分清楚","beginner":["用「帽子」来记：同一个东西，问问题的角度不同，答案就不同。","「这属于哪个**领域**？」—— 问的是地图范围（AI、ML、DL 是领域/学科级）。","「这是个什么**模型**？」—— 问的是被训练出来的产物（LLM、扩散模型、视觉模型是模型级）。","「用了什么**技术/算法**？」—— 问的是怎么做（Attention、Transformer、RAG 检索是技术级）。","「这是什么**应用架构**？」—— 问的是怎么组合（RAG 架构、Agent 循环、Workflow 流水线是架构级）。","「最终做成什么**产品**？」—— 问的是用户能用的东西（ChatGPT、Codex、NotebookLM 是产品级）。"],"advanced":["用一条「从模型到产品」的抽象层次链来定位任何 AI 名词：","「AI 世界 = 领域层（AI⊃ML⊃DL）→ 模型层（Foundation Model→LLM/Diffusion/多模态）→ 技术层（Attention、位置编码、损失函数）→ 架构层（RAG、Agent、Workflow、多智能体协作）→ 产品层（ChatGPT、Claude Code）」。","判断法则：问「它能不能被『训练』出来」？能 → 模型层或更深；问「它是不是一个『零件/接法』」？能 → 技术层或架构层。训练产物是模型，接法是架构。","示例定位：Transformer 是技术层（一种网络结构）；GPT 系列是基于 Transformer 训练出来的模型（模型层）；把 GPT 接上检索= RAG 架构（架构层）；打包成网站= ChatGPT 产品（产品层）。","顺带一个工程事实：你平时说的「大模型」绝大多数指 LLM 或基础模型；而「智能体」「Agent」在业界常被定义为『模型 + 记忆 + 规划 + 工具调用』，是一个架构概念而非单个模型。"]},{"type":"exercise","prompt":"你现在打开了一款「企业知识库问答」App，上传公司政策文件后提了个问题，系统给出的回答里标注了「依据文件第 3 页」。你觉得它最可能是下面哪种组合？","opts":["只有 LLM，全靠模型自己编","LLM + RAG（先检索你的文件，再基于片段回答）","LLM + Agent（让模型自己去改代码）","纯扩散模型"],"a":1,"explain":"回答『依据你上传的文件』并带引用，正是 RAG 的典型特征：先检索相关片段，再让模型基于片段生成答案。","jump":"sec5-step5","jumpLabel":"围绕 LLM 的脚手架（RAG 检索）这一段"},{"type":"check","title":"结课检测：你真的懂这幅地图了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"下面哪条包含关系是正确的？","opts":["AI ⊃ LLM ⊃ Deep Learning ⊃ ML","AI ⊃ ML ⊃ Deep Learning ⊃ LLM","LLM ⊃ AI ⊃ ML ⊃ Deep","Deep Learning ⊃ ML ⊃ AI ⊃ LLM"],"a":1,"explain":"AI 包含机器学习，机器学习包含深度学习，LLM 是深度学习上长出的具体模型。","jump":"sec5-step0","jumpLabel":"五层结构第一步"},{"q":"ChatGPT 最准确地说是下面哪一个？","opts":["一个 Agent 智能体","一个纯 LLM 对话产品","一个 RAG 系统","一个视觉模型"],"a":1,"explain":"ChatGPT 的核心就是大语言模型：输入→预测下一段。RAG/Agent 是对它的增强，而不是它的本质。","jump":"sec5-step4","jumpLabel":"第 4 层 LLM 这一段"},{"q":"「NotebookLM 先查你上传的资料再回答」主要用到了哪项技术？","opts":["RAG 检索增强生成","纯预训练","扩散模型","只靠提示词"],"a":0,"explain":"针对私有资料，RAG 让模型先检索相关片段再回答，这正是 NotebookLM 类产品的核心。","jump":"sec5-step5","jumpLabel":"脚手架之 RAG 这一段"},{"q":"Codex「自己读代码、改代码、跑测试、看报错再重试」的能力，对应哪种架构？","opts":["RAG 检索增强","Agent 智能体循环","纯一次性生成","工作流固定流水线"],"a":1,"explain":"自主决策 + 调用工具 + 根据反馈循环，这正是 Agent 的核心：想→做→看→再想。","jump":"sec5-step5","jumpLabel":"脚手架之 Agent 这一段"},{"q":"「Midjourney 能生成图片」用到的模型，和 ChatGPT 的 LLM 是什么关系？","opts":["同一个模型","都是 LLM","Midjourney 用的是扩散模型，是 AI 世界里另一棵大树","Midjourney 不用 AI"],"a":2,"explain":"图像生成多靠扩散模型（Diffusion），与语言类的 LLM 是并列的不同模型，提醒你 AI 世界不止语言一棵树。","jump":"sec6","jumpLabel":"现实应用里的 Midjourney / Sora"}],"done":"现在你手里有整张地图了。接下来我们要下到模型的正下方——先搞清楚：电脑到底怎么把一句话变成它算得动的『数字』。","nextLesson":"l-embedding"},{"type":"connection","known":["（这是第一节课，还没有前置知识）"],"learned":["AI → ML → DL → Foundation Model → LLM 的主干链条（包含关系）","领域 / 模型 / 技术 / 应用架构 / 产品形态 五顶帽子怎么分","RAG、Agent、Workflow 是围绕 LLM 的脚手架，不是模型","ChatGPT、Claude（LLM产品）、NotebookLM（RAG）、Coze（工作流）、Codex（Agent）、Midjourney（扩散）各代表一类"],"next":"下一课我们钻到模型正下方：Embedding——电脑怎么把『一句话』变成『一串数字』。这是理解 LLM 的第一块砖，也是 RAG、搜索、推荐的地基。"}]},"l-embedding":{"id":"l-embedding","title":"Embedding｜怎么把词变成电脑能懂的数字","subtitle":"为什么文字不能直接进神经网络？为什么不是给每个词编个号？为什么意思相近的词离得更近？","category":"c02-essentials","chapterTitle":"第一章 · 向量与语义","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["embedding","vector","cosine-similarity","emb-vector-store"],"prereqLessons":["l00-ai-world"],"nextLesson":"l-attention","sections":[{"type":"opening","question":"你让 ChatGPT 翻译『苹果很好吃』，它内部第一件事不是『读懂』这句话，而是把『苹果』变成了一串数字。猜一猜：为什么电脑不能用『苹果』这两个汉字直接思考，非得多此一举先转成数字？","guess":"有人会想：给猫=1、狗=2、苹果=3 编个号不就行了？","next":"这节课就回答『为什么不能简单编号』，以及真正的 Embedding 是怎么做到『意思相近的词，数字也相近』的。"},{"type":"why","before":"神经网络只会做数学运算：加法、乘法、比较大小、算距离。它天生看不懂『猫』『狗』『苹果』这些文字。","problem":"如果文字根本送不进神经网络，那后面的一切——翻译、对话、理解、检索——全都是空中楼阁。这是所有语言模型的『第一道门』，绕不过去。","need":"所以我们必须在『文字』和『数字』之间搭一座桥，让电脑既能「算」文字，又能保留文字的含义。这座桥就是 Embedding。","visualNote":"下面这张 2D 语义空间图，就是你要带走的直觉：位置 = 语义。"},{"type":"oneline","text":"Embedding 就是把『一个词』变成『一串数字（向量）』，并且让意思相近的词，数字串长得也相近——于是电脑就能『算』语义了。"},{"type":"visual","kind":"embedding-space","title":"Embedding 2D 语义空间（可交互）","hint":"这是把词『压扁』到二维的示意：意思相近的词会聚在一起。观察猫/狗/狮子聚在『动物角』，苹果/香蕉聚在『食物角』。试试输入几个词，看它落在哪一群。"},{"type":"intuition","blocks":[{"k":"为什么不能直接给词编号？","t":"你可能会想：猫=1、狗=2、苹果=3 不就行了？但问题是：2 和 3 只差 1，可『狗』和『苹果』的语义差得十万八千里。编号把『数字距离』和『语义距离』完全搞乱了——电脑会误以为狗和苹果几乎一样。"},{"k":"用一张坐标纸来想","t":"想象一张地图，横轴是『是不是动物』，纵轴是『是不是食物』。『猫』放左边靠上，『狗』紧挨它，『苹果』放右上角。位置越近，意思越像。Embedding 本质就是在几百上千维的『坐标纸』上，给每个词找个位置。"},{"k":"一个生活类比","t":"就像地理坐标：北京和天津坐标很近，所以在空间里相邻；语义相近的词，在 Embedding 空间里坐标也相邻。"}]},{"type":"how","intro":"Embedding 是怎么『学』出来的？核心思想只有一句话：一个词的含义 = 它经常和哪些词一起出现。","steps":[{"in":"收集海量文本","process":"从整个互联网语料里，观察『猫』总是和『狗、宠物、喵、毛』一起出现，而『苹果』总跟『水果、吃、红色』一起出现。","out":"得到每个词在语料里的『共现模式』"},{"in":"用共现模式训练向量","process":"训练一开始给每个词一组随机数字，然后不断调整，让『经常一起出现』的词向量越走越近，『从不一起出现』的词向量越走越远。","out":"每个词最终固定成一个固定长度的向量（如 300 或 768 维）"},{"in":"用向量距离比较语义","process":"两个词的向量越接近（夹角越小、余弦相似度越高），语义越相近。电脑从此『算得出』猫≈狗、苹果≠猫。","out":"文字第一次可以被数值比较"},{"in":"送入下游模型","process":"这个数字向量就是神经网络的输入。LLM 只认数字，现在它『看得懂』词了，可以开始做翻译、对话、生成。","out":"模型能对词做运算、比较、生成"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude","note":"内部第一件事就是把你的每个 Token 转成 Embedding 向量，再送进 Transformer 网络。"},{"name":"搜索引擎语义检索","note":"把『怎么养猫』和『养宠物指南』都向量化，语义相近就能互相匹配，不必字面相同也能搜到。"},{"name":"NotebookLM / RAG","note":"把你的资料切成块并向量化，用户提问时在向量空间里『找最像的那几块』再交给模型回答——这就是 RAG 的地基。"}]},{"type":"compare","pairs":[{"a":"Token","b":"Embedding","diff":"Token 是文字切出的『小块』（词/子词）；Embedding 是把每个小块变成的『数字向量』。先切 Token，再做 Embedding。"},{"a":"Embedding 模型","b":"LLM","diff":"Embedding 模型把文本压成『定位向量』（不生成文字）；LLM 生成文字。一个是『编码员』，一个是『作家』。"},{"a":"One-hot 编号","b":"Embedding","diff":"One-hot 让所有词互相『等距』、无法表达语义；Embedding 让相近的词更近，真正抓住含义。"}]},{"type":"mistakes","items":["以为 Embedding 只是『给每个词一个数字』。其实是一整串数字（向量），且数字之间存在『相似关系』——这才是关键。","以为 Embedding 模型和 LLM 是同一个东西。它们是分工不同的两个模型：一个负责编码相似度，一个负责生成文字。","以为向量维度越高一定越好。维度越高表达力越强，但更贵、更易过拟合，常见几百维就够用。","以为 Embedding 能『理解逻辑』。它只捕捉统计上的相似，不保证逻辑正确——所以光靠 Embedding 做问答会答非所问。"]},{"type":"deep","title":"深入一点：从二维直觉到真实向量空间","beginner":["Embedding 在工程上就是『查表』：模型里有一张巨大的表，每个词一行，那一行数字就是它的向量。训练好了之后，直接用查到的数字即可。","维度越高，能表达的语义越细腻，但计算越贵。常见几百维就够处理大多数任务。","真正常用的是一种叫『子词』的粒度：一个字被拆成更小的片段（如 'unbreakable' → 'un' + 'break' + 'able'），这样遇到没见过的词也能拼出向量。"],"advanced":["向量不只给每个词一个『标签』，它把语义结构编进了几何里：经典例子 king − man + woman ≈ queen，说明向量『方向』也承载意义。","Embedding 模型（如 text-embedding 系列）与 LLM 是不同模型：前者把文本压缩成『定位码』，后者生成文字。它们可以分开训练、分开使用。","计算两个向量有多像，最常用的指标是**余弦相似度** cos(θ)：只看方向、不看长度，数值越接近 1 越像。",{"code":"# 余弦相似度：越大越像\nimport numpy as np\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\ncat   = np.array([0.9, 0.1])   # 靠近动物方向\napple = np.array([0.1, 0.9])   # 靠近食物方向\ndog   = np.array([0.85, 0.15]) # 很接近猫\n\nprint(round(cosine(cat, apple), 2))  # 0.22  → 语义远\nprint(round(cosine(cat, dog), 2))    # 1.0   → 语义很近","lang":"python"},"维度本质：真实 Embedding（如 OpenAI text-embedding-3）常达上千维，一个词就是一个上千维空间里的点。降维可视化（t-SNE / PCA）只是把上千维『压扁』到 2D 方便人看。"]},{"type":"exercise","prompt":"在一个语义空间里，『国王』向量减去『男人』向量，再加上『女人』向量，猜一猜结果最可能靠近下面哪个词？","opts":["王子","女王（皇后）","父亲","阿姨"],"a":1,"explain":"这正是著名的 king − man + woman ≈ queen 现象：向量的方向承载意义，『王 - 男 + 女』就指向『女王』的方向。它说明 Embedding 抓到的不是孤立的词，而是语义结构。","jump":"sec5-step3","jumpLabel":"用向量距离比较语义这一步"},{"type":"check","title":"结课检测：你真正理解 Embedding 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么不能直接给每个词编个号（猫=1，狗=2，苹果=3）？","opts":["因为编号会让相近的词距离更近","因为编号会破坏语义距离：狗和苹果只差 1，但语义差很远","因为编号需要太多内存","因为编号不能用于神经网络"],"a":1,"explain":"编号把数字距离和语义距离搞混了：狗(2)和苹果(3)只差1会被当成很相似，但它们的含义毫无关系。","jump":"sec4","jumpLabel":"『为什么不能直接给词编号』这一段"},{"q":"两个 Embedding 向量夹角越小（余弦相似度越高），说明什么？","opts":["两个词的语义越相近","两个词的字符串越长越像","两个词出现频率越接近","两个词的长度越接近"],"a":0,"explain":"夹角越小，向量在空间里越靠近，代表语义越相近。这就是『用距离算语义』。","jump":"sec5-step2","jumpLabel":"『用向量距离比较语义』这一步"},{"q":"关于 Embedding 模型与 LLM 的关系，正确的是？","opts":["它们是同一个模型","Embedding 模型把文本变向量、LLM 生成文字，二者分工不同","LLM 内部根本不做 Embedding","Embedding 模型能直接写文章"],"a":1,"explain":"Embedding 模型负责『编码相似度』，LLM 负责『生成内容』，是两个可分开训练的模型。","jump":"sec7","jumpLabel":"『Embedding 模型 vs LLM』那一条对比"},{"q":"Embedding 的『含义』主要来自哪里？","opts":["每个字在字典里的官方解释","这个模型『预测下一个词』时学到的共现模式","开发者手写的规则","词的笔画数"],"a":1,"explain":"一个词的含义 = 它常和哪些词一起出现。模型在大量文本上学到的正是这种共现模式。","jump":"sec5-step0","jumpLabel":"『收集海量文本』这一步"},{"q":"下面哪句关于向量维度的说法正确？","opts":["维度越高一定越好，越细越好","维度越低越好，因为一定更便宜","维度是表达力与成本的权衡，常见几百维就够用，过高更贵且易过拟合","维度只影响颜色不影响语义"],"a":2,"explain":"维度是权衡的结果：高维表达强但贵且易过拟合，低维省但表达粗糙。实际常用几百维。","jump":"sec9","jumpLabel":"深入一节关于维度的说明"}],"done":"你已经理解了『文字 → 数字向量 → 算距离』这条链路，这是 RAG、搜索、推荐共同的地基。","nextLesson":"l-attention"},{"type":"connection","known":["AI 世界全景：模型只能处理数字","Embedding 是文字进入模型的第一道门"],"learned":["文字 → 向量，让电脑能算语义","相近的词向量距离更近，用余弦相似度衡量","Embedding 模型与 LLM 分工不同","向量方向也能承载意义（king − man + woman ≈ queen）"],"next":"有了『每个词是一个数字向量』，下一步就是大招：Attention——模型怎么在一句话里决定『该重点关注哪个词』。这决定了模型能不能读懂『这只狗没咬那只猫，是因为它怕它』里『它』到底指谁。"}]},"l-attention":{"id":"l-attention","title":"Attention｜模型为什么知道该关注哪个词","subtitle":"当模型读到『它』，怎么知道是猫还是狗？为什么句子再长，模型也能把前后的词对上号？","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["attention","qkv","multihead","attention-long"],"prereqLessons":["l-embedding"],"nextLesson":"l-transformer","sections":[{"type":"opening","question":"请读这句话：「小狗跑向小猫，因为它害怕小狗。」这个『它』指的到底是小猫还是小狗？只盯着『它』一个词，谁也说不清——那 ChatGPT 是怎么判断出来的呢？","guess":"有人会说「代词当然指前面离得最近的动物」。但中文里『它』常跨好几个词、甚至跨好几句指代，光看位置根本猜不准。","next":"这节课要讲的就是模型的『读心术』——Attention 注意力机制。它让模型在处理『它』时，回头看一眼整句话，自己判断该靠哪些词来理解『它』。"},{"type":"why","before":"上节课我们把每个词变成了向量。但词是孤立的：『猫』『追』『狗』『它』，每一个都只是单独的一串数字。","problem":"真正的语言是互相指代的。『猫追狗，它跑得飞快』——这个『它』是谁？只看『它』这个词本身，根本答不上来。更糟的是：在 Attention 出现以前，老式模型（RNN）看长句时，越靠前的词就越『记不清』。","need":"我们需要一个机制：在处理任何一个词时，能直接『回看』整句话里的所有词，按相关程度加权吸收它们的信息。这就是 Attention——『注意力』，它解决了『远距离指代』和『长句遗忘』两大难题。","visualNote":"下面你可以亲手造一句中文，点任何一个词，看它把注意力分给了谁。"},{"type":"oneline","text":"Attention 是这样一种机制：模型在理解某个词时，会『回头看一眼』句子里的每一个词，给它们分别打一个权重分——分数越高的词，模型花越多注意力在它身上。于是『它』到底指猫还是狗，模型有了办法分清。"},{"type":"visual","kind":"attention-heatmap","title":"Attention 热力图：点一个词，看它关注谁","hint":"输入一句话，点任意一个词（比如那棵/那株），热力图会显示这个词对其它词的『关注权重』——颜色越深，越关注。试试改动量词，体验权重如何跟着语义线索移动。"},{"type":"intuition","blocks":[{"k":"老师点名：每读一个词都在点名","t":"读到『它』这个词时，模型其实在问：『谁能告诉我『它』指谁？』——它把问题抛向所有词，然后重点听『猫』『跑』这些最相关的答案。"},{"k":"查字典：不是顺序读，而是跳着看","t":"Attention 最反直觉的一点：它不老老实实从左往右读。读到『它』，它像翻开一本字典快速扫过所有词条，直接锁定『猫』『跑』，记下『我主要靠这几个词来理解自己』。"},{"k":"聚光灯：每个词都举着无数盏灯","t":"句子里每个词都举着一盏聚光灯照向其它词。灯越亮，代表『我理解你时越依赖你』。Attention 就是计算这盏灯亮度的过程。远近都一样亮——这是它比老方法强的地方。"}]},{"type":"how","intro":"Attention 到底怎么『算』注意力？核心就一句话：每个词同时扮演三个角色——Query（我找谁）、Key（我是谁）、Value（我的内容），然后『找相似、按相似加权吸收』。","steps":[{"in":"乘上三个矩阵，得到 Q / K / V","process":"每个词的向量分别乘以三个不同的矩阵，变成三个新向量：Query『我要去匹配谁』、Key『我是谁，请拿我来匹配』、Value『我的有效内容』。","out":"单词 → (Query, Key, Value) 三件套"},{"in":"用 Query 和所有 Key 算相似度","process":"以『它』的 Query 为例，和句子里每个词的 Key 做点积（就是 Embedding 课学过的『方向越像越接近』）。","out":"得到分数列表：它 vs 猫 = 高分，它 vs 跑 = 中等……"},{"in":"Softmax 归一化成权重","process":"把所有分数经过 softmax，变成『加起来等于 100%』的权重。这一步保证分数变成可比较、可加权的概率。","out":"注意力权重：猫 0.6、跑 0.25、飞快 0.15……"},{"in":"用权重 × Value 加权求和","process":"把每个词的 Value 乘上对应权重再全部相加。权重大的词，内容在结果里占的份量就大。","out":"『它』的新向量 = 主要吸收了『猫』的信息 → 模型知道『它≈猫』"},{"in":"每个词同时做，得到上下文向量","process":"句子里每个词都执行同一套操作，得到一批『结合了全局上下文的新向量』。","out":"整句话从一串孤立向量 → 一串互相理解的向量"},{"in":"多个头并行（多头注意力）","process":"为了不只从一种角度看，模型并行做多组 Q/K/V（不同随机初始化的矩阵），相当于多个不同视角同时观察。","out":"一个头看指代关系、另一个头看语法结构、再一个看长度……组合出更丰富的理解"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude 生成每个词","note":"每生成一个 token，模型都要对上下文做一次 Attention：决定下一个词更依赖前面的哪部分。这是生成的核心动作。"},{"name":"翻译模型的对齐","note":"把『I love you』翻成中文时，Attention 让『love』和『爱』自动对上号，哪怕位置完全错开（这就是 Cross-Attention 用武之地）。"},{"name":"代码补全","note":"补全函数体时，Attention 帮模型盯住几千行前的函数签名和参数定义，而不是只看到最近几行。"},{"name":"长文档问答","note":"在长文章里问『第三部分的结论是？』，Attention 让模型跳过大段无关内容，直接聚焦第三部分的句子。"}]},{"type":"compare","pairs":[{"a":"RNN 顺序处理","b":"Attention 全局直连","diff":"RNN 必须一个字一个字按顺序传，远处信息会衰减；Attention 让任意两个位置直接相连，没有距离衰减。"},{"a":"Self-Attention","b":"Cross-Attention","diff":"Self 是同句话内部互相理解；Cross 是让一方去『读』另一方（翻译、RAG 上下文注入都用它）。"},{"a":"单头注意力","b":"多头注意力","diff":"单头只有一种看法；多头并行多组 Q/K/V，相当于同时用多个角度理解，效果明显更好。"},{"a":"注意力（Attention）","b":"记忆（Memory）","diff":"注意力是每次计算时动态算出的关注权重，不存下来；记忆是存下来的长期信息。很多人把注意力误当成记忆。"}]},{"type":"mistakes","items":["以为 Attention 是『看一遍就记住』的长期记忆。它不是记忆，而是每次计算时动态分配的关注权重——每次都要重新算，不会存下来。","以为注意力可视化等于模型的可解释性。权重高代表统计上相关，不代表模型逻辑上『是因为这个』。","把『注意力』和『上下文窗口』混为一谈。窗口决定能看多远，Attention 决定窗口内怎么分配关注。","以为只看『最近几个词』。Attention 恰恰是全局的——它牺牲计算量，换来的是真正看全上下文。","以为 Attention 零成本。它的核心开销是 O(n²)：n 个词两两算一遍。这正是上下文窗口成为瓶颈的原因。"]},{"type":"deep","title":"深入一点：从直觉到公式","beginner":["注意力权重加起来等于 1（100%）。Softmax 就是把一坨分数变成『加起来为 1、且大的更大』的数。","不必纠结矩阵怎么算，你只需记住一句口诀：『Query 找人，Key 被找，Value 是内容，三者相乘加权求和』。","它最厉害的地方：任意两个词无论隔多远都能直接相关——远处那个词和眼前这个词，算注意力的成本完全一样，这是它战胜 RNN 的根本原因。"],"advanced":["核心公式：Attention(Q, K, V) = softmax( (Q·Kᵀ) / √d ) · V。除以 √d（d 是向量维度）是为了防止点积过大把 softmax 压死、导致梯度消失。","Self-Attention 的 Q/K/V 都来自同一句话，让句子内部互相理解；Cross-Attention 的 Q 来自一方、K/V 来自另一方（如翻译、RAG 上下文注入）。","复杂度 O(n²)：n 个词两两都算一遍。这正是上下文窗口成为瓶颈的原因，也是稀疏注意力、局部注意力、线性注意力研究的动机。","不要神化注意力可视化：权重高 ≠ 模型真『懂』了，它更多是统计相关而非可解释的因果。",{"code":"# 概念示意：手工算一次注意力（极简 2 词版）\nimport math\n\ndef softmax(xs):\n    ex = [math.exp(x) for x in xs]\n    s = sum(ex)\n    return [e / s for e in ex]\n\nq = [1.0, 0.0]  # 我是『它』的 Query\nks = {\"猫\": [0.9, 0.1], \"狗\": [0.2, 0.8]}  # 两个词的 Key\n\nscores = {w: round(q[0]*k[0] + q[1]*k[1], 3) for w, k in ks.items()}\nprint(\"点积分数:\", scores)\nweights = dict(zip(scores, softmax(list(scores.values()))))\nprint(\"softmax 权重:\", {w: round(v,3) for w,v in weights.items()})\n# 猫的权重明显更高 → 模型认为『它』更像猫","lang":"python"}]},{"type":"exercise","prompt":"「它拿起了那支笔，因为【　】太亮了。」这个【　】里的词，会让『太亮了』把更多注意力分给『笔』而不是『它』，你能猜出最合理的一个词吗？","opts":["灯","笔帽","手","桌"],"a":0,"explain":"『灯太亮了』语义合理，Attention 会让『亮』和『灯』形成高权重连接；而『笔帽太亮了』虽然通顺，但更重要是体会：有了『亮』这个线索，Attention 会去找『最配得上的名词』。模型正是靠大量这样的共现线索来分配注意力。","jump":"sec5-step1","jumpLabel":"用 Query 和 Key 算相似度这一步"},{"type":"check","title":"结课检测：你真的理解 Attention 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"Attention 中 Query、Key、Value 各自的作用，最准确的说法是？","opts":["Q 是内容，K 是找人，V 是被找","Q 在找人，K 是被找的标签，V 是被吸收的内容","三者完全相同","Q 是权重，K 是分数，V 是标签"],"a":1,"explain":"Q（Query）发起匹配去『找谁』；K（Key）告诉别人『我是谁』供匹配；V（Value）是被加权吸收进的真正内容。","jump":"sec5-step0","jumpLabel":"乘上三个矩阵得到 Q/K/V 这一步"},{"q":"为什么说 Attention 解决了 RNN『记不住长句』的问题？","opts":["因为它是顺序处理的","因为任意两个词都可以直接相关，不随距离衰减","因为它把句子变短了","因为它只关心最近的词"],"a":1,"explain":"RNN 依赖顺序传递、距离远信息衰减；Attention 让任意两个位置直接相连、远近一视同仁。","jump":"sec8","jumpLabel":"『以为只看最近几个词』那条误区"},{"q":"把注意力分数做 softmax 是为了什么？","opts":["让负数变成正数","让分数变成加和为 1 的权重，且强调大的","让计算更快","让向量变短"],"a":1,"explain":"Softmax 把一坨任意分数变成『加起来为 1』、且大者更大的概率分布，这样加权求和才合理、可解释。","jump":"sec5-step2","jumpLabel":"Softmax 归一化成权重这一步"},{"q":"Self-Attention 与 Cross-Attention 的区别是？","opts":["没有区别","Self 是同句话内部互相理解；Cross 是让一方去读另一方","Self 只用于图片，Cross 只用于文字","Self 更快，Cross 更慢"],"a":1,"explain":"Self-Attention 的 Q/K/V 来自同一句话；Cross-Attention 的 Q 来自一方、K/V 来自另一方（翻译、RAG 都用）。","jump":"sec7","jumpLabel":"对比区里的 Self vs Cross 那一条"},{"q":"多头注意力（Multi-Head）的本质好处是？","opts":["让模型更快","让模型从多个不同视角同时理解，组合出更丰富的语义","让上下文窗口变长一倍","省掉 Softmax"],"a":1,"explain":"把模型注意力想象成多个不同的专家，各看一面（指代、语法、距离），最后合并，理解更全面。","jump":"sec5-step5","jumpLabel":"多个头并行这一步"}],"done":"你已经理解 Attention 是 Transformer 的心脏。这个『找相似、加权吸收』的机制，也是后面 RAG 把检索结果喂进模型时的同一套逻辑。","nextLesson":"l-transformer"},{"type":"connection","known":["词 → 向量（Embedding）","向量方向越像、语义越近（余弦相似度）"],"learned":["每个词同时扮演 Query / Key / Value 三角色","注意力 = 相似度分数 → softmax 权重 → 加权求和","Self-Attention 让句子内部互相理解，多头提供多视角","Attention 任意位置直连、无距离衰减，解决了长句遗忘"],"next":"Attention 是 Transformer 的心脏。下一课我们把这套注意力装进一个完整的架构：位置编码、多头、归一化……看看它怎么组成一个能真正训练、能翻译能写诗的大模型——Transformer。"}]},"l-transformer":{"id":"l-transformer","title":"Transformer｜大模型的地基架构","subtitle":"为什么 2017 年诞生的它，能横扫翻译、写作、代码、对话？一个 20 分钟看懂『大模型的心脏是怎么拼出来的』。","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"25-30 分钟","difficulty":3,"concepts":["transformer","position-enc","multihead","attention"],"prereqLessons":["l-attention"],"nextLesson":"l-rag","sections":[{"type":"opening","question":"上一课我们有了 Attention，它能让任何两个词互相关注。但只用 Attention 还是没法当一个能工作的模型——它不知道『第 5 个词和第 2 个词』谁先谁后，也堆不了很深。猜一猜：研究人员 2017 年到底在 Attention 外面『加了哪些零件』，才把它拼成了横扫一切的 Transformer？","guess":"很多人以为 Transformer = Attention，觉得『注意力』就是全部。","next":"这节课我们把注意力装进完整的大脑：位置编码、多头、残差、归一化、前馈网络、N 层堆叠。学完你就明白，为什么它能取代 RNN、成为所有大模型的共同地基。"},{"type":"why","before":"上一课我们有了 Attention：任何两个词都能直接互相关注。但这只是一块『积木』，离一个能真正工作的模型还差很远。","problem":"只靠 Attention 不够：1) 它不知道词的位置——『猫追狗』和『狗追猫』词全一样；2) 一层注意力学到的东西有限；3) 想堆深又容易训练不动（梯度消失）。","need":"Transformer 就是给 Attention 配上『位置感、深度、稳定训练』三件装备，把一块积木组装成一台可以训练、可以并行、可以堆得极深的机器。它是 ChatGPT、Claude、Gemini 的共同地基。","visualNote":"下面这张图是 Transformer 的主干流水线，你可以一步一步点开看每一层在干什么。"},{"type":"oneline","text":"Transformer 是 2017 年提出的一个『把注意力机制组装成完整大脑』的架构：它用『多头注意力 + 前馈网络 + 残差连接 + 位置编码』堆成一层又一层的模块，能并行、能训练得非常深，从此成为所有现代大语言模型的共同地基。"},{"type":"visual","kind":"transformer-flow","title":"Transformer 主干流水线：一步一步看","hint":"点击【下一步】，观察一个词从数字向量走到预测下一个词的完整过程：输入 → 位置编码 → 多头注意力 → 残差+归一化 → 前馈网络 → 重复堆叠 → 输出。"},{"type":"intuition","blocks":[{"k":"一个加工厂流水线","t":"把 Transformer 想成一家加工厂：原料是一串向量。每个工位（层）做两件事——同事协作（注意力，大家互通信息）+ 个人精加工（前馈网络，每个词独自想更深）。一层做完送下一层，共 N 层。"},{"k":"用乐高积木来想","t":"Attention 只是其中一块积木。Transformer 是说明书：告诉你这一层要怎么拼——注意力 + 残差 + 归一化 + 前馈，然后复制粘贴 N 次。"},{"k":"办公室里的并行会议","t":"RNN 像只有一个话筒的圆桌，每人必须轮流说（慢）；Transformer 像微信群——所有人同时发言、同时收听（并行快），谁跟谁相关自己匹配（注意力）。这就是它又快又强的秘密。"}]},{"type":"how","intro":"一个词在 Transformer 里的完整旅程。每一步都围绕同一批向量做变换，最后模型学会『预测下一个词』。","steps":[{"in":"输入：词向量 + 位置编码","process":"每个词先查表得到 Embedding 向量。但向量本身不含位置，所以再加一个位置信息（位置编码），让模型知道『这是第 5 个词』。","out":"每个词都带上位置的向量"},{"in":"多头注意力层（同事协作）","process":"这一层让每个词结合全局上下文：用上节课的 Q/K/V 机制，多组并行，输出再拼接。词的『含义』从此包含了周围所有词。","out":"每个词变成理解上下文后的新向量"},{"in":"残差连接 + 归一化（稳定训练）","process":"把『进来的向量 + 注意力算完的向量』加在一起（残差），再做归一化。这就像修了一条高速公路：信息不衰减地直接流过深层。","out":"浅层信息能无损抄近道到达深层，网络可以堆得深"},{"in":"前馈网络 FFN（个人精加工）","process":"一个两层全连接网络，对每个词独立做非线性变换，让模型有能力表达更复杂的关系。","out":"每个词被再想一想，表达能力增强"},{"in":"重复堆叠 N 层","process":"把『注意力 + 残差 + 归一化 + 前馈』复制 N 次叠起来（GPT 有十到上百层）。每层都让词的表示更抽象、更接近任务。","out":"深层的向量已经浓缩了整句话的语义"},{"in":"输出：预测下一个词","process":"最后一层接线性层 + softmax，把向量变成词典里每个词的概率，取概率最高的作为下一个词。","out":"生成一个词 → 拼回输入 → 继续预测下一个词"}]},{"type":"realworld","items":[{"name":"ChatGPT / GPT 系列","note":"Decoder-only Transformer：单纯地一层层预测下一个词，就长出了对话和推理能力。"},{"name":"Claude / Gemini","note":"同一架构的不同工程实现：同样的多头注意力 + 深层堆叠，在尺度与训练技巧上各有差异。"},{"name":"翻译与摘要模型（T5/BART）","note":"Encoder-Decoder 结构：编码器读懂全文，解码器再一句句生成译文或摘要。"},{"name":"代码补全（Codex 前身/Copilot）","note":"把代码当另一种语言喂给 Decoder-only Transformer，学会了补全、续写、改 bug。"}]},{"type":"compare","pairs":[{"a":"RNN","b":"Transformer","diff":"RNN 顺序串行、远处信息衰减、难并行；Transformer 全局直连、天然并行、能堆深。2017 后几乎完全取代 RNN。"},{"a":"Encoder-only（BERT）","b":"Decoder-only（GPT）","diff":"前者双向读全文、擅长理解（分类/检索）；后者只能从左往右、擅长生成（对话/写作/代码）。"},{"a":"单层注意力","b":"N 层堆叠的 Transformer","diff":"单层只做一次互相看；Transformer 把多次『互相看 + 精加工』叠起来，让表示一层比一层抽象。"},{"a":"Transformer","b":"Attention","diff":"Attention 是其中的一个子模块；Transformer 是包含注意力在内的一整套完整架构。很多人把两者画等号，其实 Attention ⊆ Transformer。"}]},{"type":"mistakes","items":["以为『Transformer = Attention』。Attention 只是其中一个子模块，完整架构还包括残差、归一化、前馈、位置编码。","以为 BERT 和 GPT 一样。BERT 双向理解、GPT 单向生成，职权完全不同。","以为层数越多一定越好。层越深效果提升有边际，还带来更大算力和训练难度。","把『位置编码』当可选项。没有它，『猫追狗』和『狗追猫』对模型来说完全一样——这可是天壤之别。","以为 ChatGPT 用的是完整 Encoder-Decoder。GPT 只用 Decoder-only，这是它和 T5 这类翻译模型的关键区别。"]},{"type":"deep","title":"深入一点：从直觉到架构细节","beginner":["位置编码就是给每个词加一个『第几个』的记号，否则『猫追狗』和『狗追猫』对模型来说字全一样。","残差连接简单说就是『进来和出去加一起』，像搭桥——让深层的梯度不会消失，模型才能堆数十上百层。","前馈网络 FFN 是给每个词单独换个角度想一遍，和注意力（词与词协作）分工不同、缺一不可。","GPT 其实只用了 Transformer 的一半：只有解码器那套（Decoder-only），用来不停地预测下一个词。"],"advanced":["核心是 Decoder：每个 token 只看自己和前面（因果掩码 causal mask），保证预测时不偷看未来。这是它和编码器的最大区别。","缩放点积注意力：Attention = softmax( (Q·Kᵀ) / √d )·V。除以 √d 防点积过大导致梯度消失 / softmax 饱和。","三种架构：Encoder-only（BERT：理解）、Decoder-only（GPT：生成）、Encoder-Decoder（T5：翻译/转换）。ChatGPT 系清一色 Decoder-only。","残差连接 + LayerNorm（常采用 Pre-LN 顺序：先归一化再进子层）是训练稳定性的关键工程细节，是它能堆到千亿参数的原因之一。","复杂度 O(n²)：上下文窗口越大成本越高——这直接决定了长上下文为什么贵、为什么要引入 RAG。",{"code":"# 概念示意：位置编码的经典公式（体会它想表达什么即可）\nimport math\n\ndef pos_encoding(pos, d_model=8):\n    vec = []\n    for i in range(d_model):\n        angle = pos / (10000 ** (2 * (i // 2) / d_model))\n        vec.append(round(math.sin(angle), 3) if i % 2 == 0 else round(math.cos(angle), 3))\n    return vec\n\nfor p in [0, 1, 2, 3]:\n    print(f\"第{p}个词的位置: {pos_encoding(p)}\")\n# 每个位置生成一组各不相同的位置向量 → 模型据此知道先后顺序","lang":"python"}]},{"type":"exercise","prompt":"如果完全不给模型位置编码，只给它 Attention，那么『猫追狗』和『狗追猫』这两句话，模型会怎么看待？","opts":["认为它们语义完全不同（追的方向相反）","认为它们几乎一样（词完全相同，注意力无差别混合）","认为它们字数不同","完全无法处理两个词以上的句子"],"a":1,"explain":"注意力是把所有词互相加权求和，本质记不得先后顺序。没有位置编码，模型会认为两句话『字都一样所以差不多』，分不清谁追谁。这正是位置编码存在的意义。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"type":"check","title":"结课检测：你真的理解 Transformer 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 Transformer 需要位置编码？","opts":["为了让向量维度变大","因为注意力本身不含位置信息，没有它『狗追猫』和『猫追狗』无法区分","为了加快计算","为了让训练更快收敛"],"a":1,"explain":"注意力把所有词互相加权、天然不记顺序；位置编码把『第几个』注入向量，模型才知道先后。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"q":"残差连接（Residual）的主要作用是？","opts":["增加参数数量","让信息能无损跨层传递，网络可以堆得很深且训练稳定","让模型更快生成","代替位置编码"],"a":1,"explain":"把输入与输出相加，像搭桥一样让信息直达深层，缓解梯度消失，是能堆几十上百层的关键。","jump":"sec5-step2","jumpLabel":"残差连接 + 归一化这一步"},{"q":"GPT 属于哪种结构？","opts":["Encoder-only","Decoder-only","Encoder-Decoder","既不是编码器也不是解码器"],"a":1,"explain":"GPT 只用解码器（带因果掩码、从左往右生成），反复预测下一个词。","jump":"sec9","jumpLabel":"深入节里 GPT=Decoder-only 那条"},{"q":"Attention 和 Transformer 的正确关系是？","opts":["它们是同一个东西","Transformer 是 Attention 的一个零件","Attention 是 Transformer 的一个子系统，Transformer 是完整架构","完全没有关系"],"a":2,"explain":"Attention ⊆ Transformer：Transformer 在 Attention 之外还包含残差、归一化、前馈、位置编码等。","jump":"sec8","jumpLabel":"『以为 Transformer=Attention』那条误区"},{"q":"为什么说 Transformer 比 RNN 快（并行）？","opts":["因为它跳过了很多词","因为它让所有词同时参与计算，不用一个字一个字排队","因为它更短","因为它的层更少"],"a":1,"explain":"RNN 必须按顺序串行处理每个词；Transformer 所有位置并行计算，谁跟谁相关靠注意力自己匹配。","jump":"sec7","jumpLabel":"对比区 RNN vs Transformer"}],"done":"你已经明白大模型的地基长什么样了。但这个『什么都会的模型』只记得训练时的知识——它不知道你公司的最新政策。下一课解决这个问题。","nextLesson":"l-rag"},{"type":"connection","known":["Attention：Q/K/V 加权求和，让词与词互相关注","词是向量，语义可算相似度"],"learned":["Transformer = 多头注意力 + 残差 + 归一化 + 前馈网络的 N 层堆叠","位置编码让模型感知顺序，否则猫追狗 = 狗追猫","GPT 是 Decoder-only，靠预测下一个词长出能力","O(n²) 复杂度是长上下文贵的根源，引出 RAG"],"next":"Transformer 有了，模型『什么都懂但只记得训练时的知识』。下一课我们解决这个关键问题：RAG——怎么让模型在回答前先到你的资料库查资料，从而答出它没学过的私有内容。"}]},"l-rag":{"id":"l-rag","title":"RAG｜让模型『查资料』再回答","subtitle":"为什么 ChatGPT 不知道你的私有文档？怎么让模型『翻开你的资料』再回答？从切块到生成，一条流水线看懂 RAG。","category":"c07-rag","chapterTitle":"第一章 · RAG 全流程","level":"base","estTime":"30-35 分钟","difficulty":2,"concepts":["rag-pain","rag-pipeline","chunking","emb-vector-store","vector-search","rerank"],"prereqLessons":["l-transformer","l-embedding"],"nextLesson":"l-agent","sections":[{"type":"opening","question":"你的同事把公司 80 页的员工手册发给你，让你问 ChatGPT『年假到底有几天』。但 ChatGPT 根本没见过这本手册——你猜它是会照着手册答，还是自己编一个答案？如果它答错了，该怎么办？","guess":"很多人觉得「那就把整本手册贴上问它」。但手册几十万字，靠粘贴根本塞不进一次对话，而且重点会淹没在噪声里。","next":"这节课要讲的就是正解：RAG 检索增强生成。它让模型在回答前，先去你的资料库里『只挑最相关的几段』，再照着这几段回答——既答得准，又附出处。"},{"type":"why","before":"经过前面几课，我们已经有了一个很聪明的模型（Decoder-only Transformer）。但它有一个致命限制：它只知道训练时见过的东西，而且经常一本正经地编造（幻觉）。","problem":"1) 你的合同、内部 SOP、论文——模型训练时根本没看过；2) 即使看过，版本也早就过期了；3) 让它硬答私有问题，它大概率会编。而重新训练整个模型，又贵又慢又不可能频繁做。","need":"与其改模型的『脑子』，不如每次回答时给它配一本『说明书』：先把相关的资料找出来喂给它，让它照着说。这个思路就是 RAG——简单、便宜、资料随时能更新。","visualNote":"下面这条流水线是 RAG 的完整精神：切块 → 向量化 → 检索 → 重排 → 组装 → 生成。你可以点『运行』亲手体验。"},{"type":"oneline","text":"RAG（检索增强生成）就是：让模型在回答之前，先去你的资料库里检索相关内容，把查到的片段拼进上下文，再让模型照着一小份『精选资料』作答。于是它能回答自己没学过的私有知识，还能顺便指出出处。"},{"type":"visual","kind":"rag-pipeline","title":"RAG 完整流水线：从文档到回答（可交互）","hint":"这就是升级版可交互 RAG 实验：左边填一份『你要提问的文档』，下面输问题，点【▶ 运行 RAG】。观察系统如何切块 → 向量化 → 检索 → 重排 → 组装上下文 → 生成带引用的回答。"},{"type":"intuition","blocks":[{"k":"开卷考试 vs 闭卷考试","t":"普通 LLM 是闭卷考试：只凭脑子里的记忆答题，记不住就编。RAG 是开卷考试：允许你翻资料，翻到相关的那页再答。显然开卷更可靠、更可核对。"},{"k":"图书馆查书再回答","t":"你问『公司年假制度是什么』。RAG 不会直接在记忆里编，而是先去公司知识库检索年假相关文档，找到后引用着回答。"},{"k":"不是变聪明，是带了参考书","t":"RAG 不提升模型智商，而是每次回答都带着最新、属于你的资料。资料一更新，回答立刻跟着更新，完全不用重新训练模型。"}]},{"type":"how","intro":"RAG 分两个阶段：『入库』（离线，把文档变成可检索的向量库）和『查询』（在线，用户提问时检索 + 生成）。下面是完整流程，也是本课的主干。","steps":[{"in":"先想清楚：为什么要用 RAG","process":"场景判断：需要回答私有/最新/超长知识，或答案需要可溯源时用 RAG。如果模型自带答案且内容不敏感，也许不需要 RAG。","out":"RAG 解决『知识更新与私有化』，不是『让模型变聪明』"},{"in":"解析 Parsing","process":"把原始文档（PDF、Word、网页）用解析器抽取出结构化文本，去掉页眉页脚、图表残渣，必要时做 OCR。","out":"干净、可用的纯文本"},{"in":"切块 Chunking","process":"把长的文本切成几百到上千字的小块。切多大、是否重叠、按什么切（标题/段落）直接影响检索质量。","out":"文档 → 若干 chunk（带来源、页码等元数据）"},{"in":"向量化 Embedding","process":"用 Embedding 模型把每个 chunk 变成一个向量（语义相近的向量相近）。","out":"每个 chunk → 一个向量"},{"in":"存入向量库 VectorDB","process":"把『向量 + 原文 + 元数据』存进向量数据库（FAISS、Milvus、pgvector、Qdrant），并建好索引以便毫秒级检索。","out":"可快速相似检索的向量库"},{"in":"检索 Retrieval（含 Top-K）","process":"用户提问时，把问题也向量化，在向量库里找最像的『Top-K 块』（通常 K=5~20，按余弦相似度排名）。","out":"问题 → 排好序的 N 个候选 chunk"},{"in":"重排序 Rerank","process":"初筛的 Top-K 往往有噪音。用一个更精细的模型把 K 个候选再精排，把真正相关的提到最前、滤掉无关项。","out":"更精准的少量片段（通常取前 3~5 块）"},{"in":"组装上下文 + 生成","process":"把精选 chunks 拼进 Prompt，附上问题，提示模型『只依据下面资料回答并引用出处』。LLM 据此生成带引用的回答。","out":"有出处、可更新、针对私有知识的回答"}]},{"type":"realworld","items":[{"name":"NotebookLM","note":"你上传 PDF/视频，它检索你的资料再回答，还能生成带引用的播客、摘要。教科书级 RAG 产品。"},{"name":"企业内部知识库客服","note":"把 SOP、产品手册向量化，客服 AI 查文档再回答，而不是对着空气编。"},{"name":"Claude Projects / 附件上传","note":"给对话挂上资料，模型按需检索引用，本质是一套轻量 RAG。"},{"name":"搜索增强的 ChatGPT / Perplexity","note":"它先联网检索实时网页，再基于检索结果回答——用互联网当『向量库』的 RAG。"}]},{"type":"compare","pairs":[{"a":"RAG","b":"微调 Fine-tuning","diff":"RAG 每次查最新资料、可溯源、便宜、可随时更新；微调是改模型脑子、更适合学风格学格式。知识类更新首选 RAG。"},{"a":"向量检索（语义）","b":"关键词检索（BM25）","diff":"向量找语义相近（换个说法也能找到）；关键词精准匹配字面（找人名/编号更稳）。生产常用『混合检索』互补。"},{"a":"RAG","b":"超长上下文","diff":"RAG 主动挑最相关片段、便宜快速；超长上下文把整本书塞进去、贵且重点容易淹没。大资料库优先 RAG。"},{"a":"RAG","b":"Agent","diff":"RAG 是『查资料再回答的单步机制』；Agent 是『多步决策、自己调用工具的循环』。两者常配合：Agent 需要信息时用 RAG。"}]},{"type":"mistakes","items":["以为 RAG = 把文档一股脑塞进提示词。真正的 RAG 要先切块、向量化、检索、重排，只喂最相关的几块。","忽略 chunking 质量。切坏了，再好的模型也答不准——检索进来自的都是垃圾，这叫『垃圾进、垃圾出』。","以为检索到就完了、不必做 rerank。初检的 Top-K 常有噪音，重排能明显提高准确率。","忘记引用溯源。落地到医疗/法务/企业等严肃场景，没有出处等于不可信。","把 RAG 当成解决幻觉的万灵药。资料里没有、或检索失败时，模型照样可能编——还要做『越权拒答』『检索兜底』。","只在单文档上跑 RAG 就上生产。跨多文档局部推理（关系、总分结构）需要更进阶的方案（如 GraphRAG、切分策略优化）。"]},{"type":"deep","title":"深入一点：把 RAG 的每一个零件都拆开","beginner":["chunk 太小 → 语义不完整；chunk 太大 → 噪音多、可能被截断。常见几百~一千字，配合 20%~50% 重叠（overlap）避免把完整语义在边界切断。","向量相似 ≠ 字面相似：换个说法（『年假』vs『带薪假期』）有时也能检索到，这是向量检索比关键词强的地方。","RAG 不会凭空创造知识，它只会引用你给的东西——资料库质量 ≈ 回答质量。","Top-K 的含义：K 是取前几个相似块。K 太小漏信息，K 太大引入噪音挤占上下文，通常 5~20 之间调。"],"advanced":["混合检索（Hybrid）：向量检索（语义）+ 关键词检索（BM25，精确匹配人名/编号）并行，再用加权或 RRF 融合，互补漏检。","Rerank 为什么必要：初检向量健壮但不精，专门的 rerank 模型（cross-encoder）能逐对精判相关性，显著提升准确率和最终回答质量。","引用溯源（Citation / Grounding）：让模型输出带片段编号，用户可核对来源；对合规落地几乎是刚需。","切分进阶：按章节/标题等『结构感知』切块（structure-aware chunking）、父子块（parent-child）、滚动窗口，都比盲目按字数切更好。","评估：用『召回率（该找到的找到没）+ 准确率（找到的是不是都相关）』评价检索，用『忠实度/有据率』评价最终回答，还要做『检索失败与拒答』的兜底。","Agentic RAG：把检索从单次升级成『多轮自主规划』——Agent 先判断需要什么信息、决定检索哪几个库、必要时多轮追问或修正查询词，而不是一次检索定死。",{"code":"# 概念示意：RAG 里最核心的一步——向量检索（伪代码思路）\nimport numpy as np\n\nchunks = [\"年假制度：入职满一年享 5 天…\", \"报销流程：金额低于 1000 走 OA…\"]\nchunk_vecs = [np.array([0.9, 0.1]), np.array([0.1, 0.9])]  # 示意向量\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\nquery_vec = np.array([0.85, 0.15])  # 用户问题『年假有几天』向量化\ntop_k = 1\nranked = sorted(((cosine(query_vec, v), i) for i, v in enumerate(chunk_vecs)),\n                reverse=True)[:top_k]\nprint('最相关的资料块:', chunks[ranked[0][1]])\n# → 年假制度那一段","lang":"python"}]},{"type":"exercise","prompt":"继上一课：公司手册 80 页，你的知识库已经把它切成几百块并存好向量。现在问『年假有几天』，系统检索返回了 8 个候选块，其中第 3 块是『员工福利总览』、第 7 块是『请假制度细则』。下一步系统应该做什么？","opts":["直接把 8 块全部塞进提示词","对 8 块做 Rerank 精排，只取最相关的 3~5 块再喂给模型","不用检索了，直接让模型猜","把 8 块向量相加存回库里"],"a":1,"explain":"初检的 Top-K 常有噪音。正确做法是先 Rerank 精排，把真正相关的『请假制度』提到最前、滤掉无关的『福利总览』，再只喂少量精选块给模型——既省上下文又更准。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"type":"check","title":"结课检测：你真的理解 RAG 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"RAG 解决的核心问题是？","opts":["让模型数学更好","让模型能回答私有/最新知识并可溯源，而不用重新训练","让模型更快生成","让模型学会编程"],"a":1,"explain":"RAG 的核心价值：用检索到的外部资料补充模型没学过的知识，便宜、可更新、可引用。","jump":"sec5-step0","jumpLabel":"先想清楚为什么要用 RAG 这一步"},{"q":"RAG 的『入库』阶段，正确的顺序是？","opts":["向量化 → 切块 → 存库","切块 → 向量化 → 存库","存库 → 向量化 → 切块","检索 → 切块 → 向量化"],"a":1,"explain":"先把长文档切成 chunk，再逐块向量化，最后连向量带原文存进向量库。检索是查询阶段的事。","jump":"sec5-step2","jumpLabel":"切块 Chunking 这一步"},{"q":"『切块太大（比如把整章当一个块）』最可能带来什么问题？","opts":["向量库存不下","块内噪声多、关键信息被淹没，检索和回答变差","一定比小块更准","会让模型忘掉上下文"],"a":1,"explain":"块太大噪声多、语义杂，检索命中后无关内容挤占上下文，回答质量下降。所以要用合适的块大小 + 重叠。","jump":"sec9","jumpLabel":"深入节里关于 chunk 大小/重叠的说明"},{"q":"为什么生产系统里还要做 Rerank 重排？","opts":["为了多花一点算力","初检的 Top-K 常有噪音，用更精细的模型重排能显著提升相关性与准确率","为了把回答变长","为了跳过 Embedding"],"a":1,"explain":"向量初检健壮但不精，专门的 rerank 模型能逐对精判，把真正相关的片段提到最前。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"q":"资料库里根本没有答案时，一个设计良好的 RAG 系统应该？","opts":["强行编一个最像的答案","在引用不到出处时明确『资料中未找到』或拒答，做检索兜底","把用户问题原样丢回","删掉这个问题"],"a":1,"explain":"RAG 不是幻觉万灵药。检索不到可靠出处时应『越权拒答/检索兜底』，而不是硬编。","jump":"sec8","jumpLabel":"『把 RAG 当万灵药』那条误区"}],"done":"你已经掌握 RAG 的完整流水线和调优要点。现在模型会查资料了，但它还是『你问一句、它答一句』。最后一课，我们让它自己动起手来。","nextLesson":"l-agent"},{"type":"connection","known":["Embedding：文字 → 向量，语义相近的向量相近","Transformer：模型的脑子","上下文窗口：模型一次能看多少"],"learned":["RAG 让模型先检索资料再回答，解决私有/最新/可溯源","完整流程：解析 → 切块 → 向量化 → 向量库 → 检索 Top-K → 重排 → 组装 → 生成 + 引用","chunk 大小/重叠、混合检索、Top-K、rerank、评估、Agentic RAG 等调优点","RAG vs 微调 vs 长上下文 vs Agent 的取舍"],"next":"RAG 让模型会查资料，但模型仍停在你说一句、它应一句。下一课是这个旅程的终点也是新起点：Agent——让模型自己拆目标、自己调用工具、根据反馈循环，把一整件事独立做完。"}]},"l-agent":{"id":"l-agent","title":"Agent｜让 AI 自己动手做事","subtitle":"为什么 ChatGPT 只能在对话框里打字，而 Codex 能改你的代码、跑你的测试、提交 PR？Agent 就是把『会说话』的模型，变成『会做事』的执行者。","category":"c08-agent","chapterTitle":"第一章 · 从会说到会做","level":"base","estTime":"25-30 分钟","difficulty":2,"concepts":["agent-intro","agent-loop","tool-use","agent-planning","agent-memory","agent-reflection"],"prereqLessons":["l-rag","l-transformer"],"nextLesson":"l22-ai-coding","sections":[{"type":"opening","question":"你已经能让 ChatGPT 把某个概念讲得头头是道，也能用 RAG 让它查你的资料。但如果你说『去我 GitHub 仓库里把那个测试失败修掉』——为什么 ChatGPT 只能在对话框里给建议，而 Codex 却能真的打开文件、改代码、跑测试、把活干完？","guess":"有人会说「Codex 的模型更聪明」。","next":"这节课揭穿这个误会：Agent 的厉害不在模型智商，而在于给模型装上一个『决策循环 + 一双能动手的工具』。学完你就掌握 Agent = 模型 + 工具 + 循环这条主线。"},{"type":"why","before":"到这一课，我们有了很聪明的模型、也有了让它查资料的 RAG。但你还是有个困扰：让 ChatGPT 整理个表格它倒是能，让它『去我仓库里改掉那个 bug』，它做不到。","problem":"因为聊天模型只有一张嘴：它只能输出文字，看不见你的文件、读不了你的代码、跑不了测试命令。你让它操作仓库，它连仓库在哪都不知道。","need":"Model（思考）+ Tools（手和眼）+ Loop（循环驱动）= Agent。它想一下 → 动一下 → 看一眼结果 → 再想 → 再动。这就是 ChatGPT 和 Codex 的分水岭。","visualNote":"下面这个循环图就是 Agent 的灵魂——你可以亲手点不同工具，看它每一步怎么决策、怎么应对失败。"},{"type":"oneline","text":"Agent（智能体）不是换个更厉害的模型，而是给模型装上一个『决策循环』：它会自己拆目标、自己调用工具（读写文件、执行代码、搜网页）、观察结果、再决定下一步，如此循环直到把事情做完。同样一个模型，套上这个循环，就从『只会回答』变成了『会做事』。"},{"type":"visual","kind":"agent-loop","title":"Agent 循环模拟器：想 → 做 → 看 → 再想（可交互）","hint":"这是一个升级版交互模拟器：你扮演一个修复 bug 的 Codex Agent，在每个步骤从几个工具里选一个。选对了推进，选错了会得到失败反馈，教你『Agent 正是靠不断试错修正才把活干完』。"},{"type":"intuition","blocks":[{"k":"计算器只会算，助理会办事","t":"普通聊天模型像一台高级计算器：你问它答。Agent 像你的助理：你交代一件事，它自己拆步骤、打电话（调工具）、核对结果，办完给你汇报。"},{"k":"不是变聪明，是变『能动』","t":"它没有比 ChatGPT 更聪明——它只是多了一圈『能动手、能看反馈、能再试』的回路。代码还是那个代码，差别在于它学会了执行-反馈-调整。"},{"k":"有钥匙的实习生 vs 没钥匙的实习生","t":"ChatGPT 是没钥匙的实习生：看到门（需要改文件）只会描述『你应该去改那个文件』。Agent 是有钥匙的实习生：自己开门、改文件、跑测试、看结果、再改。"}]},{"type":"how","intro":"一个 Agent 改 bug 的完整工作过程。核心就一句话：目标 → 循环（想 + 做 + 看）→ 交付。这也是本课的骨架。","steps":[{"in":"理解目标","process":"用户下达：『修好注册页面的 bug』。模型先把模糊目标翻译成具体子任务列表。","out":"一个可执行的任务清单"},{"in":"规划 Planning","process":"它推理出步骤：先找到注册页代码 → 读源码定位问题 → 想怎么改 → 改 → 跑测试验证。","out":"Agenda：找代码 → 读 → 改 → 测"},{"in":"调用工具 Tool Use（做）","process":"它请求调用工具：read_file 读代码、edit_file 修改、run_command 跑测试。工具返回结果。","out":"一次具体的『动手』"},{"in":"观察结果 Observe（看）","process":"看到工具返回值：测试报错，或编译失败。它读到反馈，判断是否达到目标。","out":"对『刚才做对没有』的感知"},{"in":"循环 Loop：再想再做","process":"若未达成，回到『想』：根据报错调整方案，再调用工具。如此循环直到测试通过或放弃。","out":"反复的 agent loop（这正是与 ChatGPT 的本质区别）"},{"in":"交付与汇报","process":"任务完成：向用户总结改了什么、测试结果，甚至主动提交 PR、申请权限。","out":"一件完成的事，而不是一段话"}]},{"type":"realworld","items":[{"name":"Codex / Claude Code","note":"Agentic Coding 的典型：能读你的仓库、找 bug、改代码、跑测试、提交 PR。这就是『ChatGPT 做不到、它做得到』的原因——它装了代码工具 + agent loop。"},{"name":"Cursor / Windsurf","note":"IDE 里的 Agent：理解整个项目上下文，跨多个文件完成重构，而不只是一行行补全。"},{"name":"浏览器 Agent（Browser Use / Operator）","note":"自己打开网页、读取、点击、填表，把逛网页办事自动化。"},{"name":"n8n / 工作流编排","note":"让 Agent 串联多个工具/API 完成端到端业务流程（取数 → 处理 → 发通知）。"}]},{"type":"compare","pairs":[{"a":"Chatbot（聊天机器人）","b":"Agent（智能体）","diff":"Chatbot 只输出文字、终结于回答；Agent 拆目标、调工具、看结果、循环迭代，终结于做成事。"},{"a":"单次工具调用","b":"多步 Agent Loop","diff":"会调一个工具的助手只是初级；真正的 Agent 会根据结果决定下一调用，持续多轮直到完成。"},{"a":"RPA（脚本化机器人）","b":"LLM Agent","diff":"RPA 按写死的剧本执行、一变就崩；Agent 动态推理、能处理没见过的异常情况。"},{"a":"Agent","b":"RAG","diff":"Agent 是『多步决策、自己调用工具的循环』；RAG 是『查资料再回答的单步机制』。Agent 需要信息时常用 RAG 当其中一个工具。"}]},{"type":"mistakes","items":["以为 Agent 只是换了个更聪明的模型。本质差别在『循环 + 工具』，不是模型本身。","以为 Agent 能无限可靠地自主执行。它也会反复失败、会犯错，所以需要权限门槛（approval gate）、观测和护栏。","忽视权限与安全。放任 Agent 删文件/发数据/花钱是最危险的坑，生产环境必须加授权与审计。","把会调用工具当成有规划和反思。会调一个函数 ≠ 会拆解复杂目标并自我修正，后者才是 Agent 的进阶。","以为多 Agent 一定更好。多数场景单 Agent 更简单可控，盲目堆 Agent 只会带来编排复杂度和成本。"]},{"type":"deep","title":"深入一点：Agent 的工程骨架","beginner":["Agent Loop 不是魔法：本质就是模型的 for/while 循环——决定下一步 → 调用工具 → 看结果 → 决定再下一步。","工具（Tool）就是一个函数：read_file、write_file、run_command、web_search。模型学会了在合适时机调用它们。","最朴素的 Agent = LLM + 工具集 + 一个决定何时停止的循环。它也可以有记忆和规划，但核心就是这个循环。"],"advanced":["Tool Use / Function Calling：模型输出结构化的『要调用哪个函数、传什么参数』，由系统执行并把结果喂回去，形成闭环。","记忆分两层：短期（当前任务的对话/工具历史）与长期（跨对话的项目知识、偏好，常存向量库）。","Planning 范式：ReAct（Reason + Act 交替）、Plan-and-Execute（先定计划再逐步执行，plan 可被动态修订）、Tree-of-Thought 等。","权限与安全 Permission：Agent 不会无限乱来——危险操作（删文件、花钱、外发数据）要求用户授权（approval gate）。","MCP（Model Context Protocol）：统一工具/数据源接入协议，让一个 Agent 能标准化接入文件系统、数据库、浏览器等多种工具，避免每家写一套私有接口。","Reflection 反思：让 Agent 回顾刚才失败的原因再调整，显著提升长任务可靠性。多 Agent 协作则是多个专业 Agent 分工。",{"code":"# 概念示意：Agent 循环的骨架，就长这样\nwhile not goal_reached:\n    thought = model.think(state, memory)      # 想：我要做哪一步？\n    if thought.should_stop: break              # 判断是否完成\n    tool_result = call_tool(thought.tool_call) # 做：调用工具\n    state.append(tool_result)                  # 看：把结果存进上下文\n    memory.update(state)                       # 记住教训\n# 交付\nreport(model.summarize(state))","lang":"python"}]},{"type":"exercise","prompt":"你（作为 Codex Agent）被要求『修好登录页的 bug』。你读完代码，发现登录按钮点击后有报错。现在到了『做』这一步——猜一猜，Agent 下一步最合理的选择是哪个？","opts":["直接凭记忆改掉一行代码","先运行测试/查看报错日志，定位错误来源，再决定改哪里","马上发邮件问用户想怎么改","直接重新写整个登录页"],"a":1,"explain":"正确动作是先『看』——运行测试或读日志拿到报错信息，有了反馈才知道要改哪。这正是 Agent loop 里『做』与『看』的配合：不观察就动手，等于闭眼改代码。","jump":"sec5-step3","jumpLabel":"观察结果 Observe 这一步"},{"type":"check","title":"结课检测：你真的理解 Agent 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 ChatGPT 不能操作你的仓库，而 Codex 可以？","opts":["因为 Codex 的模型更聪明","因为 Codex 被接上了工具（读写文件/跑命令）+ Agent 循环，ChatGPT 只有对话输出","因为 ChatGPT 没联网","因为模型大小不同"],"a":1,"explain":"决定性差异不是模型智能，而是 Agent 结构：工具让它能动手，循环让它能做→看→修正直到完成。","jump":"sec2","jumpLabel":"一句话理解 Agent 那条"},{"q":"Agent Loop 的核心循环顺序是？","opts":["看 → 做 → 想","想 → 做 → 看 → 再想","只做不看不回头","想 → 想 → 想"],"a":1,"explain":"标准 agent loop：决定下一步（想）→ 调用工具（做）→ 观察结果（看）→ 根据结果再决定下一步（再想），循环到目标达成。","jump":"sec5-step4","jumpLabel":"循环 Loop 这一步"},{"q":"MCP（Model Context Protocol）主要解决什么问题？","opts":["让模型跑得更快","统一 Agent 接入工具/数据源的接口标准，避免各家用私有协议","代替向量数据库","让模型更聪明"],"a":1,"explain":"MCP 是 Agent 与文件、数据库、浏览器等外部工具的标准化接入协议，一次接入、到处复用。","jump":"sec9","jumpLabel":"深入节里 MCP 那条"},{"q":"下面哪个最能代表『Agent 与 Chatbot 的本质区别』？","opts":["Agent 文字更长","Agent 会拆目标、调工具、看反馈并循环，终结于做成事；Chatbot 只回复文字","Agent 不需要模型","Chatbot 也能调用工具"],"a":1,"explain":"Chatbot 止于回答；Agent 以『做成事』为目标，通过循环驱动工具完成多步任务。","jump":"sec7","jumpLabel":"对比区 Chatbot vs Agent"},{"q":"为什么生产环境里 Agent 的危险操作要加『授权门槛（approval gate）』？","opts":["为了拖慢速度","Agent 也会犯错，删文件/花钱/外发数据必须先经用户确认，防止不可逆损失","模型必须要人帮它思考","为了多收费"],"a":1,"explain":"Agent 并非无限可靠，危险动作必须先授权再执行，是落地安全的关键护栏。","jump":"sec8","jumpLabel":"『忽视权限与安全』那条误区"}],"done":"你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。最后一章会带你顺着这条主线进入真正的 AI 编程实践。","nextLesson":"l22-ai-coding"},{"type":"connection","known":["Transformer：模型怎么生成内容","RAG：怎么让模型查资料","工具调用 Function Calling"],"learned":["Agent = 模型 + 工具 + 循环（想→做→看→再想）","它能拆目标、规划、调用工具、观察反馈、反复修正","关键工程点：Tool Use / Memory / Planning / Permission / MCP / Reflection","Chatbot 回答问题，Agent 做成事"],"next":"到这里，你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。想继续深入，建议顺着目标分支走：做产品学 LLM 应用与 RAG，写代码就进入 AI 编程（Agentic Coding / Claude Code）那一章——用 Agent 亲自改代码、跑测试、提交 PR。"}]},"v01-web":{"id":"v01-web","title":"一个 Web 产品是怎么跑起来的","subtitle":"你在浏览器里敲回车到内容出现，中间发生了什么？把这条链路看懂，你才谈得上『改对地方』。","course":"vibe","courseNo":"01","level":"base","estTime":"15-25 分钟","difficulty":1,"concepts":[],"prereqLessons":[],"nextLesson":"v03-api","sections":[{"type":"opening","question":"你每天打开网页、用 App、点外卖、刷视频——但有没有想过，你在浏览器地址栏输入一串字母并按下回车，到底是哪台机器、用哪段程序、按什么顺序，把你要的内容送到你面前的？","guess":"很多人会回答「就是电脑把网站打开了呀」。","next":"这节课我们不写代码，只把『一个 Web 产品』从头到尾拆开：前端、后端、数据库、服务器、浏览器、网络各是什么，数据是怎么一层层流动的，以及每一层出错时你该怀疑谁。学完你就能对着一屏『转圈』或一条报错，说出它大概死在哪个环节。"},{"type":"why","before":"你想用 AI 辅助做一个自己的小产品（一个网页、一个小工具、一个小网站）。AI 很会写代码，但你写完点开经常『跑不起来』或『一片空白』，你不知道该往哪看。","problem":"问题不在 AI 写的代码——而在于你对『这段代码在什么环境里跑、和谁通信』没有概念。你分不清『报错是我的 HTML 写错了』『还是服务器没启动』『还是数据库没连上』『还是网络被墙了』。于是只能把同样的问题反复丢给 AI，越问越乱。","need":"所以第一课先不碰一行代码，而是先建立『一台 Web 产品从上到下有哪些层、每层做什么』的骨架。当你把『前端 / 后端 / 数据库 / 服务器 / 浏览器 / 网络协议』这条链装进脑子，AI 给的报错就不再是天书，而是能对号入座的线索。"},{"type":"oneline","text":"一个 Web 产品 = 浏览器（前端，负责看得见摸得着的界面）+ 服务器上的程序（后端，负责处理逻辑和读写数据）+ 数据库（负责长期存数据），它们之间靠『网络请求』（HTTP）搬来搬去；而这一切最终都跑在『操作系统 + CPU/内存/磁盘』这台物理机器上。"},{"type":"visual","kind":"request-flow","title":"互动实验：点一次请求，看它走完整条路","hint":"点击『发送请求』，看一次『用户敲回车』的动作如何依次经过浏览器 → DNS 解析 → 网络 → 服务器 → 后端程序 → 数据库 → 再原路返回。每亮起一格就说明数据到了哪一层。"},{"type":"intuition","blocks":[{"k":"用点外卖来想","t":"前端＝你看得到的『点单 App 界面』；后端＝『餐厅后厨，负责接单、炒菜、出餐』；数据库＝『冷库里长期保存的食材和菜谱』；服务器＝『餐厅所在的整栋楼，有水电（CPU/内存/磁盘）』；浏览器就是那个帮你点单、再把菜端到你面前的『外卖小哥』。你看到的每一道菜，都是后厨＋冷库＋外卖小哥协作的结果。"},{"k":"用写信来想","t":"你在浏览器输入网址，就像写一封信：『地址』（域名）要翻译成具体的『门牌号 + 邮编』（IP + 端口），信通过『邮政网络』（网络/IP）送出去，邮局先查收信人住在哪（DNS 解析），送到后对方拆信、处理、再回信。回信能不能到，取决于信中地址写没写对。"},{"k":"一句话记住分层","t":"从上到下：浏览器（前端）→ 网络（DNS/IP/HTTP）→ 服务器 → 后端程序 → 数据库。数据请求沿这条链往下，响应再原路往上。出错时按这条链一层层排查，永远不要跳着乱试。"}]},{"type":"how","intro":"把『输入网址到页面出现』拆成一条 7 步因果链。每一步都回答『数据此刻在哪、谁在处理、为什么能做下一步』。","steps":[{"in":"① 你输入网址，按下回车","process":"浏览器得到一串人类好记的名字，比如 ai-learn.example.com。但网络本身不认名字，它只认数字地址（IP：像 203.0.113.7）。所以第一步要『翻译』。","out":"浏览器准备发起一次『网络请求』"},{"in":"② DNS 解析：把域名翻译成 IP","process":"浏览器向 DNS（域名系统）询问：ai-learn.example.com 对应哪个 IP？DNS 就像电话簿，查到后把『数字地址』告诉浏览器。没有这一步，浏览器不知道该把信寄到哪台机器。","out":"得到了服务器的 IP 地址 + 端口（默认 80/443）"},{"in":"③ 建立连接 + 发送 HTTP 请求","process":"浏览器通过 TCP（可靠的传输协议）连上服务器，然后发送一个『HTTP 请求』：里面写着『我要 GET 这个页面』，还带着浏览器自己是谁（User-Agent / Cookie）等信息。","out":"请求沿着网络，送到那台服务器的指定端口"},{"in":"④ 服务器接收并把请求交给后端程序","process":"这台机器上正跑着一个『服务器进程』（如 Nginx / Node / Python）。它把请求转交给对应后端程序；后端程序执行你自己的业务逻辑：查一查、算一算。","out":"后端程序开始处理：可能要读数据库"},{"in":"⑤ 后端读写数据库","process":"需要持久数据的，后端会去数据库查询或写入。数据库把结果（比如『这个用户的名字』）返回给后端。注意：数据库不住在浏览器里，它住在服务器那台机器上。","out":"后端拿到数据，拼出一份『响应』"},{"in":"⑥ 后端返回 HTTP 响应","process":"后端把生成的 HTML / JSON / 图片，打包成一条『HTTP 响应』发回去，附带状态码（200 成功 / 404 找不到 / 500 服务器出错）与响应头。","out":"响应沿着网络原路回到浏览器"},{"in":"⑦ 浏览器解析并渲染","process":"浏览器收到 HTML，逐行解析：先搭出页面结构，再拉取其中的 CSS/JS/图片等资源，最后把内容画到屏幕上。你这才『看到』了页面。","out":"页面出现在你眼前（一次完整的前后端往返）"}]},{"type":"realworld","items":[{"name":"你平时的网页 = 前端静态页","note":"很多『首页』其实只是浏览器直接渲染的一堆 HTML/CSS/JS 文件，可能根本没有后端。它依然需要前面的 ①②③⑦ 几步，但没有 ④⑤⑥。知道这一点，你排查为何『页面能开但功能没反应』时就能猜到问题多半在后端那段。."},{"name":"登录注册 = 必须有后端 + 数据库","note":"『注册新账号』必须把密码/信息写进数据库，所以必然经过完整的 ①→⑦。前端只是收集输入，真正的校验和存储都在后端 + 数据库。这是『看代码时』判断某功能是否需要后端的标尺。"},{"name":"动态内容（推荐、订单、消息）= 后端在返回数据","note":"你刷到的『为你推荐』是后端程序实时查库、算好、再以 JSON 返回给前端渲染的。这类功能换任何界面（网页/App/小程序）后端代码都基本相同——这也是为什么『前后端分离』这么常见。"},{"name":"云服务器 / 租一台机器","note":"你的产品真正上线后，就『住』在一台云服务器（如腾讯云、阿里云的 ECS）上，这台机器有操作系统、CPU、内存、磁盘，常年开机。你的前端文件、后端程序、数据库都装/跑在这上面。"}]},{"type":"compare","pairs":[{"a":"前端 Frontend","b":"后端 Backend","diff":"前端＝用户看到的界面（运行在浏览器/手机里，负责渲染和交互）；后端＝用户看不到、运行在服务器上的程序（负责业务逻辑、鉴权、读写数据库）。前端决定『长什么样、能不能点』，后端决定『数据对不对、安不安全』。"},{"a":"接口 API","b":"直接操作数据库","diff":"后端对外提供的是『接口（API）』——一个约定好的请求地址与返回格式；前端只调用接口，永远不直接连数据库。这样可以隔离权限、便于维护。这也是产品安全的第一道墙。"},{"a":"本地 localhost","b":"线上服务器","diff":"你在自己电脑上跑的前后端叫『本地环境』，地址常是 localhost:3000；部署上线后跑在云服务器上，是公网地址。很多『本地正常、线上挂』的问题，都源于两套环境不完全一样（如数据库没迁移、环境变量没配）。"},{"a":"TCP（可靠）","b":"UDP（快速但不可靠）","diff":"TCP 会确认每份数据都到达（网页、文件用），UDP 不确认、丢了就丢（实时音视频、游戏用）。Web 的 HTTP 默认走 TCP，所以网络差时表现为『加载慢/卡』而不是『内容错乱』。"}]},{"type":"mistakes","items":["以为『网页能打开 = 后端没问题』——错，很多页面是纯前端静态页，后端可能根本没启动。","报错时随手把错误原样丢给 AI，而不说清『发生在哪个层』——AI 只能瞎猜。正确做法是先定位：报错来自浏览器控制台、后端终端、还是数据库连接？","以为『改完代码点刷新就行』——前端改了刷新即可，后端改了常常要重启服务才能生效；数据库结构改了还要迁移。不知道该不该重启，等于不知道该层是否生效。","把 IP、域名、端口混为一谈——域名给人记，IP 给网络认，端口标识这台机器上『哪个程序在服务』。三者不同。","以为 AI 写的代码『放对文件夹就能跑』——代码必须在『正确的环境』（装好依赖、正确版本、正确目录、可执行的权限）里才能运行。环境对不上，代码再对也是白搭（这正是第 7 课上线的核心矛盾）。"]},{"type":"deep","title":"深入一点：把『机器、程序、运行方式』讲透","beginner":["这台电脑/服务器里面有什么？三样最关键的硬件：","**CPU**（中央处理器）：真正会『算』的部分，负责执行指令。它快、但几乎没有记忆。","**内存 RAM**：临时、高速的『草稿本』，程序运行时把正在用的东西放这里；一断电全清空。","**磁盘 Disk**：长期、慢速的『仓库』，文件、数据库、图片都躺在这；断电也保留。","三者关系：程序从『磁盘』读进来 → 在『内存』里运行 → 由『CPU』逐条执行。所以『进程/线程』就是运行中的程序在内存和 CPU 上的具体存在。","**操作系统（OS）**：介于硬件和你程序之间的大管家。它负责：管理文件、管理进程、分配内存、读写磁盘、管理网络与权限。你的程序不是直接拿 CPU 干活，而是『请操作系统帮你安排』。Windows / macOS / Linux 都是操作系统。"],"advanced":["**编译 (Compile) vs 解释 (Interpret)**：代码有两种变可执行的方式。编译型（如 C、Go）：先整体翻译成机器码，再运行，快但改后要重新编译；解释型（如 Python、JavaScript）：一边翻译一边运行，改了就生效，但慢。","**Runtime（运行时）**：指『解释器 / 虚拟机 / 平台环境』，如 Node.js（能让 JS 在服务器上跑）、Python 解释器、Java 虚拟机（JVM）、浏览器的 JS 引擎（V8）。同一个 JS 文件，在浏览器里和 Node 里跑，用的是不同 Runtime——所以『它在浏览器能跑，不代表服务器能跑』。","**进程 (Process) vs 线程 (Thread)**：进程＝一个独立运行的程序实例，有自己独立的内存（跑崩一个不影响别的）；线程＝进程内部可并发的轻量任务单元，共享进程内存。一个 Node 服务通常是一个进程，一次请求常会用到多个线程/异步任务来并行处理。","**文件 / 路径 / 权限**：一切配置、代码、静态资源都是『文件』，文件有『路径』（在哪个文件夹）和『权限』（谁能读/写/执行）。很多部署报错是『权限不够』（403）或『路径不对』（404）——这不是代码逻辑问题，而是环境问题。","**环境 (Environment)**：你的程序依赖很多东西：命令、依赖包、环境变量、数据库地址、端口。这些合称『运行环境』。第 7 课上线的本质，就是把『你本机那套环境』尽量一致地搬到服务器上。"]},{"type":"ask","title":"怎么用 AI 帮你改代码：先问清『第几层』","scenario":"你的页面打开了，但点击『登录』没反应，控制台报了个错。怎么把这个信息高效地交给 AI？","template":"[我要描述] 我在做一个登录功能，点击登录按钮后页面没反应。\n[它能观测到的现象] 浏览器控制台报错：Cannot read properties of undefined (reading 'catch')，出错在 main.js 第 42 行。\n[我判断在哪一层] 前端 JS 在做请求时出错（尚未到后端）。\n[请给我] 帮我定位 main.js 第 42 行为什么报错，并给出修复方案与原因。","acceptance":["AI 给的答案里是否指明了『问题所在的那一层』（前端/后端/数据库/网络/环境）？","修复方案是否同时告诉你『为什么之前会错』（因果），而不只是『把这段换成这段』？","改完是否教你该怎么验证（例如：刷新？重启后端？看哪个日志？）？","如果 AI 只给了代码而你仍不确定，是否会继续追问『这个报错出现在哪一层、我怎么验证』？"],"tip":"给 AI 的信息越『分好层』，它越能准确判断。‘分层 + 现象 + 报错 + 我的判断’ 四件套，能大幅减少来回试错。"},{"type":"exercise","prompt":"你在浏览器打开自己刚做的网站，页面显示出来了，但点『提交表单』后页面一点反应都没有，浏览器控制台也没报错。根据这一课的分层，你最应该先怀疑哪一层？","opts":["我的 HTML 结构写错了（前端静态层）","后端程序没启动或没连上（后端层）","我的屏幕/显卡坏了（硬件层）","域名没过期（网络层）"],"a":1,"explain":"页面能正常显示说明前端静态层基本没问题；但『提交表单』要发请求给后端，没反应最可能是后端没启动、路径不对、或请求根本没发出去。先检查后端服务在不在跑、接口地址对不对。","jump":"sec7-step3","jumpLabel":"第 ④ 步：服务器接收并把请求交给后端"},{"type":"check","title":"结课检测：你能给报错『分层』了吗","intro":"共 5 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"浏览器里 DNS 解析这一步骤主要解决什么问题？","opts":["把域名翻译成 IP 地址","把 HTML 渲染成画面","把代码编译成机器码","把密码加密"],"a":0,"explain":"网络只认数字 IP，DNS 负责把人类好记的域名翻译成 IP，浏览器才知道该把请求发到哪台机器。","jump":"sec5-step1"},{"q":"『注册新账号后数据能永久保存』，这件事主要由哪几层协作完成？","opts":["只有浏览器（前端）","后端程序 + 数据库，前端只负责收集输入","只有网络（TCP/IP）","只有操作系统"],"a":1,"explain":"注册必须把信息写入数据库才叫『永久保存』；后端程序负责接收并由数据库落盘，前端只是收集输入。","jump":"sec5-step4"},{"q":"『代码在浏览器能跑』是否代表『同样的代码在服务器上也能跑』？","opts":["一定可以","不一定，因为浏览器和 Node/Python 是不同的 Runtime","一定不可以","只和网速有关"],"a":1,"explain":"浏览器里的 JS 由浏览器 JS 引擎跑，服务器上的 JS 由 Node.js 跑，是不同的 Runtime，能力与可用模块不同。","jump":"sec7"},{"q":"一个『Web 产品』由前端、后端、数据库组成。下面哪句最准确？","opts":["前端能直接连接数据库","后端程序通过接口把数据给前端，数据库由后端访问","数据库必须放在浏览器里","后端程序只能写死数据，不能读数据库"],"a":1,"explain":"前端只调用后端提供的接口(API)，后端负责访问数据库并返回结果，这样能隔离权限、便于维护。","jump":"sec7-step5"},{"q":"某功能『本地 localhost 一切正常，部署到线上就报数据库连不上』，最可能是哪两类环境不一致？","opts":["前端字体大小不同","数据库地址/密码/环境变量，以及迁移状态不一致","屏幕分辨率不同","键盘语言不同"],"a":1,"explain":"本地与线上最多的差距是数据库连接信息（地址、账号、密码）、环境变量配置，以及数据库结构是否已迁移。","jump":"sec7"}],"done":"你现在能把『一个 Web 产品』按层拆开了——前端、后端、数据库、服务器、网络各归其位，报错也能分到对应层。下一课我们钻到『后端』这一层：HTTP 到底是什么，API 怎么写、怎么调。","nextLesson":"v03-api"},{"type":"connection","known":["（这是 Vibe Coding 路径的第一课，默认你已经上过《从零看懂 AI》路径或至少了解『模型/产品』概念。）"],"learned":["一个 Web 产品 = 前端 + 后端 + 数据库 + 服务器 + 网络，彼此通过 HTTP 通信","一次请求的 7 步因果链：输入地址 → DNS → 建立连接/HTTP → 服务器 → 后端 → 数据库 → 渲染返回","CPU / 内存 / 磁盘 / 操作系统 / 进程 / 线程 / 编译解释 / Runtime 的定位","前端 / 后端 / 接口 API / 本地 localhost / 线上 的区别","给 AI 提问前先给报错『分层』，能显著提高一次成功率"],"next":"下一步我们进入『后端』层。想了解 AI 生成/理解代码，可回看 AI 路径的《AI Coding》一课；想把这条链路里『数据是怎么被长期记住的』讲透，下一课（API 与后端）与再下一课（数据库、登录与安全）会分别展开。","links":[{"href":"#/lesson/l22-ai-coding","text":"回看 AI 路径《AI Coding：把 AI 变成结对程序员》"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},"v03-api":{"id":"v03-api","title":"API 与后端：前后端怎么『对话』","subtitle":"前端要数据、后端给数据，靠的是一套约定好的『暗号』——HTTP 方法与状态码。看懂它对 AI 来说轻而易举，对你是判断代码靠不靠谱的分水岭。","course":"vibe","courseNo":"03","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web"],"nextLesson":"v04-db","sections":[{"type":"opening","question":"你的 App 在前端里点了个『收藏』按钮，后端怎么知道你要『新增一条收藏』而不是『删除一条』？同样是敲同一个接口地址，凭什么这次是加分、那次是删东西？","guess":"很多人会说『靠传一个名字不一样的按钮』。","next":"答案藏在 HTTP 的『方法（Method）』里。这一课我们把前后端之间的对话协议——HTTP 方法和状态码——彻底讲透：GET 和 POST 到底差在哪，200/404/500 各代表什么，什么是 API、什么是 JSON。学完你会开始『读』接口而不是『猜』接口。"},{"type":"why","before":"AI 写了个后端接口，前端也调了。你看着代码：有一堆 `app.get('/api/friends')`、`app.post('/api/friends')`、`req.body`、`res.json(...)`。你不懂为什么有的用 get 有的用 post，也不知道返回的 `{status:'ok', data:[...]}` 是什么。","problem":"不懂 HTTP 方法与状态码，你会犯两种错：要么把『该用 POST 写数据的操作』写成了 GET，导致数据带在 URL 里、既不安全又不支持大内容；要么拿到报错号 404/500 完全没概念，不知道该看前端还是后端。AI 生成的代码你再不敢动，一改就崩。","need":"把 HTTP 的『动词』（方法）、『回执』（状态码）、『货单』（请求/响应头与正文 JSON）看明白，你就拥有了『判断一段接口代码对不对』的最小能力：方法对不对、状态码合不合理、参数传没传对。这正是把 AI 代码从『能跑』升级到『可靠』的一步。"},{"type":"oneline","text":"API 是后端对外开的一扇扇门（URL），你用『HTTP 方法』说明你想干嘛（GET 拿数据 / POST 新增 / PUT 整体更新 / PATCH 部分更新 / DELETE 删除），后端用『状态码』告诉你结果（2xx 成功 / 4xx 你这边的问题 / 5xx 服务器的问题），数据通常以 JSON 格式在请求和响应里传递。"},{"type":"visual","kind":"http-viewer","title":"互动实验：HTTP 查看器，亲手发一个请求","hint":"选一个方法、填一个地址（或点预设接口），点『发送』。它会向你展示：这次请求带了哪些方法/头部/参数，服务器会返回什么状态码与 JSON 正文，以及每个状态码对应的含义。体会『同一个 URL，方法不同 = 动作不同』。"},{"type":"intuition","blocks":[{"k":"用餐厅点菜来想","t":"API 地址（URL）＝餐厅的『窗口名』，比如『/api/friends』是『朋友窗口』；HTTP 方法＝你点菜的动作——‘看看今天的菜单’（GET）、‘点一个菜’（POST）、‘把整个菜换掉’（PUT）、‘加个辣’（PATCH）、‘退掉这个菜’（DELETE）。后端（厨师）按你的动作处理，再用状态码告诉你：‘上菜了’（200）、‘这个菜没有’（404）、‘厨房炸了’（500）。"},{"k":"用寄快递来想","t":"GET 就像‘查单号’——只读，不改变任何东西，可以来很多次；POST 就像‘下单寄件’——会产生一个新的快递（新增数据）。所以‘收藏、下单、注册、发帖’这些会新增数据的操作用 POST，而‘翻页、搜索’这种只看不动的用 GET。"},{"k":"一句话记住状态码","t":"2 开头的都成功；3 开头的是‘让你去别处看’（重定向）；4 开头的是‘你（客户端）的问题’（404 找不到、401 没登录、403 没权限、400 请求写错）；5 开头的是‘服务器（后端）的问题’（500 内部出错）。看到 4 或 5，你就能立刻判断该检查哪一边。"}]},{"type":"how","intro":"把一个 HTTP 请求拆成 5 个部分，从头到尾走一遍『前端 → 后端 → 响应回前端』。","steps":[{"in":"① 请求行：方法 + URL","process":"前端发起一行字：`POST /api/friends`。前半是方法（动作），后半是接口地址（去哪扇门）。这决定了后端接下来执行哪段逻辑。","out":"例如 POST = 新增；GET = 查询；DELETE = 删除"},{"in":"② 请求头 Headers","process":"附带的一堆元信息：Content-Type（正文是 JSON 还是表单）、Authorization（登录凭证，如 Bearer token）、Accept（你想要什么格式）、携带的 Cookie 等。后端靠这些判断『你是谁、你给的是什么』。","out":"身份与格式声明"},{"in":"③ 请求正文 Body","process":"POST / PUT 需要把要写入的数据放进正文，通常是 JSON：`{\"name\":\"小明\",\"phone\":\"138...\"}`。GET 一般没有正文，参数放在 URL 查询串里（?name=小明）。","out":"数据内容（多为 JSON）"},{"in":"④ 后端处理并返回状态码","process":"后端读到方法+地址+头+正文，跑对应的逻辑，无论成败都返回一个状态码：成功 200/201，找不到 404，参数错 400，没登录 401，服务器异常 500。","out":"状态码：2xx / 4xx / 5xx"},{"in":"⑤ 响应正文 + 响应头","process":"成功后后端通常返回一个 JSON：`{\"ok\":true,\"data\":{...}}`，前端拿到这个结构再决定如何渲染。响应头里也常有 Set-Cookie、Cache-Control 等控制信息。","out":"前端拿到 JSON，渲染到界面"}]},{"type":"realworld","items":[{"name":"浏览器开发者工具 Network 面板","note":"按 F12 → Network，你能亲眼看到每一笔请求：方法、URL、状态码、耗时、请求/响应头与 JSON。这是『读接口』最重要的工具，AI 给不了你，但它能解释你从里面截到的任何一行。"},{"name":"REST 设计风格","note":"REST 是一套流行的接口组织约定：把『资源』当名词放 URL（/users、/posts），把动作当方法（GET/POST/PUT/DELETE）。例如 GET /users/5 读用户5，DELETE /users/5 删用户5。看懂 REST，你便看懂了大半后端代码的结构。"},{"name":"第三方开放 API（天气/支付/地图）","note":"你在产品里调的天气、支付、地图接口，就是对面公司后端暴露的 API。你会看到它要求固定方法、固定鉴权头（Authorization/ApiKey）、返回固定 JSON 结构。会读 API 文档 = 会接第三方能力。"},{"name":"前后端分离项目","note":"很多现代项目前端与后端是两个独立工程，只通过一组 API 契约对接。只要接口约定不变，前端可以换成任何形态（网页/App/小程序），后端完全不用改。这也解释了为什么『接口规范』如此重要。"}]},{"type":"compare","pairs":[{"a":"GET","b":"POST","diff":"GET 用于『读』数据：参数放 URL，可分享/可缓存，不应产生副作用（不会改服务器的数据）；POST 用于『写』数据：参数放正文，用于新增/提交，会产生副作用。安全与不大数据量的操作用 GET，会改数据的操作用 POST。"},{"a":"状态码 4xx","b":"状态码 5xx","diff":"4xx 是『客户端问题』：请求写错、没登录（401）、没权限（403）、找不到（404）——请检查你前端发出去的请求；5xx 是『服务器问题』：后端代码异常（500）、超时（504）——请检查后端日志。"},{"a":"REST API","b":"GraphQL","diff":"REST 靠『多个端点 URL + 方法』组织接口；GraphQL 靠『一个端点 + 查询语句』按需取字段。REST 更简单通用、生态大；GraphQL 更灵活但要学查询语法。入门从 REST 开始最稳。"},{"a":"JSON","b":"表单 Form-encoded","diff":"JSON 是一种结构化文本（{\"k\":v}），后端好解析、支持嵌套，是现代 API 主流；传统表单格式（a=1&b=2）较简单但在复杂数据前吃力。看到 Content-Type: application/json 就知道后面是 JSON。"}]},{"type":"mistakes","items":["AI 常犯（也常让你中招）的错误案例①：把『该用 POST 的新增操作』写成了 GET，导致密码等敏感数据出现在 URL / 日志里，既不安全又不支持大内容。","错误案例②：删改操作应返回合适状态码，却一律返回 200——前端永远‘成功’，数据却没被真正删掉。看到代码里所有分支都 res.json({ok:true}) 且不看状态码，就要警惕。","错误案例③：前端没把 token/Cookie 带上（没设置 headers.Authorization），导致后端每次回 401；前端却把锅甩给‘后端 bug’。判断法：看 Network 里那次请求的请求头带没带凭证。","把 404 理解成‘页面不见了’就完事——404 也可能是‘接口地址写错’，要不检查前端 URL，要不检查后端路由。/api/users 与 /api/user 差一个字母就是两个世界。","盲目照抄 AI 生成的接口而不看返回结构：前端拿 res.data.data 却和接口对不上，出来全是 undefined。学会看 Network 里真实的 JSON 结构再写渲染。"]},{"type":"deep","title":"深入一点：怎么判读一段 AI 写的接口代码","beginner":["拿到 AI 写的后端接口，按下面三问逐一看，就能快速判断靠不靠谱：","**一问方法**：这个操作该不该用这个 HTTP 方法？读操作用 GET，写操作用 POST/PUT/DELETE。方法不对 = 语义错。","**二问状态码**：成功路径返回 2xx 吗？参数错返回 400 吗？没登录返回 401 吗？没有的数据返回 404 吗？服务器异常会抛 500 吗？一个只返回 200 的接口是不合格的。","**三问数据流**：后端取参数的字段名，和前端传的字段名一致吗（body.name）？返回的 JSON 结构和前端 res.data.xxx 对得上吗？对不上就是坑。"],"advanced":["**express（Node 后端框架最小示例）**：","```js\napp.get('/api/users/:id', async (req, res) => {\n  const user = await db.one('SELECT * FROM users WHERE id=$1', [req.params.id]);\n  res.status(200).json({ ok: true, data: user });\n});\n```","注意三件事：`:id` 是路径参数（req.params.id）；操作是读 → 用 GET；成功返回 200。若查不到应 `return res.status(404).json({ok:false})`，而不是硬返回 200 空对象。","**错误处理缺失是最大隐患**：AI 常写出‘只管成功不管失败’的接口。可靠接口要捕获异常并返回 5xx：","```js\napp.post('/api/users', async (req, res) => {\n  try { await db.insert('users', req.body); res.status(201).json({ok:true}); }\n  catch (e) { console.error(e); res.status(500).json({ok:false, msg:'写入失败'}); }\n});\n```","**‘如何向 AI 验收一个接口’**：让 AI 给出‘该方法、正常/异常状态码、请求/响应 JSON 示例’三件套；你再对照 方法→语义 是否正确。能给出完整三件套的接口定义，才值得写进产品。"]},{"type":"ask","title":"怎么用 AI 帮你写/改一个接口","scenario":"你让 AI 写一个‘新增好友’的后端接口，并希望它可靠、前后端好对接。","template":"[我要做一个] POST /api/friends 的新增好友接口。\n[我希望的入参] JSON：{ nickname, remark }。\n[我希望的结果] 成功后返回 201 + {ok,data};昵称为空返回 400;后端异常返回 500。\n[请给我] 完整的 Node/Express 代码（含错误处理），并附：请求示例 JSON、成功/失败状态码与返回体、以及前端如何 fetch 调用的示例。","acceptance":["接口是否用对了 HTTP 方法（新增→POST）？","是否覆盖了成功(201)、参数错(400)、服务器错(500) 至少三类状态码？","请求与响应 JSON 结构是否给出、且前后端字段名一致？","是否包含 try/catch 错误处理而不是只管成功？用浏览器 Network 面板实测一下接口是否按文档返回。"],"tip":"把‘我要什么入参 + 我要什么结果 + 我要什么状态码’写成模板，AI 生成的接口会立刻规范很多；再用 Network 面板实测验证，别只看它嘴上说‘OK’。"},{"type":"exercise","prompt":"你在前端写了一个请求，点按钮后 Network 面板显示某请求返回 401。你最应该先检查什么？","opts":["后端 SQL 写错了","前端这次请求有没有带上登录凭证（Authorization/Cookie）","服务器机器坏了","网络 DNS 解析失败"],"a":1,"explain":"401 = 未认证/未登录，最常见原因就是请求没带凭证。去看 Network 里这一次请求的请求头，确认是否带了 token 或 Cookie。","jump":"sec5-step1","jumpLabel":"第 ② 步：请求头 Headers"},{"type":"check","title":"结课检测：你会读 API 了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"‘把一条收藏记录保存起来’应该用哪个 HTTP 方法？","opts":["GET","POST","PUT","DELETE"],"a":1,"explain":"产生新数据的写操作应该用 POST；GET 只用于读，不该产生副作用。","jump":"sec5-step0"},{"q":"状态码 401 表示什么？","opts":["找不到页面","未认证/未登录","服务器内部错误","请求太大"],"a":1,"explain":"401 Unauthorized = 未认证，需要登录凭证；403 才是‘已登录但没权限’。","jump":"sec5-step4"},{"q":"看到返回 500，你优先怀疑哪一层？","opts":["前端渲染","浏览器缓存","后端程序异常","CSS 样式"],"a":2,"explain":"500 = Internal Server Error，是服务器（后端）处理出错，去查后端日志与代码。","jump":"sec5-step4"},{"q":"REST 接口中，URL 里的名词代表什么？","opts":["动作（增删改查）","资源（如 /users、/posts）","设计者名字","数据库类型"],"a":1,"explain":"REST 把资源当名词放 URL，动作由 HTTP 方法表达。GET /users/5 是‘读用户5’。","jump":"sec6"},{"q":"前端请求里，登录凭证通常放在哪个位置？","opts":["URL 查询串","请求头 Headers（如 Authorization）","CSS 文件","浏览器书签"],"a":1,"explain":"凭证（token/Cookie）一般放在请求头里，如 Authorization: Bearer xxx；不放会导致 401。","jump":"sec5-step1"}],"done":"你已经能读懂前后端之间的‘暗号’了：方法定动作、状态码定结果、JSON 传数据。下一课我们把线的另一头——数据本身——讲清楚：数据库怎么设计，登录与安全怎么做。","nextLesson":"v04-db"},{"type":"connection","known":["你已经知道一个 Web 产品 = 前端 + 后端 + 数据库，通过 HTTP 通信（上一课）。","你已经会调用模型/看得懂 AI 相关 API 的基础概念（AI 路径）。"],"learned":["HTTP 方法：GET 读 / POST 写 / PUT 整体更新 / PATCH 局部更新 / DELETE 删除","状态码：2xx 成功 / 4xx 客户端问题 / 5xx 服务器问题","请求 = 方法 + URL + 头 + 正文(JSON)；响应 = 状态码 + JSON","REST 设计：名词当资源，方法当动作","给 AI 描述接口需求时，用‘入参+结果+状态码’三件套模板"],"next":"接口是承上启下的：它把‘数据’从后端递给前端。可数据从哪来、怎么存、怎么保证安全？这正是下一课《数据库、登录与安全》要解决的。和 AI 路径的联系：你调用大模型 API 的本质也是‘前端→HTTP→别人家后端的接口’，底层逻辑完全相同。","links":[{"href":"#/lesson/l16-llm-api","text":"回看 AI 路径《用 API 把模型接进你的产品》(规划中)"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},"v04-db":{"id":"v04-db","title":"数据库、登录与安全","subtitle":"数据是产品的命，登录是产品的门。这一课把‘数据怎么存’、‘你怎么证明是你’、‘怎么防坏人’讲透。","course":"vibe","courseNo":"04","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api"],"nextLesson":"v07-deploy","sections":[{"type":"opening","question":"用户注册了账号、收藏了文章、下了单——这些数据如果不做任何抽象地乱放在一起，会出什么问题？‘收藏’和‘用户’之间到底是什么关系？而你按下‘登录’，服务器凭什么相信你就是那个人，而不是冒充的？","guess":"很多人觉得‘数据随便存个文件不就行了，登录就是在数据库里对一下密码’。","next":"这一课回答三件事：①数据用‘关系表’组织才不乱（表、列、主键、外键、索引、SQL）；②‘登录’不是查一下密码那么简单——Session、JWT、OAuth 各是怎么证明‘你是谁’的；③坏人会怎么攻击（SQL 注入、XSS），以及怎么守住（参数化、转义、加密/哈希、最小权限）。"},{"type":"why","before":"AI 帮你生成登录/注册/收藏/下单功能，里面全是你不认识的词：SQL、primary key、foreign key、index、session、token、bcrypt、JWT、OAuth、SQL 注入。你照抄能跑，但出问题时完全无法判断是‘表没建对’‘还是登录逻辑错’‘还是被人攻击了’。","problem":"数据库设计与安全是‘你几乎不会让 AI 自己随便发挥’的地方——因为数据是用户资产、登录是安全边界。如果不懂“为什么用户表要 id 做主键”“为什么密码要哈希不能存明文”“为什么 SQL 要参数化防止注入”，你根本没法验收 AI 的代码，等于把产品最关键的部分交出去赌运气，早晚出事。","need":"这一课把最少必备的数据库设计与安全知识补上：会看表结构、会写最基础的 SQL、能对比 Session / JWT / OAuth、知道 SQL 注入和 XSS 是什么并知道对应防御。这样当 AI 给出表结构和登录代码，你能像审稿人一样快速挑出明显错误。"},{"type":"oneline","text":"产品数据大多存在关系型数据库（如 PostgreSQL/MySQL）：数据按‘表’组织，每行一条记录，靠‘主键’唯一标识，表与表用‘外键’建立关系，用 SQL 增删改查；登录靠加密凭证证明身份（Session 服务端记、JWT 它自己证明、OAuth 让第三方背书）；安全的核心三件事——密码要哈希不要明文、SQL 用参数化防注入、输出要转义防 XSS。"},{"type":"visual","kind":"db-designer","title":"互动实验：设计一张数据库表","hint":"这是一个迷你‘表设计器’：你决定表有哪些列、哪列是主键、要不要加索引、要不要存密码明文。点击‘预览 SQL / 检查问题’，它会告诉你这张表会不会踩主键、密码明文、可空、无索引等常见坑。体会‘多花一分钟设计，省无数 bug’。"},{"type":"intuition","blocks":[{"k":"用班级花名册来想","t":"数据库里的‘表’就像一张花名册：‘列’是表头（学号、姓名、班级），‘行’是一条记录（某个同学）。‘主键（primary key）’＝学号——全班唯一，靠它能精准找到某个人；‘外键（foreign key）’＝‘本班编号’——它指向另一张‘班级表’的主键，从而把两张表关联起来。没有主键，你用‘姓名’找人会遇到重名；没有外键，班级和学生就接不上。"},{"k":"用门禁卡来想登录","t":"Session＝你在前台刷了一次脸后，前台给你一把只在这栋楼有效的临时钥匙，钥匙上是你进门时发的一个号码（sessionId），门卫每次核对后台名单；JWT＝一把自带信息的加密卡片，上面写着‘我是小明，3 小时后过期’，门卫验签名就放行，不用每次查后台；OAuth＝你出示‘微信已认证’的凭证，门卫信微信的背书就让你进。三种都是‘证明你是你’，只是证明的方式和存放地点不同。"},{"k":"一句话记住安全","t":"密码只存哈希（加盐），不存明文；SQL 永远用参数化（?/$1 占位符），别拼字符串；输出到页面要转义（防 XSS）；后端始终校验，前端校验只是体验。记住这四条，你能挡住绝大多数入门级攻击。"}]},{"type":"visual","kind":"auth-compare","title":"互动实验：Session / JWT / OAuth 三种登录横评","hint":"点击三种登录方式，看同一个‘登录→鉴权→访问’场景在后台是怎么不同的：状态存在哪、怎么验证、有没有跨端问题、优缺点一目了然。帮你给产品选对登录方案。"},{"type":"how","intro":"把‘数据入库 + 登录鉴权’拆成两条因果链：先看一张表从设计到查询怎么走，再看一次登录如何完成。","steps":[{"in":"① 设计表结构（Schema）","process":"确定这张表存什么：用户表要有 id（主键）、username、password_hash、created_at。列的类型要选对（数字用 integer、文本用 varchar）。先想好‘要回答什么问题’，再定表，否则后面改结构（迁移）很麻烦。","out":"一张结构清晰的表 + 主键"},{"in":"② 建表 + 加索引","process":"用 SQL 建表；对‘经常按它来查’的列（如 username）加上索引（index），否则数据多了每次都全表扫描、慢到卡死。索引=书的目录，能加速查找。","out":"表建好，查询有索引加持"},{"in":"③ 用 SQL 增删改查","process":"INSERT 插入、SELECT 查询、UPDATE 更新、DELETE 删除。查询可加 WHERE 过滤、JOIN 关联别表。这是后端操作数据库的日常。","out":"数据被正确写入/读出"},{"in":"④ 表和表用外键建立关系","process":"比如‘收藏表’里放一个 user_id 外键指向用户表、一个 article_id 指向文章表，就能表达‘这个用户收藏了那篇文章’的关系。","out":"数据之间有明确关联，不重复、不乱"},{"in":"⑤ 登录：验证 + 发凭证","process":"用户输入密码 → 后端把输入的密码加盐哈希，和库里存的那个哈希比对 → 相同则信任，创建会话凭证（Session 存服务端 / JWT 返回一个 token / OAuth 走第三方）。","out":"前端拿到凭证，后续请求都带上它"},{"in":"⑥ 访问控制：每步鉴权","process":"后续每个需要身份的请求，后端都校验凭证 → 合法才放行，非法返回 401。同时用权限逻辑控制在‘只能动自己的数据’（不能改别人的）。","out":"只有合法用户能访问其权限内的数据"}]},{"type":"realworld","items":[{"name":"用户系统崩了=数据库没备份/没迁移","note":"很多线上事故是数据库结构改了没做迁移，或连接串配错。知道‘表结构=产品地基’，你就会让 AI 在改表时同步给迁移脚本（ALTER TABLE…），并先在本地/测试库验证。"},{"name":"密码泄露事件=明文存储的代价","note":"反复出现的‘XX 网站密码库泄露’事故，根源常是明文或弱哈希存密码。正确做法：bcrypt/scrypt 加盐哈希。这是判断 AI 登录代码‘安全与否’的第一眼标准。"},{"name":"登录方案选择=产品形态决定","note":"简单网页用 Session 就够；前后端分离/多端（App+网页+小程序）常用 JWT；要‘微信一键登录’就用 OAuth。你会常看到这三者在真实项目里混用（如 JWT 登录 + 微信 OAuth 授权）。"},{"name":"防火墙/最小权限=运维层防御","note":"生产数据库通常不直接暴露公网，只允许服务器内网访问；应用账号只给它需要的库表权限。这是安全纵深的一部分，和‘代码那次注入’互补。"}]},{"type":"compare","pairs":[{"a":"Session（服务端会话）","b":"JWT（令牌）","diff":"Session 把状态存在服务器（内存/Redis/库），客户端只持一个 sessionId，好处是可随时踢人/注销；JWT 把身份信息加密签进 token 给客户端，服务器无状态，好处是天然适合多端与分布式，缺点是一旦签发难在过期前吊销。选型：传统/单一服务用 Session，前后端分离多端多用 JWT。"},{"a":"JWT","b":"OAuth","diff":"JWT 是一种‘凭证格式’（我信任它的签名）；OAuth 是一种‘授权协议’（用户把权限授予第三方，如‘微信允许这个 App 读我的昵称头像’）。OAuth 常把 JWT 当作其中一种 access_token 的载体。"},{"a":"哈希 Hash（单向）","b":"加密 Encrypt（可逆）","diff":"哈希不可逆：密码只做比对，任何人（包括你自己）都无法还原，适合存密码；加密可逆：能解回原文，适合传输敏感信息（但要妥善保管密钥）。拿加密去存密码是常见误区。"},{"a":"SQL 注入","b":"XSS 跨站脚本","diff":"注入是‘坏人把 SQL 代码塞进输入，骗后端执行’，防御靠参数化查询；XSS 是‘坏人把脚本塞进页面内容，骗浏览器执行’，防御靠输出转义。一个打数据库、一个打浏览器，都要防。"}]},{"type":"mistakes","items":["错误案例①（AI 高频）：密码用明文存进数据库列 `password`。正确是 `password_hash` 且用 bcrypt/scrypt 加盐哈希。看到列名叫 password 就要警觉。","错误案例②（致命）：SQL 用字符串拼接——`SELECT * FROM users WHERE name = '` + input + `'`。坏人输入 `' OR '1'='1` 就能登录一切人。必须改成参数化：`WHERE name = $1`（PG）或 `?`（MySQL）。","错误案例③：用户表没有主键，或把‘用户名’当唯一标识——重名就会数据错乱。主键必须稳定唯一（通常用自增 id 或 UUID）。","错误案例④：前端校验当安全边界——‘我在前端限制了只能填数字’并不能挡住直接调接口的攻击者。真正的校验必须在后端。","错误案例⑤：把 token 存 localStorage 又不设过期、也不校验是不是当前用户——一旦 XSS 就能偷走凭证。安全要‘防御纵深’，别只做一层。"]},{"type":"deep","title":"深入一点：手把手判读一张 AI 建的‘用户表’和登录接口","beginner":["看一张 AI 生成的用户表，先问五件事：","**有没有主键？** 要有 id（或 UUID）作主键，能唯一稳定地定位记录。","**密码是不是哈希列？** 应该叫 password_hash / password_digest，用 bcrypt，绝不存明文。","**必填列有没有 NOT NULL？** 用户名、密码哈希不能为空。","**会不会被注入？** 查询语句是不是参数化的（用占位符而非拼接）？","**有没有做访问控制？** 比如‘只能读自己的数据’，而不是任何人传个 id 就能读到别人的。"],"advanced":["**合法但可以更好的设计**：除了基础列，常加 created_at/updated_at 时间戳（审计用）；经常按 username 查就加唯一索引 `UNIQUE(username)`；邮箱/手机号单独存或用正则后端校验。","**登录接口应返回什么**：成功后（201/200）返回凭证；密码错返回 401；账号不存在也返回 401（而不是 404，避免暴露‘这账号存在’）。失败要记日志，但日志里别打明文密码。","**一个可参考的 SQL 建表**：","```sql\nCREATE TABLE users (\n  id BIGSERIAL PRIMARY KEY,\n  username VARCHAR(50) NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n```","**登录校验（参数化防注入的示范）**：","```js\nconst row = await db.oneOrNone('SELECT * FROM users WHERE username=$1', [username]);\nconst ok = row && await bcrypt.compare(password, row.password_hash);\nif (!ok) return res.status(401).json({ ok:false, msg:'用户名或密码错误' });\n```","注意 `$1` 占位符 + `[username]` 参数数组 = 参数化，SQL 注入无从下手。"]},{"type":"ask","title":"怎么用 AI 帮你设计数据库和登录","scenario":"你做了一个‘用户能注册、能收藏文章’的小产品，想让 AI 一次性给出靠谱的表设计和登录方案。","template":"[产品场景] 用户注册登录后，可以收藏文章（一个用户可收藏多篇文章）。\n[请帮我设计] ①用户表与收藏表的结构（含主键、外键、索引）；②注册/登录后端代码，密码用 bcrypt 加盐哈希、SQL 用参数化防注入；③返回 401/201 等状态码。\n[验收标准] 请说明：主键是谁、外键怎么关联、密码如何存储、如何防 SQL 注入、登录凭证用 Session 还是 JWT 并说明理由。","acceptance":["表结构是否给出了主键、外键和需要加的索引？","密码是否明确用了 bcrypt 之类加盐哈希而非明文？","SQL 是否参数化（占位符）而非字符串拼接？","登录凭证方案是否说明了 Session/JWT 的选择及理由？是否覆盖成功与失败状态码？"],"tip":"涉及数据库和安全，务必让 AI 把‘为什么这么做’讲出来，而不能只给代码。你再用上面的‘五问’走一遍，就能当半个审查。"},{"type":"exercise","prompt":"你的登录接口被人用输入 `' OR '1'='1` 打穿了，任何密码都能登进去。这最可能是下面哪种代码导致的？","opts":["用 bcrypt 哈希密码","SQL 用了字符串拼接用户输入（未参数化）","给 username 加了唯一索引","登录返回了 401"],"a":1,"explain":"把用户输入直接拼进 SQL 会造成 SQL 注入——输入里含有的引号和 OR 让查询恒真，从而绕过密码。改成参数化查询即可堵住。","jump":"sec8","jumpLabel":"深入一点的 SQL 注入示范段"},{"type":"check","title":"结课检测：数据库与安全你真的懂了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"用户的‘收藏表’要关联用户和文章，最正规的做法的核心是？","opts":["把所有用户名和文章名塞进同一列","用外键 user_id 和 article_id 分别指向用户表、文章表的主键","每次复制一份用户表","收藏不存数据库"],"a":1,"explain":"用外键指向各自表的主键，才能表达‘哪个用户收藏了哪篇文章’的关系且不重复存储。","jump":"sec5-step3"},{"q":"密码正确的存储方式是？","opts":["明文存进 password 列","加密（可逆）后存","加盐哈希（如 bcrypt）后存，且不存明文","存进 cookie"],"a":2,"explain":"哈希是不可逆的，任何人不包括你自己都无法还原密码，只能用于比对；加盐防止相同密码产生相同哈希。","jump":"sec5-step4"},{"q":"SQL 注入的根本防御是？","opts":["在前端把输入框禁用","用参数化查询（占位符）","把数据库放到公网","把 SQL 写成大写字母"],"a":1,"explain":"参数化查询把用户输入当作数据而不是可执行的 SQL 代码，因此注入失效。","jump":"sec8"},{"q":"Session 与 JWT 的区别，哪句最准确？","opts":["Session 把状态存服务器，JWT 把身份信息加密进令牌交给客户端","两者完全一样","JWT 不能加密","Session 只用于 HTTPS"],"a":0,"explain":"Session 服务端有状态、可随时注销；JWT 无状态、令牌自证身份，适合多端，但签发后较难在过期前撤销。","jump":"sec6"},{"q":"别人的博客里嵌了你的登录页代码，结果是坏人代码执行——这属于用什么方式防御的问题？","opts":["SQL 注入","XSS 跨站脚本","数据库索引","密码哈希"],"a":1,"explain":"把脚本塞进页面内容让浏览器执行的是 XSS，防御靠输出转义 + CSP 等；这不是 SQL 注入（那是打数据库的）。","jump":"sec6"}],"done":"你现在能看懂表结构、能审 AI 的建表与登录代码、知道 Session/JWT/OAuth 怎么选、也知道 SQL 注入/XSS 怎么防。下一课我们把这一切真正‘送上线’：从本地 Demo 变成一台公网可访问、稳定可回滚的真实产品。","nextLesson":"v07-deploy"},{"type":"connection","known":["你知道后端通过 API 和数据库交互（上一课）。","你知道数据要长期保存、要按关系组织（本课）。"],"learned":["数据库用表组织数据：列、行、主键唯一、外键关联、索引加速","SQL 增删改查与参数化防注入","登录三方案：Session 存服务端 / JWT 自证令牌 / OAuth 第三方授权","安全四原则：密码哈希、SQL 参数化、输出转义、后端校验"],"next":"数据和身份都准备好了，下一步是把它们‘送上线’。这与 AI 路径的联系：当你要做的是 AI 产品（如 RAG 问答），RAG 的向量库也是一种‘数据库’，登录/安全同样适用。下一课《从本地 Demo 到正式上线》会把 部署、健康检查、回滚 讲透。","links":[{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——了解向量数据库在 AI 产品里的角色"},{"href":"#/lesson/l20-ai-eng","text":"回看 AI 路径《AI 工程：从原型到生产》(规划中)"}]}]},"v07-deploy":{"id":"v07-deploy","title":"从本地 Demo 到正式上线","subtitle":"代码在你自己电脑上能跑，不算数；让全世界都能访问、且挂了能快速恢复，才是‘上线’。这一课讲清楚那条从 localhost 到公网的最后一公里。","course":"vibe","courseNo":"07","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api","v04-db"],"nextLesson":"","sections":[{"type":"opening","question":"你的产品在自己电脑上跑得欢，你联调、测试都通过了。现在要把它放到公网，让外地、外网、别家浏览器都能访问——为什么这件事永远比想象中麻烦？常见的‘本地正常、线上挂掉’到底差在哪？","guess":"很多人以为‘上线就是把文件传到服务器上，然后就能用了’。","next":"这一课我们拆解上线全流程：环境如何保持一致（环境变量）、如何把项目部署到服务器/云平台、域名与 HTTPS 怎么配、上线后怎么确认它是‘健康的’（健康检查）、出问题怎么快速回滚、以及要不要上 CI/CD。学完后你拥有的能力是：把 AI 做的 Demo 安全地变成可上线产品，并知道每一步万一失败该怎么退回来。"},{"type":"why","before":"你写好了产品，AI 也说‘好了，部署吧’。可你一部署，报‘连接数据库失败’‘端口被占用’‘找不到 .env’‘静态资源 404’……你完全不知道从哪查起，只能一遍遍粘日志给 AI，反复重装环境。","problem":"本地与线上天然不同：路径不同、数据库地址不同、端口不同、依赖版本可能不同、还要面对公网连接、域名、HTTPS 证书、防火墙。如果你没有‘环境一致性’与‘可回滚’的意识，即使这次勉强跑起来，下次改动也会随时把线上搞挂而无法恢复。","need":"掌握上线的最小可靠流程：用环境变量（.env）把差异集中管理；部署常走三大路径（静态托管 / PaaS 平台 / 自管服务器）分别怎么选；配域名 + HTTPS；加‘健康检查’让系统自己喊救命；上线清单与回滚流程让‘挂了也能退回去’。这是把 Demo 变成产品的临门一脚。"},{"type":"oneline","text":"上线 = 把代码 + 环境一致地搬上公网机器 + 配好域名/HTTPS + 挂上健康检查 + 准备好一键回滚。核心三句话：环境用变量隔离差异（不同环境不同值）、部署用脚本/平台保证可重复（别靠手敲）、发布用‘灰度/可回滚’控制风险（挂了能退）。"},{"type":"visual","kind":"deploy-console","title":"互动实验：部署控制台，看一次完整上线","hint":"这是一个模拟部署终端：点‘部署’会经历 构建 → 迁移 → 健康检查 → 流量切换；如果健康检查失败，系统会拒绝放量并自动回滚到上一个版本。你还能故意制造‘健康检查失败’来亲眼看到回滚是怎么保命的。"},{"type":"intuition","blocks":[{"k":"用开餐厅来想","t":"本地 Demo 像在你的厨房试菜——火候是你自己调好的、食材在你冰箱里。上线＝在商业街上开正式的餐厅：要租店面（服务器）、接水电气（网络/HTTPS）、换统一采购的食材（数据库搬到线上）、店员按标准作业（健康检查/监控）、万一某天厨房着火（服务挂）要能立刻换上备用后厨（回滚/容灾）。‘本地试菜’和‘正式营业’根本不是一回事。"},{"k":"用电梯/红绿灯来想健康检查","t":"健康检查＝系统自己定时喊一嗓子‘我还活着’（探测 /health 接口）。就像电梯每隔几秒报一次运行状态。如果它不喊了，编排系统（如负载均衡）就把它踢出队伍并拉起一个新的——而不是让用户对着白屏干等。"},{"k":"一句话记住上线","t":"环境变量隔离差异 → 构建产物可重复 → 部署到线上 → 健康检查确认活着 → 出问题回滚上个版本。五个动作，缺一不可；其中‘能回滚’是你最后的保险绳。"}]},{"type":"visual","kind":"llm-retry","title":"互动实验：给 LLM 调用加上超时 + 重试 + 回退","hint":"你的产品里调了大模型 API（这也是你 AI 产品的‘后厨’）。网络抖动/超时/限流在线上是家常便饭。这个实验模拟‘调用 → 超时 → 重试 → 回退(fallback)’，体会电商级 API 调用为什么要设计超时与降级。这也是 Vibe Coding 路径与 AI 路径的连接点。"},{"type":"how","intro":"把一次‘安全上线’拆成 6 步：每一步都有明确的‘成功标志’和‘失败补救’。","steps":[{"in":"① 环境变量：把差异抽出来","process":"本地/测试/线上需要不同的数据库地址、密钥、端口。把它们写进环境变量（如 .env 文件或平台面板），代码里用 process.env.XXX（Node）/ os.environ（Python）读取，而不是写死。","out":"代码与环境解耦：同一份代码换环境即可"},{"in":"② 构建 + 迁移","process":"前端打包成静态文件（npm run build → dist/）；数据库结构变化用迁移脚本（migration）跑一遍。构建产物要是‘可重复’的——同一份源码应产出同样的产物。","out":"得到一个可直接发布的‘构建物’+ 数据库就绪"},{"in":"③ 部署到线上","process":"三大路径：静态托管（页面纯前端，丢到 GitHub Pages/CF Pages/OSS 即可）；PaaS 平台（Vercel/Netlify/Railway/Render，把代码推送即可自动部署，适合新手与中等项目）；自管服务器（买 ECS/VPS，自己配 Nginx + 进程守护如 PM2/systemd）。新手从 PaaS 起步最稳。","out":"公网可以访问你的服务"},{"in":"④ 域名 + HTTPS","process":"买个域名，把 DNS 解析到你的服务（A 记录指向 IP / CNAME 指向平台）；再签 HTTPS 证书（平台自动，或云厂商+Letʼs Encrypt），让访问走 https:// 加密。浏览器地址栏的小锁 = 加密。","out":"用户通过好记的 https://你的域名 访问"},{"in":"⑤ 健康检查 + 监控","process":"后端提供 /health 接口（返回 200 + 状态）。负载均衡/编排平台每 X 秒探测它：活着→正常放量；不活→摘除并重启该实例，同时报给你（监控告警）。","out":"系统自己‘喊救命’，而不是等用户来报"},{"in":"⑥ 发布即回滚预案","process":"大型发布用‘灰度’：先 10% 流量验证，稳妥再全量；每版都保留上一个版本，发现异常立刻一键回滚（切回旧版本）。回滚能力 = 你改线上时的底气。","out":"即使新版本有问题，也可在几分钟内恢复"}]},{"type":"realworld","items":[{"name":"GitHub Pages（本站就是这么上线的）","note":"纯前端静态站可直接推到 GitHub Pages，免费公网、自带 HTTPS。适合‘文档/演示/静态首页’。注意它只托管静态资源，没有后端/数据库——需要后端的要另选 PaaS 或 VPS。"},{"name":"Vercel / Render / Railway（PaaS）","note":"‘连上 Git 仓库，push 即部署’：自动构建、自动 HTTPS、给环境变量面板、自动健康检查与回滚。是前端+轻后端产品（含 Next.js 全栈）最省心的上线方式。"},{"name":"云服务器 + 进程守护（VPS）","note":"腾讯云/阿里云的 ECS 上装 Node/Python、用 PM2/systemd 守护进程、Nginx 反代 + HTTPS。灵活可控但维护成本高。适合要自己掌控环境、或者后端较重/要连自己数据库的产品。"},{"name":"CI/CD（持续集成/持续部署）","note":"把‘测试 → 构建 → 部署’做成流水线：你 push 代码，系统自动跑测试并部署。好处是上线行为可重复、可审计；新手至少理解它的存在，平滑后再引入 (如 GitHub Actions)。"}]},{"type":"compare","pairs":[{"a":"静态托管（GitHub Pages/OSS）","b":"PaaS 平台（Vercel/Render）","diff":"静态托管只能放纯前端静态文件、无后端、一般免费；PaaS 能托管前端+后端（有的带数据库），源码推送自动构建/部署/HTTPS，更适合‘有后端的完整产品’。纯静态选前者，有后端选后者。"},{"a":"PaaS 平台","b":"自管云服务器（VPS+PM2+Nginx）","diff":"PaaS 帮你管环境、自动部署、内置回滚，省心但灵活度有限；VPS 完全可控（能装任意软件）但要自己维护系统、进程守护、HTTPS、备份，运维成本高。新手/中小产品从 PaaS 起步，要深度控制再上 VPS。"},{"a":"环境变量 .env","b":"写死在代码里","diff":"环境变量让同一份代码在不同环境（本地/测试/线上）用不同配置，且密钥不进代码库；写死会导致‘本地行、线上不行’，且密钥泄露风险大。必须用环境变量管理差异与密钥。"},{"a":"健康检查 /health","b":"用户报错才知道挂了","diff":"健康检查是主动、自动、秒级的探活，挂了立刻摘除重启并告警；等用户报告则被动、慢、伤口碑。生产环境必须有健康检查。"}]},{"type":"mistakes","items":["错误案例①：把数据库连接串、API 密钥写死在代码/前端里并 push 到公开仓库——等于把保险柜密码贴在门口。密钥必须进环境变量并严格保密。","错误案例②：没有环境意识，‘本地跑通了就认为线上能跑’。正确的验证方式：线上部署后跑一遍健康检查 + 真实浏览器访问，而不是‘本地 200 就完事’。","错误案例③：上线直接改线上数据库结构却不做迁移回滚——出事退不回去。数据库结构变更要保留迁移脚本、可逆可回退。","错误案例④：追逐‘最新框架/功能’把线上当实验场，改一次崩一次却没有任何回滚按钮。生产稳定 > 炫技；改版前后都要有一键回滚能力。","错误案例⑤：把‘调大模型 API’当成不会失败——线上网络抖动、超时、限流很常见。不给 API 调用加超时/重试/回退(fallback) 的 AI 功能，用户会频繁看到转圈/报错。"]},{"type":"deep","title":"深入一点：一次失败的线上事故是怎么被救回来的","beginner":["把‘回滚像不像重装系统’想明白：回滚不是把线上机器清空重装，而是‘把流量切回上一个已知良好的版本镜像/构建物’。现代平台（PaaS、容器编排）都保留旧版本，一键切换即可，秒级恢复。","健康检查的 /health 接口长什么样？就是一个后端路由，返回 200 和一个简单的 JSON：`{status:'ok'}`。它常常还会顺带检查数据库能否连上。如果数据库挂了，/health 也会返回失败——这样编排系统才会判断这台机器‘不健康’并把它踢出去。"],"advanced":["**一次事故的完整剧本**：新版本把数据库连接串写错 → 部署平台探测 /health → 数据库连不上 → /health 返回 500 → 平台判定‘不健康’→ 拒绝放量 / 自动回滚到旧版本 → 监控告警发到你手机 → 你看日志定位到环境变量拼错 → 修正后重新部署。全程用户几乎无感知。这就是‘健康检查 + 回滚 + 监控’三件套的价值。","**LLM 调用的可靠性设计（与 AI 路径的接口）**：真实产品调大模型 API 时，用模式是‘超时 + 指数退避重试 + 回退（缓存结果 / 备用模型 / 返回友好提示）’：","```js\nconst response = await fetchLLMWithRetry({\n  prompt, timeoutMs: 8000,            // 超时：8 秒没回应就放弃重试\n  retries: 3, backoffMs: 1000,         // 重试 3 次，指数退避\n  fallback: () => cache.get(key)       // 兜底：用缓存或降级文案\n});\n```","**上线检查清单（Checklist）**：①环境变量配全了吗？②数据库迁移跑了吗？③HTTPS 生效了吗（浏览器锁）？④/health 探针过吗？⑤日志与告警接了吗？⑥旧版本能一键回滚吗？⑦真实浏览器/多设备验证了吗？全部打勾，才算一次‘可上线发布’。"]},{"type":"ask","title":"怎么让 AI 帮你安全上线","scenario":"你的产品要第一次上线，不确定从哪下手、怕把线上搞挂。","template":"[我的产品] 是一个 [前端 + Node 后端 + PostgreSQL] 的小产品，目前只在本地能跑。\n[请给我] 一份最小可靠的上线方案：推荐用哪种托管方式（静态/PaaS/VPS）并说明理由；列出需要的环境变量清单；给出数据库迁移与开启 HTTPS 的步骤；提供 /health 接口示例与回滚预案。\n[验收标准] 每一步是否有明确操作与验证方法？是否包含失败时的回滚步骤？","acceptance":["部署方案是否说明了选型理由（静态/PaaS/VPS）与本产品的适配性？","环境变量清单是否完整且不包含明文密钥？","是否提供了可复现的部署步骤与验证方式（健康检查/浏览器访问）？","是否有明确的回滚/恢复预案，而不是‘挂了重装’？先小范围(灰度)验证再全量了吗？"],"tip":"上线是最不能‘赌一把’的环节。让 AI 给出‘选型 + 环境变量 + 验证 + 回滚’全套，再逐项打勾验收；任何一步读不懂就让 AI 解释‘为什么这样做’，直到你能复述为止。"},{"type":"exercise","prompt":"你上线了新版本，负载均衡探测 /health 连续几次都返回 500。接下来最正确的自动动作是什么？","opts":["继续放大流量，等用户反馈","把该实例摘除并自动回滚到上一个良好版本","重启浏览器","删掉数据库"],"a":1,"explain":"健康检查失败说明新版不健康，应把它踢出流量并回滚到上一版本，让用户在无感知的情况下继续使用。","jump":"sec7-step4","jumpLabel":"第 ⑤ 步：健康检查 + 监控"},{"type":"check","title":"结课检测：你的上线观念成立了吗","intro":"共 5 题。全部答对可进入下一节后续课程（或视为完成本路径第一批）。","questions":[{"q":"‘本地跑通 = 线上一定能跑’这句话？","opts":["完全正确","错误，本地与线上环境(变量/依赖/数据库)常不同，需部署后验证","只对前端成立","只对数据库成立"],"a":1,"explain":"环境差异（连接串、密钥、依赖版本、端口）是‘本地行、线上挂’的常见原因，必须部署后做健康检查与真实访问验证。","jump":"sec4"},{"q":"数据库地址、API 密钥这类差异应当怎么管？","opts":["写死在代码里方便","放进环境变量按环境区分，且密钥不进代码库","藏在注释里","放前端页面里"],"a":1,"explain":"环境变量让同一代码适应不同环境、密钥不进仓库，安全且可维护。","jump":"sec5-step0"},{"q":"完全不会写代码、只想让前端+后端都能自动上线，最省心的选项是？","opts":["自建机房","PaaS 平台（如 Vercel/Render），连 Git push 即部署","用纯记事本手写服务器脚本","不部署"],"a":1,"explain":"PaaS 负责构建、部署、HTTPS、健康检查与回滚，对新手最友好；VPS 更适合要深度控制的高级场景。","jump":"sec7"},{"q":"/health 健康检查的探测失败时，编排系统最合理的动作是？","opts":["什么都不做","摘除不健康实例并重启/拉起新的，必要时候选回滚","把数据库清空","关掉域名"],"a":1,"explain":"自动摘除+重启，必要时回滚旧版本，让用户几乎无感知；同时告警提醒你排查。","jump":"sec7-step4"},{"q":"调用大模型 API 时，‘超时 + 重试 + 回退(fallback)’组合主要防范什么？","opts":["防止代码有语法错误","线上网络抖动、超时、限流导致的偶发失败","防止数据库被删","防止前端样式错乱"],"a":1,"explain":"线上第三方 API 偶发失败是常态，超时避免无限等待、重试提高成功率、回退(缓存/备用/友好提示)兜底，保证用户体验不崩。","jump":"sec7"}],"done":"你已经掌握了从 localhost 到公网‘最后一百米’的全部关键：环境变量隔离、部署三路径选型、域名+HTTPS、健康检查、回滚预案、上线清单。Vibe Coding 第一批四门课到此收官——你已经能看懂代码结构、判断接口与数据库靠不靠谱、把 Demo 安全上线了。","nextLesson":""},{"type":"connection","known":["你知道一个 Web 产品如何分层（课1）、前后端怎么通信（课3）、数据怎么存与登录安全（课4）。","你会调大模型 API / 了解 RAG、Agent（AI 路径）。"],"learned":["环境变量隔离本地/测试/线上差异，密钥不进代码库","部署三路径：静态托管 / PaaS / 自管 VPS，以及各自适用场景","域名 + HTTPS（浏览器小锁）怎么配","健康检查(/health)探活 + 监控告警，挂了自动摘除","灰度 + 一键回滚 = 改线上时的底气；上线检查清单"],"next":"Vibe Coding 第一批四个环节到此闭环：看懂 → 懂接口 → 懂数据/安全 → 懂上线。下一步安排：第二批课程将覆盖 前端与语言基础（课2）、终端与 Git（课5）、存储缓存与测试排错（课6）、系统设计与 AI 产品工程（课8）。与本路径之外的联系：AI 产品的上线同样遵循本课原则，且多了‘LLM 调用可靠性’（超时/重试/回退）这一环——已在课 7 实验里有真机感受。","links":[{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"},{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——AI 产品上线的数据侧"},{"href":"#/lesson/l-agent","text":"回看 AI 路径《Agent：让 AI 自己动手做事》——Agent 产品化时的可靠性思考"}]}]}},"lessonsByCat":{"c01-ai-world":[{"id":"l00-ai-world","title":"一张图看懂整个 AI 世界","subtitle":"在学任何一个概念之前，先拿到整张地图：你现在站在哪里，接下来要走到哪里。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"15-20 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl","ai-apps","ai-limits"],"prereqLessons":[],"nextLesson":"l-embedding","sections":[{"type":"opening","question":"你每天听到的 ChatGPT、大语言模型（LLM）、Transformer、Agent、RAG……它们到底谁包含谁、谁建在谁之上？如果你现在只能用一句话回答「它们是什么关系」，你会怎么说？","guess":"很多人会脱口而出「都是一回事，就是 AI」。","next":"这节课不教任何公式，只画一张总地图。学完你不仅能说清这些词的关系，还能知道接下来 5 节旗舰课各自站在这张地图的哪个格子里。"},{"type":"why","before":"你在标题、文章、面试里反复遇到 Token、Attention、Transformer、RAG、Agent、Fine-tune……每个词单独看都懂一点，但凑在一起就乱。","problem":"初学者最大的障碍不是「不够努力」，而是没有地图：他不知道现在学的东西将来会连到哪里，于是学一个忘一个，越学越焦虑。","need":"所以第一节课我们不讲任何实现细节，只建立骨架：AI 世界分哪几层、每一层由什么构成、你将来要学的每一块长在哪个位置。地图在手里，后面的路才走得稳。"},{"type":"oneline","text":"AI（人工智能）是整片森林；机器学习是其中『会自己从数据里找规律』的那片林子；深度学习是最能长的那几棵大树；大语言模型（LLM）是最近最抢眼、能和你聊天的那一棵；而 RAG、Agent 这些，是围绕这棵树搭起来的『脚手架』——让树上的果子更好摘。"},{"type":"visual","kind":"ai-world-map","title":"AI 世界全景图","hint":"从最外层的 AI 一路收缩到 LLM，再向外展开 Vision / Speech / Agent / RAG 等应用方向。点击让你看明白的节点，就能往下一层走。"},{"type":"intuition","blocks":[{"k":"用俄罗斯套娃来想","t":"AI 是最大的套娃，机器学习是里面一层，深度学习再里面一层，LLM 是最小最精致的那层。每往里一层，都建立在外层之上——这叫『包含』，不是『并列』。"},{"k":"用搭积木来想","t":"只给你一个 LLM 你只能『聊天』。但当你往它外面搭『检索』（RAG）、『工具调用』（Agent）、『工作流编排』（Workflow）这些积木，你就从『会聊天』升级成『会办事』。产品形态 = 模型 + 一层层积木。"},{"k":"一句话记住主干","t":"AI ⊃ ML ⊃ DeepLearning ⊃ Foundation Model ⊃ LLM。这一个箭头链，就是整张地图的主干，也串起了你即将学的六节课。"}]},{"type":"how","intro":"把 AI 世界拆成「五层结构」与「五大应用方向」，你学完至少知道每块知识的归属，再也不会把它们混为一谈。","steps":[{"in":"第 0 层 · AI（人工智能）","process":"最上层总称：让机器表现出智能的一切技术，包括早期靠人写规则、搜索、专家系统。","out":"范围最大，是『目标』而不是某一门具体技术"},{"in":"第 1 层 · Machine Learning 机器学习","process":"不再靠人写死规则，而是让机器从数据里『自己找规律』，再拿规律去做预测。","out":"监督学习 / 无监督学习 / 强化学习 三大流派"},{"in":"第 2 层 · Deep Learning 深度学习","process":"用『多层神经网络』来自动提取特征，是机器学习的子集，能力更强：不用人手设计特征。","out":"CNN（图像）、RNN/Transformer（序列）、扩散模型（生成）等结构"},{"in":"第 3 层 · Foundation Model 基础模型","process":"在大规模数据上预训练好的『通用大脑』，可以微调或直接复用到很多不同任务。","out":"LLM（语言）、视觉基础模型、多模态基础模型"},{"in":"第 4 层 · LLM 大语言模型","process":"把『预测下一个词』当唯一训练目标，靠海量文本硬学出来的语言模型，意外获得了语言与世界的知识。","out":"ChatGPT、Claude、Gemini 背后的模型本体"},{"in":"围绕 LLM 的『脚手架』与应用架构","process":"光会聊天不够，为了让模型能办成事，在外面叠加外围技术。","out":"Prompt 提示 · RAG 检索增强 · Workflow 工作流 · Agent 智能体 · 多模态"}]},{"type":"realworld","items":[{"name":"ChatGPT","note":"「纯 LLM 对话产品」：你打字，它预测下一段话。它本身不做检索也不调工具，是最纯粹的一层。"},{"name":"Claude / Gemini","note":"同样是 LLM 驱动的对话产品，但在模型能力与对齐上做得不同，代表『同一个塔、不同的果』。"},{"name":"NotebookLM / 企业知识库问答","note":"「LLM + RAG」：你上传私有资料，系统先检索相关片段，再让模型基于这些片段回答，杜绝凭空编造。"},{"name":"Workflow 编排（如 Zapier AI / Coze 工作流）","note":"「LLM + 规则流程」：把『先做A、判断结果再做B』写成固定流水线，模型只负责其中某一环。"},{"name":"Codex / Claude Code","note":"「LLM + Agent 智能体」：不只是回答，还能自主决定『读文件→改代码→跑测试→看报错→再改』，直到把活干完。"},{"name":"Midjourney / Sora","note":"「不是 LLM 的另一棵树」：用扩散模型做图像/视频生成。提醒你 AI 世界不只有语言这一棵大树。"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是「目标——机器有智能」；机器学习是实现它的一种主流手段（用数据学出来）。早期用规则实现的人工智能，不属于机器学习，但仍然属于 AI。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是「从数据学习」；机器学习范围更大（含决策树、SVM 等传统算法），深度学习专指用多层神经网络，能自动提取特征，是机器学习的一个子集。"},{"a":"LLM","b":"Foundation Model","diff":"LLM 是专做语言的基础模型；Foundation Model 是更大的类，还包括视觉、多模态基础模型。LLM ⊂ 基础模型。"},{"a":"RAG","b":"Agent","diff":"RAG 是『给模型外接资料库』的检索增强；Agent 是『让模型自主决策与调用工具』的智能体。两者常配合：Agent 需要信息时用 RAG 检索。它们都不是模型本身，而是脚手架。"},{"a":"模型（Model）","b":"产品（Product）","diff":"模型是被训练出来的『大脑』；产品是把这个大脑装进界面、加上检索/记忆/工具后的完整应用。你用的是产品，不直接是模型。"}]},{"type":"mistakes","items":["把「AI、机器学习、深度学习、LLM」当同义词——它们是一层层包含关系，不是并列。","以为 ChatGPT = 整个 AI。ChatGPT 只是 LLM 的一颗果实；AI 世界还有视觉、语音、生成、机器人、Agent 等一大片。","以为 RAG 和 Agent 是「模型」。它们是在模型外面搭的脚手架/架构，本身没有『大脑』。","以为只有学完高等数学才能开始。第一门旗舰课（Embedding）就能带你把概念走通，数学按「够用」给，不是研究生讲义。","以为 Fine-tuning（微调）和 RAG 是一回事。前者改模型自身权重，后者不改模型、只改给它看的外部资料——它们解决不同问题。"]},{"type":"deep","title":"深入一点：把「领域 / 模型 / 技术 / 应用架构 / 产品形态」五顶帽子分清楚","beginner":["用「帽子」来记：同一个东西，问问题的角度不同，答案就不同。","「这属于哪个**领域**？」—— 问的是地图范围（AI、ML、DL 是领域/学科级）。","「这是个什么**模型**？」—— 问的是被训练出来的产物（LLM、扩散模型、视觉模型是模型级）。","「用了什么**技术/算法**？」—— 问的是怎么做（Attention、Transformer、RAG 检索是技术级）。","「这是什么**应用架构**？」—— 问的是怎么组合（RAG 架构、Agent 循环、Workflow 流水线是架构级）。","「最终做成什么**产品**？」—— 问的是用户能用的东西（ChatGPT、Codex、NotebookLM 是产品级）。"],"advanced":["用一条「从模型到产品」的抽象层次链来定位任何 AI 名词：","「AI 世界 = 领域层（AI⊃ML⊃DL）→ 模型层（Foundation Model→LLM/Diffusion/多模态）→ 技术层（Attention、位置编码、损失函数）→ 架构层（RAG、Agent、Workflow、多智能体协作）→ 产品层（ChatGPT、Claude Code）」。","判断法则：问「它能不能被『训练』出来」？能 → 模型层或更深；问「它是不是一个『零件/接法』」？能 → 技术层或架构层。训练产物是模型，接法是架构。","示例定位：Transformer 是技术层（一种网络结构）；GPT 系列是基于 Transformer 训练出来的模型（模型层）；把 GPT 接上检索= RAG 架构（架构层）；打包成网站= ChatGPT 产品（产品层）。","顺带一个工程事实：你平时说的「大模型」绝大多数指 LLM 或基础模型；而「智能体」「Agent」在业界常被定义为『模型 + 记忆 + 规划 + 工具调用』，是一个架构概念而非单个模型。"]},{"type":"exercise","prompt":"你现在打开了一款「企业知识库问答」App，上传公司政策文件后提了个问题，系统给出的回答里标注了「依据文件第 3 页」。你觉得它最可能是下面哪种组合？","opts":["只有 LLM，全靠模型自己编","LLM + RAG（先检索你的文件，再基于片段回答）","LLM + Agent（让模型自己去改代码）","纯扩散模型"],"a":1,"explain":"回答『依据你上传的文件』并带引用，正是 RAG 的典型特征：先检索相关片段，再让模型基于片段生成答案。","jump":"sec5-step5","jumpLabel":"围绕 LLM 的脚手架（RAG 检索）这一段"},{"type":"check","title":"结课检测：你真的懂这幅地图了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"下面哪条包含关系是正确的？","opts":["AI ⊃ LLM ⊃ Deep Learning ⊃ ML","AI ⊃ ML ⊃ Deep Learning ⊃ LLM","LLM ⊃ AI ⊃ ML ⊃ Deep","Deep Learning ⊃ ML ⊃ AI ⊃ LLM"],"a":1,"explain":"AI 包含机器学习，机器学习包含深度学习，LLM 是深度学习上长出的具体模型。","jump":"sec5-step0","jumpLabel":"五层结构第一步"},{"q":"ChatGPT 最准确地说是下面哪一个？","opts":["一个 Agent 智能体","一个纯 LLM 对话产品","一个 RAG 系统","一个视觉模型"],"a":1,"explain":"ChatGPT 的核心就是大语言模型：输入→预测下一段。RAG/Agent 是对它的增强，而不是它的本质。","jump":"sec5-step4","jumpLabel":"第 4 层 LLM 这一段"},{"q":"「NotebookLM 先查你上传的资料再回答」主要用到了哪项技术？","opts":["RAG 检索增强生成","纯预训练","扩散模型","只靠提示词"],"a":0,"explain":"针对私有资料，RAG 让模型先检索相关片段再回答，这正是 NotebookLM 类产品的核心。","jump":"sec5-step5","jumpLabel":"脚手架之 RAG 这一段"},{"q":"Codex「自己读代码、改代码、跑测试、看报错再重试」的能力，对应哪种架构？","opts":["RAG 检索增强","Agent 智能体循环","纯一次性生成","工作流固定流水线"],"a":1,"explain":"自主决策 + 调用工具 + 根据反馈循环，这正是 Agent 的核心：想→做→看→再想。","jump":"sec5-step5","jumpLabel":"脚手架之 Agent 这一段"},{"q":"「Midjourney 能生成图片」用到的模型，和 ChatGPT 的 LLM 是什么关系？","opts":["同一个模型","都是 LLM","Midjourney 用的是扩散模型，是 AI 世界里另一棵大树","Midjourney 不用 AI"],"a":2,"explain":"图像生成多靠扩散模型（Diffusion），与语言类的 LLM 是并列的不同模型，提醒你 AI 世界不止语言一棵树。","jump":"sec6","jumpLabel":"现实应用里的 Midjourney / Sora"}],"done":"现在你手里有整张地图了。接下来我们要下到模型的正下方——先搞清楚：电脑到底怎么把一句话变成它算得动的『数字』。","nextLesson":"l-embedding"},{"type":"connection","known":["（这是第一节课，还没有前置知识）"],"learned":["AI → ML → DL → Foundation Model → LLM 的主干链条（包含关系）","领域 / 模型 / 技术 / 应用架构 / 产品形态 五顶帽子怎么分","RAG、Agent、Workflow 是围绕 LLM 的脚手架，不是模型","ChatGPT、Claude（LLM产品）、NotebookLM（RAG）、Coze（工作流）、Codex（Agent）、Midjourney（扩散）各代表一类"],"next":"下一课我们钻到模型正下方：Embedding——电脑怎么把『一句话』变成『一串数字』。这是理解 LLM 的第一块砖，也是 RAG、搜索、推荐的地基。"}]}],"c02-essentials":[{"id":"l-embedding","title":"Embedding｜怎么把词变成电脑能懂的数字","subtitle":"为什么文字不能直接进神经网络？为什么不是给每个词编个号？为什么意思相近的词离得更近？","category":"c02-essentials","chapterTitle":"第一章 · 向量与语义","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["embedding","vector","cosine-similarity","emb-vector-store"],"prereqLessons":["l00-ai-world"],"nextLesson":"l-attention","sections":[{"type":"opening","question":"你让 ChatGPT 翻译『苹果很好吃』，它内部第一件事不是『读懂』这句话，而是把『苹果』变成了一串数字。猜一猜：为什么电脑不能用『苹果』这两个汉字直接思考，非得多此一举先转成数字？","guess":"有人会想：给猫=1、狗=2、苹果=3 编个号不就行了？","next":"这节课就回答『为什么不能简单编号』，以及真正的 Embedding 是怎么做到『意思相近的词，数字也相近』的。"},{"type":"why","before":"神经网络只会做数学运算：加法、乘法、比较大小、算距离。它天生看不懂『猫』『狗』『苹果』这些文字。","problem":"如果文字根本送不进神经网络，那后面的一切——翻译、对话、理解、检索——全都是空中楼阁。这是所有语言模型的『第一道门』，绕不过去。","need":"所以我们必须在『文字』和『数字』之间搭一座桥，让电脑既能「算」文字，又能保留文字的含义。这座桥就是 Embedding。","visualNote":"下面这张 2D 语义空间图，就是你要带走的直觉：位置 = 语义。"},{"type":"oneline","text":"Embedding 就是把『一个词』变成『一串数字（向量）』，并且让意思相近的词，数字串长得也相近——于是电脑就能『算』语义了。"},{"type":"visual","kind":"embedding-space","title":"Embedding 2D 语义空间（可交互）","hint":"这是把词『压扁』到二维的示意：意思相近的词会聚在一起。观察猫/狗/狮子聚在『动物角』，苹果/香蕉聚在『食物角』。试试输入几个词，看它落在哪一群。"},{"type":"intuition","blocks":[{"k":"为什么不能直接给词编号？","t":"你可能会想：猫=1、狗=2、苹果=3 不就行了？但问题是：2 和 3 只差 1，可『狗』和『苹果』的语义差得十万八千里。编号把『数字距离』和『语义距离』完全搞乱了——电脑会误以为狗和苹果几乎一样。"},{"k":"用一张坐标纸来想","t":"想象一张地图，横轴是『是不是动物』，纵轴是『是不是食物』。『猫』放左边靠上，『狗』紧挨它，『苹果』放右上角。位置越近，意思越像。Embedding 本质就是在几百上千维的『坐标纸』上，给每个词找个位置。"},{"k":"一个生活类比","t":"就像地理坐标：北京和天津坐标很近，所以在空间里相邻；语义相近的词，在 Embedding 空间里坐标也相邻。"}]},{"type":"how","intro":"Embedding 是怎么『学』出来的？核心思想只有一句话：一个词的含义 = 它经常和哪些词一起出现。","steps":[{"in":"收集海量文本","process":"从整个互联网语料里，观察『猫』总是和『狗、宠物、喵、毛』一起出现，而『苹果』总跟『水果、吃、红色』一起出现。","out":"得到每个词在语料里的『共现模式』"},{"in":"用共现模式训练向量","process":"训练一开始给每个词一组随机数字，然后不断调整，让『经常一起出现』的词向量越走越近，『从不一起出现』的词向量越走越远。","out":"每个词最终固定成一个固定长度的向量（如 300 或 768 维）"},{"in":"用向量距离比较语义","process":"两个词的向量越接近（夹角越小、余弦相似度越高），语义越相近。电脑从此『算得出』猫≈狗、苹果≠猫。","out":"文字第一次可以被数值比较"},{"in":"送入下游模型","process":"这个数字向量就是神经网络的输入。LLM 只认数字，现在它『看得懂』词了，可以开始做翻译、对话、生成。","out":"模型能对词做运算、比较、生成"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude","note":"内部第一件事就是把你的每个 Token 转成 Embedding 向量，再送进 Transformer 网络。"},{"name":"搜索引擎语义检索","note":"把『怎么养猫』和『养宠物指南』都向量化，语义相近就能互相匹配，不必字面相同也能搜到。"},{"name":"NotebookLM / RAG","note":"把你的资料切成块并向量化，用户提问时在向量空间里『找最像的那几块』再交给模型回答——这就是 RAG 的地基。"}]},{"type":"compare","pairs":[{"a":"Token","b":"Embedding","diff":"Token 是文字切出的『小块』（词/子词）；Embedding 是把每个小块变成的『数字向量』。先切 Token，再做 Embedding。"},{"a":"Embedding 模型","b":"LLM","diff":"Embedding 模型把文本压成『定位向量』（不生成文字）；LLM 生成文字。一个是『编码员』，一个是『作家』。"},{"a":"One-hot 编号","b":"Embedding","diff":"One-hot 让所有词互相『等距』、无法表达语义；Embedding 让相近的词更近，真正抓住含义。"}]},{"type":"mistakes","items":["以为 Embedding 只是『给每个词一个数字』。其实是一整串数字（向量），且数字之间存在『相似关系』——这才是关键。","以为 Embedding 模型和 LLM 是同一个东西。它们是分工不同的两个模型：一个负责编码相似度，一个负责生成文字。","以为向量维度越高一定越好。维度越高表达力越强，但更贵、更易过拟合，常见几百维就够用。","以为 Embedding 能『理解逻辑』。它只捕捉统计上的相似，不保证逻辑正确——所以光靠 Embedding 做问答会答非所问。"]},{"type":"deep","title":"深入一点：从二维直觉到真实向量空间","beginner":["Embedding 在工程上就是『查表』：模型里有一张巨大的表，每个词一行，那一行数字就是它的向量。训练好了之后，直接用查到的数字即可。","维度越高，能表达的语义越细腻，但计算越贵。常见几百维就够处理大多数任务。","真正常用的是一种叫『子词』的粒度：一个字被拆成更小的片段（如 'unbreakable' → 'un' + 'break' + 'able'），这样遇到没见过的词也能拼出向量。"],"advanced":["向量不只给每个词一个『标签』，它把语义结构编进了几何里：经典例子 king − man + woman ≈ queen，说明向量『方向』也承载意义。","Embedding 模型（如 text-embedding 系列）与 LLM 是不同模型：前者把文本压缩成『定位码』，后者生成文字。它们可以分开训练、分开使用。","计算两个向量有多像，最常用的指标是**余弦相似度** cos(θ)：只看方向、不看长度，数值越接近 1 越像。",{"code":"# 余弦相似度：越大越像\nimport numpy as np\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\ncat   = np.array([0.9, 0.1])   # 靠近动物方向\napple = np.array([0.1, 0.9])   # 靠近食物方向\ndog   = np.array([0.85, 0.15]) # 很接近猫\n\nprint(round(cosine(cat, apple), 2))  # 0.22  → 语义远\nprint(round(cosine(cat, dog), 2))    # 1.0   → 语义很近","lang":"python"},"维度本质：真实 Embedding（如 OpenAI text-embedding-3）常达上千维，一个词就是一个上千维空间里的点。降维可视化（t-SNE / PCA）只是把上千维『压扁』到 2D 方便人看。"]},{"type":"exercise","prompt":"在一个语义空间里，『国王』向量减去『男人』向量，再加上『女人』向量，猜一猜结果最可能靠近下面哪个词？","opts":["王子","女王（皇后）","父亲","阿姨"],"a":1,"explain":"这正是著名的 king − man + woman ≈ queen 现象：向量的方向承载意义，『王 - 男 + 女』就指向『女王』的方向。它说明 Embedding 抓到的不是孤立的词，而是语义结构。","jump":"sec5-step3","jumpLabel":"用向量距离比较语义这一步"},{"type":"check","title":"结课检测：你真正理解 Embedding 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么不能直接给每个词编个号（猫=1，狗=2，苹果=3）？","opts":["因为编号会让相近的词距离更近","因为编号会破坏语义距离：狗和苹果只差 1，但语义差很远","因为编号需要太多内存","因为编号不能用于神经网络"],"a":1,"explain":"编号把数字距离和语义距离搞混了：狗(2)和苹果(3)只差1会被当成很相似，但它们的含义毫无关系。","jump":"sec4","jumpLabel":"『为什么不能直接给词编号』这一段"},{"q":"两个 Embedding 向量夹角越小（余弦相似度越高），说明什么？","opts":["两个词的语义越相近","两个词的字符串越长越像","两个词出现频率越接近","两个词的长度越接近"],"a":0,"explain":"夹角越小，向量在空间里越靠近，代表语义越相近。这就是『用距离算语义』。","jump":"sec5-step2","jumpLabel":"『用向量距离比较语义』这一步"},{"q":"关于 Embedding 模型与 LLM 的关系，正确的是？","opts":["它们是同一个模型","Embedding 模型把文本变向量、LLM 生成文字，二者分工不同","LLM 内部根本不做 Embedding","Embedding 模型能直接写文章"],"a":1,"explain":"Embedding 模型负责『编码相似度』，LLM 负责『生成内容』，是两个可分开训练的模型。","jump":"sec7","jumpLabel":"『Embedding 模型 vs LLM』那一条对比"},{"q":"Embedding 的『含义』主要来自哪里？","opts":["每个字在字典里的官方解释","这个模型『预测下一个词』时学到的共现模式","开发者手写的规则","词的笔画数"],"a":1,"explain":"一个词的含义 = 它常和哪些词一起出现。模型在大量文本上学到的正是这种共现模式。","jump":"sec5-step0","jumpLabel":"『收集海量文本』这一步"},{"q":"下面哪句关于向量维度的说法正确？","opts":["维度越高一定越好，越细越好","维度越低越好，因为一定更便宜","维度是表达力与成本的权衡，常见几百维就够用，过高更贵且易过拟合","维度只影响颜色不影响语义"],"a":2,"explain":"维度是权衡的结果：高维表达强但贵且易过拟合，低维省但表达粗糙。实际常用几百维。","jump":"sec9","jumpLabel":"深入一节关于维度的说明"}],"done":"你已经理解了『文字 → 数字向量 → 算距离』这条链路，这是 RAG、搜索、推荐共同的地基。","nextLesson":"l-attention"},{"type":"connection","known":["AI 世界全景：模型只能处理数字","Embedding 是文字进入模型的第一道门"],"learned":["文字 → 向量，让电脑能算语义","相近的词向量距离更近，用余弦相似度衡量","Embedding 模型与 LLM 分工不同","向量方向也能承载意义（king − man + woman ≈ queen）"],"next":"有了『每个词是一个数字向量』，下一步就是大招：Attention——模型怎么在一句话里决定『该重点关注哪个词』。这决定了模型能不能读懂『这只狗没咬那只猫，是因为它怕它』里『它』到底指谁。"}]}],"c05-llm":[{"id":"l-attention","title":"Attention｜模型为什么知道该关注哪个词","subtitle":"当模型读到『它』，怎么知道是猫还是狗？为什么句子再长，模型也能把前后的词对上号？","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["attention","qkv","multihead","attention-long"],"prereqLessons":["l-embedding"],"nextLesson":"l-transformer","sections":[{"type":"opening","question":"请读这句话：「小狗跑向小猫，因为它害怕小狗。」这个『它』指的到底是小猫还是小狗？只盯着『它』一个词，谁也说不清——那 ChatGPT 是怎么判断出来的呢？","guess":"有人会说「代词当然指前面离得最近的动物」。但中文里『它』常跨好几个词、甚至跨好几句指代，光看位置根本猜不准。","next":"这节课要讲的就是模型的『读心术』——Attention 注意力机制。它让模型在处理『它』时，回头看一眼整句话，自己判断该靠哪些词来理解『它』。"},{"type":"why","before":"上节课我们把每个词变成了向量。但词是孤立的：『猫』『追』『狗』『它』，每一个都只是单独的一串数字。","problem":"真正的语言是互相指代的。『猫追狗，它跑得飞快』——这个『它』是谁？只看『它』这个词本身，根本答不上来。更糟的是：在 Attention 出现以前，老式模型（RNN）看长句时，越靠前的词就越『记不清』。","need":"我们需要一个机制：在处理任何一个词时，能直接『回看』整句话里的所有词，按相关程度加权吸收它们的信息。这就是 Attention——『注意力』，它解决了『远距离指代』和『长句遗忘』两大难题。","visualNote":"下面你可以亲手造一句中文，点任何一个词，看它把注意力分给了谁。"},{"type":"oneline","text":"Attention 是这样一种机制：模型在理解某个词时，会『回头看一眼』句子里的每一个词，给它们分别打一个权重分——分数越高的词，模型花越多注意力在它身上。于是『它』到底指猫还是狗，模型有了办法分清。"},{"type":"visual","kind":"attention-heatmap","title":"Attention 热力图：点一个词，看它关注谁","hint":"输入一句话，点任意一个词（比如那棵/那株），热力图会显示这个词对其它词的『关注权重』——颜色越深，越关注。试试改动量词，体验权重如何跟着语义线索移动。"},{"type":"intuition","blocks":[{"k":"老师点名：每读一个词都在点名","t":"读到『它』这个词时，模型其实在问：『谁能告诉我『它』指谁？』——它把问题抛向所有词，然后重点听『猫』『跑』这些最相关的答案。"},{"k":"查字典：不是顺序读，而是跳着看","t":"Attention 最反直觉的一点：它不老老实实从左往右读。读到『它』，它像翻开一本字典快速扫过所有词条，直接锁定『猫』『跑』，记下『我主要靠这几个词来理解自己』。"},{"k":"聚光灯：每个词都举着无数盏灯","t":"句子里每个词都举着一盏聚光灯照向其它词。灯越亮，代表『我理解你时越依赖你』。Attention 就是计算这盏灯亮度的过程。远近都一样亮——这是它比老方法强的地方。"}]},{"type":"how","intro":"Attention 到底怎么『算』注意力？核心就一句话：每个词同时扮演三个角色——Query（我找谁）、Key（我是谁）、Value（我的内容），然后『找相似、按相似加权吸收』。","steps":[{"in":"乘上三个矩阵，得到 Q / K / V","process":"每个词的向量分别乘以三个不同的矩阵，变成三个新向量：Query『我要去匹配谁』、Key『我是谁，请拿我来匹配』、Value『我的有效内容』。","out":"单词 → (Query, Key, Value) 三件套"},{"in":"用 Query 和所有 Key 算相似度","process":"以『它』的 Query 为例，和句子里每个词的 Key 做点积（就是 Embedding 课学过的『方向越像越接近』）。","out":"得到分数列表：它 vs 猫 = 高分，它 vs 跑 = 中等……"},{"in":"Softmax 归一化成权重","process":"把所有分数经过 softmax，变成『加起来等于 100%』的权重。这一步保证分数变成可比较、可加权的概率。","out":"注意力权重：猫 0.6、跑 0.25、飞快 0.15……"},{"in":"用权重 × Value 加权求和","process":"把每个词的 Value 乘上对应权重再全部相加。权重大的词，内容在结果里占的份量就大。","out":"『它』的新向量 = 主要吸收了『猫』的信息 → 模型知道『它≈猫』"},{"in":"每个词同时做，得到上下文向量","process":"句子里每个词都执行同一套操作，得到一批『结合了全局上下文的新向量』。","out":"整句话从一串孤立向量 → 一串互相理解的向量"},{"in":"多个头并行（多头注意力）","process":"为了不只从一种角度看，模型并行做多组 Q/K/V（不同随机初始化的矩阵），相当于多个不同视角同时观察。","out":"一个头看指代关系、另一个头看语法结构、再一个看长度……组合出更丰富的理解"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude 生成每个词","note":"每生成一个 token，模型都要对上下文做一次 Attention：决定下一个词更依赖前面的哪部分。这是生成的核心动作。"},{"name":"翻译模型的对齐","note":"把『I love you』翻成中文时，Attention 让『love』和『爱』自动对上号，哪怕位置完全错开（这就是 Cross-Attention 用武之地）。"},{"name":"代码补全","note":"补全函数体时，Attention 帮模型盯住几千行前的函数签名和参数定义，而不是只看到最近几行。"},{"name":"长文档问答","note":"在长文章里问『第三部分的结论是？』，Attention 让模型跳过大段无关内容，直接聚焦第三部分的句子。"}]},{"type":"compare","pairs":[{"a":"RNN 顺序处理","b":"Attention 全局直连","diff":"RNN 必须一个字一个字按顺序传，远处信息会衰减；Attention 让任意两个位置直接相连，没有距离衰减。"},{"a":"Self-Attention","b":"Cross-Attention","diff":"Self 是同句话内部互相理解；Cross 是让一方去『读』另一方（翻译、RAG 上下文注入都用它）。"},{"a":"单头注意力","b":"多头注意力","diff":"单头只有一种看法；多头并行多组 Q/K/V，相当于同时用多个角度理解，效果明显更好。"},{"a":"注意力（Attention）","b":"记忆（Memory）","diff":"注意力是每次计算时动态算出的关注权重，不存下来；记忆是存下来的长期信息。很多人把注意力误当成记忆。"}]},{"type":"mistakes","items":["以为 Attention 是『看一遍就记住』的长期记忆。它不是记忆，而是每次计算时动态分配的关注权重——每次都要重新算，不会存下来。","以为注意力可视化等于模型的可解释性。权重高代表统计上相关，不代表模型逻辑上『是因为这个』。","把『注意力』和『上下文窗口』混为一谈。窗口决定能看多远，Attention 决定窗口内怎么分配关注。","以为只看『最近几个词』。Attention 恰恰是全局的——它牺牲计算量，换来的是真正看全上下文。","以为 Attention 零成本。它的核心开销是 O(n²)：n 个词两两算一遍。这正是上下文窗口成为瓶颈的原因。"]},{"type":"deep","title":"深入一点：从直觉到公式","beginner":["注意力权重加起来等于 1（100%）。Softmax 就是把一坨分数变成『加起来为 1、且大的更大』的数。","不必纠结矩阵怎么算，你只需记住一句口诀：『Query 找人，Key 被找，Value 是内容，三者相乘加权求和』。","它最厉害的地方：任意两个词无论隔多远都能直接相关——远处那个词和眼前这个词，算注意力的成本完全一样，这是它战胜 RNN 的根本原因。"],"advanced":["核心公式：Attention(Q, K, V) = softmax( (Q·Kᵀ) / √d ) · V。除以 √d（d 是向量维度）是为了防止点积过大把 softmax 压死、导致梯度消失。","Self-Attention 的 Q/K/V 都来自同一句话，让句子内部互相理解；Cross-Attention 的 Q 来自一方、K/V 来自另一方（如翻译、RAG 上下文注入）。","复杂度 O(n²)：n 个词两两都算一遍。这正是上下文窗口成为瓶颈的原因，也是稀疏注意力、局部注意力、线性注意力研究的动机。","不要神化注意力可视化：权重高 ≠ 模型真『懂』了，它更多是统计相关而非可解释的因果。",{"code":"# 概念示意：手工算一次注意力（极简 2 词版）\nimport math\n\ndef softmax(xs):\n    ex = [math.exp(x) for x in xs]\n    s = sum(ex)\n    return [e / s for e in ex]\n\nq = [1.0, 0.0]  # 我是『它』的 Query\nks = {\"猫\": [0.9, 0.1], \"狗\": [0.2, 0.8]}  # 两个词的 Key\n\nscores = {w: round(q[0]*k[0] + q[1]*k[1], 3) for w, k in ks.items()}\nprint(\"点积分数:\", scores)\nweights = dict(zip(scores, softmax(list(scores.values()))))\nprint(\"softmax 权重:\", {w: round(v,3) for w,v in weights.items()})\n# 猫的权重明显更高 → 模型认为『它』更像猫","lang":"python"}]},{"type":"exercise","prompt":"「它拿起了那支笔，因为【　】太亮了。」这个【　】里的词，会让『太亮了』把更多注意力分给『笔』而不是『它』，你能猜出最合理的一个词吗？","opts":["灯","笔帽","手","桌"],"a":0,"explain":"『灯太亮了』语义合理，Attention 会让『亮』和『灯』形成高权重连接；而『笔帽太亮了』虽然通顺，但更重要是体会：有了『亮』这个线索，Attention 会去找『最配得上的名词』。模型正是靠大量这样的共现线索来分配注意力。","jump":"sec5-step1","jumpLabel":"用 Query 和 Key 算相似度这一步"},{"type":"check","title":"结课检测：你真的理解 Attention 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"Attention 中 Query、Key、Value 各自的作用，最准确的说法是？","opts":["Q 是内容，K 是找人，V 是被找","Q 在找人，K 是被找的标签，V 是被吸收的内容","三者完全相同","Q 是权重，K 是分数，V 是标签"],"a":1,"explain":"Q（Query）发起匹配去『找谁』；K（Key）告诉别人『我是谁』供匹配；V（Value）是被加权吸收进的真正内容。","jump":"sec5-step0","jumpLabel":"乘上三个矩阵得到 Q/K/V 这一步"},{"q":"为什么说 Attention 解决了 RNN『记不住长句』的问题？","opts":["因为它是顺序处理的","因为任意两个词都可以直接相关，不随距离衰减","因为它把句子变短了","因为它只关心最近的词"],"a":1,"explain":"RNN 依赖顺序传递、距离远信息衰减；Attention 让任意两个位置直接相连、远近一视同仁。","jump":"sec8","jumpLabel":"『以为只看最近几个词』那条误区"},{"q":"把注意力分数做 softmax 是为了什么？","opts":["让负数变成正数","让分数变成加和为 1 的权重，且强调大的","让计算更快","让向量变短"],"a":1,"explain":"Softmax 把一坨任意分数变成『加起来为 1』、且大者更大的概率分布，这样加权求和才合理、可解释。","jump":"sec5-step2","jumpLabel":"Softmax 归一化成权重这一步"},{"q":"Self-Attention 与 Cross-Attention 的区别是？","opts":["没有区别","Self 是同句话内部互相理解；Cross 是让一方去读另一方","Self 只用于图片，Cross 只用于文字","Self 更快，Cross 更慢"],"a":1,"explain":"Self-Attention 的 Q/K/V 来自同一句话；Cross-Attention 的 Q 来自一方、K/V 来自另一方（翻译、RAG 都用）。","jump":"sec7","jumpLabel":"对比区里的 Self vs Cross 那一条"},{"q":"多头注意力（Multi-Head）的本质好处是？","opts":["让模型更快","让模型从多个不同视角同时理解，组合出更丰富的语义","让上下文窗口变长一倍","省掉 Softmax"],"a":1,"explain":"把模型注意力想象成多个不同的专家，各看一面（指代、语法、距离），最后合并，理解更全面。","jump":"sec5-step5","jumpLabel":"多个头并行这一步"}],"done":"你已经理解 Attention 是 Transformer 的心脏。这个『找相似、加权吸收』的机制，也是后面 RAG 把检索结果喂进模型时的同一套逻辑。","nextLesson":"l-transformer"},{"type":"connection","known":["词 → 向量（Embedding）","向量方向越像、语义越近（余弦相似度）"],"learned":["每个词同时扮演 Query / Key / Value 三角色","注意力 = 相似度分数 → softmax 权重 → 加权求和","Self-Attention 让句子内部互相理解，多头提供多视角","Attention 任意位置直连、无距离衰减，解决了长句遗忘"],"next":"Attention 是 Transformer 的心脏。下一课我们把这套注意力装进一个完整的架构：位置编码、多头、归一化……看看它怎么组成一个能真正训练、能翻译能写诗的大模型——Transformer。"}]},{"id":"l-transformer","title":"Transformer｜大模型的地基架构","subtitle":"为什么 2017 年诞生的它，能横扫翻译、写作、代码、对话？一个 20 分钟看懂『大模型的心脏是怎么拼出来的』。","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"25-30 分钟","difficulty":3,"concepts":["transformer","position-enc","multihead","attention"],"prereqLessons":["l-attention"],"nextLesson":"l-rag","sections":[{"type":"opening","question":"上一课我们有了 Attention，它能让任何两个词互相关注。但只用 Attention 还是没法当一个能工作的模型——它不知道『第 5 个词和第 2 个词』谁先谁后，也堆不了很深。猜一猜：研究人员 2017 年到底在 Attention 外面『加了哪些零件』，才把它拼成了横扫一切的 Transformer？","guess":"很多人以为 Transformer = Attention，觉得『注意力』就是全部。","next":"这节课我们把注意力装进完整的大脑：位置编码、多头、残差、归一化、前馈网络、N 层堆叠。学完你就明白，为什么它能取代 RNN、成为所有大模型的共同地基。"},{"type":"why","before":"上一课我们有了 Attention：任何两个词都能直接互相关注。但这只是一块『积木』，离一个能真正工作的模型还差很远。","problem":"只靠 Attention 不够：1) 它不知道词的位置——『猫追狗』和『狗追猫』词全一样；2) 一层注意力学到的东西有限；3) 想堆深又容易训练不动（梯度消失）。","need":"Transformer 就是给 Attention 配上『位置感、深度、稳定训练』三件装备，把一块积木组装成一台可以训练、可以并行、可以堆得极深的机器。它是 ChatGPT、Claude、Gemini 的共同地基。","visualNote":"下面这张图是 Transformer 的主干流水线，你可以一步一步点开看每一层在干什么。"},{"type":"oneline","text":"Transformer 是 2017 年提出的一个『把注意力机制组装成完整大脑』的架构：它用『多头注意力 + 前馈网络 + 残差连接 + 位置编码』堆成一层又一层的模块，能并行、能训练得非常深，从此成为所有现代大语言模型的共同地基。"},{"type":"visual","kind":"transformer-flow","title":"Transformer 主干流水线：一步一步看","hint":"点击【下一步】，观察一个词从数字向量走到预测下一个词的完整过程：输入 → 位置编码 → 多头注意力 → 残差+归一化 → 前馈网络 → 重复堆叠 → 输出。"},{"type":"intuition","blocks":[{"k":"一个加工厂流水线","t":"把 Transformer 想成一家加工厂：原料是一串向量。每个工位（层）做两件事——同事协作（注意力，大家互通信息）+ 个人精加工（前馈网络，每个词独自想更深）。一层做完送下一层，共 N 层。"},{"k":"用乐高积木来想","t":"Attention 只是其中一块积木。Transformer 是说明书：告诉你这一层要怎么拼——注意力 + 残差 + 归一化 + 前馈，然后复制粘贴 N 次。"},{"k":"办公室里的并行会议","t":"RNN 像只有一个话筒的圆桌，每人必须轮流说（慢）；Transformer 像微信群——所有人同时发言、同时收听（并行快），谁跟谁相关自己匹配（注意力）。这就是它又快又强的秘密。"}]},{"type":"how","intro":"一个词在 Transformer 里的完整旅程。每一步都围绕同一批向量做变换，最后模型学会『预测下一个词』。","steps":[{"in":"输入：词向量 + 位置编码","process":"每个词先查表得到 Embedding 向量。但向量本身不含位置，所以再加一个位置信息（位置编码），让模型知道『这是第 5 个词』。","out":"每个词都带上位置的向量"},{"in":"多头注意力层（同事协作）","process":"这一层让每个词结合全局上下文：用上节课的 Q/K/V 机制，多组并行，输出再拼接。词的『含义』从此包含了周围所有词。","out":"每个词变成理解上下文后的新向量"},{"in":"残差连接 + 归一化（稳定训练）","process":"把『进来的向量 + 注意力算完的向量』加在一起（残差），再做归一化。这就像修了一条高速公路：信息不衰减地直接流过深层。","out":"浅层信息能无损抄近道到达深层，网络可以堆得深"},{"in":"前馈网络 FFN（个人精加工）","process":"一个两层全连接网络，对每个词独立做非线性变换，让模型有能力表达更复杂的关系。","out":"每个词被再想一想，表达能力增强"},{"in":"重复堆叠 N 层","process":"把『注意力 + 残差 + 归一化 + 前馈』复制 N 次叠起来（GPT 有十到上百层）。每层都让词的表示更抽象、更接近任务。","out":"深层的向量已经浓缩了整句话的语义"},{"in":"输出：预测下一个词","process":"最后一层接线性层 + softmax，把向量变成词典里每个词的概率，取概率最高的作为下一个词。","out":"生成一个词 → 拼回输入 → 继续预测下一个词"}]},{"type":"realworld","items":[{"name":"ChatGPT / GPT 系列","note":"Decoder-only Transformer：单纯地一层层预测下一个词，就长出了对话和推理能力。"},{"name":"Claude / Gemini","note":"同一架构的不同工程实现：同样的多头注意力 + 深层堆叠，在尺度与训练技巧上各有差异。"},{"name":"翻译与摘要模型（T5/BART）","note":"Encoder-Decoder 结构：编码器读懂全文，解码器再一句句生成译文或摘要。"},{"name":"代码补全（Codex 前身/Copilot）","note":"把代码当另一种语言喂给 Decoder-only Transformer，学会了补全、续写、改 bug。"}]},{"type":"compare","pairs":[{"a":"RNN","b":"Transformer","diff":"RNN 顺序串行、远处信息衰减、难并行；Transformer 全局直连、天然并行、能堆深。2017 后几乎完全取代 RNN。"},{"a":"Encoder-only（BERT）","b":"Decoder-only（GPT）","diff":"前者双向读全文、擅长理解（分类/检索）；后者只能从左往右、擅长生成（对话/写作/代码）。"},{"a":"单层注意力","b":"N 层堆叠的 Transformer","diff":"单层只做一次互相看；Transformer 把多次『互相看 + 精加工』叠起来，让表示一层比一层抽象。"},{"a":"Transformer","b":"Attention","diff":"Attention 是其中的一个子模块；Transformer 是包含注意力在内的一整套完整架构。很多人把两者画等号，其实 Attention ⊆ Transformer。"}]},{"type":"mistakes","items":["以为『Transformer = Attention』。Attention 只是其中一个子模块，完整架构还包括残差、归一化、前馈、位置编码。","以为 BERT 和 GPT 一样。BERT 双向理解、GPT 单向生成，职权完全不同。","以为层数越多一定越好。层越深效果提升有边际，还带来更大算力和训练难度。","把『位置编码』当可选项。没有它，『猫追狗』和『狗追猫』对模型来说完全一样——这可是天壤之别。","以为 ChatGPT 用的是完整 Encoder-Decoder。GPT 只用 Decoder-only，这是它和 T5 这类翻译模型的关键区别。"]},{"type":"deep","title":"深入一点：从直觉到架构细节","beginner":["位置编码就是给每个词加一个『第几个』的记号，否则『猫追狗』和『狗追猫』对模型来说字全一样。","残差连接简单说就是『进来和出去加一起』，像搭桥——让深层的梯度不会消失，模型才能堆数十上百层。","前馈网络 FFN 是给每个词单独换个角度想一遍，和注意力（词与词协作）分工不同、缺一不可。","GPT 其实只用了 Transformer 的一半：只有解码器那套（Decoder-only），用来不停地预测下一个词。"],"advanced":["核心是 Decoder：每个 token 只看自己和前面（因果掩码 causal mask），保证预测时不偷看未来。这是它和编码器的最大区别。","缩放点积注意力：Attention = softmax( (Q·Kᵀ) / √d )·V。除以 √d 防点积过大导致梯度消失 / softmax 饱和。","三种架构：Encoder-only（BERT：理解）、Decoder-only（GPT：生成）、Encoder-Decoder（T5：翻译/转换）。ChatGPT 系清一色 Decoder-only。","残差连接 + LayerNorm（常采用 Pre-LN 顺序：先归一化再进子层）是训练稳定性的关键工程细节，是它能堆到千亿参数的原因之一。","复杂度 O(n²)：上下文窗口越大成本越高——这直接决定了长上下文为什么贵、为什么要引入 RAG。",{"code":"# 概念示意：位置编码的经典公式（体会它想表达什么即可）\nimport math\n\ndef pos_encoding(pos, d_model=8):\n    vec = []\n    for i in range(d_model):\n        angle = pos / (10000 ** (2 * (i // 2) / d_model))\n        vec.append(round(math.sin(angle), 3) if i % 2 == 0 else round(math.cos(angle), 3))\n    return vec\n\nfor p in [0, 1, 2, 3]:\n    print(f\"第{p}个词的位置: {pos_encoding(p)}\")\n# 每个位置生成一组各不相同的位置向量 → 模型据此知道先后顺序","lang":"python"}]},{"type":"exercise","prompt":"如果完全不给模型位置编码，只给它 Attention，那么『猫追狗』和『狗追猫』这两句话，模型会怎么看待？","opts":["认为它们语义完全不同（追的方向相反）","认为它们几乎一样（词完全相同，注意力无差别混合）","认为它们字数不同","完全无法处理两个词以上的句子"],"a":1,"explain":"注意力是把所有词互相加权求和，本质记不得先后顺序。没有位置编码，模型会认为两句话『字都一样所以差不多』，分不清谁追谁。这正是位置编码存在的意义。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"type":"check","title":"结课检测：你真的理解 Transformer 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 Transformer 需要位置编码？","opts":["为了让向量维度变大","因为注意力本身不含位置信息，没有它『狗追猫』和『猫追狗』无法区分","为了加快计算","为了让训练更快收敛"],"a":1,"explain":"注意力把所有词互相加权、天然不记顺序；位置编码把『第几个』注入向量，模型才知道先后。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"q":"残差连接（Residual）的主要作用是？","opts":["增加参数数量","让信息能无损跨层传递，网络可以堆得很深且训练稳定","让模型更快生成","代替位置编码"],"a":1,"explain":"把输入与输出相加，像搭桥一样让信息直达深层，缓解梯度消失，是能堆几十上百层的关键。","jump":"sec5-step2","jumpLabel":"残差连接 + 归一化这一步"},{"q":"GPT 属于哪种结构？","opts":["Encoder-only","Decoder-only","Encoder-Decoder","既不是编码器也不是解码器"],"a":1,"explain":"GPT 只用解码器（带因果掩码、从左往右生成），反复预测下一个词。","jump":"sec9","jumpLabel":"深入节里 GPT=Decoder-only 那条"},{"q":"Attention 和 Transformer 的正确关系是？","opts":["它们是同一个东西","Transformer 是 Attention 的一个零件","Attention 是 Transformer 的一个子系统，Transformer 是完整架构","完全没有关系"],"a":2,"explain":"Attention ⊆ Transformer：Transformer 在 Attention 之外还包含残差、归一化、前馈、位置编码等。","jump":"sec8","jumpLabel":"『以为 Transformer=Attention』那条误区"},{"q":"为什么说 Transformer 比 RNN 快（并行）？","opts":["因为它跳过了很多词","因为它让所有词同时参与计算，不用一个字一个字排队","因为它更短","因为它的层更少"],"a":1,"explain":"RNN 必须按顺序串行处理每个词；Transformer 所有位置并行计算，谁跟谁相关靠注意力自己匹配。","jump":"sec7","jumpLabel":"对比区 RNN vs Transformer"}],"done":"你已经明白大模型的地基长什么样了。但这个『什么都会的模型』只记得训练时的知识——它不知道你公司的最新政策。下一课解决这个问题。","nextLesson":"l-rag"},{"type":"connection","known":["Attention：Q/K/V 加权求和，让词与词互相关注","词是向量，语义可算相似度"],"learned":["Transformer = 多头注意力 + 残差 + 归一化 + 前馈网络的 N 层堆叠","位置编码让模型感知顺序，否则猫追狗 = 狗追猫","GPT 是 Decoder-only，靠预测下一个词长出能力","O(n²) 复杂度是长上下文贵的根源，引出 RAG"],"next":"Transformer 有了，模型『什么都懂但只记得训练时的知识』。下一课我们解决这个关键问题：RAG——怎么让模型在回答前先到你的资料库查资料，从而答出它没学过的私有内容。"}]}],"c07-rag":[{"id":"l-rag","title":"RAG｜让模型『查资料』再回答","subtitle":"为什么 ChatGPT 不知道你的私有文档？怎么让模型『翻开你的资料』再回答？从切块到生成，一条流水线看懂 RAG。","category":"c07-rag","chapterTitle":"第一章 · RAG 全流程","level":"base","estTime":"30-35 分钟","difficulty":2,"concepts":["rag-pain","rag-pipeline","chunking","emb-vector-store","vector-search","rerank"],"prereqLessons":["l-transformer","l-embedding"],"nextLesson":"l-agent","sections":[{"type":"opening","question":"你的同事把公司 80 页的员工手册发给你，让你问 ChatGPT『年假到底有几天』。但 ChatGPT 根本没见过这本手册——你猜它是会照着手册答，还是自己编一个答案？如果它答错了，该怎么办？","guess":"很多人觉得「那就把整本手册贴上问它」。但手册几十万字，靠粘贴根本塞不进一次对话，而且重点会淹没在噪声里。","next":"这节课要讲的就是正解：RAG 检索增强生成。它让模型在回答前，先去你的资料库里『只挑最相关的几段』，再照着这几段回答——既答得准，又附出处。"},{"type":"why","before":"经过前面几课，我们已经有了一个很聪明的模型（Decoder-only Transformer）。但它有一个致命限制：它只知道训练时见过的东西，而且经常一本正经地编造（幻觉）。","problem":"1) 你的合同、内部 SOP、论文——模型训练时根本没看过；2) 即使看过，版本也早就过期了；3) 让它硬答私有问题，它大概率会编。而重新训练整个模型，又贵又慢又不可能频繁做。","need":"与其改模型的『脑子』，不如每次回答时给它配一本『说明书』：先把相关的资料找出来喂给它，让它照着说。这个思路就是 RAG——简单、便宜、资料随时能更新。","visualNote":"下面这条流水线是 RAG 的完整精神：切块 → 向量化 → 检索 → 重排 → 组装 → 生成。你可以点『运行』亲手体验。"},{"type":"oneline","text":"RAG（检索增强生成）就是：让模型在回答之前，先去你的资料库里检索相关内容，把查到的片段拼进上下文，再让模型照着一小份『精选资料』作答。于是它能回答自己没学过的私有知识，还能顺便指出出处。"},{"type":"visual","kind":"rag-pipeline","title":"RAG 完整流水线：从文档到回答（可交互）","hint":"这就是升级版可交互 RAG 实验：左边填一份『你要提问的文档』，下面输问题，点【▶ 运行 RAG】。观察系统如何切块 → 向量化 → 检索 → 重排 → 组装上下文 → 生成带引用的回答。"},{"type":"intuition","blocks":[{"k":"开卷考试 vs 闭卷考试","t":"普通 LLM 是闭卷考试：只凭脑子里的记忆答题，记不住就编。RAG 是开卷考试：允许你翻资料，翻到相关的那页再答。显然开卷更可靠、更可核对。"},{"k":"图书馆查书再回答","t":"你问『公司年假制度是什么』。RAG 不会直接在记忆里编，而是先去公司知识库检索年假相关文档，找到后引用着回答。"},{"k":"不是变聪明，是带了参考书","t":"RAG 不提升模型智商，而是每次回答都带着最新、属于你的资料。资料一更新，回答立刻跟着更新，完全不用重新训练模型。"}]},{"type":"how","intro":"RAG 分两个阶段：『入库』（离线，把文档变成可检索的向量库）和『查询』（在线，用户提问时检索 + 生成）。下面是完整流程，也是本课的主干。","steps":[{"in":"先想清楚：为什么要用 RAG","process":"场景判断：需要回答私有/最新/超长知识，或答案需要可溯源时用 RAG。如果模型自带答案且内容不敏感，也许不需要 RAG。","out":"RAG 解决『知识更新与私有化』，不是『让模型变聪明』"},{"in":"解析 Parsing","process":"把原始文档（PDF、Word、网页）用解析器抽取出结构化文本，去掉页眉页脚、图表残渣，必要时做 OCR。","out":"干净、可用的纯文本"},{"in":"切块 Chunking","process":"把长的文本切成几百到上千字的小块。切多大、是否重叠、按什么切（标题/段落）直接影响检索质量。","out":"文档 → 若干 chunk（带来源、页码等元数据）"},{"in":"向量化 Embedding","process":"用 Embedding 模型把每个 chunk 变成一个向量（语义相近的向量相近）。","out":"每个 chunk → 一个向量"},{"in":"存入向量库 VectorDB","process":"把『向量 + 原文 + 元数据』存进向量数据库（FAISS、Milvus、pgvector、Qdrant），并建好索引以便毫秒级检索。","out":"可快速相似检索的向量库"},{"in":"检索 Retrieval（含 Top-K）","process":"用户提问时，把问题也向量化，在向量库里找最像的『Top-K 块』（通常 K=5~20，按余弦相似度排名）。","out":"问题 → 排好序的 N 个候选 chunk"},{"in":"重排序 Rerank","process":"初筛的 Top-K 往往有噪音。用一个更精细的模型把 K 个候选再精排，把真正相关的提到最前、滤掉无关项。","out":"更精准的少量片段（通常取前 3~5 块）"},{"in":"组装上下文 + 生成","process":"把精选 chunks 拼进 Prompt，附上问题，提示模型『只依据下面资料回答并引用出处』。LLM 据此生成带引用的回答。","out":"有出处、可更新、针对私有知识的回答"}]},{"type":"realworld","items":[{"name":"NotebookLM","note":"你上传 PDF/视频，它检索你的资料再回答，还能生成带引用的播客、摘要。教科书级 RAG 产品。"},{"name":"企业内部知识库客服","note":"把 SOP、产品手册向量化，客服 AI 查文档再回答，而不是对着空气编。"},{"name":"Claude Projects / 附件上传","note":"给对话挂上资料，模型按需检索引用，本质是一套轻量 RAG。"},{"name":"搜索增强的 ChatGPT / Perplexity","note":"它先联网检索实时网页，再基于检索结果回答——用互联网当『向量库』的 RAG。"}]},{"type":"compare","pairs":[{"a":"RAG","b":"微调 Fine-tuning","diff":"RAG 每次查最新资料、可溯源、便宜、可随时更新；微调是改模型脑子、更适合学风格学格式。知识类更新首选 RAG。"},{"a":"向量检索（语义）","b":"关键词检索（BM25）","diff":"向量找语义相近（换个说法也能找到）；关键词精准匹配字面（找人名/编号更稳）。生产常用『混合检索』互补。"},{"a":"RAG","b":"超长上下文","diff":"RAG 主动挑最相关片段、便宜快速；超长上下文把整本书塞进去、贵且重点容易淹没。大资料库优先 RAG。"},{"a":"RAG","b":"Agent","diff":"RAG 是『查资料再回答的单步机制』；Agent 是『多步决策、自己调用工具的循环』。两者常配合：Agent 需要信息时用 RAG。"}]},{"type":"mistakes","items":["以为 RAG = 把文档一股脑塞进提示词。真正的 RAG 要先切块、向量化、检索、重排，只喂最相关的几块。","忽略 chunking 质量。切坏了，再好的模型也答不准——检索进来自的都是垃圾，这叫『垃圾进、垃圾出』。","以为检索到就完了、不必做 rerank。初检的 Top-K 常有噪音，重排能明显提高准确率。","忘记引用溯源。落地到医疗/法务/企业等严肃场景，没有出处等于不可信。","把 RAG 当成解决幻觉的万灵药。资料里没有、或检索失败时，模型照样可能编——还要做『越权拒答』『检索兜底』。","只在单文档上跑 RAG 就上生产。跨多文档局部推理（关系、总分结构）需要更进阶的方案（如 GraphRAG、切分策略优化）。"]},{"type":"deep","title":"深入一点：把 RAG 的每一个零件都拆开","beginner":["chunk 太小 → 语义不完整；chunk 太大 → 噪音多、可能被截断。常见几百~一千字，配合 20%~50% 重叠（overlap）避免把完整语义在边界切断。","向量相似 ≠ 字面相似：换个说法（『年假』vs『带薪假期』）有时也能检索到，这是向量检索比关键词强的地方。","RAG 不会凭空创造知识，它只会引用你给的东西——资料库质量 ≈ 回答质量。","Top-K 的含义：K 是取前几个相似块。K 太小漏信息，K 太大引入噪音挤占上下文，通常 5~20 之间调。"],"advanced":["混合检索（Hybrid）：向量检索（语义）+ 关键词检索（BM25，精确匹配人名/编号）并行，再用加权或 RRF 融合，互补漏检。","Rerank 为什么必要：初检向量健壮但不精，专门的 rerank 模型（cross-encoder）能逐对精判相关性，显著提升准确率和最终回答质量。","引用溯源（Citation / Grounding）：让模型输出带片段编号，用户可核对来源；对合规落地几乎是刚需。","切分进阶：按章节/标题等『结构感知』切块（structure-aware chunking）、父子块（parent-child）、滚动窗口，都比盲目按字数切更好。","评估：用『召回率（该找到的找到没）+ 准确率（找到的是不是都相关）』评价检索，用『忠实度/有据率』评价最终回答，还要做『检索失败与拒答』的兜底。","Agentic RAG：把检索从单次升级成『多轮自主规划』——Agent 先判断需要什么信息、决定检索哪几个库、必要时多轮追问或修正查询词，而不是一次检索定死。",{"code":"# 概念示意：RAG 里最核心的一步——向量检索（伪代码思路）\nimport numpy as np\n\nchunks = [\"年假制度：入职满一年享 5 天…\", \"报销流程：金额低于 1000 走 OA…\"]\nchunk_vecs = [np.array([0.9, 0.1]), np.array([0.1, 0.9])]  # 示意向量\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\nquery_vec = np.array([0.85, 0.15])  # 用户问题『年假有几天』向量化\ntop_k = 1\nranked = sorted(((cosine(query_vec, v), i) for i, v in enumerate(chunk_vecs)),\n                reverse=True)[:top_k]\nprint('最相关的资料块:', chunks[ranked[0][1]])\n# → 年假制度那一段","lang":"python"}]},{"type":"exercise","prompt":"继上一课：公司手册 80 页，你的知识库已经把它切成几百块并存好向量。现在问『年假有几天』，系统检索返回了 8 个候选块，其中第 3 块是『员工福利总览』、第 7 块是『请假制度细则』。下一步系统应该做什么？","opts":["直接把 8 块全部塞进提示词","对 8 块做 Rerank 精排，只取最相关的 3~5 块再喂给模型","不用检索了，直接让模型猜","把 8 块向量相加存回库里"],"a":1,"explain":"初检的 Top-K 常有噪音。正确做法是先 Rerank 精排，把真正相关的『请假制度』提到最前、滤掉无关的『福利总览』，再只喂少量精选块给模型——既省上下文又更准。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"type":"check","title":"结课检测：你真的理解 RAG 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"RAG 解决的核心问题是？","opts":["让模型数学更好","让模型能回答私有/最新知识并可溯源，而不用重新训练","让模型更快生成","让模型学会编程"],"a":1,"explain":"RAG 的核心价值：用检索到的外部资料补充模型没学过的知识，便宜、可更新、可引用。","jump":"sec5-step0","jumpLabel":"先想清楚为什么要用 RAG 这一步"},{"q":"RAG 的『入库』阶段，正确的顺序是？","opts":["向量化 → 切块 → 存库","切块 → 向量化 → 存库","存库 → 向量化 → 切块","检索 → 切块 → 向量化"],"a":1,"explain":"先把长文档切成 chunk，再逐块向量化，最后连向量带原文存进向量库。检索是查询阶段的事。","jump":"sec5-step2","jumpLabel":"切块 Chunking 这一步"},{"q":"『切块太大（比如把整章当一个块）』最可能带来什么问题？","opts":["向量库存不下","块内噪声多、关键信息被淹没，检索和回答变差","一定比小块更准","会让模型忘掉上下文"],"a":1,"explain":"块太大噪声多、语义杂，检索命中后无关内容挤占上下文，回答质量下降。所以要用合适的块大小 + 重叠。","jump":"sec9","jumpLabel":"深入节里关于 chunk 大小/重叠的说明"},{"q":"为什么生产系统里还要做 Rerank 重排？","opts":["为了多花一点算力","初检的 Top-K 常有噪音，用更精细的模型重排能显著提升相关性与准确率","为了把回答变长","为了跳过 Embedding"],"a":1,"explain":"向量初检健壮但不精，专门的 rerank 模型能逐对精判，把真正相关的片段提到最前。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"q":"资料库里根本没有答案时，一个设计良好的 RAG 系统应该？","opts":["强行编一个最像的答案","在引用不到出处时明确『资料中未找到』或拒答，做检索兜底","把用户问题原样丢回","删掉这个问题"],"a":1,"explain":"RAG 不是幻觉万灵药。检索不到可靠出处时应『越权拒答/检索兜底』，而不是硬编。","jump":"sec8","jumpLabel":"『把 RAG 当万灵药』那条误区"}],"done":"你已经掌握 RAG 的完整流水线和调优要点。现在模型会查资料了，但它还是『你问一句、它答一句』。最后一课，我们让它自己动起手来。","nextLesson":"l-agent"},{"type":"connection","known":["Embedding：文字 → 向量，语义相近的向量相近","Transformer：模型的脑子","上下文窗口：模型一次能看多少"],"learned":["RAG 让模型先检索资料再回答，解决私有/最新/可溯源","完整流程：解析 → 切块 → 向量化 → 向量库 → 检索 Top-K → 重排 → 组装 → 生成 + 引用","chunk 大小/重叠、混合检索、Top-K、rerank、评估、Agentic RAG 等调优点","RAG vs 微调 vs 长上下文 vs Agent 的取舍"],"next":"RAG 让模型会查资料，但模型仍停在你说一句、它应一句。下一课是这个旅程的终点也是新起点：Agent——让模型自己拆目标、自己调用工具、根据反馈循环，把一整件事独立做完。"}]}],"c08-agent":[{"id":"l-agent","title":"Agent｜让 AI 自己动手做事","subtitle":"为什么 ChatGPT 只能在对话框里打字，而 Codex 能改你的代码、跑你的测试、提交 PR？Agent 就是把『会说话』的模型，变成『会做事』的执行者。","category":"c08-agent","chapterTitle":"第一章 · 从会说到会做","level":"base","estTime":"25-30 分钟","difficulty":2,"concepts":["agent-intro","agent-loop","tool-use","agent-planning","agent-memory","agent-reflection"],"prereqLessons":["l-rag","l-transformer"],"nextLesson":"l22-ai-coding","sections":[{"type":"opening","question":"你已经能让 ChatGPT 把某个概念讲得头头是道，也能用 RAG 让它查你的资料。但如果你说『去我 GitHub 仓库里把那个测试失败修掉』——为什么 ChatGPT 只能在对话框里给建议，而 Codex 却能真的打开文件、改代码、跑测试、把活干完？","guess":"有人会说「Codex 的模型更聪明」。","next":"这节课揭穿这个误会：Agent 的厉害不在模型智商，而在于给模型装上一个『决策循环 + 一双能动手的工具』。学完你就掌握 Agent = 模型 + 工具 + 循环这条主线。"},{"type":"why","before":"到这一课，我们有了很聪明的模型、也有了让它查资料的 RAG。但你还是有个困扰：让 ChatGPT 整理个表格它倒是能，让它『去我仓库里改掉那个 bug』，它做不到。","problem":"因为聊天模型只有一张嘴：它只能输出文字，看不见你的文件、读不了你的代码、跑不了测试命令。你让它操作仓库，它连仓库在哪都不知道。","need":"Model（思考）+ Tools（手和眼）+ Loop（循环驱动）= Agent。它想一下 → 动一下 → 看一眼结果 → 再想 → 再动。这就是 ChatGPT 和 Codex 的分水岭。","visualNote":"下面这个循环图就是 Agent 的灵魂——你可以亲手点不同工具，看它每一步怎么决策、怎么应对失败。"},{"type":"oneline","text":"Agent（智能体）不是换个更厉害的模型，而是给模型装上一个『决策循环』：它会自己拆目标、自己调用工具（读写文件、执行代码、搜网页）、观察结果、再决定下一步，如此循环直到把事情做完。同样一个模型，套上这个循环，就从『只会回答』变成了『会做事』。"},{"type":"visual","kind":"agent-loop","title":"Agent 循环模拟器：想 → 做 → 看 → 再想（可交互）","hint":"这是一个升级版交互模拟器：你扮演一个修复 bug 的 Codex Agent，在每个步骤从几个工具里选一个。选对了推进，选错了会得到失败反馈，教你『Agent 正是靠不断试错修正才把活干完』。"},{"type":"intuition","blocks":[{"k":"计算器只会算，助理会办事","t":"普通聊天模型像一台高级计算器：你问它答。Agent 像你的助理：你交代一件事，它自己拆步骤、打电话（调工具）、核对结果，办完给你汇报。"},{"k":"不是变聪明，是变『能动』","t":"它没有比 ChatGPT 更聪明——它只是多了一圈『能动手、能看反馈、能再试』的回路。代码还是那个代码，差别在于它学会了执行-反馈-调整。"},{"k":"有钥匙的实习生 vs 没钥匙的实习生","t":"ChatGPT 是没钥匙的实习生：看到门（需要改文件）只会描述『你应该去改那个文件』。Agent 是有钥匙的实习生：自己开门、改文件、跑测试、看结果、再改。"}]},{"type":"how","intro":"一个 Agent 改 bug 的完整工作过程。核心就一句话：目标 → 循环（想 + 做 + 看）→ 交付。这也是本课的骨架。","steps":[{"in":"理解目标","process":"用户下达：『修好注册页面的 bug』。模型先把模糊目标翻译成具体子任务列表。","out":"一个可执行的任务清单"},{"in":"规划 Planning","process":"它推理出步骤：先找到注册页代码 → 读源码定位问题 → 想怎么改 → 改 → 跑测试验证。","out":"Agenda：找代码 → 读 → 改 → 测"},{"in":"调用工具 Tool Use（做）","process":"它请求调用工具：read_file 读代码、edit_file 修改、run_command 跑测试。工具返回结果。","out":"一次具体的『动手』"},{"in":"观察结果 Observe（看）","process":"看到工具返回值：测试报错，或编译失败。它读到反馈，判断是否达到目标。","out":"对『刚才做对没有』的感知"},{"in":"循环 Loop：再想再做","process":"若未达成，回到『想』：根据报错调整方案，再调用工具。如此循环直到测试通过或放弃。","out":"反复的 agent loop（这正是与 ChatGPT 的本质区别）"},{"in":"交付与汇报","process":"任务完成：向用户总结改了什么、测试结果，甚至主动提交 PR、申请权限。","out":"一件完成的事，而不是一段话"}]},{"type":"realworld","items":[{"name":"Codex / Claude Code","note":"Agentic Coding 的典型：能读你的仓库、找 bug、改代码、跑测试、提交 PR。这就是『ChatGPT 做不到、它做得到』的原因——它装了代码工具 + agent loop。"},{"name":"Cursor / Windsurf","note":"IDE 里的 Agent：理解整个项目上下文，跨多个文件完成重构，而不只是一行行补全。"},{"name":"浏览器 Agent（Browser Use / Operator）","note":"自己打开网页、读取、点击、填表，把逛网页办事自动化。"},{"name":"n8n / 工作流编排","note":"让 Agent 串联多个工具/API 完成端到端业务流程（取数 → 处理 → 发通知）。"}]},{"type":"compare","pairs":[{"a":"Chatbot（聊天机器人）","b":"Agent（智能体）","diff":"Chatbot 只输出文字、终结于回答；Agent 拆目标、调工具、看结果、循环迭代，终结于做成事。"},{"a":"单次工具调用","b":"多步 Agent Loop","diff":"会调一个工具的助手只是初级；真正的 Agent 会根据结果决定下一调用，持续多轮直到完成。"},{"a":"RPA（脚本化机器人）","b":"LLM Agent","diff":"RPA 按写死的剧本执行、一变就崩；Agent 动态推理、能处理没见过的异常情况。"},{"a":"Agent","b":"RAG","diff":"Agent 是『多步决策、自己调用工具的循环』；RAG 是『查资料再回答的单步机制』。Agent 需要信息时常用 RAG 当其中一个工具。"}]},{"type":"mistakes","items":["以为 Agent 只是换了个更聪明的模型。本质差别在『循环 + 工具』，不是模型本身。","以为 Agent 能无限可靠地自主执行。它也会反复失败、会犯错，所以需要权限门槛（approval gate）、观测和护栏。","忽视权限与安全。放任 Agent 删文件/发数据/花钱是最危险的坑，生产环境必须加授权与审计。","把会调用工具当成有规划和反思。会调一个函数 ≠ 会拆解复杂目标并自我修正，后者才是 Agent 的进阶。","以为多 Agent 一定更好。多数场景单 Agent 更简单可控，盲目堆 Agent 只会带来编排复杂度和成本。"]},{"type":"deep","title":"深入一点：Agent 的工程骨架","beginner":["Agent Loop 不是魔法：本质就是模型的 for/while 循环——决定下一步 → 调用工具 → 看结果 → 决定再下一步。","工具（Tool）就是一个函数：read_file、write_file、run_command、web_search。模型学会了在合适时机调用它们。","最朴素的 Agent = LLM + 工具集 + 一个决定何时停止的循环。它也可以有记忆和规划，但核心就是这个循环。"],"advanced":["Tool Use / Function Calling：模型输出结构化的『要调用哪个函数、传什么参数』，由系统执行并把结果喂回去，形成闭环。","记忆分两层：短期（当前任务的对话/工具历史）与长期（跨对话的项目知识、偏好，常存向量库）。","Planning 范式：ReAct（Reason + Act 交替）、Plan-and-Execute（先定计划再逐步执行，plan 可被动态修订）、Tree-of-Thought 等。","权限与安全 Permission：Agent 不会无限乱来——危险操作（删文件、花钱、外发数据）要求用户授权（approval gate）。","MCP（Model Context Protocol）：统一工具/数据源接入协议，让一个 Agent 能标准化接入文件系统、数据库、浏览器等多种工具，避免每家写一套私有接口。","Reflection 反思：让 Agent 回顾刚才失败的原因再调整，显著提升长任务可靠性。多 Agent 协作则是多个专业 Agent 分工。",{"code":"# 概念示意：Agent 循环的骨架，就长这样\nwhile not goal_reached:\n    thought = model.think(state, memory)      # 想：我要做哪一步？\n    if thought.should_stop: break              # 判断是否完成\n    tool_result = call_tool(thought.tool_call) # 做：调用工具\n    state.append(tool_result)                  # 看：把结果存进上下文\n    memory.update(state)                       # 记住教训\n# 交付\nreport(model.summarize(state))","lang":"python"}]},{"type":"exercise","prompt":"你（作为 Codex Agent）被要求『修好登录页的 bug』。你读完代码，发现登录按钮点击后有报错。现在到了『做』这一步——猜一猜，Agent 下一步最合理的选择是哪个？","opts":["直接凭记忆改掉一行代码","先运行测试/查看报错日志，定位错误来源，再决定改哪里","马上发邮件问用户想怎么改","直接重新写整个登录页"],"a":1,"explain":"正确动作是先『看』——运行测试或读日志拿到报错信息，有了反馈才知道要改哪。这正是 Agent loop 里『做』与『看』的配合：不观察就动手，等于闭眼改代码。","jump":"sec5-step3","jumpLabel":"观察结果 Observe 这一步"},{"type":"check","title":"结课检测：你真的理解 Agent 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 ChatGPT 不能操作你的仓库，而 Codex 可以？","opts":["因为 Codex 的模型更聪明","因为 Codex 被接上了工具（读写文件/跑命令）+ Agent 循环，ChatGPT 只有对话输出","因为 ChatGPT 没联网","因为模型大小不同"],"a":1,"explain":"决定性差异不是模型智能，而是 Agent 结构：工具让它能动手，循环让它能做→看→修正直到完成。","jump":"sec2","jumpLabel":"一句话理解 Agent 那条"},{"q":"Agent Loop 的核心循环顺序是？","opts":["看 → 做 → 想","想 → 做 → 看 → 再想","只做不看不回头","想 → 想 → 想"],"a":1,"explain":"标准 agent loop：决定下一步（想）→ 调用工具（做）→ 观察结果（看）→ 根据结果再决定下一步（再想），循环到目标达成。","jump":"sec5-step4","jumpLabel":"循环 Loop 这一步"},{"q":"MCP（Model Context Protocol）主要解决什么问题？","opts":["让模型跑得更快","统一 Agent 接入工具/数据源的接口标准，避免各家用私有协议","代替向量数据库","让模型更聪明"],"a":1,"explain":"MCP 是 Agent 与文件、数据库、浏览器等外部工具的标准化接入协议，一次接入、到处复用。","jump":"sec9","jumpLabel":"深入节里 MCP 那条"},{"q":"下面哪个最能代表『Agent 与 Chatbot 的本质区别』？","opts":["Agent 文字更长","Agent 会拆目标、调工具、看反馈并循环，终结于做成事；Chatbot 只回复文字","Agent 不需要模型","Chatbot 也能调用工具"],"a":1,"explain":"Chatbot 止于回答；Agent 以『做成事』为目标，通过循环驱动工具完成多步任务。","jump":"sec7","jumpLabel":"对比区 Chatbot vs Agent"},{"q":"为什么生产环境里 Agent 的危险操作要加『授权门槛（approval gate）』？","opts":["为了拖慢速度","Agent 也会犯错，删文件/花钱/外发数据必须先经用户确认，防止不可逆损失","模型必须要人帮它思考","为了多收费"],"a":1,"explain":"Agent 并非无限可靠，危险动作必须先授权再执行，是落地安全的关键护栏。","jump":"sec8","jumpLabel":"『忽视权限与安全』那条误区"}],"done":"你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。最后一章会带你顺着这条主线进入真正的 AI 编程实践。","nextLesson":"l22-ai-coding"},{"type":"connection","known":["Transformer：模型怎么生成内容","RAG：怎么让模型查资料","工具调用 Function Calling"],"learned":["Agent = 模型 + 工具 + 循环（想→做→看→再想）","它能拆目标、规划、调用工具、观察反馈、反复修正","关键工程点：Tool Use / Memory / Planning / Permission / MCP / Reflection","Chatbot 回答问题，Agent 做成事"],"next":"到这里，你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。想继续深入，建议顺着目标分支走：做产品学 LLM 应用与 RAG，写代码就进入 AI 编程（Agentic Coding / Claude Code）那一章——用 Agent 亲自改代码、跑测试、提交 PR。"}]}],"undefined":[{"id":"v01-web","title":"一个 Web 产品是怎么跑起来的","subtitle":"你在浏览器里敲回车到内容出现，中间发生了什么？把这条链路看懂，你才谈得上『改对地方』。","course":"vibe","courseNo":"01","level":"base","estTime":"15-25 分钟","difficulty":1,"concepts":[],"prereqLessons":[],"nextLesson":"v03-api","sections":[{"type":"opening","question":"你每天打开网页、用 App、点外卖、刷视频——但有没有想过，你在浏览器地址栏输入一串字母并按下回车，到底是哪台机器、用哪段程序、按什么顺序，把你要的内容送到你面前的？","guess":"很多人会回答「就是电脑把网站打开了呀」。","next":"这节课我们不写代码，只把『一个 Web 产品』从头到尾拆开：前端、后端、数据库、服务器、浏览器、网络各是什么，数据是怎么一层层流动的，以及每一层出错时你该怀疑谁。学完你就能对着一屏『转圈』或一条报错，说出它大概死在哪个环节。"},{"type":"why","before":"你想用 AI 辅助做一个自己的小产品（一个网页、一个小工具、一个小网站）。AI 很会写代码，但你写完点开经常『跑不起来』或『一片空白』，你不知道该往哪看。","problem":"问题不在 AI 写的代码——而在于你对『这段代码在什么环境里跑、和谁通信』没有概念。你分不清『报错是我的 HTML 写错了』『还是服务器没启动』『还是数据库没连上』『还是网络被墙了』。于是只能把同样的问题反复丢给 AI，越问越乱。","need":"所以第一课先不碰一行代码，而是先建立『一台 Web 产品从上到下有哪些层、每层做什么』的骨架。当你把『前端 / 后端 / 数据库 / 服务器 / 浏览器 / 网络协议』这条链装进脑子，AI 给的报错就不再是天书，而是能对号入座的线索。"},{"type":"oneline","text":"一个 Web 产品 = 浏览器（前端，负责看得见摸得着的界面）+ 服务器上的程序（后端，负责处理逻辑和读写数据）+ 数据库（负责长期存数据），它们之间靠『网络请求』（HTTP）搬来搬去；而这一切最终都跑在『操作系统 + CPU/内存/磁盘』这台物理机器上。"},{"type":"visual","kind":"request-flow","title":"互动实验：点一次请求，看它走完整条路","hint":"点击『发送请求』，看一次『用户敲回车』的动作如何依次经过浏览器 → DNS 解析 → 网络 → 服务器 → 后端程序 → 数据库 → 再原路返回。每亮起一格就说明数据到了哪一层。"},{"type":"intuition","blocks":[{"k":"用点外卖来想","t":"前端＝你看得到的『点单 App 界面』；后端＝『餐厅后厨，负责接单、炒菜、出餐』；数据库＝『冷库里长期保存的食材和菜谱』；服务器＝『餐厅所在的整栋楼，有水电（CPU/内存/磁盘）』；浏览器就是那个帮你点单、再把菜端到你面前的『外卖小哥』。你看到的每一道菜，都是后厨＋冷库＋外卖小哥协作的结果。"},{"k":"用写信来想","t":"你在浏览器输入网址，就像写一封信：『地址』（域名）要翻译成具体的『门牌号 + 邮编』（IP + 端口），信通过『邮政网络』（网络/IP）送出去，邮局先查收信人住在哪（DNS 解析），送到后对方拆信、处理、再回信。回信能不能到，取决于信中地址写没写对。"},{"k":"一句话记住分层","t":"从上到下：浏览器（前端）→ 网络（DNS/IP/HTTP）→ 服务器 → 后端程序 → 数据库。数据请求沿这条链往下，响应再原路往上。出错时按这条链一层层排查，永远不要跳着乱试。"}]},{"type":"how","intro":"把『输入网址到页面出现』拆成一条 7 步因果链。每一步都回答『数据此刻在哪、谁在处理、为什么能做下一步』。","steps":[{"in":"① 你输入网址，按下回车","process":"浏览器得到一串人类好记的名字，比如 ai-learn.example.com。但网络本身不认名字，它只认数字地址（IP：像 203.0.113.7）。所以第一步要『翻译』。","out":"浏览器准备发起一次『网络请求』"},{"in":"② DNS 解析：把域名翻译成 IP","process":"浏览器向 DNS（域名系统）询问：ai-learn.example.com 对应哪个 IP？DNS 就像电话簿，查到后把『数字地址』告诉浏览器。没有这一步，浏览器不知道该把信寄到哪台机器。","out":"得到了服务器的 IP 地址 + 端口（默认 80/443）"},{"in":"③ 建立连接 + 发送 HTTP 请求","process":"浏览器通过 TCP（可靠的传输协议）连上服务器，然后发送一个『HTTP 请求』：里面写着『我要 GET 这个页面』，还带着浏览器自己是谁（User-Agent / Cookie）等信息。","out":"请求沿着网络，送到那台服务器的指定端口"},{"in":"④ 服务器接收并把请求交给后端程序","process":"这台机器上正跑着一个『服务器进程』（如 Nginx / Node / Python）。它把请求转交给对应后端程序；后端程序执行你自己的业务逻辑：查一查、算一算。","out":"后端程序开始处理：可能要读数据库"},{"in":"⑤ 后端读写数据库","process":"需要持久数据的，后端会去数据库查询或写入。数据库把结果（比如『这个用户的名字』）返回给后端。注意：数据库不住在浏览器里，它住在服务器那台机器上。","out":"后端拿到数据，拼出一份『响应』"},{"in":"⑥ 后端返回 HTTP 响应","process":"后端把生成的 HTML / JSON / 图片，打包成一条『HTTP 响应』发回去，附带状态码（200 成功 / 404 找不到 / 500 服务器出错）与响应头。","out":"响应沿着网络原路回到浏览器"},{"in":"⑦ 浏览器解析并渲染","process":"浏览器收到 HTML，逐行解析：先搭出页面结构，再拉取其中的 CSS/JS/图片等资源，最后把内容画到屏幕上。你这才『看到』了页面。","out":"页面出现在你眼前（一次完整的前后端往返）"}]},{"type":"realworld","items":[{"name":"你平时的网页 = 前端静态页","note":"很多『首页』其实只是浏览器直接渲染的一堆 HTML/CSS/JS 文件，可能根本没有后端。它依然需要前面的 ①②③⑦ 几步，但没有 ④⑤⑥。知道这一点，你排查为何『页面能开但功能没反应』时就能猜到问题多半在后端那段。."},{"name":"登录注册 = 必须有后端 + 数据库","note":"『注册新账号』必须把密码/信息写进数据库，所以必然经过完整的 ①→⑦。前端只是收集输入，真正的校验和存储都在后端 + 数据库。这是『看代码时』判断某功能是否需要后端的标尺。"},{"name":"动态内容（推荐、订单、消息）= 后端在返回数据","note":"你刷到的『为你推荐』是后端程序实时查库、算好、再以 JSON 返回给前端渲染的。这类功能换任何界面（网页/App/小程序）后端代码都基本相同——这也是为什么『前后端分离』这么常见。"},{"name":"云服务器 / 租一台机器","note":"你的产品真正上线后，就『住』在一台云服务器（如腾讯云、阿里云的 ECS）上，这台机器有操作系统、CPU、内存、磁盘，常年开机。你的前端文件、后端程序、数据库都装/跑在这上面。"}]},{"type":"compare","pairs":[{"a":"前端 Frontend","b":"后端 Backend","diff":"前端＝用户看到的界面（运行在浏览器/手机里，负责渲染和交互）；后端＝用户看不到、运行在服务器上的程序（负责业务逻辑、鉴权、读写数据库）。前端决定『长什么样、能不能点』，后端决定『数据对不对、安不安全』。"},{"a":"接口 API","b":"直接操作数据库","diff":"后端对外提供的是『接口（API）』——一个约定好的请求地址与返回格式；前端只调用接口，永远不直接连数据库。这样可以隔离权限、便于维护。这也是产品安全的第一道墙。"},{"a":"本地 localhost","b":"线上服务器","diff":"你在自己电脑上跑的前后端叫『本地环境』，地址常是 localhost:3000；部署上线后跑在云服务器上，是公网地址。很多『本地正常、线上挂』的问题，都源于两套环境不完全一样（如数据库没迁移、环境变量没配）。"},{"a":"TCP（可靠）","b":"UDP（快速但不可靠）","diff":"TCP 会确认每份数据都到达（网页、文件用），UDP 不确认、丢了就丢（实时音视频、游戏用）。Web 的 HTTP 默认走 TCP，所以网络差时表现为『加载慢/卡』而不是『内容错乱』。"}]},{"type":"mistakes","items":["以为『网页能打开 = 后端没问题』——错，很多页面是纯前端静态页，后端可能根本没启动。","报错时随手把错误原样丢给 AI，而不说清『发生在哪个层』——AI 只能瞎猜。正确做法是先定位：报错来自浏览器控制台、后端终端、还是数据库连接？","以为『改完代码点刷新就行』——前端改了刷新即可，后端改了常常要重启服务才能生效；数据库结构改了还要迁移。不知道该不该重启，等于不知道该层是否生效。","把 IP、域名、端口混为一谈——域名给人记，IP 给网络认，端口标识这台机器上『哪个程序在服务』。三者不同。","以为 AI 写的代码『放对文件夹就能跑』——代码必须在『正确的环境』（装好依赖、正确版本、正确目录、可执行的权限）里才能运行。环境对不上，代码再对也是白搭（这正是第 7 课上线的核心矛盾）。"]},{"type":"deep","title":"深入一点：把『机器、程序、运行方式』讲透","beginner":["这台电脑/服务器里面有什么？三样最关键的硬件：","**CPU**（中央处理器）：真正会『算』的部分，负责执行指令。它快、但几乎没有记忆。","**内存 RAM**：临时、高速的『草稿本』，程序运行时把正在用的东西放这里；一断电全清空。","**磁盘 Disk**：长期、慢速的『仓库』，文件、数据库、图片都躺在这；断电也保留。","三者关系：程序从『磁盘』读进来 → 在『内存』里运行 → 由『CPU』逐条执行。所以『进程/线程』就是运行中的程序在内存和 CPU 上的具体存在。","**操作系统（OS）**：介于硬件和你程序之间的大管家。它负责：管理文件、管理进程、分配内存、读写磁盘、管理网络与权限。你的程序不是直接拿 CPU 干活，而是『请操作系统帮你安排』。Windows / macOS / Linux 都是操作系统。"],"advanced":["**编译 (Compile) vs 解释 (Interpret)**：代码有两种变可执行的方式。编译型（如 C、Go）：先整体翻译成机器码，再运行，快但改后要重新编译；解释型（如 Python、JavaScript）：一边翻译一边运行，改了就生效，但慢。","**Runtime（运行时）**：指『解释器 / 虚拟机 / 平台环境』，如 Node.js（能让 JS 在服务器上跑）、Python 解释器、Java 虚拟机（JVM）、浏览器的 JS 引擎（V8）。同一个 JS 文件，在浏览器里和 Node 里跑，用的是不同 Runtime——所以『它在浏览器能跑，不代表服务器能跑』。","**进程 (Process) vs 线程 (Thread)**：进程＝一个独立运行的程序实例，有自己独立的内存（跑崩一个不影响别的）；线程＝进程内部可并发的轻量任务单元，共享进程内存。一个 Node 服务通常是一个进程，一次请求常会用到多个线程/异步任务来并行处理。","**文件 / 路径 / 权限**：一切配置、代码、静态资源都是『文件』，文件有『路径』（在哪个文件夹）和『权限』（谁能读/写/执行）。很多部署报错是『权限不够』（403）或『路径不对』（404）——这不是代码逻辑问题，而是环境问题。","**环境 (Environment)**：你的程序依赖很多东西：命令、依赖包、环境变量、数据库地址、端口。这些合称『运行环境』。第 7 课上线的本质，就是把『你本机那套环境』尽量一致地搬到服务器上。"]},{"type":"ask","title":"怎么用 AI 帮你改代码：先问清『第几层』","scenario":"你的页面打开了，但点击『登录』没反应，控制台报了个错。怎么把这个信息高效地交给 AI？","template":"[我要描述] 我在做一个登录功能，点击登录按钮后页面没反应。\n[它能观测到的现象] 浏览器控制台报错：Cannot read properties of undefined (reading 'catch')，出错在 main.js 第 42 行。\n[我判断在哪一层] 前端 JS 在做请求时出错（尚未到后端）。\n[请给我] 帮我定位 main.js 第 42 行为什么报错，并给出修复方案与原因。","acceptance":["AI 给的答案里是否指明了『问题所在的那一层』（前端/后端/数据库/网络/环境）？","修复方案是否同时告诉你『为什么之前会错』（因果），而不只是『把这段换成这段』？","改完是否教你该怎么验证（例如：刷新？重启后端？看哪个日志？）？","如果 AI 只给了代码而你仍不确定，是否会继续追问『这个报错出现在哪一层、我怎么验证』？"],"tip":"给 AI 的信息越『分好层』，它越能准确判断。‘分层 + 现象 + 报错 + 我的判断’ 四件套，能大幅减少来回试错。"},{"type":"exercise","prompt":"你在浏览器打开自己刚做的网站，页面显示出来了，但点『提交表单』后页面一点反应都没有，浏览器控制台也没报错。根据这一课的分层，你最应该先怀疑哪一层？","opts":["我的 HTML 结构写错了（前端静态层）","后端程序没启动或没连上（后端层）","我的屏幕/显卡坏了（硬件层）","域名没过期（网络层）"],"a":1,"explain":"页面能正常显示说明前端静态层基本没问题；但『提交表单』要发请求给后端，没反应最可能是后端没启动、路径不对、或请求根本没发出去。先检查后端服务在不在跑、接口地址对不对。","jump":"sec7-step3","jumpLabel":"第 ④ 步：服务器接收并把请求交给后端"},{"type":"check","title":"结课检测：你能给报错『分层』了吗","intro":"共 5 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"浏览器里 DNS 解析这一步骤主要解决什么问题？","opts":["把域名翻译成 IP 地址","把 HTML 渲染成画面","把代码编译成机器码","把密码加密"],"a":0,"explain":"网络只认数字 IP，DNS 负责把人类好记的域名翻译成 IP，浏览器才知道该把请求发到哪台机器。","jump":"sec5-step1"},{"q":"『注册新账号后数据能永久保存』，这件事主要由哪几层协作完成？","opts":["只有浏览器（前端）","后端程序 + 数据库，前端只负责收集输入","只有网络（TCP/IP）","只有操作系统"],"a":1,"explain":"注册必须把信息写入数据库才叫『永久保存』；后端程序负责接收并由数据库落盘，前端只是收集输入。","jump":"sec5-step4"},{"q":"『代码在浏览器能跑』是否代表『同样的代码在服务器上也能跑』？","opts":["一定可以","不一定，因为浏览器和 Node/Python 是不同的 Runtime","一定不可以","只和网速有关"],"a":1,"explain":"浏览器里的 JS 由浏览器 JS 引擎跑，服务器上的 JS 由 Node.js 跑，是不同的 Runtime，能力与可用模块不同。","jump":"sec7"},{"q":"一个『Web 产品』由前端、后端、数据库组成。下面哪句最准确？","opts":["前端能直接连接数据库","后端程序通过接口把数据给前端，数据库由后端访问","数据库必须放在浏览器里","后端程序只能写死数据，不能读数据库"],"a":1,"explain":"前端只调用后端提供的接口(API)，后端负责访问数据库并返回结果，这样能隔离权限、便于维护。","jump":"sec7-step5"},{"q":"某功能『本地 localhost 一切正常，部署到线上就报数据库连不上』，最可能是哪两类环境不一致？","opts":["前端字体大小不同","数据库地址/密码/环境变量，以及迁移状态不一致","屏幕分辨率不同","键盘语言不同"],"a":1,"explain":"本地与线上最多的差距是数据库连接信息（地址、账号、密码）、环境变量配置，以及数据库结构是否已迁移。","jump":"sec7"}],"done":"你现在能把『一个 Web 产品』按层拆开了——前端、后端、数据库、服务器、网络各归其位，报错也能分到对应层。下一课我们钻到『后端』这一层：HTTP 到底是什么，API 怎么写、怎么调。","nextLesson":"v03-api"},{"type":"connection","known":["（这是 Vibe Coding 路径的第一课，默认你已经上过《从零看懂 AI》路径或至少了解『模型/产品』概念。）"],"learned":["一个 Web 产品 = 前端 + 后端 + 数据库 + 服务器 + 网络，彼此通过 HTTP 通信","一次请求的 7 步因果链：输入地址 → DNS → 建立连接/HTTP → 服务器 → 后端 → 数据库 → 渲染返回","CPU / 内存 / 磁盘 / 操作系统 / 进程 / 线程 / 编译解释 / Runtime 的定位","前端 / 后端 / 接口 API / 本地 localhost / 线上 的区别","给 AI 提问前先给报错『分层』，能显著提高一次成功率"],"next":"下一步我们进入『后端』层。想了解 AI 生成/理解代码，可回看 AI 路径的《AI Coding》一课；想把这条链路里『数据是怎么被长期记住的』讲透，下一课（API 与后端）与再下一课（数据库、登录与安全）会分别展开。","links":[{"href":"#/lesson/l22-ai-coding","text":"回看 AI 路径《AI Coding：把 AI 变成结对程序员》"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},{"id":"v03-api","title":"API 与后端：前后端怎么『对话』","subtitle":"前端要数据、后端给数据，靠的是一套约定好的『暗号』——HTTP 方法与状态码。看懂它对 AI 来说轻而易举，对你是判断代码靠不靠谱的分水岭。","course":"vibe","courseNo":"03","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web"],"nextLesson":"v04-db","sections":[{"type":"opening","question":"你的 App 在前端里点了个『收藏』按钮，后端怎么知道你要『新增一条收藏』而不是『删除一条』？同样是敲同一个接口地址，凭什么这次是加分、那次是删东西？","guess":"很多人会说『靠传一个名字不一样的按钮』。","next":"答案藏在 HTTP 的『方法（Method）』里。这一课我们把前后端之间的对话协议——HTTP 方法和状态码——彻底讲透：GET 和 POST 到底差在哪，200/404/500 各代表什么，什么是 API、什么是 JSON。学完你会开始『读』接口而不是『猜』接口。"},{"type":"why","before":"AI 写了个后端接口，前端也调了。你看着代码：有一堆 `app.get('/api/friends')`、`app.post('/api/friends')`、`req.body`、`res.json(...)`。你不懂为什么有的用 get 有的用 post，也不知道返回的 `{status:'ok', data:[...]}` 是什么。","problem":"不懂 HTTP 方法与状态码，你会犯两种错：要么把『该用 POST 写数据的操作』写成了 GET，导致数据带在 URL 里、既不安全又不支持大内容；要么拿到报错号 404/500 完全没概念，不知道该看前端还是后端。AI 生成的代码你再不敢动，一改就崩。","need":"把 HTTP 的『动词』（方法）、『回执』（状态码）、『货单』（请求/响应头与正文 JSON）看明白，你就拥有了『判断一段接口代码对不对』的最小能力：方法对不对、状态码合不合理、参数传没传对。这正是把 AI 代码从『能跑』升级到『可靠』的一步。"},{"type":"oneline","text":"API 是后端对外开的一扇扇门（URL），你用『HTTP 方法』说明你想干嘛（GET 拿数据 / POST 新增 / PUT 整体更新 / PATCH 部分更新 / DELETE 删除），后端用『状态码』告诉你结果（2xx 成功 / 4xx 你这边的问题 / 5xx 服务器的问题），数据通常以 JSON 格式在请求和响应里传递。"},{"type":"visual","kind":"http-viewer","title":"互动实验：HTTP 查看器，亲手发一个请求","hint":"选一个方法、填一个地址（或点预设接口），点『发送』。它会向你展示：这次请求带了哪些方法/头部/参数，服务器会返回什么状态码与 JSON 正文，以及每个状态码对应的含义。体会『同一个 URL，方法不同 = 动作不同』。"},{"type":"intuition","blocks":[{"k":"用餐厅点菜来想","t":"API 地址（URL）＝餐厅的『窗口名』，比如『/api/friends』是『朋友窗口』；HTTP 方法＝你点菜的动作——‘看看今天的菜单’（GET）、‘点一个菜’（POST）、‘把整个菜换掉’（PUT）、‘加个辣’（PATCH）、‘退掉这个菜’（DELETE）。后端（厨师）按你的动作处理，再用状态码告诉你：‘上菜了’（200）、‘这个菜没有’（404）、‘厨房炸了’（500）。"},{"k":"用寄快递来想","t":"GET 就像‘查单号’——只读，不改变任何东西，可以来很多次；POST 就像‘下单寄件’——会产生一个新的快递（新增数据）。所以‘收藏、下单、注册、发帖’这些会新增数据的操作用 POST，而‘翻页、搜索’这种只看不动的用 GET。"},{"k":"一句话记住状态码","t":"2 开头的都成功；3 开头的是‘让你去别处看’（重定向）；4 开头的是‘你（客户端）的问题’（404 找不到、401 没登录、403 没权限、400 请求写错）；5 开头的是‘服务器（后端）的问题’（500 内部出错）。看到 4 或 5，你就能立刻判断该检查哪一边。"}]},{"type":"how","intro":"把一个 HTTP 请求拆成 5 个部分，从头到尾走一遍『前端 → 后端 → 响应回前端』。","steps":[{"in":"① 请求行：方法 + URL","process":"前端发起一行字：`POST /api/friends`。前半是方法（动作），后半是接口地址（去哪扇门）。这决定了后端接下来执行哪段逻辑。","out":"例如 POST = 新增；GET = 查询；DELETE = 删除"},{"in":"② 请求头 Headers","process":"附带的一堆元信息：Content-Type（正文是 JSON 还是表单）、Authorization（登录凭证，如 Bearer token）、Accept（你想要什么格式）、携带的 Cookie 等。后端靠这些判断『你是谁、你给的是什么』。","out":"身份与格式声明"},{"in":"③ 请求正文 Body","process":"POST / PUT 需要把要写入的数据放进正文，通常是 JSON：`{\"name\":\"小明\",\"phone\":\"138...\"}`。GET 一般没有正文，参数放在 URL 查询串里（?name=小明）。","out":"数据内容（多为 JSON）"},{"in":"④ 后端处理并返回状态码","process":"后端读到方法+地址+头+正文，跑对应的逻辑，无论成败都返回一个状态码：成功 200/201，找不到 404，参数错 400，没登录 401，服务器异常 500。","out":"状态码：2xx / 4xx / 5xx"},{"in":"⑤ 响应正文 + 响应头","process":"成功后后端通常返回一个 JSON：`{\"ok\":true,\"data\":{...}}`，前端拿到这个结构再决定如何渲染。响应头里也常有 Set-Cookie、Cache-Control 等控制信息。","out":"前端拿到 JSON，渲染到界面"}]},{"type":"realworld","items":[{"name":"浏览器开发者工具 Network 面板","note":"按 F12 → Network，你能亲眼看到每一笔请求：方法、URL、状态码、耗时、请求/响应头与 JSON。这是『读接口』最重要的工具，AI 给不了你，但它能解释你从里面截到的任何一行。"},{"name":"REST 设计风格","note":"REST 是一套流行的接口组织约定：把『资源』当名词放 URL（/users、/posts），把动作当方法（GET/POST/PUT/DELETE）。例如 GET /users/5 读用户5，DELETE /users/5 删用户5。看懂 REST，你便看懂了大半后端代码的结构。"},{"name":"第三方开放 API（天气/支付/地图）","note":"你在产品里调的天气、支付、地图接口，就是对面公司后端暴露的 API。你会看到它要求固定方法、固定鉴权头（Authorization/ApiKey）、返回固定 JSON 结构。会读 API 文档 = 会接第三方能力。"},{"name":"前后端分离项目","note":"很多现代项目前端与后端是两个独立工程，只通过一组 API 契约对接。只要接口约定不变，前端可以换成任何形态（网页/App/小程序），后端完全不用改。这也解释了为什么『接口规范』如此重要。"}]},{"type":"compare","pairs":[{"a":"GET","b":"POST","diff":"GET 用于『读』数据：参数放 URL，可分享/可缓存，不应产生副作用（不会改服务器的数据）；POST 用于『写』数据：参数放正文，用于新增/提交，会产生副作用。安全与不大数据量的操作用 GET，会改数据的操作用 POST。"},{"a":"状态码 4xx","b":"状态码 5xx","diff":"4xx 是『客户端问题』：请求写错、没登录（401）、没权限（403）、找不到（404）——请检查你前端发出去的请求；5xx 是『服务器问题』：后端代码异常（500）、超时（504）——请检查后端日志。"},{"a":"REST API","b":"GraphQL","diff":"REST 靠『多个端点 URL + 方法』组织接口；GraphQL 靠『一个端点 + 查询语句』按需取字段。REST 更简单通用、生态大；GraphQL 更灵活但要学查询语法。入门从 REST 开始最稳。"},{"a":"JSON","b":"表单 Form-encoded","diff":"JSON 是一种结构化文本（{\"k\":v}），后端好解析、支持嵌套，是现代 API 主流；传统表单格式（a=1&b=2）较简单但在复杂数据前吃力。看到 Content-Type: application/json 就知道后面是 JSON。"}]},{"type":"mistakes","items":["AI 常犯（也常让你中招）的错误案例①：把『该用 POST 的新增操作』写成了 GET，导致密码等敏感数据出现在 URL / 日志里，既不安全又不支持大内容。","错误案例②：删改操作应返回合适状态码，却一律返回 200——前端永远‘成功’，数据却没被真正删掉。看到代码里所有分支都 res.json({ok:true}) 且不看状态码，就要警惕。","错误案例③：前端没把 token/Cookie 带上（没设置 headers.Authorization），导致后端每次回 401；前端却把锅甩给‘后端 bug’。判断法：看 Network 里那次请求的请求头带没带凭证。","把 404 理解成‘页面不见了’就完事——404 也可能是‘接口地址写错’，要不检查前端 URL，要不检查后端路由。/api/users 与 /api/user 差一个字母就是两个世界。","盲目照抄 AI 生成的接口而不看返回结构：前端拿 res.data.data 却和接口对不上，出来全是 undefined。学会看 Network 里真实的 JSON 结构再写渲染。"]},{"type":"deep","title":"深入一点：怎么判读一段 AI 写的接口代码","beginner":["拿到 AI 写的后端接口，按下面三问逐一看，就能快速判断靠不靠谱：","**一问方法**：这个操作该不该用这个 HTTP 方法？读操作用 GET，写操作用 POST/PUT/DELETE。方法不对 = 语义错。","**二问状态码**：成功路径返回 2xx 吗？参数错返回 400 吗？没登录返回 401 吗？没有的数据返回 404 吗？服务器异常会抛 500 吗？一个只返回 200 的接口是不合格的。","**三问数据流**：后端取参数的字段名，和前端传的字段名一致吗（body.name）？返回的 JSON 结构和前端 res.data.xxx 对得上吗？对不上就是坑。"],"advanced":["**express（Node 后端框架最小示例）**：","```js\napp.get('/api/users/:id', async (req, res) => {\n  const user = await db.one('SELECT * FROM users WHERE id=$1', [req.params.id]);\n  res.status(200).json({ ok: true, data: user });\n});\n```","注意三件事：`:id` 是路径参数（req.params.id）；操作是读 → 用 GET；成功返回 200。若查不到应 `return res.status(404).json({ok:false})`，而不是硬返回 200 空对象。","**错误处理缺失是最大隐患**：AI 常写出‘只管成功不管失败’的接口。可靠接口要捕获异常并返回 5xx：","```js\napp.post('/api/users', async (req, res) => {\n  try { await db.insert('users', req.body); res.status(201).json({ok:true}); }\n  catch (e) { console.error(e); res.status(500).json({ok:false, msg:'写入失败'}); }\n});\n```","**‘如何向 AI 验收一个接口’**：让 AI 给出‘该方法、正常/异常状态码、请求/响应 JSON 示例’三件套；你再对照 方法→语义 是否正确。能给出完整三件套的接口定义，才值得写进产品。"]},{"type":"ask","title":"怎么用 AI 帮你写/改一个接口","scenario":"你让 AI 写一个‘新增好友’的后端接口，并希望它可靠、前后端好对接。","template":"[我要做一个] POST /api/friends 的新增好友接口。\n[我希望的入参] JSON：{ nickname, remark }。\n[我希望的结果] 成功后返回 201 + {ok,data};昵称为空返回 400;后端异常返回 500。\n[请给我] 完整的 Node/Express 代码（含错误处理），并附：请求示例 JSON、成功/失败状态码与返回体、以及前端如何 fetch 调用的示例。","acceptance":["接口是否用对了 HTTP 方法（新增→POST）？","是否覆盖了成功(201)、参数错(400)、服务器错(500) 至少三类状态码？","请求与响应 JSON 结构是否给出、且前后端字段名一致？","是否包含 try/catch 错误处理而不是只管成功？用浏览器 Network 面板实测一下接口是否按文档返回。"],"tip":"把‘我要什么入参 + 我要什么结果 + 我要什么状态码’写成模板，AI 生成的接口会立刻规范很多；再用 Network 面板实测验证，别只看它嘴上说‘OK’。"},{"type":"exercise","prompt":"你在前端写了一个请求，点按钮后 Network 面板显示某请求返回 401。你最应该先检查什么？","opts":["后端 SQL 写错了","前端这次请求有没有带上登录凭证（Authorization/Cookie）","服务器机器坏了","网络 DNS 解析失败"],"a":1,"explain":"401 = 未认证/未登录，最常见原因就是请求没带凭证。去看 Network 里这一次请求的请求头，确认是否带了 token 或 Cookie。","jump":"sec5-step1","jumpLabel":"第 ② 步：请求头 Headers"},{"type":"check","title":"结课检测：你会读 API 了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"‘把一条收藏记录保存起来’应该用哪个 HTTP 方法？","opts":["GET","POST","PUT","DELETE"],"a":1,"explain":"产生新数据的写操作应该用 POST；GET 只用于读，不该产生副作用。","jump":"sec5-step0"},{"q":"状态码 401 表示什么？","opts":["找不到页面","未认证/未登录","服务器内部错误","请求太大"],"a":1,"explain":"401 Unauthorized = 未认证，需要登录凭证；403 才是‘已登录但没权限’。","jump":"sec5-step4"},{"q":"看到返回 500，你优先怀疑哪一层？","opts":["前端渲染","浏览器缓存","后端程序异常","CSS 样式"],"a":2,"explain":"500 = Internal Server Error，是服务器（后端）处理出错，去查后端日志与代码。","jump":"sec5-step4"},{"q":"REST 接口中，URL 里的名词代表什么？","opts":["动作（增删改查）","资源（如 /users、/posts）","设计者名字","数据库类型"],"a":1,"explain":"REST 把资源当名词放 URL，动作由 HTTP 方法表达。GET /users/5 是‘读用户5’。","jump":"sec6"},{"q":"前端请求里，登录凭证通常放在哪个位置？","opts":["URL 查询串","请求头 Headers（如 Authorization）","CSS 文件","浏览器书签"],"a":1,"explain":"凭证（token/Cookie）一般放在请求头里，如 Authorization: Bearer xxx；不放会导致 401。","jump":"sec5-step1"}],"done":"你已经能读懂前后端之间的‘暗号’了：方法定动作、状态码定结果、JSON 传数据。下一课我们把线的另一头——数据本身——讲清楚：数据库怎么设计，登录与安全怎么做。","nextLesson":"v04-db"},{"type":"connection","known":["你已经知道一个 Web 产品 = 前端 + 后端 + 数据库，通过 HTTP 通信（上一课）。","你已经会调用模型/看得懂 AI 相关 API 的基础概念（AI 路径）。"],"learned":["HTTP 方法：GET 读 / POST 写 / PUT 整体更新 / PATCH 局部更新 / DELETE 删除","状态码：2xx 成功 / 4xx 客户端问题 / 5xx 服务器问题","请求 = 方法 + URL + 头 + 正文(JSON)；响应 = 状态码 + JSON","REST 设计：名词当资源，方法当动作","给 AI 描述接口需求时，用‘入参+结果+状态码’三件套模板"],"next":"接口是承上启下的：它把‘数据’从后端递给前端。可数据从哪来、怎么存、怎么保证安全？这正是下一课《数据库、登录与安全》要解决的。和 AI 路径的联系：你调用大模型 API 的本质也是‘前端→HTTP→别人家后端的接口’，底层逻辑完全相同。","links":[{"href":"#/lesson/l16-llm-api","text":"回看 AI 路径《用 API 把模型接进你的产品》(规划中)"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},{"id":"v04-db","title":"数据库、登录与安全","subtitle":"数据是产品的命，登录是产品的门。这一课把‘数据怎么存’、‘你怎么证明是你’、‘怎么防坏人’讲透。","course":"vibe","courseNo":"04","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api"],"nextLesson":"v07-deploy","sections":[{"type":"opening","question":"用户注册了账号、收藏了文章、下了单——这些数据如果不做任何抽象地乱放在一起，会出什么问题？‘收藏’和‘用户’之间到底是什么关系？而你按下‘登录’，服务器凭什么相信你就是那个人，而不是冒充的？","guess":"很多人觉得‘数据随便存个文件不就行了，登录就是在数据库里对一下密码’。","next":"这一课回答三件事：①数据用‘关系表’组织才不乱（表、列、主键、外键、索引、SQL）；②‘登录’不是查一下密码那么简单——Session、JWT、OAuth 各是怎么证明‘你是谁’的；③坏人会怎么攻击（SQL 注入、XSS），以及怎么守住（参数化、转义、加密/哈希、最小权限）。"},{"type":"why","before":"AI 帮你生成登录/注册/收藏/下单功能，里面全是你不认识的词：SQL、primary key、foreign key、index、session、token、bcrypt、JWT、OAuth、SQL 注入。你照抄能跑，但出问题时完全无法判断是‘表没建对’‘还是登录逻辑错’‘还是被人攻击了’。","problem":"数据库设计与安全是‘你几乎不会让 AI 自己随便发挥’的地方——因为数据是用户资产、登录是安全边界。如果不懂“为什么用户表要 id 做主键”“为什么密码要哈希不能存明文”“为什么 SQL 要参数化防止注入”，你根本没法验收 AI 的代码，等于把产品最关键的部分交出去赌运气，早晚出事。","need":"这一课把最少必备的数据库设计与安全知识补上：会看表结构、会写最基础的 SQL、能对比 Session / JWT / OAuth、知道 SQL 注入和 XSS 是什么并知道对应防御。这样当 AI 给出表结构和登录代码，你能像审稿人一样快速挑出明显错误。"},{"type":"oneline","text":"产品数据大多存在关系型数据库（如 PostgreSQL/MySQL）：数据按‘表’组织，每行一条记录，靠‘主键’唯一标识，表与表用‘外键’建立关系，用 SQL 增删改查；登录靠加密凭证证明身份（Session 服务端记、JWT 它自己证明、OAuth 让第三方背书）；安全的核心三件事——密码要哈希不要明文、SQL 用参数化防注入、输出要转义防 XSS。"},{"type":"visual","kind":"db-designer","title":"互动实验：设计一张数据库表","hint":"这是一个迷你‘表设计器’：你决定表有哪些列、哪列是主键、要不要加索引、要不要存密码明文。点击‘预览 SQL / 检查问题’，它会告诉你这张表会不会踩主键、密码明文、可空、无索引等常见坑。体会‘多花一分钟设计，省无数 bug’。"},{"type":"intuition","blocks":[{"k":"用班级花名册来想","t":"数据库里的‘表’就像一张花名册：‘列’是表头（学号、姓名、班级），‘行’是一条记录（某个同学）。‘主键（primary key）’＝学号——全班唯一，靠它能精准找到某个人；‘外键（foreign key）’＝‘本班编号’——它指向另一张‘班级表’的主键，从而把两张表关联起来。没有主键，你用‘姓名’找人会遇到重名；没有外键，班级和学生就接不上。"},{"k":"用门禁卡来想登录","t":"Session＝你在前台刷了一次脸后，前台给你一把只在这栋楼有效的临时钥匙，钥匙上是你进门时发的一个号码（sessionId），门卫每次核对后台名单；JWT＝一把自带信息的加密卡片，上面写着‘我是小明，3 小时后过期’，门卫验签名就放行，不用每次查后台；OAuth＝你出示‘微信已认证’的凭证，门卫信微信的背书就让你进。三种都是‘证明你是你’，只是证明的方式和存放地点不同。"},{"k":"一句话记住安全","t":"密码只存哈希（加盐），不存明文；SQL 永远用参数化（?/$1 占位符），别拼字符串；输出到页面要转义（防 XSS）；后端始终校验，前端校验只是体验。记住这四条，你能挡住绝大多数入门级攻击。"}]},{"type":"visual","kind":"auth-compare","title":"互动实验：Session / JWT / OAuth 三种登录横评","hint":"点击三种登录方式，看同一个‘登录→鉴权→访问’场景在后台是怎么不同的：状态存在哪、怎么验证、有没有跨端问题、优缺点一目了然。帮你给产品选对登录方案。"},{"type":"how","intro":"把‘数据入库 + 登录鉴权’拆成两条因果链：先看一张表从设计到查询怎么走，再看一次登录如何完成。","steps":[{"in":"① 设计表结构（Schema）","process":"确定这张表存什么：用户表要有 id（主键）、username、password_hash、created_at。列的类型要选对（数字用 integer、文本用 varchar）。先想好‘要回答什么问题’，再定表，否则后面改结构（迁移）很麻烦。","out":"一张结构清晰的表 + 主键"},{"in":"② 建表 + 加索引","process":"用 SQL 建表；对‘经常按它来查’的列（如 username）加上索引（index），否则数据多了每次都全表扫描、慢到卡死。索引=书的目录，能加速查找。","out":"表建好，查询有索引加持"},{"in":"③ 用 SQL 增删改查","process":"INSERT 插入、SELECT 查询、UPDATE 更新、DELETE 删除。查询可加 WHERE 过滤、JOIN 关联别表。这是后端操作数据库的日常。","out":"数据被正确写入/读出"},{"in":"④ 表和表用外键建立关系","process":"比如‘收藏表’里放一个 user_id 外键指向用户表、一个 article_id 指向文章表，就能表达‘这个用户收藏了那篇文章’的关系。","out":"数据之间有明确关联，不重复、不乱"},{"in":"⑤ 登录：验证 + 发凭证","process":"用户输入密码 → 后端把输入的密码加盐哈希，和库里存的那个哈希比对 → 相同则信任，创建会话凭证（Session 存服务端 / JWT 返回一个 token / OAuth 走第三方）。","out":"前端拿到凭证，后续请求都带上它"},{"in":"⑥ 访问控制：每步鉴权","process":"后续每个需要身份的请求，后端都校验凭证 → 合法才放行，非法返回 401。同时用权限逻辑控制在‘只能动自己的数据’（不能改别人的）。","out":"只有合法用户能访问其权限内的数据"}]},{"type":"realworld","items":[{"name":"用户系统崩了=数据库没备份/没迁移","note":"很多线上事故是数据库结构改了没做迁移，或连接串配错。知道‘表结构=产品地基’，你就会让 AI 在改表时同步给迁移脚本（ALTER TABLE…），并先在本地/测试库验证。"},{"name":"密码泄露事件=明文存储的代价","note":"反复出现的‘XX 网站密码库泄露’事故，根源常是明文或弱哈希存密码。正确做法：bcrypt/scrypt 加盐哈希。这是判断 AI 登录代码‘安全与否’的第一眼标准。"},{"name":"登录方案选择=产品形态决定","note":"简单网页用 Session 就够；前后端分离/多端（App+网页+小程序）常用 JWT；要‘微信一键登录’就用 OAuth。你会常看到这三者在真实项目里混用（如 JWT 登录 + 微信 OAuth 授权）。"},{"name":"防火墙/最小权限=运维层防御","note":"生产数据库通常不直接暴露公网，只允许服务器内网访问；应用账号只给它需要的库表权限。这是安全纵深的一部分，和‘代码那次注入’互补。"}]},{"type":"compare","pairs":[{"a":"Session（服务端会话）","b":"JWT（令牌）","diff":"Session 把状态存在服务器（内存/Redis/库），客户端只持一个 sessionId，好处是可随时踢人/注销；JWT 把身份信息加密签进 token 给客户端，服务器无状态，好处是天然适合多端与分布式，缺点是一旦签发难在过期前吊销。选型：传统/单一服务用 Session，前后端分离多端多用 JWT。"},{"a":"JWT","b":"OAuth","diff":"JWT 是一种‘凭证格式’（我信任它的签名）；OAuth 是一种‘授权协议’（用户把权限授予第三方，如‘微信允许这个 App 读我的昵称头像’）。OAuth 常把 JWT 当作其中一种 access_token 的载体。"},{"a":"哈希 Hash（单向）","b":"加密 Encrypt（可逆）","diff":"哈希不可逆：密码只做比对，任何人（包括你自己）都无法还原，适合存密码；加密可逆：能解回原文，适合传输敏感信息（但要妥善保管密钥）。拿加密去存密码是常见误区。"},{"a":"SQL 注入","b":"XSS 跨站脚本","diff":"注入是‘坏人把 SQL 代码塞进输入，骗后端执行’，防御靠参数化查询；XSS 是‘坏人把脚本塞进页面内容，骗浏览器执行’，防御靠输出转义。一个打数据库、一个打浏览器，都要防。"}]},{"type":"mistakes","items":["错误案例①（AI 高频）：密码用明文存进数据库列 `password`。正确是 `password_hash` 且用 bcrypt/scrypt 加盐哈希。看到列名叫 password 就要警觉。","错误案例②（致命）：SQL 用字符串拼接——`SELECT * FROM users WHERE name = '` + input + `'`。坏人输入 `' OR '1'='1` 就能登录一切人。必须改成参数化：`WHERE name = $1`（PG）或 `?`（MySQL）。","错误案例③：用户表没有主键，或把‘用户名’当唯一标识——重名就会数据错乱。主键必须稳定唯一（通常用自增 id 或 UUID）。","错误案例④：前端校验当安全边界——‘我在前端限制了只能填数字’并不能挡住直接调接口的攻击者。真正的校验必须在后端。","错误案例⑤：把 token 存 localStorage 又不设过期、也不校验是不是当前用户——一旦 XSS 就能偷走凭证。安全要‘防御纵深’，别只做一层。"]},{"type":"deep","title":"深入一点：手把手判读一张 AI 建的‘用户表’和登录接口","beginner":["看一张 AI 生成的用户表，先问五件事：","**有没有主键？** 要有 id（或 UUID）作主键，能唯一稳定地定位记录。","**密码是不是哈希列？** 应该叫 password_hash / password_digest，用 bcrypt，绝不存明文。","**必填列有没有 NOT NULL？** 用户名、密码哈希不能为空。","**会不会被注入？** 查询语句是不是参数化的（用占位符而非拼接）？","**有没有做访问控制？** 比如‘只能读自己的数据’，而不是任何人传个 id 就能读到别人的。"],"advanced":["**合法但可以更好的设计**：除了基础列，常加 created_at/updated_at 时间戳（审计用）；经常按 username 查就加唯一索引 `UNIQUE(username)`；邮箱/手机号单独存或用正则后端校验。","**登录接口应返回什么**：成功后（201/200）返回凭证；密码错返回 401；账号不存在也返回 401（而不是 404，避免暴露‘这账号存在’）。失败要记日志，但日志里别打明文密码。","**一个可参考的 SQL 建表**：","```sql\nCREATE TABLE users (\n  id BIGSERIAL PRIMARY KEY,\n  username VARCHAR(50) NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n```","**登录校验（参数化防注入的示范）**：","```js\nconst row = await db.oneOrNone('SELECT * FROM users WHERE username=$1', [username]);\nconst ok = row && await bcrypt.compare(password, row.password_hash);\nif (!ok) return res.status(401).json({ ok:false, msg:'用户名或密码错误' });\n```","注意 `$1` 占位符 + `[username]` 参数数组 = 参数化，SQL 注入无从下手。"]},{"type":"ask","title":"怎么用 AI 帮你设计数据库和登录","scenario":"你做了一个‘用户能注册、能收藏文章’的小产品，想让 AI 一次性给出靠谱的表设计和登录方案。","template":"[产品场景] 用户注册登录后，可以收藏文章（一个用户可收藏多篇文章）。\n[请帮我设计] ①用户表与收藏表的结构（含主键、外键、索引）；②注册/登录后端代码，密码用 bcrypt 加盐哈希、SQL 用参数化防注入；③返回 401/201 等状态码。\n[验收标准] 请说明：主键是谁、外键怎么关联、密码如何存储、如何防 SQL 注入、登录凭证用 Session 还是 JWT 并说明理由。","acceptance":["表结构是否给出了主键、外键和需要加的索引？","密码是否明确用了 bcrypt 之类加盐哈希而非明文？","SQL 是否参数化（占位符）而非字符串拼接？","登录凭证方案是否说明了 Session/JWT 的选择及理由？是否覆盖成功与失败状态码？"],"tip":"涉及数据库和安全，务必让 AI 把‘为什么这么做’讲出来，而不能只给代码。你再用上面的‘五问’走一遍，就能当半个审查。"},{"type":"exercise","prompt":"你的登录接口被人用输入 `' OR '1'='1` 打穿了，任何密码都能登进去。这最可能是下面哪种代码导致的？","opts":["用 bcrypt 哈希密码","SQL 用了字符串拼接用户输入（未参数化）","给 username 加了唯一索引","登录返回了 401"],"a":1,"explain":"把用户输入直接拼进 SQL 会造成 SQL 注入——输入里含有的引号和 OR 让查询恒真，从而绕过密码。改成参数化查询即可堵住。","jump":"sec8","jumpLabel":"深入一点的 SQL 注入示范段"},{"type":"check","title":"结课检测：数据库与安全你真的懂了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"用户的‘收藏表’要关联用户和文章，最正规的做法的核心是？","opts":["把所有用户名和文章名塞进同一列","用外键 user_id 和 article_id 分别指向用户表、文章表的主键","每次复制一份用户表","收藏不存数据库"],"a":1,"explain":"用外键指向各自表的主键，才能表达‘哪个用户收藏了哪篇文章’的关系且不重复存储。","jump":"sec5-step3"},{"q":"密码正确的存储方式是？","opts":["明文存进 password 列","加密（可逆）后存","加盐哈希（如 bcrypt）后存，且不存明文","存进 cookie"],"a":2,"explain":"哈希是不可逆的，任何人不包括你自己都无法还原密码，只能用于比对；加盐防止相同密码产生相同哈希。","jump":"sec5-step4"},{"q":"SQL 注入的根本防御是？","opts":["在前端把输入框禁用","用参数化查询（占位符）","把数据库放到公网","把 SQL 写成大写字母"],"a":1,"explain":"参数化查询把用户输入当作数据而不是可执行的 SQL 代码，因此注入失效。","jump":"sec8"},{"q":"Session 与 JWT 的区别，哪句最准确？","opts":["Session 把状态存服务器，JWT 把身份信息加密进令牌交给客户端","两者完全一样","JWT 不能加密","Session 只用于 HTTPS"],"a":0,"explain":"Session 服务端有状态、可随时注销；JWT 无状态、令牌自证身份，适合多端，但签发后较难在过期前撤销。","jump":"sec6"},{"q":"别人的博客里嵌了你的登录页代码，结果是坏人代码执行——这属于用什么方式防御的问题？","opts":["SQL 注入","XSS 跨站脚本","数据库索引","密码哈希"],"a":1,"explain":"把脚本塞进页面内容让浏览器执行的是 XSS，防御靠输出转义 + CSP 等；这不是 SQL 注入（那是打数据库的）。","jump":"sec6"}],"done":"你现在能看懂表结构、能审 AI 的建表与登录代码、知道 Session/JWT/OAuth 怎么选、也知道 SQL 注入/XSS 怎么防。下一课我们把这一切真正‘送上线’：从本地 Demo 变成一台公网可访问、稳定可回滚的真实产品。","nextLesson":"v07-deploy"},{"type":"connection","known":["你知道后端通过 API 和数据库交互（上一课）。","你知道数据要长期保存、要按关系组织（本课）。"],"learned":["数据库用表组织数据：列、行、主键唯一、外键关联、索引加速","SQL 增删改查与参数化防注入","登录三方案：Session 存服务端 / JWT 自证令牌 / OAuth 第三方授权","安全四原则：密码哈希、SQL 参数化、输出转义、后端校验"],"next":"数据和身份都准备好了，下一步是把它们‘送上线’。这与 AI 路径的联系：当你要做的是 AI 产品（如 RAG 问答），RAG 的向量库也是一种‘数据库’，登录/安全同样适用。下一课《从本地 Demo 到正式上线》会把 部署、健康检查、回滚 讲透。","links":[{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——了解向量数据库在 AI 产品里的角色"},{"href":"#/lesson/l20-ai-eng","text":"回看 AI 路径《AI 工程：从原型到生产》(规划中)"}]}]},{"id":"v07-deploy","title":"从本地 Demo 到正式上线","subtitle":"代码在你自己电脑上能跑，不算数；让全世界都能访问、且挂了能快速恢复，才是‘上线’。这一课讲清楚那条从 localhost 到公网的最后一公里。","course":"vibe","courseNo":"07","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api","v04-db"],"nextLesson":"","sections":[{"type":"opening","question":"你的产品在自己电脑上跑得欢，你联调、测试都通过了。现在要把它放到公网，让外地、外网、别家浏览器都能访问——为什么这件事永远比想象中麻烦？常见的‘本地正常、线上挂掉’到底差在哪？","guess":"很多人以为‘上线就是把文件传到服务器上，然后就能用了’。","next":"这一课我们拆解上线全流程：环境如何保持一致（环境变量）、如何把项目部署到服务器/云平台、域名与 HTTPS 怎么配、上线后怎么确认它是‘健康的’（健康检查）、出问题怎么快速回滚、以及要不要上 CI/CD。学完后你拥有的能力是：把 AI 做的 Demo 安全地变成可上线产品，并知道每一步万一失败该怎么退回来。"},{"type":"why","before":"你写好了产品，AI 也说‘好了，部署吧’。可你一部署，报‘连接数据库失败’‘端口被占用’‘找不到 .env’‘静态资源 404’……你完全不知道从哪查起，只能一遍遍粘日志给 AI，反复重装环境。","problem":"本地与线上天然不同：路径不同、数据库地址不同、端口不同、依赖版本可能不同、还要面对公网连接、域名、HTTPS 证书、防火墙。如果你没有‘环境一致性’与‘可回滚’的意识，即使这次勉强跑起来，下次改动也会随时把线上搞挂而无法恢复。","need":"掌握上线的最小可靠流程：用环境变量（.env）把差异集中管理；部署常走三大路径（静态托管 / PaaS 平台 / 自管服务器）分别怎么选；配域名 + HTTPS；加‘健康检查’让系统自己喊救命；上线清单与回滚流程让‘挂了也能退回去’。这是把 Demo 变成产品的临门一脚。"},{"type":"oneline","text":"上线 = 把代码 + 环境一致地搬上公网机器 + 配好域名/HTTPS + 挂上健康检查 + 准备好一键回滚。核心三句话：环境用变量隔离差异（不同环境不同值）、部署用脚本/平台保证可重复（别靠手敲）、发布用‘灰度/可回滚’控制风险（挂了能退）。"},{"type":"visual","kind":"deploy-console","title":"互动实验：部署控制台，看一次完整上线","hint":"这是一个模拟部署终端：点‘部署’会经历 构建 → 迁移 → 健康检查 → 流量切换；如果健康检查失败，系统会拒绝放量并自动回滚到上一个版本。你还能故意制造‘健康检查失败’来亲眼看到回滚是怎么保命的。"},{"type":"intuition","blocks":[{"k":"用开餐厅来想","t":"本地 Demo 像在你的厨房试菜——火候是你自己调好的、食材在你冰箱里。上线＝在商业街上开正式的餐厅：要租店面（服务器）、接水电气（网络/HTTPS）、换统一采购的食材（数据库搬到线上）、店员按标准作业（健康检查/监控）、万一某天厨房着火（服务挂）要能立刻换上备用后厨（回滚/容灾）。‘本地试菜’和‘正式营业’根本不是一回事。"},{"k":"用电梯/红绿灯来想健康检查","t":"健康检查＝系统自己定时喊一嗓子‘我还活着’（探测 /health 接口）。就像电梯每隔几秒报一次运行状态。如果它不喊了，编排系统（如负载均衡）就把它踢出队伍并拉起一个新的——而不是让用户对着白屏干等。"},{"k":"一句话记住上线","t":"环境变量隔离差异 → 构建产物可重复 → 部署到线上 → 健康检查确认活着 → 出问题回滚上个版本。五个动作，缺一不可；其中‘能回滚’是你最后的保险绳。"}]},{"type":"visual","kind":"llm-retry","title":"互动实验：给 LLM 调用加上超时 + 重试 + 回退","hint":"你的产品里调了大模型 API（这也是你 AI 产品的‘后厨’）。网络抖动/超时/限流在线上是家常便饭。这个实验模拟‘调用 → 超时 → 重试 → 回退(fallback)’，体会电商级 API 调用为什么要设计超时与降级。这也是 Vibe Coding 路径与 AI 路径的连接点。"},{"type":"how","intro":"把一次‘安全上线’拆成 6 步：每一步都有明确的‘成功标志’和‘失败补救’。","steps":[{"in":"① 环境变量：把差异抽出来","process":"本地/测试/线上需要不同的数据库地址、密钥、端口。把它们写进环境变量（如 .env 文件或平台面板），代码里用 process.env.XXX（Node）/ os.environ（Python）读取，而不是写死。","out":"代码与环境解耦：同一份代码换环境即可"},{"in":"② 构建 + 迁移","process":"前端打包成静态文件（npm run build → dist/）；数据库结构变化用迁移脚本（migration）跑一遍。构建产物要是‘可重复’的——同一份源码应产出同样的产物。","out":"得到一个可直接发布的‘构建物’+ 数据库就绪"},{"in":"③ 部署到线上","process":"三大路径：静态托管（页面纯前端，丢到 GitHub Pages/CF Pages/OSS 即可）；PaaS 平台（Vercel/Netlify/Railway/Render，把代码推送即可自动部署，适合新手与中等项目）；自管服务器（买 ECS/VPS，自己配 Nginx + 进程守护如 PM2/systemd）。新手从 PaaS 起步最稳。","out":"公网可以访问你的服务"},{"in":"④ 域名 + HTTPS","process":"买个域名，把 DNS 解析到你的服务（A 记录指向 IP / CNAME 指向平台）；再签 HTTPS 证书（平台自动，或云厂商+Letʼs Encrypt），让访问走 https:// 加密。浏览器地址栏的小锁 = 加密。","out":"用户通过好记的 https://你的域名 访问"},{"in":"⑤ 健康检查 + 监控","process":"后端提供 /health 接口（返回 200 + 状态）。负载均衡/编排平台每 X 秒探测它：活着→正常放量；不活→摘除并重启该实例，同时报给你（监控告警）。","out":"系统自己‘喊救命’，而不是等用户来报"},{"in":"⑥ 发布即回滚预案","process":"大型发布用‘灰度’：先 10% 流量验证，稳妥再全量；每版都保留上一个版本，发现异常立刻一键回滚（切回旧版本）。回滚能力 = 你改线上时的底气。","out":"即使新版本有问题，也可在几分钟内恢复"}]},{"type":"realworld","items":[{"name":"GitHub Pages（本站就是这么上线的）","note":"纯前端静态站可直接推到 GitHub Pages，免费公网、自带 HTTPS。适合‘文档/演示/静态首页’。注意它只托管静态资源，没有后端/数据库——需要后端的要另选 PaaS 或 VPS。"},{"name":"Vercel / Render / Railway（PaaS）","note":"‘连上 Git 仓库，push 即部署’：自动构建、自动 HTTPS、给环境变量面板、自动健康检查与回滚。是前端+轻后端产品（含 Next.js 全栈）最省心的上线方式。"},{"name":"云服务器 + 进程守护（VPS）","note":"腾讯云/阿里云的 ECS 上装 Node/Python、用 PM2/systemd 守护进程、Nginx 反代 + HTTPS。灵活可控但维护成本高。适合要自己掌控环境、或者后端较重/要连自己数据库的产品。"},{"name":"CI/CD（持续集成/持续部署）","note":"把‘测试 → 构建 → 部署’做成流水线：你 push 代码，系统自动跑测试并部署。好处是上线行为可重复、可审计；新手至少理解它的存在，平滑后再引入 (如 GitHub Actions)。"}]},{"type":"compare","pairs":[{"a":"静态托管（GitHub Pages/OSS）","b":"PaaS 平台（Vercel/Render）","diff":"静态托管只能放纯前端静态文件、无后端、一般免费；PaaS 能托管前端+后端（有的带数据库），源码推送自动构建/部署/HTTPS，更适合‘有后端的完整产品’。纯静态选前者，有后端选后者。"},{"a":"PaaS 平台","b":"自管云服务器（VPS+PM2+Nginx）","diff":"PaaS 帮你管环境、自动部署、内置回滚，省心但灵活度有限；VPS 完全可控（能装任意软件）但要自己维护系统、进程守护、HTTPS、备份，运维成本高。新手/中小产品从 PaaS 起步，要深度控制再上 VPS。"},{"a":"环境变量 .env","b":"写死在代码里","diff":"环境变量让同一份代码在不同环境（本地/测试/线上）用不同配置，且密钥不进代码库；写死会导致‘本地行、线上不行’，且密钥泄露风险大。必须用环境变量管理差异与密钥。"},{"a":"健康检查 /health","b":"用户报错才知道挂了","diff":"健康检查是主动、自动、秒级的探活，挂了立刻摘除重启并告警；等用户报告则被动、慢、伤口碑。生产环境必须有健康检查。"}]},{"type":"mistakes","items":["错误案例①：把数据库连接串、API 密钥写死在代码/前端里并 push 到公开仓库——等于把保险柜密码贴在门口。密钥必须进环境变量并严格保密。","错误案例②：没有环境意识，‘本地跑通了就认为线上能跑’。正确的验证方式：线上部署后跑一遍健康检查 + 真实浏览器访问，而不是‘本地 200 就完事’。","错误案例③：上线直接改线上数据库结构却不做迁移回滚——出事退不回去。数据库结构变更要保留迁移脚本、可逆可回退。","错误案例④：追逐‘最新框架/功能’把线上当实验场，改一次崩一次却没有任何回滚按钮。生产稳定 > 炫技；改版前后都要有一键回滚能力。","错误案例⑤：把‘调大模型 API’当成不会失败——线上网络抖动、超时、限流很常见。不给 API 调用加超时/重试/回退(fallback) 的 AI 功能，用户会频繁看到转圈/报错。"]},{"type":"deep","title":"深入一点：一次失败的线上事故是怎么被救回来的","beginner":["把‘回滚像不像重装系统’想明白：回滚不是把线上机器清空重装，而是‘把流量切回上一个已知良好的版本镜像/构建物’。现代平台（PaaS、容器编排）都保留旧版本，一键切换即可，秒级恢复。","健康检查的 /health 接口长什么样？就是一个后端路由，返回 200 和一个简单的 JSON：`{status:'ok'}`。它常常还会顺带检查数据库能否连上。如果数据库挂了，/health 也会返回失败——这样编排系统才会判断这台机器‘不健康’并把它踢出去。"],"advanced":["**一次事故的完整剧本**：新版本把数据库连接串写错 → 部署平台探测 /health → 数据库连不上 → /health 返回 500 → 平台判定‘不健康’→ 拒绝放量 / 自动回滚到旧版本 → 监控告警发到你手机 → 你看日志定位到环境变量拼错 → 修正后重新部署。全程用户几乎无感知。这就是‘健康检查 + 回滚 + 监控’三件套的价值。","**LLM 调用的可靠性设计（与 AI 路径的接口）**：真实产品调大模型 API 时，用模式是‘超时 + 指数退避重试 + 回退（缓存结果 / 备用模型 / 返回友好提示）’：","```js\nconst response = await fetchLLMWithRetry({\n  prompt, timeoutMs: 8000,            // 超时：8 秒没回应就放弃重试\n  retries: 3, backoffMs: 1000,         // 重试 3 次，指数退避\n  fallback: () => cache.get(key)       // 兜底：用缓存或降级文案\n});\n```","**上线检查清单（Checklist）**：①环境变量配全了吗？②数据库迁移跑了吗？③HTTPS 生效了吗（浏览器锁）？④/health 探针过吗？⑤日志与告警接了吗？⑥旧版本能一键回滚吗？⑦真实浏览器/多设备验证了吗？全部打勾，才算一次‘可上线发布’。"]},{"type":"ask","title":"怎么让 AI 帮你安全上线","scenario":"你的产品要第一次上线，不确定从哪下手、怕把线上搞挂。","template":"[我的产品] 是一个 [前端 + Node 后端 + PostgreSQL] 的小产品，目前只在本地能跑。\n[请给我] 一份最小可靠的上线方案：推荐用哪种托管方式（静态/PaaS/VPS）并说明理由；列出需要的环境变量清单；给出数据库迁移与开启 HTTPS 的步骤；提供 /health 接口示例与回滚预案。\n[验收标准] 每一步是否有明确操作与验证方法？是否包含失败时的回滚步骤？","acceptance":["部署方案是否说明了选型理由（静态/PaaS/VPS）与本产品的适配性？","环境变量清单是否完整且不包含明文密钥？","是否提供了可复现的部署步骤与验证方式（健康检查/浏览器访问）？","是否有明确的回滚/恢复预案，而不是‘挂了重装’？先小范围(灰度)验证再全量了吗？"],"tip":"上线是最不能‘赌一把’的环节。让 AI 给出‘选型 + 环境变量 + 验证 + 回滚’全套，再逐项打勾验收；任何一步读不懂就让 AI 解释‘为什么这样做’，直到你能复述为止。"},{"type":"exercise","prompt":"你上线了新版本，负载均衡探测 /health 连续几次都返回 500。接下来最正确的自动动作是什么？","opts":["继续放大流量，等用户反馈","把该实例摘除并自动回滚到上一个良好版本","重启浏览器","删掉数据库"],"a":1,"explain":"健康检查失败说明新版不健康，应把它踢出流量并回滚到上一版本，让用户在无感知的情况下继续使用。","jump":"sec7-step4","jumpLabel":"第 ⑤ 步：健康检查 + 监控"},{"type":"check","title":"结课检测：你的上线观念成立了吗","intro":"共 5 题。全部答对可进入下一节后续课程（或视为完成本路径第一批）。","questions":[{"q":"‘本地跑通 = 线上一定能跑’这句话？","opts":["完全正确","错误，本地与线上环境(变量/依赖/数据库)常不同，需部署后验证","只对前端成立","只对数据库成立"],"a":1,"explain":"环境差异（连接串、密钥、依赖版本、端口）是‘本地行、线上挂’的常见原因，必须部署后做健康检查与真实访问验证。","jump":"sec4"},{"q":"数据库地址、API 密钥这类差异应当怎么管？","opts":["写死在代码里方便","放进环境变量按环境区分，且密钥不进代码库","藏在注释里","放前端页面里"],"a":1,"explain":"环境变量让同一代码适应不同环境、密钥不进仓库，安全且可维护。","jump":"sec5-step0"},{"q":"完全不会写代码、只想让前端+后端都能自动上线，最省心的选项是？","opts":["自建机房","PaaS 平台（如 Vercel/Render），连 Git push 即部署","用纯记事本手写服务器脚本","不部署"],"a":1,"explain":"PaaS 负责构建、部署、HTTPS、健康检查与回滚，对新手最友好；VPS 更适合要深度控制的高级场景。","jump":"sec7"},{"q":"/health 健康检查的探测失败时，编排系统最合理的动作是？","opts":["什么都不做","摘除不健康实例并重启/拉起新的，必要时候选回滚","把数据库清空","关掉域名"],"a":1,"explain":"自动摘除+重启，必要时回滚旧版本，让用户几乎无感知；同时告警提醒你排查。","jump":"sec7-step4"},{"q":"调用大模型 API 时，‘超时 + 重试 + 回退(fallback)’组合主要防范什么？","opts":["防止代码有语法错误","线上网络抖动、超时、限流导致的偶发失败","防止数据库被删","防止前端样式错乱"],"a":1,"explain":"线上第三方 API 偶发失败是常态，超时避免无限等待、重试提高成功率、回退(缓存/备用/友好提示)兜底，保证用户体验不崩。","jump":"sec7"}],"done":"你已经掌握了从 localhost 到公网‘最后一百米’的全部关键：环境变量隔离、部署三路径选型、域名+HTTPS、健康检查、回滚预案、上线清单。Vibe Coding 第一批四门课到此收官——你已经能看懂代码结构、判断接口与数据库靠不靠谱、把 Demo 安全上线了。","nextLesson":""},{"type":"connection","known":["你知道一个 Web 产品如何分层（课1）、前后端怎么通信（课3）、数据怎么存与登录安全（课4）。","你会调大模型 API / 了解 RAG、Agent（AI 路径）。"],"learned":["环境变量隔离本地/测试/线上差异，密钥不进代码库","部署三路径：静态托管 / PaaS / 自管 VPS，以及各自适用场景","域名 + HTTPS（浏览器小锁）怎么配","健康检查(/health)探活 + 监控告警，挂了自动摘除","灰度 + 一键回滚 = 改线上时的底气；上线检查清单"],"next":"Vibe Coding 第一批四个环节到此闭环：看懂 → 懂接口 → 懂数据/安全 → 懂上线。下一步安排：第二批课程将覆盖 前端与语言基础（课2）、终端与 Git（课5）、存储缓存与测试排错（课6）、系统设计与 AI 产品工程（课8）。与本路径之外的联系：AI 产品的上线同样遵循本课原则，且多了‘LLM 调用可靠性’（超时/重试/回退）这一环——已在课 7 实验里有真机感受。","links":[{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"},{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——AI 产品上线的数据侧"},{"href":"#/lesson/l-agent","text":"回看 AI 路径《Agent：让 AI 自己动手做事》——Agent 产品化时的可靠性思考"}]}]}]},"lessonConceptMap":{"ai-what":["l00-ai-world"],"ai-ml-dl":["l00-ai-world"],"ai-apps":["l00-ai-world"],"ai-limits":["l00-ai-world"],"embedding":["l-embedding"],"vector":["l-embedding"],"cosine-similarity":["l-embedding"],"emb-vector-store":["l-embedding","l-rag"],"attention":["l-attention","l-transformer"],"qkv":["l-attention"],"multihead":["l-attention","l-transformer"],"attention-long":["l-attention"],"transformer":["l-transformer"],"position-enc":["l-transformer"],"rag-pain":["l-rag"],"rag-pipeline":["l-rag"],"chunking":["l-rag"],"vector-search":["l-rag"],"rerank":["l-rag"],"agent-intro":["l-agent"],"agent-loop":["l-agent"],"tool-use":["l-agent"],"agent-planning":["l-agent"],"agent-memory":["l-agent"],"agent-reflection":["l-agent"]}};
  var lessons = DATA.lessons, curriculum = DATA.curriculum;
  var lessonsByCat = DATA.lessonsByCat, lessonConceptMap = DATA.lessonConceptMap;
  var flagship = DATA.flagship || [];

  function getLesson(id) { return lessons[id] || null; }
  function getLessonsByCategory(catId) { return lessonsByCat[catId] || []; }
  function lessonForConcept(cid) { return lessonConceptMap[cid] || []; }
  function getCurriculumLessonMeta(id) {
    for (var ci = 0; ci < (curriculum.categories || []).length; ci++) {
      var cat = curriculum.categories[ci];
      for (var hi = 0; hi < (cat.chapters || []).length; hi++) {
        var ch = cat.chapters[hi];
        for (var li = 0; li < (ch.lessons || []).length; li++) {
          if (ch.lessons[li].id === id) return ch.lessons[li];
        }
      }
    }
    return null;
  }
  function readyLessons() { return Object.keys(lessons).map(function (id) { return lessons[id]; }); }
  function flagshipLessons() {
    var out = [];
    flagship.forEach(function (id) { if (lessons[id]) out.push(lessons[id]); });
    return out;
  }
  function flaggedMeta(id) { return getCurriculumLessonMeta(id); }

  var L = {
    version: DATA.version,
    builtAt: DATA.builtAt,
    curriculum: curriculum,
    lessonCount: DATA.lessonCount,
    flagship: flagship,
    lessons: lessons,
    byId: lessons,
    lessonsByCat: lessonsByCat,
    lessonConceptMap: lessonConceptMap,
    getLesson: getLesson,
    getLessonsByCategory: getLessonsByCategory,
    lessonForConcept: lessonForConcept,
    getCurriculumLessonMeta: getCurriculumLessonMeta,
    readyLessons: readyLessons,
    flagshipLessons: flagshipLessons,
    flaggedMeta: flaggedMeta
  };

  if (typeof window !== "undefined") window.LEARN = L;
  if (typeof module !== "undefined" && module.exports) module.exports = L;
})();